    "q.l3#4.o1" to "綿は汗を吸うと乾きにくく、濡れたまま肌に張り付いて低体温を早めるから",
    "q.l3#4.o2" to "綿はアレルギーを起こすから",
    "q.l3#4.o3" to "綿は通気性が悪いので余計に寒いから",
    "q.l3#4.e" to "ベースレイヤーの仕事は汗を肌から運び出すことです。綿は水を吸うとほとんど放出せず、冷えた湿りが肌に残って熱を奪い続けます。ポリエステルやメリノウールなど、汗を素早く通す素材を選びます。",

    "q.l3#5.p" to "6,000 m 級の高山靴に推奨される素材はどれですか。",
    "q.l3#5.o0" to "普通の皮革",
    "q.l3#5.o1" to "GORE-TEX などの防水透湿素材",
    "q.l3#5.o2" to "綿織物",
    "q.l3#5.o3" to "プラスチックのハードシェル",
    "q.l3#5.e" to "6,000 m 級は軽さ、履き心地、グリップを重視しつつ、長時間の歩行にも耐える必要があります。GORE-TEX などの防水透湿メンブレンは水を通さず汗気を逃がします。防水だけして透湿しないと靴の中で汗が溜まり、これもまた濡れによる冷却を招きます。",

    "q.l3#6.p" to "登山用ソックスで避けるべき素材はどれですか。",
    "q.l3#6.o0" to "メリノウール",
    "q.l3#6.o1" to "ポリエステルなどの合成繊維",
    "q.l3#6.o2" to "綿",
    "q.l3#6.o3" to "ナイロン",
    "q.l3#6.e" to "肌着と同じ理屈です。綿は汗を吸ってもほとんど放出せず、冷えた湿りが足に残って熱を奪い続け、マメのリスクも大きく上げます。合成繊維（綿混でないもの）かメリノウールを選び、保温と足の血流のために丈の長いタイプが適します。",

    "q.l3#7.p" to "スパッツ（ゲイター）の選び方として正しいのはどれですか。",
    "q.l3#7.o0" to "どの行程でも同じショートタイプを使う",
    "q.l3#7.o1" to "高所の山ではロングタイプが望ましく、靴への雪の侵入を防ぐ",
    "q.l3#7.o2" to "スパッツは雨のときだけ使う",
    "q.l3#7.o3" to "短いほど軽くてよい",
    "q.l3#7.e" to "スパッツは筒状の布をブーツの外に巻き、雪や異物の侵入を防ぐ道具です。高所は積雪が深いので、ショートではすぐ埋もれて役に立たなくなります。ロングが適します。ショートは整備されたトレッキングルートや、アルプス式の薄い積雪に向きます。",

    "q.l3#8.p" to "キャンプシューズやサンダルの主な役割と条件はどれですか。",
    "q.l3#8.o0" to "登頂用で、硬くなければならない",
    "q.l3#8.o1" to "キャンプ内での行動用で、保温・防水・滑り止めが条件",
    "q.l3#8.o2" to "テクニカルな登攀用で、前爪が必要",
    "q.l3#8.o3" to "飾りなので、持たなくてもよい",
    "q.l3#8.e" to "これは「メインブーツを休ませる」ための装備です。テントに入ったらキャンプシューズやサンダルに履き替えることで、高山靴のインナーが乾き、足が長時間圧迫されるのを避けられます。技術的な機能は持ちませんが、翌日の足の状態に直結します。",

    "q.l3#9.p" to "長距離の遠征で「丈の長いソックス」を選ぶ意味はどれですか。",
    "q.l3#9.o0" to "専門的に見えるから",
    "q.l3#9.o1" to "保温しながら足の血流を助けるから",
    "q.l3#9.o2" to "着脱がしやすいから",
    "q.l3#9.o3" to "クッションが厚くなるから",
    "q.l3#9.e" to "長く歩くと足はむくみ、血流が悪くなります。丈の長いソックスはふくらはぎまで覆い、保温しつつ均一な圧力で静脈還流を助けます。何日も続く行程では、三日目に足がもたないかどうかに直結します。",

    // ---------- l4 雪面の歩行技術（8 問） ----------
    "q.l4#0.p" to "キックステップ（蹴り込み）で正しいのはどれですか。",
    "q.l4#0.o0" to "大步でまたぎ、歩数を減らす",
    "q.l4#0.o1" to "小刻みで均一なリズムでステップを蹴り、重心を安定させる",
    "q.l4#0.o2" to "つま先だけで地面を突く",
    "q.l4#0.o3" to "終始かかとで雪面を叩く",
    "q.l4#0.e" to "小刻みで均一なリズムは重心を安定させ、エネルギーの無駄を減らします。大步でまたぐと重心が大きく振られ、雪面では最もバランスを崩しやすい歩き方になります。",

    "q.l4#1.p" to "歩行中、ピッケルはどちらの手に持ちますか。",
    "q.l4#1.o0" to "下り側の手",
    "q.l4#1.o1" to "上り側の手。いつでも制動に移れるように",
    "q.l4#1.o2" to "どちらの手でも持たない",
    "q.l4#1.o3" to "ザックの外側に掛けておく",
    "q.l4#1.e" to "上り側の手でピッケルを持ちます（杖のように突く piolet canne）。ピックは後ろ、ヘッドは前です。バランスを崩したら、持ち替えずにそのまま体重をかけてセルフアレストに移れます。持ち替える数秒が、そのまま事故の窓になるからです。",

    "q.l4#2.p" to "登りで高地の息苦しさをやわらげる技術はどれですか。",
    "q.l4#2.o0" to "息を止めて進む",
    "q.l4#2.o1" to "プレッシャーブリージング：深く吸い、強く吐く。歩調と合わせる",
    "q.l4#2.o2" to "速く浅い呼吸をする",
    "q.l4#2.o3" to "手袋を口にくわえて呼吸する",
    "q.l4#2.e" to "プレッシャーブリージングは意識的に強く吐くことで肺内の陽圧を高め、ガス交換の効率を上げます。歩調と合わせると（たとえば二〜三步に一回の呼吸）、高所の息苦しさがはっきり軽くなります。",

    "q.l4#3.p" to "隊列で雪面を登るとき、ステップの蹴り方として正しいのはどれですか。",
    "q.l4#3.o0" to "各自が自分の一列を蹴る",
    "q.l4#3.o1" to "先頭が均一なリズムでステップを蹴り、後続は同じステップを踏む",
    "q.l4#3.o2" to "誰がどこを蹴ってもよい",
    "q.l4#3.o3" to "できるだけ深く大きく蹴る",
    "q.l4#3.e" to "ステップを統一すると後続の体力消耗が大きく減り、隊列全体が同じルートと同じリズムを保てます。平らで間隔の揃ったステップを蹴ること自体が、チームの効率と安全を表しています。",

    "q.l4#4.p" to "高所歩行におけるペース配分の核心はどれですか。",
    "q.l4#4.o0" to "できるだけ速く。早く着けば早く休める",
    "q.l4#4.o1" to "持続可能な一定のペースを保ち、急な力みを避ける",
    "q.l4#4.o2" to "速くしたり遅くしたりして体力を温存する",
    "q.l4#4.o3" to "自分のペースは考えず、仲間の速度だけ見る",
    "q.l4#4.e" to "高所では酸素供給が制限されるため、急な力みを繰り返すと乳酸が急速に溜まり低酸素が悪化します。一定のペースとプレッシャーブリージングを組み合わせれば、より遠くまで歩け、誰かのダッシュで隊列が崩れることも防げます。",

    "q.l4#5.p" to "雪面での隊列のペースは誰が決めるべきですか。",
    "q.l4#5.o0" to "隊で最も体力のある人",
    "q.l4#5.o1" to "最も遅い隊員に合わせ、全員がまとまって進む",
    "q.l4#5.o2" to "リーダーが計画時刻どおりに厳格に決める",
    "q.l4#5.o3" to "各自が自分のペースで歩く",
    "q.l4#5.e" to "雪面で距離が開くと、後方の隊員は保護も支援も失います。またペースが速すぎると、体力の劣る人が危険地形に着く前に使い果たしてしまいます。最も遅い人に合わせることが、隊全体に安全余裕を残すことになります。",

    "q.l4#6.p" to "ある程度の傾斜がある氷の斜面を通過するとき、教本が勧める方法はどれですか。",
    "q.l4#6.o0" to "いつもどおりロープで結んで進む",
    "q.l4#6.o1" to "固定ロープか交互確保のシステムを設ける。通常はロープで結んで進まない",
    "q.l4#6.o2" to "速度を上げて一気に通過する",
    "q.l4#6.o3" to "摩擦を増やすためアイゼンを外す",
    "q.l4#6.e" to "氷面での制動は雪面より成功率が大きく下がり、氷の斜面でロープを結ぶと逆に隊ごと引きずり落とされかねません。傾斜のある氷面では、固定ロープか交互確保でシステムとして守るのが正解です。個人の制動能力に頼るべきではありません。",

    "q.l4#7.p" to "雪面をジグザグ（之字形）に登る最大の利点はどれですか。",
    "q.l4#7.o0" to "距離が短くなる",
    "q.l4#7.o1" to "一区間あたりの実質的な傾斜が下がり、体力消耗が減る",
    "q.l4#7.o2" to "眺めがよい",
    "q.l4#7.o3" to "ピッケルを使わずに済む",
    "q.l4#7.e" to "ジグザグは急斜面をいくつもの緩い区間に分け、ふくらはぎと足首の負担を大きく下げます。フレンチ（平爪）テクニックとも相性がよい方法です。代償は距離が延びることで、時間の見積もりを調整する必要があります。引き返し時刻に余裕を残す理由の一つでもあります。",

    // ---------- l5 アイゼンの歩行技術（10 問） ----------
    "q.l5#0.p" to "フレンチテクニック（平爪）の要点はどれですか。",
    "q.l5#0.o0" to "前爪だけで氷面を突く",
    "q.l5#0.o1" to "アイゼンの底の爪をすべて面に当て、足裏を平らに置く",
    "q.l5#0.o2" to "片足で跳ねながら進む",
    "q.l5#0.o3" to "ブーツの側面を氷に食い込ませる",
    "q.l5#0.e" to "フレンチの鍵は「平ら」であることです。底の 12 本の爪をすべて面に当てれば、荷重が太ももと全身に分散し、最も省エネになります。だからこそ、緩い雪面を長時間移動するのに向いています。",

    "q.l5#1.p" to "前爪（ジャーマン）テクニックが最も体力を消耗するのはなぜですか。",
    "q.l5#1.o0" to "腕の力で引き上げるから",
    "q.l5#1.o1" to "荷重が前爪に集中し、ふくらはぎが使い続けられるから",
    "q.l5#1.o2" to "息を止めていなければならないから",
    "q.l5#1.o3" to "摩擦力が大きいから",
    "q.l5#1.e" to "前爪テクニックは体重を二〜三本の前爪に預けるため、ふくらはぎが等尺性収縮を続けて姿勢を保たなければなりません。極端に消耗し、長時間は維持できません。だから急斜面でしか使わないのです。",

    "q.l5#2.p" to "雪面をトラバースするときはどんな歩法を使いますか。",
    "q.l5#2.o0" to "前爪テクニックで、前爪を垂直に蹴り込む",
    "q.l5#2.o1" to "ダックステップ：かかとを寄せ、つま先を外に向け、アイゼン全体を面に当てる",
    "q.l5#2.o2" to "横向きに跳ねて進む",
    "q.l5#2.o3" to "膝をついて這う",
    "q.l5#2.e" to "ダックステップなら、横方向の前爪と底の爪が同時に面を捉え、体重が内側の数本の爪だけに集中して滑るのを防げます。トラバースでは重心をやや斜面側に傾けます。",

    "q.l5#3.p" to "フレンチテクニック（平爪）が最も適する地形はどれですか。",
    "q.l5#3.o0" to "垂直な氷壁",
    "q.l5#3.o1" to "低〜中角度の硬い雪面。長時間の行進に向く",
    "q.l5#3.o2" to "オーバーハングしたルーフ",
    "q.l5#3.o3" to "平地でしか使えない",
    "q.l5#3.e" to "フレンチは荷重を全身と太ももに分散するため最も省エネで、低〜中角度の雪面を長時間歩く主力技術です。急な地形では前爪テクニックが必要になりますが、そちらは長時間維持できません。",

    "q.l5#4.p" to "急斜面で前爪（ジャーマン）テクニックを長時間使うと、どうなりますか。",
    "q.l5#4.o0" to "歩くほど楽になる",
    "q.l5#4.o1" to "ふくらはぎが急速に疲労し、やがて姿勢を保てなくなる",
    "q.l5#4.o2" to "アイゼンが自然に外れる",
    "q.l5#4.o3" to "何の影響もない",
    "q.l5#4.e" to "前爪テクニックは体重を二〜三本の前爪に集中させるため、ふくらはぎが等尺性収縮を続け、非常に疲れやすくなります。短い急斜面にしか向かない理由であり、ルート計画で体力の予算に入れておくべき理由でもあります。",

    "q.l5#5.p" to "アメリカンテクニック（ミックス）では、両足をどう使いますか。",
    "q.l5#5.o0" to "両足とも面に平らに当てる",
    "q.l5#5.o1" to "両足とも前爪を使う",
    "q.l5#5.o2" to "片足は平らに当てて支え、もう片足は前爪で推進する。これを交互に",
    "q.l5#5.o3" to "片足だけで力を出し、もう片足は休ませる",
    "q.l5#5.e" to "アメリカンはフレンチとジャーマンの間をつなぐ技術です。平らに当てた足が安定と短い休息を与え、前爪の足が推進力を生みます。中〜やや急の斜面で、純粋な前爪テクニックのようにふくらはぎを急速に使い切らずに効率を保てます。",

    "q.l5#6.p" to "【組み合わせ】アイゼンのグレードと、組み合わせるべきブーツを対応させてください。",
    "q.l5#6.l0" to "C1 フルストラップ式",
    "q.l5#6.l1" to "C2 前ストラップ・後ろクリップ式",
    "q.l5#6.l2" to "C3 フルクリップ式",
    "q.l5#6.r0" to "B1 ソフトソールブーツ",
    "q.l5#6.r1" to "B2 セミハードブーツ",
    "q.l5#6.r2" to "B3 フルハードブーツ",
    "q.l5#6.e" to "ブーツとアイゼンは必ず対応させます。ソフトソールに C1、セミハードに C2、フルハードに C3。フルクリップ式をソフトソールに付けるとブーツが変形してクリップが噛み合わず、急斜面で外れることがあります。明確に危険な組み合わせです。",

    "q.l5#7.p" to "氷の斜面を歩く基本となる二つの技術はどれですか。",
    "q.l5#7.o0" to "平歩技術と側歩技術",
    "q.l5#7.o1" to "全爪技術（フレンチ）と前爪技術（ジャーマン）",
    "q.l5#7.o2" to "跳躍技術と滑降技術",
    "q.l5#7.o3" to "登り技術と下り技術",
    "q.l5#7.e" to "全爪技術は前爪以外のすべての爪を氷面に食い込ませ、前爪技術は前爪を垂直に蹴り込みます。複雑な地形では両者を混ぜて使うことが多く、だからこそミックスの話をする前に、この二つを確実に身につける必要があります。",

    "q.l5#8.p" to "全爪（フレンチ）テクニックで、主に荷重を受ける部位はどこですか。",
    "q.l5#8.o0" to "ふくらはぎ",
    "q.l5#8.o1" to "太もも",
    "q.l5#8.o2" to "前腕",
    "q.l5#8.o3" to "腰と背中",
    "q.l5#8.e" to "足裏を平らに保つので、力は主に太ももと全身が担います。だから非常に省エネで長時間維持できます。前爪技術は逆で、二〜三本の前爪に荷重が集中し、ふくらはぎが使い続けられます。二つの技術では体力の収支がまったく違います。",

    "q.l5#9.p" to "全爪（フレンチ）テクニックが特に適する氷の斜面の角度はどれですか。",
    "q.l5#9.o0" to "0°〜30°",
    "q.l5#9.o1" to "30°〜50°",
    "q.l5#9.o2" to "50°〜70°",
    "q.l5#9.o3" to "70° 以上",
    "q.l5#9.e" to "教本は 0°〜30° という範囲を明確に示しています。これより急だと足裏を平らに保てず、前爪技術に切り替える必要があります。各技術の適用角度を覚えておくことは、いつ技術を替えるべきかを先読みすることでもあります。",

    // ---------- l6 セルフアレスト（10 問） ----------
    "q.l6#0.p" to "セルフアレストのとき、両足はどう置きますか。",
    "q.l6#0.o0" to "両足で雪面を強く蹴って止める",
    "q.l6#0.o1" to "雪面から上げ、つま先を上に向け、体重をすべてピッケルに預ける",
    "q.l6#0.o2" to "つま先を雪に刺して固定する",
    "q.l6#0.o3" to "両足をそろえて雪面に平らに置く",
    "q.l6#0.e" to "足が雪面に触れると、ピッケルに預けるはずの体重がそこへ逃げ、制動効率がすぐに落ちます。足首や膝を痛める原因にもなります。正解は両足を上げ、体重のすべてをピックを通して雪面に伝えることです。",

    "q.l6#1.p" to "滑落中、頭が下で足が上を向いています。最初にすべきことは何ですか。",
    "q.l6#1.o0" to "まずロープをつかもうとする",
    "q.l6#1.o1" to "すぐに体を反転させ、うつ伏せで足を下にした姿勢になり、それから制動に入る",
    "q.l6#1.o2" to "そのまま滑り続け、速度が落ちるのを待つ",
    "q.l6#1.o3" to "まずザックを捨てる",
    "q.l6#1.e" to "頭が下だとピックの角度が決まらず雪面に効きません。しかも頭から衝突する危険が極めて高い状態です。まず腹筋と体幹で反転してうつ伏せの制動姿勢をつくり、それからピックを押し込みます。",

    "q.l6#2.p" to "セルフアレストを学ぶ最も正しい方法はどれですか。",
    "q.l6#2.o0" to "解説動画を見れば十分",
    "q.l6#2.o1" to "教本を読んで要点を覚えればよい",
    "q.l6#2.o2" to "安全な柔らかい雪の斜面で、インストラクターの確保のもと、本能になるまで反復して実地練習する",
    "q.l6#2.o3" to "実際の急斜面で一度転べば覚える",
    "q.l6#2.e" to "セルフアレストは条件反射レベルの技能で、管理された環境で数百回繰り返して初めて安定した反応になります。斜面が緩く、下方が開け、雪質が柔らかく、インストラクターの確保がある場所で練習しなければなりません。",

    "q.l6#3.p" to "セルフアレストで最も効果的な力のかけ方はどれですか。",
    "q.l6#3.o0" to "腕で勢いよく押し下げる",
    "q.l6#3.o1" to "体重でピックを垂直に押し下げる",
    "q.l6#3.o2" to "シャフトを横向きに雪面へ打ち込む",
    "q.l6#3.o3" to "ピックを雪面で素早く払う",
    "q.l6#3.e" to "腕の力は疲労と恐慌の中で持続しません。体重で押し下げてこそ、ピックは深く食い込みます。だから姿勢（うつ伏せ、両足を上げる）が蛮力より重要なのです。",

    "q.l6#4.p" to "硬い雪や氷面では、セルフアレストの効果はどうなりますか。",
    "q.l6#4.o0" to "よりよく効き、押せばすぐ止まる",
    "q.l6#4.o1" to "制動距離が大幅に伸び、まったく効かないこともある",
    "q.l6#4.o2" to "柔らかい雪とまったく変わらない",
    "q.l6#4.o3" to "自動的に滑降になる",
    "q.l6#4.e" to "ピックは硬い雪や氷面では噛み合いません。だから無確保で硬い雪の急斜面に入ってはいけないのです。技術は回避の代わりにはならず、技術が効かなくなる境界を理解することも同じくらい重要です。",

    "q.l6#5.p" to "セルフアレストで、両手はどう分担しますか。",
    "q.l6#5.o0" to "両手でシャフトを握る",
    "q.l6#5.o1" to "両手でヘッドを押さえる",
    "q.l6#5.o2" to "片手でピック付近のヘッドを押さえて体重をかけ、もう片方でシャフトを握って方向と安定を保つ",
    "q.l6#5.o3" to "片手だけで操作し、もう片方は空けておく",
    "q.l6#5.e" to "ヘッドを押さえる手が体重をピックへ伝え、シャフトを握る手が安定と方向修正を担います。分担がはっきりしているからこそ、力が出て、しかもぶれずに止まれます。",

    "q.l6#6.p" to "【並べ替え】滑落制動の動作を正しい順番に並べてください。",
    "q.l6#6.o0" to "ピッケルを確実に握り、セルフアレストの握りでヘッドを体の下に当てる",
    "q.l6#6.o1" to "頭が上・足が下で、雪面に顔を向けたうつ伏せの姿勢になる",
    "q.l6#6.o2" to "体重でピックを雪と氷に押し込み、両脚を開いて膝を雪面に当てる",
    "q.l6#6.o3" to "両足を跳ね上げ、アイゼンが雪面に刺さって回転するのを防ぐ",
    "q.l6#6.e" to "順番で最も見落とされるのが最後の一文、両足を跳ね上げるです。足が雪面に触れるとピッケルに預けるべき体重が逃げ、しかもアイゼンが急に噛んで体が回転し、制動そのものが途切れてしまいます。",

    "q.l6#7.p" to "セルフアレストのとき、ピッケルのアッズ（横刃側）はどこに寄せますか。",
    "q.l6#7.o0" to "膝の外側",
    "q.l6#7.o1" to "肩のくぼみ",
    "q.l6#7.o2" to "腰",
    "q.l6#7.o3" to "頭の横の遠く",
    "q.l6#7.e" to "アッズを肩のくぼみに寄せると、シャフトが体の中心線の近くに来て荷重が胴体の真下に集中し、押し下げが最も効きます。位置が離れると荷重が分散し、ピックがぶれて制動距離が大幅に伸びます。",

    "q.l6#8.p" to "【複数選択】セルフアレストの成否を左右する主な要因はどれですか。",
    "q.l6#8.o0" to "雪・氷面の傾斜",
    "q.l6#8.o1" to "雪・氷面の硬さ",
    "q.l6#8.o2" to "滑落した人の姿勢",
    "q.l6#8.o3" to "反応速度",
    "q.l6#8.o4" to "装備のブランドと価格",
    "q.l6#8.e" to "教本は率直にこう述べています。反応速度だけでなく、制動の成否は傾斜・硬さ・姿勢にも左右され、最も熟練した動作でも止められないことがある、と。この限界を認めてこそ、滑落しないことのほうが制動を覚えるより重要だと分かります。",

    "q.l6#9.p" to "制動時の両脚と膝の正しい姿勢はどれですか。",
    "q.l6#9.o0" to "両脚をそろえ、膝を浮かせる",
    "q.l6#9.o1" to "両脚を開き、膝を雪・氷面に当てる",
    "q.l6#9.o2" to "片脚を伸ばし、もう片方を曲げる",
    "q.l6#9.o3" to "両脚を高く上げて雪面から離す",
    "q.l6#9.e" to "脚を開くと横向きの安定が生まれ、体が回転するのを防げます。膝を雪面に当てると追加の支点になり、重心をピッケルの上に保ちやすくなります。区別したいのは、膝は軽く触れてよく、両足（アイゼン）は上げるという点です。",

    // ---------- l7 滑落を防ぐ（10 問） ----------
    "q.l7#0.p" to "歩行中に滑落を防ぐ最も効果的な方法はどれですか。",
    "q.l7#0.o0" to "少し速く歩く",
    "q.l7#0.o1" to "ピッケルでセルフビレイを取り、一歩ごとに仮の支点をつくる",
    "q.l7#0.o2" to "ピッケルをザックにしまう",
    "q.l7#0.o3" to "ロープで守れば十分",
    "q.l7#0.e" to "セルフビレイは歩行中の最も直接的な防御線です。ピッケルを持つ手で歩調に合わせてシャフトを雪面に刺し、第三の支点をつくります。滑落のほとんどは、この支えが欠けた一瞬に起きます。",

    "q.l7#1.p" to "ロープで結んで歩行中、相棒が突然滑落しました。まず何をしますか。",
    "q.l7#1.o0" to "すぐに駆け下りて引き止める",
    "q.l7#1.o1" to "すぐに制動姿勢に入り、ロープを締めて相手を支える",
    "q.l7#1.o2" to "引きずられないよう先にロープを解く",
    "q.l7#1.o3" to "大声で助けを呼び、誰か来るのを待つ",
    "q.l7#1.e" to "ロープ隊の保護の原理は、まず自分が安定してこそロープが制動を伝えられるというものです。駆け下りたりロープを解いたりすれば、隊ごと滑り落ちます。氷河事故で最もよくある連鎖的な失敗です。",

    "q.l7#2.p" to "バランスを崩した瞬間、最初の動作はどれですか。",
    "q.l7#2.o0" to "まず装備を整える",
    "q.l7#2.o1" to "仲間に大声で警告し、同時にうつ伏せになって制動に入る",
    "q.l7#2.o2" to "まず傾斜を見積もる",
    "q.l7#2.o3" to "まず下に何があるか見る",
    "q.l7#2.e" to "滑落の最初の二秒で結末が決まります。仲間への警告は全員を保護状態に移すため、自分がすぐうつ伏せで制動に入るのは損切りの中核動作です。",

    "q.l7#3.p" to "ロープで結んで歩行するとき、ロープはどんな状態に保ちますか。",
    "q.l7#3.o0" to "緩いほどよく、動きやすいほうがよい",
    "q.l7#3.o1" to "適度に張り、大きな下垂をつくらない",
    "q.l7#3.o2" to "完全にピンと張る",
    "q.l7#3.o3" to "好きなようにしてよい",
    "q.l7#3.e" to "ロープが大きく垂れていると、落ちた人はしばらく自由落下してから荷重がかかり、衝撃が何倍にもなります。ロープが雪面を切る原因にもなります。適度に張っておけば、制動がより早く効きます。",

    "q.l7#4.p" to "「滑落しないこと」が「制動を覚えること」より根本的なのはなぜですか。",
    "q.l7#4.o0" to "制動技術は役に立たないから",
    "q.l7#4.o1" to "硬い雪や急斜面では制動が効かないことがあり、バランスを崩さないことが最も確実な防御だから",
    "q.l7#4.o2" to "制動は体力を使いすぎるから",
    "q.l7#4.o3" to "インストラクターが練習を許さないから",
    "q.l7#4.e" to "セルフアレストは必須の技能ですが、効かなくなる境界がはっきりしています。本当に確実な安全戦略は、滑落しうる地形に無確保で入らないことです。技能は最後の防御線であって、最初の防御線ではありません。",

    "q.l7#5.p" to "制動中、ピックが硬い雪面ではじかれて噛み合いません。どうしますか。",
    "q.l7#5.o0" to "手を上げて振り下ろし直す",
    "q.l7#5.o1" to "うつ伏せの姿勢を保ち、体重で押し続けてピックを少しずつ噛ませる",
    "q.l7#5.o2" to "シャフトで雪面を横に切る",
    "q.l7#5.o3" to "制動を諦め、頭の保護に切り替える",
    "q.l7#5.e" to "手を上げると制動がその瞬間に完全に失われ、築いた押し下げの姿勢も失います。正解はうつ伏せのまま押し続け、滑りながらピックを徐々に深く噛ませることです。制動は一回の動作ではなく、進行的な過程です。",

    "q.l7#6.p" to "「氷面での制動は非常に難しい」と言われるのはなぜですか。",
    "q.l7#6.o0" to "氷面が冷たすぎるから",
    "q.l7#6.o1" to "ピックが氷面に噛み込みにくいため、氷の斜面では制動に頼らず固定ロープを設けるべきだから",
    "q.l7#6.o2" to "氷面の摩擦力が大きすぎるから",
    "q.l7#6.o3" to "氷面は壊れやすいから",
    "q.l7#6.e" to "制動はピックが噛むことに依存しますが、氷面は最も噛みにくい相手です。教本の対策はシステム的です。傾斜のある氷面では固定ロープか交互確保を設け、通常はロープで結んで歩かない。個人の技術に望みを託すのではなく、システムで解決するのです。",

    "q.l7#7.p" to "【並べ替え】ロープで結んで歩行中に相棒が滑落しました。正しい対処の順序はどれですか。",
    "q.l7#7.o0" to "すぐ制動姿勢に入り、自分を安定させる",
    "q.l7#7.o1" to "ロープを締め、落ちた相手に制動をかける",
    "q.l7#7.o2" to "独立したビレイステーションをつくる（スノーバー、ピッケルの埋設など）",
    "q.l7#7.o3" to "荷重をステーションに移してから救助を行う",
    "q.l7#7.e" to "四つの順序は入れ替えられません。まず自分が安定してこそ次の動作ができます。ステーションをつくらずに救助すれば、二人分の体重があなたにのしかかります。実際にはこれを数分で終える必要があるため、事前の反復が欠かせません。",

    "q.l7#8.p" to "制動が決まり滑落が止まったら、次に何をしますか。",
    "q.l7#8.o0" to "すぐ立ち上がって歩き続ける",
    "q.l7#8.o1" to "制動を保ったまま段階的に保護をつくり、荷重をステーションへ移す",
    "q.l7#8.o2" to "まずロープを解く",
    "q.l7#8.o3" to "まず装備の破損を点検する",
    "q.l7#8.e" to "滑落が止まったことは安全を意味しません。まだ無保護の姿勢で、もう一度滑れば制動し直すのは困難です。制動を保ったまままず確実な保護をつくり、自分を「解放」してから、けがとルートに対処します。",

    "q.l7#9.p" to "【複数選択】滑落の予防として有効なのはどれですか。",
    "q.l7#9.o0" to "歩行中、ピッケルでセルフビレイを続ける",
    "q.l7#9.o1" to "硬い雪や氷の斜面に固定ロープを設ける",
    "q.l7#9.o2" to "持続可能な一定のペースを保ち、急な力みによるバランス崩れを避ける",
    "q.l7#9.o3" to "最も遅い人に合わせて歩き、隊列が開かないようにする",
    "q.l7#9.o4" to "歩行速度を上げて露出時間を短くする",
    "q.l7#9.e" to "この四つは、個人の技術、システムの保護、ペース管理、隊の連携という四つの層から滑落の確率を下げます。滑落予防は決して単一の動作ではなく、これらを同時に成立させることです。",

    // ---------- l8 下山と下降技術（10 問） ----------
    "q.l8#0.p" to "下山の局面で事故が多くなるのはなぜですか。",
    "q.l8#0.o0" to "下りの道のほうが歩きにくいから",
    "q.l8#0.o1" to "体力を消耗して注意力と動作の質が落ちるから",
    "q.l8#0.o2" to "下山時はいつも天候が悪いから",
    "q.l8#0.o3" to "装備が故障するから",
    "q.l8#0.e" to "登頂で目標を達成すると警戒心は自然に緩み、しかも体は限界に近づいています。登山事故の多くが下山中に起きる——「登頂は行程の半分にすぎない」という言葉の由来です。",

    "q.l8#1.p" to "コントロールされたグリセード（滑降）が許される条件はどれですか。",
    "q.l8#1.o0" to "傾斜が十分に急であればよい",
    "q.l8#1.o1" to "クレバスなし、落石の危険なし、下方が開けており、いつでもセルフアレストに移れる",
    "q.l8#1.o2" to "どんな雪面でもよい",
    "q.l8#1.o3" to "仲間が同意すればよい",
    "q.l8#1.e" to "滑降は不可逆な加速行為で、始まると止めるのは困難です。クレバス、落石、下方の人間を排除し、いつでも反転して制動できることを確認してください。それができなければ、素直に下降登攀（ダウングライミング）すべきです。",

    "q.l8#2.p" to "テクニカルな地形を下るときの第一選択はどれですか。",
    "q.l8#2.o0" to "壁に向かって下降し、三点支持を保つ",
    "q.l8#2.o1" to "壁に背を向けて速く走り下りる",
    "q.l8#2.o2" to "そのまま滑降する",
    "q.l8#2.o3" to "座って滑り下りる",
    "q.l8#2.e" to "壁に向かって下れば足元のスタンスが見え、重心が壁に近くて安定し、両手も支えに使えます。壁に背を向けて下ると足元が見えません。よくある誤りです。",

    "q.l8#3.p" to "下山でもっとも起きやすい危険な誤りはどれですか。",
    "q.l8#3.o0" to "壁に向かい、三点支持で下降する",
    "q.l8#3.o1" to "重心を前に傾け、壁に背を向けて下る",
    "q.l8#3.o2" to "安定したペースを保つ",
    "q.l8#3.o3" to "ピッケルでセルフビレイを取る",
    "q.l8#3.e" to "壁に背を向けて下ると足元が見えず、重心を前に傾けるとさらに不安定になります。疲労で脚のコントロールが落ちることも重なり、これが下山中の事故が多い本当の理由です。",

    "q.l8#4.p" to "滑降を始める前に必ず済ませておくことは何ですか。",
    "q.l8#4.o0" to "ピッケルをザックにしまう",
    "q.l8#4.o1" to "下方に人がいないこと、ルートにクレバスや落石がないことを確認し、ピッケルをすぐ制動できる状態に保つ",
    "q.l8#4.o2" to "ザックのショルダーを締める",
    "q.l8#4.o3" to "家族に行程を知らせる",
    "q.l8#4.e" to "滑降は不可逆な加速行為です。始める前に下方の人、クレバス、落石を排除し、ピッケルを構えたままにしておくこと。そうでなければ、不意の事態に減速する手段がまったくありません。",

    "q.l8#5.p" to "長い下山で、隊の疲労はどう管理しますか。",
    "q.l8#5.o0" to "一気に下まで歩き、休憩を減らす",
    "q.l8#5.o1" to "決まった間隔で短く止まり、水分とエネルギーを補給し、隊の状態を見直す",
    "q.l8#5.o2" to "速度を上げて露出時間を短くする",
    "q.l8#5.o3" to "けが人が出たときだけ止まる",
    "q.l8#5.e" to "下山は事故の多い局面で、疲労が主な引き金です。規則的で短い休憩はエネルギーを補うだけでなく、天候・ルート・仲間の状態を見直す機会になります。連続行軍では、この判断が最も抜け落ちやすいのです。",

    "q.l8#6.p" to "【並べ替え】下降前の準備を合理的な順序に並べてください。",
    "q.l8#6.o0" to "下降ルートと着地点を確認し、下方の人を排除する",
    "q.l8#6.o1" to "ロープ、ビレイ器、カラビナ、スリングが揃っているか確認する",
    "q.l8#6.o2" to "確実な支点を設ける（既存のステーションを確認するのでもよい）",
    "q.l8#6.o3" to "ロープを整理し、絡みや結び目を避けてから下降を始める",
    "q.l8#6.e" to "下降は「命を一点に預ける」操作なので、どこへ行くかを確かめ、装備を確かめ、それから依存先をつくります。ロープの整理も同じくらい重要です。絡んだり結び目があると下降できず、ロープ上に長時間ぶら下がることになります。",

    "q.l8#7.p" to "下降で懸垂下降とダウングライミングのどちらを選ぶかは、主に何で決めますか。",
    "q.l8#7.o0" to "下降距離が短いほど懸垂下降すべき",
    "q.l8#7.o1" to "地形の難しさ、使える支点、隊の力量",
    "q.l8#7.o2" to "天候",
    "q.l8#7.o3" to "装備の新旧",
    "q.l8#7.e" to "懸垂下降は速いが支点と操作に依存し、ダウングライミングは遅いが自律的です。テクニカルな地形か、支点は信頼できるか、隊は熟練しているか——この三つで決まります。なお懸垂下降は事故率が高く、操作ミスに対する余裕がほとんどありません。",

    "q.l8#8.p" to "懸垂下降で必要になる一般的な技術装備はどれですか。",
    "q.l8#8.o0" to "カラビナ 1 枚、スリング 1 本",
    "q.l8#8.o1" to "カラビナ数枚、ロングスリングかパーソナルアンカー、プルージック用の補助ロープなど",
    "q.l8#8.o2" to "ロープだけでよい",
    "q.l8#8.o3" to "ビレイ器だけでよい",
    "q.l8#8.e" to "教本が挙げる下降装備は、カラビナ複数、ロングスリングかパーソナルアンカー、プルージック用の補助ロープなどです。下降では支点を回収しながら下りることが多く、しかも予備を持つ必要があります。装備が足りないと高い場所で場当たり的な処理を強いられ、そこが事故の温床になります。",

    "q.l8#9.p" to "【複数選択】下降局面の主なリスクはどれですか。",
    "q.l8#9.o0" to "支点が外れる・破断する",
    "q.l8#9.o1" to "ロープの端に結び目がなく、ロープから抜けて墜落する",
    "q.l8#9.o2" to "ロープが絡まる、またはスタックする",
    "q.l8#9.o3" to "落石と下方の人間",
    "q.l8#9.o4" to "下りは楽なので、下降局面のリスクは上昇より全体として低い",
    "q.l8#9.e" to "この四つは下降事故のよくある原因です。とくに見落とされやすいのがロープ端の結び目です。ロープが足りないうえ端に結び目がないと、本人が気づかないうちに端から抜けてそのまま墜落します。疲労した下山局面で特に多い誤りです。",

    // ---------- l9 ロープワーク（10 問） ----------
    "q.l9#0.p" to "ロープをハーネスに結びつける結びで、氷河ルートで最もよく使われるものはどれですか。",
    "q.l9#0.o0" to "リトレースドエイト（通し結びのエイトノット）",
    "q.l9#0.o1" to "引き結び（平結び）",
    "q.l9#0.o2" to "オーバーハンドノット",
    "q.l9#0.o3" to "もやい結び",
    "q.l9#0.e" to "リトレースドエイトは強度が高く、構造が目で追いやすく、他人が確認しやすい結びです。荷重後も比較的ほどきやすい利点があります。引き結びは荷重で滑ったり固着したりするおそれがあり、確保用の連結には絶対に使えません。",

    "q.l9#1.p" to "片手で素早く長さを調整しながら、ロープをカラビナに固定したいときはどの結びですか。",
    "q.l9#1.o0" to "ダブルフィッシャーマンズ",
    "q.l9#1.o1" to "クローブヒッチ",
    "q.l9#1.o2" to "バタフライノット",
    "q.l9#1.o3" to "水結び",
    "q.l9#1.e" to "クローブヒッチはカラビナ上で片手で押し引きして長さを調整でき、ビレイステーションへのセルフアンカー（self-anchor）の標準的な方法です。ダブルフィッシャーマンズは二本のロープの連結、バタフライはロープ中間の支点に使います。",

    "q.l9#2.p" to "プルージックなどの摩擦結びの主な特性はどれですか。",
    "q.l9#2.o0" to "荷重がかかるとロープをつかみ、荷重が外れるとロープ沿いに動かせる",
    "q.l9#2.o1" to "メインロープを永久に置き換えられる",
    "q.l9#2.o2" to "飾りの結びにしか使えない",
    "q.l9#2.o3" to "荷重がかかると自然にほどける",
    "q.l9#2.e" to "一方向だけつかむ性質があるため、登攀、バックアップ、機械的有利システムに使えます。同時に、信頼できるかどうかはロープ径の組み合わせと巻き数に左右されます。だからこそ実地で試して確かめる必要があります。",

    "q.l9#3.p" to "結び終えたあと、末端はどのくらい残しますか。",
    "q.l9#3.o0" to "1 cm 程度でよい",
    "q.l9#3.o1" to "ロープ径の 10 倍以上",
    "q.l9#3.o2" to "末端は残さなくてよい",
    "q.l9#3.o3" to "長ければ長いほどよく、最低 1 m",
    "q.l9#3.e" to "十分な末端は、荷重や繰り返しの揺れで結びが滑り抜けるのを防ぐ基本です。あわせて、仲間と相互確認する習慣をつけたいところです。結びは保護システムの中で唯一、手作業で完結し、工場検査がない部分だからです。",

    "q.l9#4.p" to "二本のロープをつなぐ、またはプルージック用のループをつくる結びはどれですか。",
    "q.l9#4.o0" to "引き結び",
    "q.l9#4.o1" to "ダブルフィッシャーマンズ",
    "q.l9#4.o2" to "オーバーハンドノット",
    "q.l9#4.o3" to "もやい結び",
    "q.l9#4.e" to "ダブルフィッシャーマンズは非常に安定していてほどけにくい一方、荷重後はほどきにくいため、ロープの連結や閉じた補助ロープのループづくりに向きます。引き結びは荷重で滑ることがあり、荷重のかかる連結には絶対に使えません。",

    "q.l9#5.p" to "摩擦結びの信頼性がロープ径の組み合わせに左右されるのはなぜですか。",
    "q.l9#5.o0" to "ロープ径の組み合わせは関係がない",
    "q.l9#5.o1" to "補助ロープがメインロープに対して細すぎると接触と圧縮が足りず、つかめない",
    "q.l9#5.o2" to "補助ロープは細いほどよくつかめる",
    "q.l9#5.o3" to "補助ロープは太いほどよくつかめる",
    "q.l9#5.e" to "摩擦結びは、補助ロープがメインロープを締めつけることで把握力を作ります。細すぎれば接触面積も圧縮も足りず、太すぎれば密に巻けません。使う前に必ず組み合わせを確認し、安全な場所で実際に試してから頼るべきです。",

    "q.l9#6.p" to "バタフライノット（alpine butterfly）の主な用途はどれですか。",
    "q.l9#6.o0" to "二本のロープをつなぐ",
    "q.l9#6.o1" to "ロープ中間に、多方向に荷重を受けられる固定ループをつくる",
    "q.l9#6.o2" to "エイトノットの代わりにハーネスへ結ぶ",
    "q.l9#6.o3" to "プルージック用のループをつくる",
    "q.l9#6.e" to "バタフライノットはロープ中間にループをつくり、どちらの方向の荷重にも耐えられるため、ロープ隊、氷河行進、救助システムでよく使われます。ロープ区間の途中に結び目をつくり、雪面に沈み込む摩擦を増やすのにも使われます。",

    "q.l9#7.p" to "【組み合わせ】結びと主な用途を対応させてください。",
    "q.l9#7.l0" to "エイトノット",
    "q.l9#7.l1" to "ダブルフィッシャーマンズ",
    "q.l9#7.l2" to "プルージック",
    "q.l9#7.l3" to "もやい結び",
    "q.l9#7.r0" to "支点やハーネスへの連結で最もよく使う",
    "q.l9#7.r1" to "二本のロープをつなぐ、または閉じた補助ロープのループをつくる",
    "q.l9#7.r2" to "摩擦結び。荷重でつかみ、荷重が外れれば動かせる",
    "q.l9#7.r3" to "支点への連結。船を係留するときにもよく使う",
    "q.l9#7.e" to "この四つで、氷河行進と基礎的な確保のほとんどの場面をまかなえます。教本はこれらを「支点への連結」「ロープの連結」「摩擦結び」に分類しています。形で覚えるより、機能で覚えたほうがはるかに定着します。",

    "q.l9#8.p" to "結びとロープ強度の関係について、正しい認識はどれですか。",
    "q.l9#8.o0" to "結んでもロープの強度は変わらない",
    "q.l9#8.o1" to "どんな結びでもその部分の強度は下がり、下がり幅は結びによって違う",
    "q.l9#8.o2" to "結ぶとロープは強くなる",
    "q.l9#8.o3" to "上手に結べば強度に影響しない",
    "q.l9#8.e" to "ロープは結び目で屈曲し、荷重時に繊維への力のかかり方が不均一になるため、強度は必ず下がります。違うのは下がり幅だけです。教本が「結びによる強度変化の対照表」をわざわざ載せているのは、機能だけでなく強度の損失も見て選ぶ必要があるからです。",

    "q.l9#9.p" to "教本は結びの意味を一行でこうまとめています。「結びはロープに（ ）を与える」。",
    "q.l9#9.a0" to "命",
    "q.l9#9.a1" to "生命力",
    "q.l9#9.e" to "原文は「結びはロープに生命力を与える」。ロープそのものはただの一本の線にすぎず、結びによって保護具、支点、他のロープとつながって初めて、命を預けられるシステムになる——結びの本質を突いた言葉です。",

    // ---------- l10 氷河のロープ隊（10 問） ----------
    "q.l10#0.p" to "氷河でのロープ隊で最も理想的な人数はどれですか。",
    "q.l10#0.o0" to "2 人",
    "q.l10#0.o1" to "3 人",
    "q.l10#0.o2" to "6 人以上",
    "q.l10#0.o3" to "1 人で結ぶ",
    "q.l10#0.e" to "3 人のロープ隊なら、1 人がクレバスに落ちたときにビレイステーションを築き、救助システムを操作する人手が残ります。2 人隊では、落ちた瞬間に残る 1 人が制動とステーション構築と救助を同時に担うことになり、余裕がほとんどありません。",

    "q.l10#1.p" to "氷河でのロープ隊の一般的な間隔はどれですか。",
    "q.l10#1.o0" to "2〜3 m",
    "q.l10#1.o1" to "8〜12 m",
    "q.l10#1.o2" to "30 m 以上",
    "q.l10#1.o3" to "短ければ短いほどよい",
    "q.l10#1.e" to "8〜12 m なら、落ちたときに仲間が反応し制動する距離を確保でき、同時に会話と連携もしやすくなります。間隔が短すぎると、落下の衝撃をほとんど緩衝できません。",

    "q.l10#2.p" to "ロープ隊が本当に保護として機能する前提はどれですか。",
    "q.l10#2.o0" to "ロープで結べば自動的に安全になる",
    "q.l10#2.o1" to "仲間が効果的に制動し、保護をつくれること",
    "q.l10#2.o2" to "ロープが十分に長いこと",
    "q.l10#2.o3" to "人数が多いこと",
    "q.l10#2.e" to "ロープ隊の安全は「制動」と「固定」という二つの動作が確実に実行されることから生まれます。制動能力やステーション技術を欠いたロープ隊は、ただ互いを結んで一緒に落ちるだけです。",

    "q.l10#3.p" to "氷河行進でロープ区間の間に結び目（バタフライなど）を入れる効果はどれですか。",
    "q.l10#3.o0" to "純粋な飾り",
    "q.l10#3.o1" to "ロープが雪面に沈み込む摩擦を増し、落ちた人の下墜を抑える",
    "q.l10#3.o2" to "仲間を見分けやすくする",
    "q.l10#3.o3" to "ロープの重量を減らす",
    "q.l10#3.e" to "結び目は雪面上に余分な抵抗点をつくり、落下深度を目に見えて減らします。上の仲間が保護をつくる時間を稼ぐことにもなります。安価ですが効果の高いバッファです。",

    "q.l10#4.p" to "氷河行進中、救助器材はどこに置きますか。",
    "q.l10#4.o0" to "ザックの最も奥",
    "q.l10#4.o1" to "手が届く位置。いつでも取り出せるように",
    "q.l10#4.o2" to "キャンプのテントに残す",
    "q.l10#4.o3" to "仲間に預ける",
    "q.l10#4.e" to "クレバス救助の黄金の窓は数分しかありません。プルージックのループ、カラビナ、スノーバーがザックの底に埋まっていて、探し出したころには仲間が低体温になっていた、ロープが雪庇に切られていた——そういうことが起きます。",

    "q.l10#5.p" to "2 人隊が 3 人隊に比べて抱える最大のリスクはどれですか。",
    "q.l10#5.o0" to "行進速度が遅くなる",
    "q.l10#5.o1" to "1 人が落ちたとき、残る人手で制動と救助操作を両立しにくい",
    "q.l10#5.o2" to "ロープの長さが足りない",
    "q.l10#5.o3" to "装備を多く持ち歩く必要がある",
    "q.l10#5.e" to "2 人隊で 1 人がクレバスに落ちると、残る 1 人が制動を保ちながらステーションを築き、引き上げシステムを操作しなければならず、余裕はほぼありません。どうしても 2 人で結ぶなら、より保守的なルート選択と、より十分な事前の想定が必要です。",

    "q.l10#6.p" to "氷河行進中、むやみにロープを解くべきでないのはなぜですか。",
    "q.l10#6.o0" to "結び直すのが面倒だから",
    "q.l10#6.o1" to "クレバス帯のリスクは連続していて、解いた瞬間に保護を失うから",
    "q.l10#6.o2" to "ロープをなくしやすいから",
    "q.l10#6.o3" to "仲間に叱られるから",
    "q.l10#6.e" to "氷河のリスク分布は一様ではなく予測も難しいため、途中でロープを解くのは「この区間は大丈夫」という誤判断の下で行われがちです。本当に解く必要があるなら、まず行進を止め、地形と雪況を確認してから全員でまとめて行動します。",

    "q.l10#7.p" to "【組み合わせ】国際的に共通の登攀コールとその意味を対応させてください。",
    "q.l10#7.l0" to "On belay",
    "q.l10#7.l1" to "Climbing",
    "q.l10#7.l2" to "Falling",
    "q.l10#7.l3" to "Off belay",
    "q.l10#7.r0" to "確保できた、始めてよい",
    "q.l10#7.r1" to "登り始める",
    "q.l10#7.r2" to "落ちた（警告）",
    "q.l10#7.r3" to "確保を解く、確保終了",
    "q.l10#7.e" to "コールシステムの価値は「説明が要らない」ことにあります。高所は風が強く距離も離れるため、短く、双方が同じ意味で受け取れる言葉でなければ誤解を招きます。確保の場面で最も危険なのは「相手も分かっているはず」という思い込みです。教本が国際共通のコールをわざわざ挙げているのは、隊をまたぎ言語をまたぐ最低限の合意だからです。",

    "q.l10#8.p" to "確保者に必要な基本的な技術装備はどれですか。",
    "q.l10#8.o0" to "ハーネス 1、カラビナ 1、ビレイ器 1、手袋 1 組、ヘルメット 1",
    "q.l10#8.o1" to "ビレイ器とカラビナだけでよい",
    "q.l10#8.o2" to "ヘルメットとゴーグル",
    "q.l10#8.o3" to "ハーネスとロープ",
    "q.l10#8.e" to "この一覧は単純に見えますが、欠けた一つひとつが具体的な結果を招きます。手袋がなければ手を傷めてロープ操作に影響し、ヘルメットがなければ落石に対応できません。確保者は「他人を受け止める人」なので、自分の装備こそ先に整っていなければならないのです。",

    "q.l10#9.p" to "登攀を始める前に「相互チェック」を行うのはなぜですか。",
    "q.l10#9.o0" to "隊の規律として決められているから",
    "q.l10#9.o1" to "ハーネス、結び、ビレイ器の誤りは自分では見えにくいから",
    "q.l10#9.o2" to "進捗を記録するため",
    "q.l10#9.o3" to "準備運動のため",
    "q.l10#9.e" to "自分で自分を確認すると、どうしても「自分が結んだつもりの形」しか見えません。仲間なら背後から、横から、あなたの視界に入らない場所を見られます。教本が「登攀前の相互チェック」をコミュニケーションの最初の項目に置いているのは、他人の視点で自分の盲点を補う行為だからです。",

    // ---------- l11 ビレイステーションの原則（12 問） ----------
    "q.l11#0.p" to "SRENE 原則の R は何を表しますか。",
    "q.l11#0.o0" to "Rapid（速い）",
    "q.l11#0.o1" to "Redundant（冗長）",
    "q.l11#0.o2" to "Rope（ロープ）",
    "q.l11#0.o3" to "Rigid（剛い）",
    "q.l11#0.e" to "Redundant（冗長性）は、システムに互いに独立した支点を複数持ち、どれか一つが外れても残りで荷重を支えられることを求めます。ビレイステーションの安全性で最も核となる項目です。",

    "q.l11#1.p" to "「No Extension」という原則の意味はどれですか。",
    "q.l11#1.o0" to "ロープは長ければ長いほどよい",
    "q.l11#1.o1" to "ある支点が外れたとき、システムに衝撃的な伸びが出てはいけない",
    "q.l11#1.o2" to "ビレイステーションは低い場所につくってはいけない",
    "q.l11#1.o3" to "予備の器材は不要である",
    "q.l11#1.e" to "支点の間に緩みがあると、一つが外れた瞬間に残りへ急激な衝撃荷重がかかります（衝撃力は静的荷重よりはるかに大きい）。No Extension は、あらかじめ均等に張っておくことでこの衝撃を避けるという要求です。",

    "q.l11#2.p" to "ビレイステーション設計の最も核となる考え方はどれですか。",
    "q.l11#2.o0" to "器材をできるだけ節約する",
    "q.l11#2.o1" to "単一の支点が外れてもシステム全体が崩壊しない",
    "q.l11#2.o2" to "できるだけ高い位置につくる",
    "q.l11#2.o3" to "最も太いロープだけを使う",
    "q.l11#2.e" to "岩や雪の支点は絶対確実とは言えません。だからシステムの設計目標はフェイルセーフ、つまりどの単一の破断も致命的にならず、クライマーが反応しバックアップを取る時間を残すことになります。",

    "q.l11#3.p" to "EARNEST が SRENE に対して補った二つの軸はどれですか。",
    "q.l11#3.o0" to "Efficient（効率的）と Timely（迅速）",
    "q.l11#3.o1" to "Easy（簡単）と Tight（張った）",
    "q.l11#3.o2" to "Equal（等しい）と Nice（美しい）",
    "q.l11#3.o3" to "Empty（空）と True（真）",
    "q.l11#3.e" to "ビレイステーションは安全なだけでなく、素早く組めて操作が煩雑でないことも求められます。組み立てている時間そのものがリスクにさらされている時間だからです。ここが EARNEST のほうが実際の現場に近い点です。",

    "q.l11#4.p" to "雪上の支点の信頼性は主に何で決まりますか。",
    "q.l11#4.o0" to "器材のブランド",
    "q.l11#4.o1" to "雪質と埋設の質",
    "q.l11#4.o2" to "ロープの色",
    "q.l11#4.o3" to "標高",
    "q.l11#4.e" to "同じスノーバーやデッドマンでも、深い雪、湿った雪、スノーブリッジの縁では保持力が大きく違います。雪上の支点は、決まった手順を当てはめるのではなく、その場で雪層の構造を判断しなければなりません。",

    "q.l11#5.p" to "ビレイステーションで「荷重の均等化」が強調されるのはなぜですか。",
    "q.l11#5.o0" to "見た目を整えるため",
    "q.l11#5.o1" to "荷重を設計どおり各支点に分散し、一点への過負荷を避けるため",
    "q.l11#5.o2" to "器材を節約するため",
    "q.l11#5.o3" to "撤収しやすくするため",
    "q.l11#5.e" to "均等化とは、各支点が設計値に近い荷重を分担することであり、どれか一点に全部を負わせないことです。ある点が先に限界に達して外れると、荷重は残りへ突然移り、連鎖的な破断を招きやすくなります。",

    "q.l11#6.p" to "次のうち、ビレイステーションの「冗長性」に反するのはどれですか。",
    "q.l11#6.o0" to "強度の異なる器材を混ぜて使う",
    "q.l11#6.o1" to "二つの支点が実際には同じクラック、同じ岩体に依存している",
    "q.l11#6.o2" to "支点どうしをスリングでつなぐ",
    "q.l11#6.o3" to "支点を三つ設ける",
    "q.l11#6.e" to "冗長性は各支点が独立して破断することを求めます。二点が同じクラックを共有していれば、そのクラックが割れたとき二点が同時に外れます。形は「二点」でも、実質は一点です。非常によくある、しかも致命的な偽の冗長性です。",

    "q.l11#7.p" to "【組み合わせ】ビレイステーション評価の略語と意味を対応させてください。",
    "q.l11#7.l0" to "S（Solid）",
    "q.l11#7.l1" to "R（Redundant）",
    "q.l11#7.l2" to "E（Equalized）",
    "q.l11#7.l3" to "No Extension",
    "q.l11#7.r0" to "堅固：各支点の強度が想定荷重に耐える",
    "q.l11#7.r1" to "冗長：互いに独立した複数の支点がある",
    "q.l11#7.r2" to "均等：荷重が各支点に合理的に配分されている",
    "q.l11#7.r3" to "非伸長：支点が外れても衝撃的な伸びが出ない",
    "q.l11#7.e" to "この四つがビレイステーション評価の基本枠組みで、略して SRENE です。覚えておきたいのは順番です。まず単点が堅固かを見て、次にシステムに冗長性があるかを見る。単点が信頼できなければ、冗長性を論じる意味はありません。",

    "q.l11#8.p" to "荷重のデータから見て、スリングの角度はどの範囲に収めるべきですか。",
    "q.l11#8.o0" to "60° 以内",
    "q.l11#8.o1" to "90° 以内",
    "q.l11#8.o2" to "120° 以内",
    "q.l11#8.o3" to "角度は荷重に影響しない",
    "q.l11#8.e" to "角度 0° なら各点およそ 50%、60° で約 58%、90° で約 71%。角度が開くほど、同じ体重が各点により大きな荷重をかけます。「60° 以内に収める」という経験則は、この数値から来ています。",

    "q.l11#9.p" to "ビレイステーションの「効率」と「迅速さ」も評価に入るのはなぜですか。",
    "q.l11#9.o0" to "操作を見栄えよくするため",
    "q.l11#9.o1" to "ステーションを組む時間そのものがリスクにさらされている時間だから",
    "q.l11#9.o2" to "器材を節約するため",
    "q.l11#9.o3" to "教えるときに便利だから",
    "q.l11#9.e" to "ステーションを組んでいるとき、あなたはしばしば無確保か不十分な確保の状態にあります。この露出時間が短いほどリスクは下がります。だから「速く組めて操作が煩雑でない」は手抜きではなく、安全指標の一部なのです。",

    "q.l11#10.p" to "【複数選択】合格したビレイステーションが備えるべき特徴はどれですか。",
    "q.l11#10.o0" to "各支点そのものが堅固である",
    "q.l11#10.o1" to "各支点が互いに独立して破断する",
    "q.l11#10.o2" to "荷重が各支点に合理的に配分されている",
    "q.l11#10.o3" to "衝撃を吸収するため、システムに伸び代を残す",
    "q.l11#10.e" to "前三つは要求です。最後はちょうど逆で、ステーションは「伸びない」ことが求められます。伸び代を残すと、ある点が外れたときに残りへ衝撃荷重がかかり、衝撃力は静的荷重をはるかに超えます。",

    "q.l11#11.p" to "現場の条件で単一の支点しか使えないとき、正しいのはどれですか。",
    "q.l11#11.o0" to "登攀を諦め、来た道を戻る",
    "q.l11#11.o1" to "できる限り信頼できるものに仕上げ、その支点に依存する時間を最小にする",
    "q.l11#11.o2" to "とりあえずもう一点足して二点に見せる",
    "q.l11#11.o3" to "ロープを直接ハーネスに結ぶ",
    "q.l11#11.e" to "現実には単点しか取れない場面もあります（信頼できるアイススクリューが一本だけ、など）。そのときの態度は「これには冗長性がない」と認めることです。だからこそ支点を最善に仕上げ、人をできるだけ早く通過させます。無効な点を一つ足して偽の安心感をつくるべきではありません。",

    // ---------- l12 クレバス救助（12 問） ----------
    "q.l12#0.p" to "相棒がクレバスに落ちました。まず何をしますか。",
    "q.l12#0.o0" to "すぐ飛び込んで助ける",
    "q.l12#0.o1" to "すぐセルフアレストし、ビレイステーションを築いて荷重を移す",
    "q.l12#0.o2" to "まず電話で助けを呼ぶ",
    "q.l12#0.o3" to "まずロープを切る",
    "q.l12#0.e" to "落ちた人の体重が今すべてあなたにかかっています。まずセルフアレストで自分を安定させ、独立したステーションを築いて荷重を移し、それから救助システムを操作する余力をつくります。飛び込むのもロープを切るのも、状況を即座に悪化させます。",

    "q.l12#1.p" to "救助の引き上げで最もよく使われる機械的有利システムはどれですか。",
    "q.l12#1.o0" to "1:1 の直接引き",
    "q.l12#1.o1" to "3:1 の Z システム（Z ドラッグ）",
    "q.l12#1.o2" to "10:1 システム",
    "q.l12#1.o3" to "機械的有利は不要",
    "q.l12#1.e" to "3:1 の Z システムは、プルージックとプーリー一つで 3 倍の機械的有利が得られます。構造が単純で素早く組め、必要な器材も少ないため、氷河救助の標準的な選択です。",

    "q.l12#2.p" to "スノーブリッジが特に危険なのはなぜですか。",
    "q.l12#2.o0" to "いつも音を立てるから",
    "q.l12#2.o1" to "新雪に覆われると普通の雪面と見分けがつかないから",
    "q.l12#2.o2" to "夜にしか現れないから",
    "q.l12#2.o3" to "必ず薄いから",
    "q.l12#2.e" to "スノーブリッジは最も見えにくい氷河のリスクです。表面は平らで厚そうに見えても、下は空洞です。信頼できるかどうかは、クレバスの走向、雪層の構造、季節条件から判断するしかなく、だからこそロープで結ぶ必要があります。",

    "q.l12#3.p" to "クレバス帯を通過するとき、ロープはどんな状態にしますか。",
    "q.l12#3.o0" to "動きやすいよう大きく垂らす",
    "q.l12#3.o1" to "適度に張り、大きな下垂をつくらない",
    "q.l12#3.o2" to "張れば張るほどよい",
    "q.l12#3.o3" to "ロープで結ぶ必要はない",
    "q.l12#3.e" to "ロープが垂れていると、落ちた人はまず自由落下し、そのあと急に荷重がかかって衝撃が何倍にもなります。適度に張っておけば制動が早く効き、ロープがクレバス縁の雪庇を切る危険も減ります。",

    "q.l12#4.p" to "スノーブリッジを通過する最も確実な方法はどれですか。",
    "q.l12#4.o0" to "1 人で素早く走り抜ける",
    "q.l12#4.o1" to "ロープで結んで進み、ロープを張り気味に保ち、1 人が渡るとき残りは制動できる姿勢を取る",
    "q.l12#4.o2" to "すべてのスノーブリッジを迂回する",
    "q.l12#4.o3" to "強く踏みつけて試してから渡る",
    "q.l12#4.e" to "スノーブリッジの信頼性は見た目では判断できません。ロープで結び、いつでも制動できる状態にしておくことが、「不確実」を「管理できるリスク」に変える方法です。強く踏みつけると、むしろその場で崩落させてしまいます。",

    "q.l12#5.p" to "隊員がロープでクレバスに吊り下がっているとき、最も警戒すべきことは何ですか。",
    "q.l12#5.o0" to "隊員がクレバスの中で眠ってしまう",
    "q.l12#5.o1" to "荷重のかかったロープがクレバス縁の雪庇を削り続け、突然切れることがある",
    "q.l12#5.o2" to "装備が体から落ちる",
    "q.l12#5.o3" to "天候が急変する",
    "q.l12#5.e" to "荷重のかかったロープは雪庇を繰り返し削り、溝をどんどん深くします。これが救助の時間的圧力の主な源です。雪庇を切り抜かれる前に引き上げを終えるか、先に荷重を確実なステーションへ移さなければなりません。",

    "q.l12#6.p" to "プルージックで Z システムを組むとき、なぜバックアップが必須ですか。",
    "q.l12#6.o0" to "システムを完全に見せるため",
    "q.l12#6.o1" to "メインのプルージックが効かなくなると機械的有利が一瞬で失われ、落ちた人が再び落下するから",
    "q.l12#6.o2" to "摩擦力を増やすため",
    "q.l12#6.o3" to "ロープを節約するため",
    "q.l12#6.e" to "プルージックの把握は摩擦に依存するため、凍結、泥汚れ、ロープの摩耗で効かなくなることがあります。バックアップがあれば、メインが失われた瞬間に荷重を受け止め、二次落下による追加のけがと時間損失を避けられます。",

    "q.l12#7.p" to "【並べ替え】クレバス救助の標準手順を順番に並べてください。",
    "q.l12#7.o0" to "すぐセルフアレストし、自分を安定させる",
    "q.l12#7.o1" to "独立したビレイステーションを築く",
    "q.l12#7.o2" to "荷重を体からステーションへ移す",
    "q.l12#7.o3" to "3:1 の機械的有利システムで引き上げる",
    "q.l12#7.e" to "四つの順序は入れ替えられません。とくに飛ばされやすいのが三番目です。荷重を移さないままだと、体で相棒を支え続けなければならず、システムを操作する手がまったく空きません。救助が失敗する最もよくある原因です。",

    "q.l12#8.p" to "クレバスに落ちた本人は何をすべきですか。",
    "q.l12#8.o0" to "ロープを大きく揺らして注意を引く",
    "q.l12#8.o1" to "落ち着き、プルージックで自己登攀を試み、ロープがクレバス縁の雪庇を削り続けるのを避ける",
    "q.l12#8.o2" to "すぐロープを解く",
    "q.l12#8.o3" to "下へ這って出口を探す",
    "q.l12#8.e" to "落ちた本人の協力は救助の難易度を大きく下げます。ロープを揺らすと雪庇の切削が進み、解けば接続そのものを失います。正解は自分を安定させ、ロープの切削を減らし、可能ならプルージックで体重の一部を分担することです。",

    "q.l12#9.p" to "【複数選択】氷河のロープ隊で携行し、手が届く位置に置くべき救助器材はどれですか。",
    "q.l12#9.o0" to "プルージック用の補助ロープ（スリング）",
    "q.l12#9.o1" to "カラビナとプーリー",
    "q.l12#9.o2" to "スノーバーまたはアイススクリュー",
    "q.l12#9.o3" to "スリング",
    "q.l12#9.o4" to "トレッキングポール",
    "q.l12#9.e" to "この四つで応変システムが組み上がります。プルージックが一方向の把握を、カラビナとプーリーが機械的有利を、スノーバー／アイススクリューがステーションを、スリングが連結と延長を担います。鍵は「手が届く」ことです。ザックの底に埋まった器材は、無いのと同じです。",

    "q.l12#10.p" to "引き上げを始める前に、必ず荷重をステーションへ移さなければならないのはなぜですか。",
    "q.l12#10.o0" to "ロープの荷重を均一にするため",
    "q.l12#10.o1" to "移さなければ両手が制動の維持に取られ、システムを操作できないから",
    "q.l12#10.o2" to "体力を節約するため",
    "q.l12#10.o3" to "ロープを保護するため",
    "q.l12#10.e" to "落ちた人の体重がすべて自分にかかっている間は、制動を維持するために力を出し続けなければならず、手も空かず操作も安定しません。荷重をステーションに預けることが、「人体アンカー」から「オペレーター」になる唯一の方法です。",

    "q.l12#11.p" to "救助システムにおけるプルージックの役割はどれですか。",
    "q.l12#11.o0" to "見た目の飾り",
    "q.l12#11.o1" to "一方向の把握。荷重でロープをつかみ、荷重が外れれば沿って動かせる",
    "q.l12#11.o2" to "ロープの強度を上げる",
    "q.l12#11.o3" to "防水",
    "q.l12#11.e" to "「一方向の把握」という性質があるからこそ、機械的有利システムが成立します。プルージックはロープ沿いに進めるのに、荷重がかかると後退しません。信頼性はロープ径の組み合わせと巻き数に左右されるため、事前に検証してから頼る必要があります。",

    // ---------- l13 急性高山病（AMS）の識別 ----------
    "q.l13#0.p" to "Lake Louise 基準で、AMS と診断するために必ず含まれる症状はどれですか。",
    "q.l13#0.o0" to "頭痛があり、さらに悪心・めまい・疲労感・不眠のうち少なくとも一つを伴う",
    "q.l13#0.o1" to "咳だけがある",
    "q.l13#0.o2" to "脚の筋肉痛だけがある",
    "q.l13#0.o3" to "食欲がむしろ良くなる",
    "q.l13#0.e" to "頭痛は AMS の中核症状です。単なる疲労感や不眠だけでは診断できず、頭痛との組み合わせが必要です。この基準の実用的な価値は、キャンプで素早く自己評価し、判断を下せるところにあります。",

    "q.l13#1.p" to "AMS の症状が出たとき、正しい対処はどれですか。",
    "q.l13#1.o0" to "痛み止めを飲んで計画どおり登り続ける",
    "q.l13#1.o1" to "登るのをやめる。悪化するなら直ちに下降する",
    "q.l13#1.o2" to "コーヒーを多く飲んで気力を出し、歩き続ける",
    "q.l13#1.o3" to "症状を無視して我慢すれば治る",
    "q.l13#1.e" to "AMS は致死的な HACE や HAPE に進展することがあります。登るのをやめれば体に適応の時間ができ、悪化したら下降が唯一の確実な治療です。「我慢すれば治る」という考えは命を賭けることになります。",

    "q.l13#2.p" to "痛み止めで頭痛が消えました。このまま登り続けてよいですか。",
    "q.l13#2.o0" to "よい。症状はもう消えた",
    "q.l13#2.o1" to "よくない。症状が隠れただけで、体が適応したわけではない",
    "q.l13#2.o2" to "よいが、ゆっくり歩くこと",
    "q.l13#2.o3" to "水を多く飲めばよい",
    "q.l13#2.e" to "痛み止めは信号を抑えるだけで、標高による生理的ストレスは続いています。薬に隠れて登り続けると、AMS が前触れなく HACE や HAPE へ進展することがあります。",

    "q.l13#3.p" to "AMS の症状は通常、高所に到着してからどれくらいで出始めますか。",
    "q.l13#3.o0" to "すぐに出る",
    "q.l13#3.o1" to "6〜12 時間",
    "q.l13#3.o2" to "3 日以後",
    "q.l13#3.o3" to "1 週間以後",
    "q.l13#3.e" to "このタイミングが重要です。キャンプに着き、夕食を済ませ、これから寝るという時間帯に出始めることが多く、夜は最も見落とされやすく、最も悪化しやすい時間帯だからです。",

    "q.l13#4.p" to "軽度 AMS の現場での対処として正しいのはどれですか。",
    "q.l13#4.o0" to "計画どおり登り続ける",
    "q.l13#4.o1" to "登るのをやめ、その標高で休む。引かなければ、または悪化すれば下山する",
    "q.l13#4.o2" to "痛み止めを飲んで登り続ける",
    "q.l13#4.o3" to "すぐ 2,000 m 下降する",
    "q.l13#4.e" to "軽度 AMS の第一選択は、登るのをやめて適応の時間を与えることです。痛み止めは頭痛をやわらげますが適応の過程は変わりません。休息後も症状が続くか悪化するなら、下降が確実な治療になります。",

    "q.l13#5.p" to "「高く登って低く寝る」が適応の効率を高めるのはなぜですか。",
    "q.l13#5.o0" to "日中のほうが暖かいから",
    "q.l13#5.o1" to "日中の低酸素曝露が適応の刺激になり、夜は低い標高に戻ることで睡眠の質を確保できるから",
    "q.l13#5.o2" to "装備を少なく運べるから",
    "q.l13#5.o3" to "夜間の行進のほうが安全だから",
    "q.l13#5.e" to "適応は低酸素の刺激に依存しますが、睡眠の質もまた適応の必要条件です。夜間に強い低酸素にさらされると、周期性呼吸と症状が悪化します。高く登って低く寝る方法はこの二つを両立させるため、高い場所に居続けるより効率がよいのです。",

    "q.l13#6.p" to "AMS が出ているのに登り続けた場合、最悪どうなりますか。",
    "q.l13#6.o0" to "少し疲れるだけ",
    "q.l13#6.o1" to "HACE や HAPE に進展し、数時間で命に関わることがある",
    "q.l13#6.o2" to "食欲が落ちる",
    "q.l13#6.o3" to "睡眠の質が下がる",
    "q.l13#6.e" to "AMS 自体はふつう休息や下降で改善しますが、重症の前駆状態になりえます。「症状が出たら登らない」が繰り返し強調されるのは、悪化の連鎖の起点をそこで断つからです。",

    "q.l13#7.p" to "AMS が悪化しているかどうかは、何に注目して判断しますか。",
    "q.l13#7.o0" to "頭痛が消えたかどうか",
    "q.l13#7.o1" to "症状が進行性に悪化しているか。とくに意識・歩行・呼吸の変化",
    "q.l13#7.o2" to "体温が正常かどうか",
    "q.l13#7.o3" to "血中酸素の数値が上がったかどうか",
    "q.l13#7.e" to "AMS から HACE／HAPE への転換点は、意識、歩行、呼吸という三つの軸に現れます。この三つを注視するほうが、単一の症状や SpO₂ の一つの数値を見つめるより確実です。",

    "q.l13#8.p" to "AMS の頭痛にはどんな特徴がありますか。",
    "q.l13#8.o0" to "ふつう最初に現れる症状である",
    "q.l13#8.o1" to "夜にしか出ない",
    "q.l13#8.o2" to "運動時だけ出る",
    "q.l13#8.o3" to "ふつう最後に現れる症状である",
    "q.l13#8.e" to "頭痛は AMS の最初のサインであることが多く、Lake Louise 基準でも必須条件です。あまりに「よくある」ため、単なる疲れによる頭痛として見落とされがちです。だからこそ「標高が上がったあとに出た」という背景が判断の鍵になります。",

    "q.l13#9.p" to "アセタゾラミドを高山病の予防に使うとき、教本が示す用法はどれですか。",
    "q.l13#9.o0" to "1 日 3 回、毎回 250 mg",
    "q.l13#9.o1" to "1 日 2 回、毎回 125 mg。登る 1 日前ごろから始め、登ったあと 2 日ほどで中止する",
    "q.l13#9.o2" to "1 日 1 回、500 mg",
    "q.l13#9.o3" to "症状が出てからだけ服用する",
    "q.l13#9.e" to "比較的新しい医学理論では、1 日 2 回・毎回 125 mg が推奨されます。旧版の米国薬局方が示した 1 日 3 回 250 mg より少ない量です。低い用量でも効果があり、重い副作用も起こりにくくなります。処方薬なので医師の指示に従ってください。",

    "q.l13#10.p" to "「服薬で症状がやわらいだ」ことを登り続ける根拠にできないのはなぜですか。",
    "q.l13#10.o0" to "薬が錯覚を起こさせるから",
    "q.l13#10.o1" to "薬は症状をやわらげるだけで、低酸素への適応は改善しないから",
    "q.l13#10.o2" to "薬が効かなくなるから",
    "q.l13#10.o3" to "薬を増やし続ける必要があるから",
    "q.l13#10.e" to "高山病の対処で最も重要な認識です。症状は警報であって、病気そのものではありません。薬は警報を切りますが、低酸素による生理的負荷は積み上がり続けます。薬に隠れて登り続けるのは、無音のまま病状を進めることになります。",

    "q.l13#11.p" to "【複数選択】AMS と紛らわしく、慎重に鑑別すべきものはどれですか。",
    "q.l13#11.o0" to "脱水",
    "q.l13#11.o1" to "風邪などの上気道感染",
    "q.l13#11.o2" to "過度の疲労",
    "q.l13#11.o3" to "睡眠不足",
    "q.l13#11.o4" to "雪眼（紫外線性角膜炎）",
    "q.l13#11.e" to "この四つはすべて頭痛、倦怠感、悪心、睡眠不良を起こし、AMS の症状と大きく重なります。鑑別の鍵は、標高の上昇に伴って出たか、休息で改善するか、歩行や意識の変化を伴うか、という三点です。",

    "q.l13#12.p" to "臨床・ガイドの資料によると、標高 4,000 m 以上での急性高山病の発症率はおよそどのくらいですか。",
    "q.l13#12.o0" to "5〜10%",
    "q.l13#12.o1" to "20〜30%",
    "q.l13#12.o2" to "50〜65%",
    "q.l13#12.o3" to "ほぼ 100%",
    "q.l13#12.e" to "標高が高く、上がるのが速いほど発症率は上がります。4,000 m 以上では約 50〜65% に急性高山病が起こり、2,500〜4,300 m の研究データでは約 25〜43% とされています。高山病は例外ではなく日常だということです。だから「計画どおり適応する」のは保守的ではなく、必須なのです。",

    "q.l13#13.p" to "年齢と高山病リスクの関係について、正しい記述はどれですか。",
    "q.l13#13.o0" to "若い人は高山病にならない",
    "q.l13#13.o1" to "年齢が高いほど必ずリスクが上がる",
    "q.l13#13.o2" to "加齢は発症リスクを大きく上げない。上昇速度と睡眠標高が鍵である",
    "q.l13#13.o3" to "体力の劣る人だけがなる",
    "q.l13#13.e" to "中程度の標高での研究では、年配のハイカー（平均 65 歳）の発症率は若年層と同程度でした。リスクを決めるのは上昇速度、睡眠標高、個人の生理反応です。年齢や体力のせいにするのは、非常に危険な誤判断です。",

    // ---------- l14 HACE と HAPE ----------
    "q.l14#0.p" to "HACE を疑うとき、最も警戒すべき徴候はどれですか。",
    "q.l14#0.o0" to "歩行の不安定（まっすぐ歩けない）と意識の変化",
    "q.l14#0.o1" to "軽い頭痛",
    "q.l14#0.o2" to "食欲がやや落ちる",
    "q.l14#0.o3" to "軽い脚の張り",
    "q.l14#0.e" to "運動失調と意識の変化は HACE の中核徴候で、脳浮腫が運動機能と認知機能に及んでいることを意味します。これらが出たら直ちに下降し、医療支援を求めるべきで、経過観察で待ってはいけません。",

    "q.l14#1.p" to "HAPE の最も典型的な初期症状はどれですか。",
    "q.l14#1.o0" to "安静時にも息が苦しく、行動能力が急激に落ちる",
    "q.l14#1.o1" to "軽い鼻水",
    "q.l14#1.o2" to "指先の軽いしびれ",
    "q.l14#1.o3" to "喉の渇き",
    "q.l14#1.e" to "HAPE の特徴は「休んでいても息が苦しい」ことです。単なる体力の使いすぎと違い、休息で改善せず悪化し続け、泡沫状の痰やチアノーゼに進むことがあります。直ちに下降すべき信号です。",

    "q.l14#2.p" to "HACE と HAPE の根本的な治療手段はどれですか。",
    "q.l14#2.o0" to "痛み止めを飲んで登り続ける",
    "q.l14#2.o1" to "直ちにより低い標高へ下降し、酸素投与などの補助治療を併用する",
    "q.l14#2.o2" to "その場で 2 日休む",
    "q.l14#2.o3" to "水を多く飲んでよく寝る",
    "q.l14#2.e" to "下降は病態を確実に逆転させられる唯一の手段で、原因（低酸素）を直接取り除きます。酸素投与、高圧酸素室、薬剤は、すぐに下降できないときに時間を稼ぐ補助手段です。",

    "q.l14#3.p" to "臨床資料による HACE 治療時のデキサメタゾンの一般的な用法はどれですか。",
    "q.l14#3.o0" to "初回 8〜10 mg、その後 6 時間ごとに 4 mg",
    "q.l14#3.o1" to "1 日 1 回 2 mg",
    "q.l14#3.o2" to "2 時間ごとに 10 mg",
    "q.l14#3.o3" to "意識を失ったときだけ使う",
    "q.l14#3.e" to "これは治療用量で、医療監視下で使わなければなりません。薬は下降の時間を稼ぐ道具であって、下降の代わりにはなりません。下降こそが HACE と HAPE の根本治療です。",

    "q.l14#4.p" to "HAPE と HACE が併発する割合はおよそどのくらいですか。",
    "q.l14#4.o0" to "ほとんど併発しない",
    "q.l14#4.o1" to "HAPE の約 13〜20% に HACE を併発する",
    "q.l14#4.o2" to "100% 併発する",
    "q.l14#4.o3" to "子どもだけに併発する",
    "q.l14#4.e" to "この数字は、二つの重症高山病がしばしば同時に起きることを示しています。だから隊員に肺水腫の徴候が出たら、意識と歩行の変化にも同時に警戒し、最悪を想定して直ちに下山する必要があります。",

    "q.l14#5.p" to "隊員が自分で歩けなくなった場合、対処の重点は何ですか。",
    "q.l14#5.o0" to "自力で歩き続けるよう励ます",
    "q.l14#5.o1" to "人手を集めて搬送し、同時に酸素投与、高圧酸素室の検討、できるだけ早い下降を行う",
    "q.l14#5.o2" to "その場で休ませ、回復を待つ",
    "q.l14#5.o3" to "まずキャンプに戻って装備を取る",
    "q.l14#5.e" to "行動能力を失ったということは、病状が重症段階に入ったということです。ここからの下降は隊の搬送か外部救助に頼るしかありません。だから「ここまで進ませない」ことが本当の安全戦略であり、AMS を早期に見つける価値もそこにあります。",

    "q.l14#6.p" to "携帯型高圧酸素室（ガモフバッグなど）の役割はどれですか。",
    "q.l14#6.o0" to "高山病を完全に治す",
    "q.l14#6.o1" to "すぐに下降できないとき、低い標高の環境を疑似的につくり、病状を一時的に安定させる",
    "q.l14#6.o2" to "下降の代わりになる",
    "q.l14#6.o3" to "主に保温のため",
    "q.l14#6.e" to "高圧酸素室は時間を稼ぐ道具で、治療の終点ではありません。悪天候で下山できず、ヘリを待つしかない状況では病状を一時的に抑えられますが、最終的には必ず下降しなければなりません。",

    "q.l14#7.p" to "高山病の薬について、正しい姿勢はどれですか。",
    "q.l14#7.o0" to "服薬で症状がやわらいだら登り続けてよい",
    "q.l14#7.o1" to "時間を稼ぐ補助手段であり、医師の指示で使い、下降の代わりにはならない",
    "q.l14#7.o2" to "隊員に気軽に分け与えてよい",
    "q.l14#7.o3" to "早く飲むほどよく、医師の評価は不要",
    "q.l14#7.e" to "薬には明確な適用、禁忌、副作用があります。しかも薬に隠れて登り続けると、病状の進展という信号を覆い隠します。標準的なやり方は、医師の評価を経て使い、下降を根本治療と位置づけることです。",

    "q.l14#8.p" to "デキサメタゾンを高所脳浮腫に使うとき、よく用いられる用量はどれですか。",
    "q.l14#8.o0" to "12 時間ごとに 20 mg",
    "q.l14#8.o1" to "6 時間ごとに 4 mg",
    "q.l14#8.o2" to "1 日 1 回 8 mg",
    "q.l14#8.o3" to "2 時間ごとに 10 mg",
    "q.l14#8.e" to "教本が示す用量は 6 時間ごとに 4 mg です。頭蓋内圧を下げ、脳浮腫の症状をやわらげ、通常は投与後 6 時間以内に改善が見られます。ただし強調すべきは、それが下山の時間を稼ぐだけで、下降の代わりにならないという点です。",

    "q.l14#9.p" to "デキサメタゾンは高所肺水腫に治療効果がありますか。",
    "q.l14#9.o0" to "ある。第一選択薬である",
    "q.l14#9.o1" to "ない。肺水腫にはまったく治療効果がない",
    "q.l14#9.o2" to "あるが、倍量が必要",
    "q.l14#9.o3" to "子どものときだけ有効",
    "q.l14#9.e" to "ここは混同しやすい点です。デキサメタゾンが効くのは脳浮腫で、肺水腫には効きません。ニフェジピンは肺水腫に効きますが、脳浮腫への効果は限定的です。二つの重症高山病で薬が違うのですから、間違えれば治療にならないのと同じです。",

    "q.l14#10.p" to "ニフェジピンを高所肺水腫に使うとき、推奨される用法と注意すべき副作用はどれですか。",
    "q.l14#10.o0" to "12 時間ごとに 20〜30 mg の徐放剤。血圧が急速に下がることがあり、急に立ち上がると失神するおそれがある",
    "q.l14#10.o1" to "6 時間ごとに 4 mg。眠気が出る",
    "q.l14#10.o2" to "1 日 1 回 125 mg。血圧が上がる",
    "q.l14#10.o3" to "静注のみ。副作用はない",
    "q.l14#10.e" to "ニフェジピンは低酸素による肺動脈の収縮をやわらげ、肺水腫の予防と治療に使われます。ただし副作用は現実的です。血圧が急速に下がり、座位や臥位から急に立ち上がると失神することがあり、急斜面や夜間のトイレ起きでは特に危険です。",

    "q.l14#11.p" to "嘔吐が止まらない高山病患者に、デキサメタゾンはどう投与しますか。",
    "q.l14#11.o0" to "経口で、量を増やして",
    "q.l14#11.o1" to "必ず注射で投与する",
    "q.l14#11.o2" to "舌下に含ませる",
    "q.l14#11.o3" to "投与できないので待つしかない",
    "q.l14#11.e" to "嘔吐が続くということは、経口薬が吸収されず、吐き出される可能性もあるということです。教本はこの場合に注射が必要だと明言しています。高山病の救急計画では、投与経路そのものを事前に決めておくべきだという教訓でもあります。",

    // ---------- l15 適応の計画と薬（12 問） ----------
    "q.l15#0.p" to "標高 3,000 m を超えたあと、睡眠標高は 1 日あたりどれくらい上げるのが推奨されますか。",
    "q.l15#0.o0" to "500 m 以内",
    "q.l15#0.o1" to "1,500 m 以内",
    "q.l15#0.o2" to "速ければ速いほどよい",
    "q.l15#0.o3" to "制限はない",
    "q.l15#0.e" to "睡眠標高の 1 日の上昇を 500 m 以内に抑え、およそ 1,000 m 上がるごとに休養日を入れる——国際的なガイドラインで繰り返し示される基本です。体が代償機構を働かせる時間を残すためです。（資料によって 300〜700 m と幅があり、本コースはその中でも広く使われる値を採っています。）",

    "q.l15#1.p" to "「高く登って低く寝る」の意味はどれですか。",
    "q.l15#1.o0" to "日中はより高い標高へ上がって活動し、夜は低い標高に戻って眠る",
    "q.l15#1.o1" to "日中は休み、夜に歩く",
    "q.l15#1.o2" to "ずっと同じ標高にいる",
    "q.l15#1.o3" to "最も高い場所でだけ眠る",
    "q.l15#1.e" to "日中の高所曝露は赤血球産生や呼吸調節といった適応機構を刺激し、夜に低い標高へ戻れば症状が軽くなり睡眠の質も上がります。この二つを組み合わせるのが最も効率のよい適応のしかたです。",

    "q.l15#2.p" to "次のうち、高所適応の負担を増やす行動はどれですか。",
    "q.l15#2.o0" to "十分な水分補給",
    "q.l15#2.o1" to "アルコール摂取や鎮静系薬剤の服用",
    "q.l15#2.o2" to "炭水化物中心の食事",
    "q.l15#2.o3" to "睡眠を確保すること",
    "q.l15#2.e" to "アルコールと鎮静剤は呼吸の駆動を抑え、とくに夜間の周期性呼吸と低酸素を悪化させ、発症リスクをはっきり上げます。高所では睡眠中の呼吸の質そのものが適応の一部です。",

    "q.l15#3.p" to "パルスオキシメーターで血中酸素を測る意味はどれですか。",
    "q.l15#3.o0" to "症状の判断を完全に置き換えられる",
    "q.l15#3.o1" to "客観的な参考になる。とくに高山病の既往がある人には有効",
    "q.l15#3.o2" to "記録を残すためだけ",
    "q.l15#3.o3" to "実際的な意味はない",
    "q.l15#3.e" to "血中酸素は有用な参考値ですが、個人差が大きく、これだけで判断してはいけません。症状と機能の状態（まっすぐ歩けるか、普通に動けるか）が常に第一の判断材料です。",

    "q.l15#4.p" to "HAPE の高危険群の予防に、医師が検討することがある薬はどれですか。",
    "q.l15#4.o0" to "ニフェジピンまたはシルデナフィル（ホスホジエステラーゼ阻害薬）",
    "q.l15#4.o1" to "広域抗生物質",
    "q.l15#4.o2" to "一般的な痛み止め",
    "q.l15#4.o3" to "ビタミン剤",
    "q.l15#4.e" to "これらは肺動脈圧を下げ、HAPE の高危険群の予防に用いられますが、医師の評価を経て使うものです。作用する段階がアセタゾラミドと異なり、互いに置き換えはできません。",

    "q.l15#5.p" to "「上がるのが速すぎる」ことが高山病の最も強いリスク要因の一つなのはなぜですか。",
    "q.l15#5.o0" to "歩きすぎて疲れるから",
    "q.l15#5.o1" to "呼吸調節や赤血球増加といった代償が間に合わないから",
    "q.l15#5.o2" to "荷物が重くなるから",
    "q.l15#5.o3" to "山の天気が変わりやすいから",
    "q.l15#5.e" to "適応は生理的な代償の積み重ねで、「日」単位の時間が要ります。上がる速さが代償の速さを超えると、症状という形で現れます。上昇速度に関するあらゆる勧告は、ここから来ています。",

    "q.l15#6.p" to "十分な水分補給が高所適応に果たす役割はどれですか。",
    "q.l15#6.o0" to "喉の渇きを癒やすだけ",
    "q.l15#6.o1" to "循環と代謝を保つ。脱水は症状をはっきり悪化させる",
    "q.l15#6.o2" to "肺水腫を予防できる",
    "q.l15#6.o3" to "予防薬の代わりになる",
    "q.l15#6.e" to "高所の乾燥した空気と速い呼吸は水分喪失を大きく増やします。脱水は血液を粘らせ、低酸素感と頭痛を悪化させます。ただし過剰な水分摂取も避け、均等で十分な量を保つのが適切です。",

    "q.l15#7.p" to "高所で過労を避けるべきなのはなぜですか。",
    "q.l15#7.o0" to "すぐ疲れるから",
    "q.l15#7.o1" to "過労は HAPE の誘因になりうる。とくにまだ適応していないとき",
    "q.l15#7.o2" to "脱水を招くから",
    "q.l15#7.o3" to "隊の進行が遅れるから",
    "q.l15#7.e" to "激しい運動は肺動脈圧をさらに上げ、まだ適応していない人では HAPE の明確な誘因の一つになります。ペースを抑えるのは省エネのためだけでなく、発症リスクを下げる手段でもあるのです。",

    "q.l15#8.p" to "アセタゾラミドはいつ飲み始め、いつ止めますか。",
    "q.l15#8.o0" to "高所に着いてから始め、適応したら止める",
    "q.l15#8.o1" to "標高を上げる 1 日前ごろから始め、上げたあと 2 日ほどで止める",
    "q.l15#8.o2" to "行程全体を通して飲み続ける",
    "q.l15#8.o3" to "症状が出たときだけ飲む",
    "q.l15#8.e" to "1 日前から始めるのは、上昇した時点で薬が効いているようにするためです。上げたあと 2 日ほどで止めるのは、そのころには体が自分で適応し始めているからです。アセタゾラミドの働きは「適応の速度を上げる」ことであって、適応の過程を代替するものではありません。",

    "q.l15#9.p" to "アセタゾラミドを止めると症状が反動で出ますか。",
    "q.l15#9.o0" to "出る。漸減しなければならない",
    "q.l15#9.o1" to "出ない。適応の速度が平常値に戻るだけ",
    "q.l15#9.o2" to "出る。症状は倍になって現れる",
    "q.l15#9.o3" to "標高による",
    "q.l15#9.e" to "教本は、中止しても症状の反動はなく、適応の速度が正常な水準に戻るだけだと明言しています。これは重要な点です。薬は何かを「抑えていた」のではなく、適応の過程をしばらく速めていただけだということです。",

    "q.l15#10.p" to "高山病の頭痛をやわらげるアスピリンの用法はどれですか。",
    "q.l15#10.o0" to "頭痛が出てから 500 mg を 1 回",
    "q.l15#10.o1" to "標高を上げる 1 日前から、1 日 3 回・毎回 320 mg を適応の過程が終わるまで",
    "q.l15#10.o2" to "1 日 1 回 100 mg",
    "q.l15#10.o3" to "就寝前だけ",
    "q.l15#10.e" to "これは「痛くなってから飲む」のではなく「予防的に使う」方法です。前もって始め、規則的に飲み、適応の過程が終わるまで続けます。アスピリンには胃腸障害と出血のリスクがあり、薬の判断として医師の評価が必要です。",

    "q.l15#11.p" to "イチョウ葉エキスの高山病予防について、正しい認識はどれですか。",
    "q.l15#11.o0" to "アセタゾラミドより効果が高く、代替できる",
    "q.l15#11.o1" to "一定程度の予防効果はあるが、対照試験ではアセタゾラミドに遠く及ばない",
    "q.l15#11.o2" to "まったく効果がない",
    "q.l15#11.o3" to "脳浮腫にだけ効く",
    "q.l15#11.e" to "教本の姿勢は慎重です。症状をやわらげるという試験結果もある一方、試験ごとに用量も条件も大きく異なり、正確な定量はできません。しかもアセタゾラミドとの対照試験では、効果ははるかに劣っていました。抗凝固薬との相互作用にも注意が必要です。",

    // ---------- l16 低体温症と凍傷（12 問） ----------
    "q.l16#0.p" to "「震えが止まる」ことは何を意味しますか。",
    "q.l16#0.o0" to "体が寒さに適応した",
    "q.l16#0.o1" to "低体温症が悪化している。危険信号である",
    "q.l16#0.o2" to "そのまま進んでよい",
    "q.l16#0.o3" to "すぐ水を飲む必要がある",
    "q.l16#0.e" to "震えは体が熱を作る最後の手段です。震えが止まったということは、産熱機構が尽き、体温が加速的に下がっているということです。軽度から中等度・重度へ移る分岐点であり、直ちに対処しなければなりません。",

    "q.l16#1.p" to "凍傷の現場での復温方法として正しいのはどれですか。",
    "q.l16#1.o0" to "雪で患部を繰り返し揉む",
    "q.l16#1.o1" to "37〜40℃ の湯に約 30 分浸し、皮膚が赤く柔らかくなるまで",
    "q.l16#1.o2" to "焚き火で炙る",
    "q.l16#1.o3" to "湯たんぽを直接当てる",
    "q.l16#1.e" to "凍傷の組織には内部に氷晶ができており、機械的に揉むと細胞を二次的に傷つけます。高温は感覚を失った皮膚をやけどさせます。標準は温水による速やかな復温だけで、応急的には傷のない手や腋の下で温める方法もあります。",

    "q.l16#2.p" to "どういう状況では現場で凍傷を復温すべきではありませんか。",
    "q.l16#2.o0" to "凍傷なら必ず復温する",
    "q.l16#2.o1" to "再凍結の危険があるとき。復温後に凍り直すと損傷はさらに重くなる",
    "q.l16#2.o2" to "日中は復温してはいけない",
    "q.l16#2.o3" to "軽度の凍傷だけ復温する",
    "q.l16#2.e" to "復温して再び凍るというサイクルは、凍傷が続くよりはるかに重い組織破壊を招きます。まだ寒気にさらされ続ける可能性があり、保温を保証できないなら、患部を保護し摩擦を避け、持続的に保温できる場所まで下がってから復温するのが正解です。",

    "q.l16#3.p" to "中等度以上の低体温症で、四肢の激しい動きを避けるのはなぜですか。",
    "q.l16#3.o0" to "体力を消耗するから",
    "q.l16#3.o1" to "低温の心筋は不整脈を起こしやすいから",
    "q.l16#3.o2" to "患者がいらだつから",
    "q.l16#3.o3" to "凍傷が悪化するから",
    "q.l16#3.e" to "低体温症の救急で最も直感に反する点です。患者に自分で歩かせるのは、しばしば致命的になります。低体温では心筋の興奮性が非常に高く、突然の四肢の動きや乱暴な搬動が心室細動を直接引き起こすことがあります。",

    "q.l16#4.p" to "凍傷の復温に適した水温はどれですか。",
    "q.l16#4.o0" to "0〜5℃",
    "q.l16#4.o1" to "20〜25℃",
    "q.l16#4.o2" to "37〜40℃",
    "q.l16#4.o3" to "60℃ 以上",
    "q.l16#4.e" to "低すぎれば効果的に復温できず、高すぎれば感覚を失った皮膚をやけどします。37〜40℃ は氷晶を速く溶かせて、熱損傷も起こさない範囲です。復温の過程は激しく痛むため、痛みの管理も必要です。",

    "q.l16#5.p" to "低体温症の救急で、四肢より体幹を優先して温めるのはなぜですか。",
    "q.l16#5.o0" to "四肢は重要でないから",
    "q.l16#5.o1" to "四肢を温めると末梢の冷えた血液が体幹へ戻り、深部体温がさらに下がるから",
    "q.l16#5.o2" to "体幹のほうが操作しやすいから",
    "q.l16#5.o3" to "四肢はすでに凍傷になっているから",
    "q.l16#5.e" to "低体温症の処置で最も重要な原則の一つです。先に四肢を温めると、末梢の冷血が体幹へ戻り、深部体温がさらに下がって不整脈を誘発することがあります。だから体幹が優先で、四肢はその次です。",

    "q.l16#6.p" to "軽度低体温症の現場での処置はどれですか。",
    "q.l16#6.o0" to "すぐ病院へ運ぶ",
    "q.l16#6.o1" to "風と寒さから離し、濡れた衣類を替え、熱量を補い、悪化しないか観察を続ける",
    "q.l16#6.o2" to "熱を作らせるため歩かせ続ける",
    "q.l16#6.o3" to "雪で体を揉んで循環を促す",
    "q.l16#6.e" to "軽度なら自力で熱を作れます。要点は熱の喪失を止め、エネルギーを補うことです。ただし観察を続ける必要があります。震えが止まるのは多くの場合、中等度へ移った信号であって、回復の合図ではありません。",

    "q.l16#7.p" to "凍傷の患部に湯たんぽを直接当ててもよいですか。",
    "q.l16#7.o0" to "よい。早く温めるほどよい",
    "q.l16#7.o1" to "よくない。感覚を失った皮膚はやけどしやすく、37〜40℃ の湯に浸すしかない",
    "q.l16#7.o2" to "タオルを巻けばよい",
    "q.l16#7.o3" to "温度が高すぎなければよい",
    "q.l16#7.e" to "凍傷部は痛覚も温覚も障害されており、「熱すぎる」という反応が返ってきません。直接の熱源は追加のやけどを起こしやすく、回復しえた組織を完全に壊死させてしまいます。",

    "q.l16#8.p" to "【複数選択】低体温症の救急で、誤っている対応はどれですか。",
    "q.l16#8.o0" to "「体を温める」ために飲酒させる",
    "q.l16#8.o1" to "重度の低体温症の人に自分で歩かせて熱を作らせる",
    "q.l16#8.o2" to "凍傷になった四肢を力を込めて揉む",
    "q.l16#8.o3" to "体幹より先に四肢を温める",
    "q.l16#8.o4" to "患者を風を避ける場所へ移し、濡れた衣類を替える",
    "q.l16#8.e" to "四つとも誤りで、しかも理由がそれぞれ違います。アルコールは末梢血管を広げて放熱を速め、重度の低体温症で歩かせると不整脈を誘発し、揉むと凍傷組織を二次損傷し、先に四肢を温めると冷血が体幹へ戻って深部体温をさらに下げます。",

    "q.l16#9.p" to "低体温症の救急における優先順位の核心はどれですか。",
    "q.l16#9.o0" to "四肢を先に温め、そのあと体幹",
    "q.l16#9.o1" to "体幹の深部を優先して温め、同時に乱暴な搬動と四肢の激しい動きを避ける",
    "q.l16#9.o2" to "まず温かい水を飲ませる",
    "q.l16#9.o3" to "まず衣類をすべて脱がせる",
    "q.l16#9.e" to "体幹優先は低体温症処置の第一原則です。体幹が温まってこそ心臓と脳が機能を取り戻し、血液を四肢へ送れるようになります。順序を逆にすると、深部体温はさらに下がります。",

    "q.l16#10.p" to "凍傷を復温したあとの、正しい後処置はどれですか。",
    "q.l16#10.o0" to "水疱を刺して圧を抜く",
    "q.l16#10.o1" to "水疱は刺さず、無菌の被覆材でゆるく包み、患部に体重をかけない",
    "q.l16#10.o2" to "力を込めてマッサージして血行を促す",
    "q.l16#10.o3" to "すぐ患部を熱源に当てる",
    "q.l16#10.e" to "復温後の組織は非常に脆い状態です。水疱は天然の保護層で、刺せば感染を招きます。マッサージは機械的損傷を起こし、熱源は感覚を失った皮膚をやけどします。正解は保護し、乾燥させ、体重をかけず、できるだけ早く医療機関へ運ぶことです。",

    "q.l16#11.p" to "凍傷はどんな長期後遺症を残すことがありますか。",
    "q.l16#11.o0" to "通常は完全に回復し、後遺症はない",
    "q.l16#11.o1" to "冷えに弱くなる、感覚異常、発汗異常など。回復に数か月以上かかることもある",
    "q.l16#11.o2" to "見た目に影響するだけ",
    "q.l16#11.o3" to "運動能力にだけ影響する",
    "q.l16#11.e" to "凍傷が傷つけるのは深部組織と神経末梢です。見た目が戻っても、冷えに弱い、しびれ、刺痛、発汗異常といった後遺症が長く残ることがあります。だからこそ「凍傷を治す」より「凍傷をつくらない」ほうがはるかに重要なのです。",

    // ---------- l17 アイスクライミング入門（14 問） ----------
    "q.l17#0.p" to "ピックを振るとき、正しい力の出し方はどれですか。",
    "q.l17#0.o0" to "上腕で力まかせに叩きつける",
    "q.l17#0.o1" to "手首を返して振り、ピックが垂直に氷へ入るようにする",
    "q.l17#0.o2" to "ハンマー面で氷面を叩く",
    "q.l17#0.o3" to "水平に氷面を切る",
    "q.l17#0.e" to "手首を使うと、ピックは垂直の角度で速く氷に入り、噛みやすく力も要りません。上腕で叩くと斜めに入って氷を砕き、剥離面ができて荷重を受けられなくなります。",

    "q.l17#1.p" to "アイスクライミングの「三点支持」とは何ですか。",
    "q.l17#1.o0" to "両手と片足（または両足と片手）の三か所を安定させてから、四つ目を動かす",
    "q.l17#1.o1" to "3 人で一緒に登ること",
    "q.l17#1.o2" to "三つの結び目に同時に荷重をかけること",
    "q.l17#1.o3" to "装備にフックを三つ付けること",
    "q.l17#1.e" to "三点支持はアイスとロックの共通の移動原則です。常に信頼できる接触点を三つ残し、一度に一つだけ動かします。これならどれか一つが外れても支えが残ります。",

    "q.l17#2.p" to "WI4 の典型的な特徴はどれですか。",
    "q.l17#2.o0" to "低角度の氷面で、歩いて通過できる",
    "q.l17#2.o1" to "ほぼ垂直で短い垂直区間を含み、確保位置がよくないことがある",
    "q.l17#2.o2" to "すべてオーバーハングしたルーフ",
    "q.l17#2.o3" to "ストック一本で足りる",
    "q.l17#2.e" to "WI4 は地形がほぼ垂直になり、短い垂直区間も出てきます。しかもアイススクリューを打つ位置がよくないことがあり、より高い技術と判断が求められます。WI1〜WI2 は学ぶのに適した低難度の地形です。",

    "q.l17#3.p" to "アイスクライミングでピックを振る回数を抑えるべきなのはなぜですか。",
    "q.l17#3.o0" to "力を節約するため",
    "q.l17#3.o1" to "叩きすぎると氷が砕け、荷重を受けられない剥離面ができるから",
    "q.l17#3.o2" to "ピッケルが摩耗するから",
    "q.l17#3.o3" to "仲間にうるさいから",
    "q.l17#3.e" to "失敗した一振りごとに、氷壁には「穴」が残ります。何度も叩くと氷面全体が荷重を支えられなくなり、かえって腕の力に頼らざるをえなくなります。悪循環です。",

    "q.l17#4.p" to "アイスクライミングがスポーツクライミングより危険なのはなぜですか。",
    "q.l17#4.o0" to "寒いから",
    "q.l17#4.o1" to "アイススクリューは荷重で抜けることがあり、氷の状態は毎日変わるから",
    "q.l17#4.o2" to "支点がないから",
    "q.l17#4.o3" to "ロープが使えないから",
    "q.l17#4.e" to "岩のナッツやボルトは正しくセットすれば比較的信頼できます。アイススクリューは氷そのものの質に依存し、氷は溶け、脆くなり、空洞ができます。昨日まで確実だった支点が、今日は意味を失っていることがあるのです。",

    "q.l17#5.p" to "アイスクライミングで「まず足を決めてからピックを振る」と強調されるのはなぜですか。",
    "q.l17#5.o0" to "腕は脚より疲れやすいから",
    "q.l17#5.o1" to "脚が主な荷重支持と休息の部位で、腕は補助にすぎないから",
    "q.l17#5.o2" to "ピッケルが高価だから",
    "q.l17#5.o3" to "そのほうが格好よく見えるから",
    "q.l17#5.e" to "アイスでは腕の力はあっという間に消耗します。長時間荷重を支えられるのは脚のほうです。足が決まらないうちにピックを振ると、腕が先に売り切れ、脱落の危険が増します。",

    "q.l17#6.p" to "氷の状態が「悪くなる」のはどんな条件のときですか。",
    "q.l17#6.o0" to "深夜に冷え込んだあと",
    "q.l17#6.o1" to "強い日射や気温上昇のあと、氷が柔らかくなり蜂の巣状の構造ができるとき",
    "q.l17#6.o2" to "新雪が降った直後",
    "q.l17#6.o3" to "風速が大きく上がったとき",
    "q.l17#6.e" to "氷は温度の関数です。朝の硬い氷はピックを正確に決めやすく、午後の柔らかい氷は登りやすそうに見えて、支点は抜けやすくなります。氷の判断には時刻、向き、気温、日射の履歴を合わせて見る必要があります。",

    "q.l17#7.p" to "アイススクリューを打つ前に、最も確認すべきことは何ですか。",
    "q.l17#7.o0" to "スクリューの色が目立つかどうか",
    "q.l17#7.o1" to "その場所の氷が密で、空洞や蜂の巣状になっていないか",
    "q.l17#7.o2" to "写真に記録しやすいかどうか",
    "q.l17#7.o3" to "地面からの高さ",
    "q.l17#7.e" to "アイススクリューの強度は打ち方ではなく、氷そのもので決まります。空洞や蜂の巣状の氷に打ったスクリューは墜落の衝撃にほとんど耐えられません。ここがアイスの確保とロックの確保の最も本質的な違いです。",

    "q.l17#8.p" to "アイスクライミングで前腕に「パンプ」を感じたとき、まず何をすべきですか。",
    "q.l17#8.o0" to "速度を上げて早く通過する",
    "q.l17#8.o1" to "早めに立てる場所を見つけ、体重を両足に預けて腕を休める",
    "q.l17#8.o2" to "安定のため、さらに強く握る",
    "q.l17#8.o3" to "すぐ自主的に下降する",
    "q.l17#8.e" to "パンプは前腕の血流不足の表れで、そのまま続ければ握力はすぐ失われます。まだ制御できているうちに体重を足へ移し、前腕の血流を戻すのが正しい反応です。これが「足を怠るな」という言葉の実戦的な意味です。",

    "q.l17#9.p" to "【組み合わせ】WI の氷の難度と典型的な特徴を対応させてください。",
    "q.l17#9.l0" to "WI2",
    "q.l17#9.l1" to "WI3",
    "q.l17#9.l2" to "WI4",
    "q.l17#9.l3" to "WI5",
    "q.l17#9.r0" to "約 60° の連続した氷面。バルジが出ることがあり、確保は良好",
    "q.l17#9.r1" to "60〜75° が続く。確保はふつう良好だが体力を使う",
    "q.l17#9.r2" to "ほぼ垂直で短い垂直区間を含む。確保位置がよくないことがある",
    "q.l17#9.r3" to "垂直が続き、確保が乏しく強度も高い",
    "q.l17#9.e" to "WI のグレードは「地形の角度＋確保の条件＋体力消耗」という三つの変数をまとめた結果です。グレードが上がるほど撤退と自己救助の余地は小さくなります。だからグレードはあくまで参考で、実際の成否を決めるのはその日の氷の状態と隊の力量です。",

    "q.l17#10.p" to "【複数選択】アイスクライミングで手の届く位置に携行すべき装備はどれですか。",
    "q.l17#10.o0" to "アイススクリュー数本",
    "q.l17#10.o1" to "カラビナとクイックドロー",
    "q.l17#10.o2" to "プルージック用の補助ロープ",
    "q.l17#10.o3" to "ビレイ器",
    "q.l17#10.o4" to "予備の寝袋",
    "q.l17#10.e" to "アイスクライミングは「動きながら確保をつくる」スポーツで、ザックに埋めた装備は無いのと同じです。教本の救助装備リスト（アイススクリュー、カラビナ、スリング、プーリー、プルージック、アッセンダー）も同じ論理です。使う可能性のあるものはすべて手元に置きます。",

    "q.l17#11.p" to "アイススクリューが「抜ける」ことがあるのはなぜですか。",
    "q.l17#11.o0" to "スクリューが短いから",
    "q.l17#11.o1" to "氷自体に空洞や蜂の巣状の部分、融解が進んだ部分があり、強度が足りないから",
    "q.l17#11.o2" to "掛ける装備が多すぎるから",
    "q.l17#11.o3" to "スクリューが鈍っているから",
    "q.l17#11.e" to "スクリューの強度は打ち方ではなく氷そのもので決まります。空洞や蜂の巣状の氷に打ったスクリューは墜落の衝撃にほとんど耐えられません。これがアイスの確保とロックの最も本質的な違いであり、打つ前に氷質を確かめる理由です。",

    "q.l17#12.p" to "「アイスクライミングのグレードは参考にすぎない」と言われるのはなぜですか。",
    "q.l17#12.o0" to "グレードが適当に決められているから",
    "q.l17#12.o1" to "氷の状態が毎日変わるから。日射、気温、季節が同じルートの難度を大きく変える",
    "q.l17#12.o2" to "国によってグレードが通用しないから",
    "q.l17#12.o3" to "グレードは長さしか表していないから",
    "q.l17#12.e" to "氷は温度の関数です。朝の硬い氷はピックをより正確に決める必要があり、午後の柔らかい氷は登りやすそうで支点は抜けやすい。同じルートでも時間帯によって難度が 1 グレード以上変わることがあります。だから現場の判断は常に資料の数字より優先されます。",

    "q.l17#13.p" to "【並べ替え】アイスクライミングの「三点支持」のリズムを正しい順番に並べてください。",
    "q.l17#13.o0" to "まず氷面を観察し、ピックを入れる点と足を置く点を選ぶ",
    "q.l17#13.o1" to "前爪を蹴り込んで安定させ、両足の支えをつくる",
    "q.l17#13.o2" to "両足が決まってからピックを振り入れ、噛みを確認する",
    "q.l17#13.o3" to "三か所が安定してから、四つ目を動かす",
    "q.l17#13.e" to "この順序が「足を怠るな」というアイスの核心的な規律を説明しています。長時間荷重を支えられるのは足で、腕は補助です。足を決める前にピックを振ると腕が先に売り切れ、急な氷では致命的になります。",

    // ---------- l18 雪崩（13 問） ----------
    "q.l18#0.p" to "雪崩が最も集中する斜面の角度はどれですか。",
    "q.l18#0.o0" to "10°〜25°",
    "q.l18#0.o1" to "34°〜45°",
    "q.l18#0.o2" to "55°〜70°",
    "q.l18#0.o3" to "垂直な氷壁",
    "q.l18#0.e" to "統計では、雪崩のほとんどが 34°〜45° で起きています（96% が 30°〜50° の範囲）。この角度は雪が積もれて、しかも滑るのに十分な急さという「危険な窓」で、登山ルートが最もよく通る角度でもあります。",

    "q.l18#1.p" to "危険度 3「かなり危険」のときに事故が最も多いのはなぜですか。",
    "q.l18#1.o0" to "雪層が最も不安定だから",
    "q.l18#1.o1" to "条件がまだ大丈夫に見え、最も過小評価されやすいから",
    "q.l18#1.o2" to "誰もが家にいるから",
    "q.l18#1.o3" to "予報が不正確だから",
    "q.l18#1.e" to "レベル 3 の矛盾はここにあります。雪崩の可能性は確かにあるのに、地形は「許容できる」ように見えるため、多くの人が雪崩地形に入ります。レベル 4、5 では広く回避されるので、事故の割合はむしろ下がります。リスク判断で最も危険なのは、極端な条件ではなく、過小評価された中程度の条件です。",

    "q.l18#2.p" to "雪崩の三点セットと呼ばれるものはどれですか。",
    "q.l18#2.o0" to "ビーコン（トランシーバー）、プローブ、ショベル",
    "q.l18#2.o1" to "ヘルメット、ロープ、ハーネス",
    "q.l18#2.o2" to "ピッケル、アイゼン、アイススクリュー",
    "q.l18#2.o3" to "テント、寝袋、マット",
    "q.l18#2.e" to "ビーコンは捜索と位置特定、プローブは埋まった人の正確な位置の確認、ショベルは掘り出しに使います。どれも欠かせず、しかも十数分の黄金の窓で有効な救助を終えるには訓練が要ります。",

    "q.l18#3.p" to "「それほど急に見えない」斜面がかえって危険なのはなぜですか。",
    "q.l18#3.o0" to "雪層が厚いから",
    "q.l18#3.o1" to "34°〜45° が雪崩の最も集中する範囲で、しかも人の目は角度を低く見積もりやすいから",
    "q.l18#3.o2" to "人が速く歩くから",
    "q.l18#3.o3" to "日差しが強いから",
    "q.l18#3.e" to "およそ 30° 未満では緩すぎてスラブ雪崩ができにくく、およそ 50° を超えると雪が積もりません。危険な窓はちょうど「まだ歩けそう」と感じる角度帯に落ちる——だからこそ最も過小評価されるのです。",

    "q.l18#4.p" to "雪崩地形を通過するときの正しいやり方はどれですか。",
    "q.l18#4.o0" to "全員で一気に速く通過する",
    "q.l18#4.o1" to "間隔を空け、1 人ずつ通過し、監視役を置き、退路を計画しておく",
    "q.l18#4.o2" to "谷底の最短ルートを行く",
    "q.l18#4.o3" to "できるだけ雪の厚いところを歩く",
    "q.l18#4.e" to "1 人ずつ通過すればリスクを個人に限定できます。監視役は事故が起きた瞬間に位置を特定し救助を組織できます。全員で同時に渡れば、引き金を引けば全員が埋まる——最悪の結果です。",

    "q.l18#5.p" to "雪面で「whumpf」という沈み込みの音を聞いたとき、何を意味しますか。",
    "q.l18#5.o0" to "雪の穴を踏んだだけ",
    "q.l18#5.o1" to "雪層に引き金を引かれやすい弱層があり、安定性が低い",
    "q.l18#5.o2" to "雪が厚く、通過性がよい",
    "q.l18#5.o3" to "雪層はすでに安定している",
    "q.l18#5.e" to "whumpf は雪層が瞬間的に沈み込む音で、弱層が壊れ始めたことを示します。きわめて直接的な安定性の信号です。そのまま斜面に入るのは、スラブ雪崩が起きるかどうかを自分で試すことと同じです。",

    "q.l18#6.p" to "スラブ（板状）雪崩がルーズスノー雪崩より致命的なのはなぜですか。",
    "q.l18#6.o0" to "気温が低いから",
    "q.l18#6.o1" to "雪板が一斉に崩れて埋め、埋まった人は自力で脱出するのが極めて難しいから",
    "q.l18#6.o2" to "音が大きいから",
    "q.l18#6.o3" to "発生頻度が高いから",
    "q.l18#6.e" to "スラブ雪崩は面全体がほぼ同時に割れ、人は斜面の上ですでに支えを失っています。埋まると雪の重みと急速な固化で自力脱出はほぼ不可能です。だから雪崩救助は一秒を争うのです。",

    "q.l18#7.p" to "ビーコン（トランシーバー）の使い方として正しいのはどれですか。",
    "q.l18#7.o0" to "ザックに入れて持ち歩けばよい",
    "q.l18#7.o1" to "出発前に送信状態を相互確認し、捜索手順を定期的に訓練する",
    "q.l18#7.o2" to "隊長だけが 1 台持てばよい",
    "q.l18#7.o3" to "電池を節約するため切っておく",
    "q.l18#7.e" to "ザックに入れたビーコンはほとんど意味がありません。埋まると腕がまったく動かないことがあり、体に密着させて（通常は胸）携行する必要があります。捜索手順も訓練しておかなければ、現場で十数分の黄金時間に位置を特定できません。",

    "q.l18#8.p" to "雪崩地形に入る前に、隊が最もすべき準備は何ですか。",
    "q.l18#8.o0" to "装備を揃えておけば十分",
    "q.l18#8.o1" to "その日の雪崩予報を確認し、現場の観察と合わせてルートと計画を随時調整する",
    "q.l18#8.o2" to "自分の経験だけを信じる",
    "q.l18#8.o3" to "前の人のトレースをたどる",
    "q.l18#8.e" to "予報は地域スケールの判断を与え、現場の観察は斜面スケールの証拠を与えます。どちらも欠かせません。とくに前の人のトレースをたどるのは危険です。トレースは数時間前のもので、雪層の条件はもう変わっているからです。",

    "q.l18#9.p" to "統計によると、登山の遭難死亡事故で最も多いのはどれですか。",
    "q.l18#9.o0" to "雪崩が最多で、次が滑落",
    "q.l18#9.o1" to "滑落が最多で、次が雪崩",
    "q.l18#9.o2" to "病気が最多で、次が落石",
    "q.l18#9.o3" to "低体温症が最多で、次が雪崩",
    "q.l18#9.e" to "教本の順位は明確です。滑落が最も多く、次が雪崩。この順位には現実的な意味があります。雪崩は最も恐ろしいリスクと見なされがちですが、実際に命を奪うのが多いのは、より「日常的」な滑落なのです。リスクの順位は印象ではなくデータで決めるべきです。",

    "q.l18#10.p" to "雪崩に埋まった人の黄金の救助時間はおよそどのくらいですか。",
    "q.l18#10.o0" to "十数分",
    "q.l18#10.o1" to "2 時間",
    "q.l18#10.o2" to "6 時間",
    "q.l18#10.o3" to "24 時間",
    "q.l18#10.e" to "十数分——この時間尺度が、救助は仲間が直ちに行わなければならないことを決めています。専門救助の到着を待ってはほぼ間に合いません。だから雪崩の三点セット（ビーコン、プローブ、ショベル）は必ず携行し、使い込んでおく必要があるのです。「持っていればよい」ではありません。",

    "q.l18#11.p" to "【複数選択】雪崩リスクを判断するときに注目すべき現場の信号はどれですか。",
    "q.l18#11.o0" to "雪層が「whumpf」と沈み込む音",
    "q.l18#11.o1" to "斜面に新しい亀裂が現れる",
    "q.l18#11.o2" to "新雪の堆積や明らかな風による雪の吹き溜まりがある",
    "q.l18#11.o3" to "下りで雪面がはっきり「鳴る」ように沈む",
    "q.l18#11.o4" to "空に巻雲が広がり、視界が非常に良い",
    "q.l18#11.e" to "これらは安定性が下がっている直接の証拠です。価値は「今」にある点にあります。地域の予報はスケールの判断を与えますが、現場の信号は足元のこの斜面の今の状態を映します。両方が必要です。",

    "q.l18#12.p" to "図は同じ山の三つの斜面です。雪崩リスクが最も高い区間をクリックしてください。",
    "q.l18#12.e" to "雪崩が最も集中する角度は 34°〜45° です。左の緩斜面（約 16°）は緩すぎてスラブ雪崩ができにくく、右の急斜面（約 60°）は急すぎて厚い雪板が積もりません。中央の約 40° だけが「積もれて、しかも滑る」危険な窓に入ります。そしてこの角度こそ登山ルートが最もよく通るところであり、過小評価されやすい理由でもあります。",

    // ---------- l19 登攀計画と撤退の判断（16 問） ----------
    "q.l19#0.p" to "ターンアラウンドタイム（引き返し時刻）を決める効果はどれですか。",
    "q.l19#0.o0" to "その時刻が来たら無条件に撤退し、目標への執着に縛られないようにする",
    "q.l19#0.o1" to "登る速さを計算するため",
    "q.l19#0.o2" to "食料をどれだけ持つか決めるため",
    "q.l19#0.o3" to "形式上の決まりごと",
    "q.l19#0.e" to "ターンアラウンドタイムは、判断を「現場の感情」から切り離します。出発前の冷静なときに決めたルールが、疲労と未練の中にいる現場のあなたに代わって判断を実行します。サミットフィーバーに対抗する最も有効な道具です。",

    "q.l19#1.p" to "サミットフィーバーの典型的な原因はどれですか。",
    "q.l19#1.o0" to "天気が良すぎるから",
    "q.l19#1.o1" to "サンクコストと隊の圧力で判断がゆがむから",
    "q.l19#1.o2" to "装備が足りないから",
    "q.l19#1.o3" to "標高が低いから",
    "q.l19#1.e" to "投じた時間、費用、体力があると、人は「やめるべきだ」と認めたがらなくなります。隊の中の沈黙や励まし合いが、さらに疑問を抑え込みます。この仕組みを理解することが、事前に客観的な判断ルールをつくる前提になります。",

    "q.l19#2.p" to "隊の撤退判断はいつ決めておくべきですか。",
    "q.l19#2.o0" to "出発前に客観的な引き金となる条件と決定権を決めておく",
    "q.l19#2.o1" to "頂上に着いてから話す",
    "q.l19#2.o2" to "危険に直面してからその場で話し合う",
    "q.l19#2.o3" to "最も体力のある人が現場で決める",
    "q.l19#2.e" to "疲労し、低酸素で、感情が動いている現場で撤退を議論すれば、ほぼ必ず「進む」ほうに傾きます。出発前に客観的な条件（時刻、天候の変化、隊員の状態など）と最終決定権を決めておくことが、信頼できる方法です。",

    "q.l19#3.p" to "多くの事故が下山中に起きるのはなぜですか。",
    "q.l19#3.o0" to "下りのほうが歩きにくいから",
    "q.l19#3.o1" to "目標を達成して警戒が緩み、しかも体力は限界に近いから",
    "q.l19#3.o2" to "下山時はいつも天候が悪いから",
    "q.l19#3.o3" to "装備が故障するから",
    "q.l19#3.e" to "「登頂は行程の半分にすぎない」の本当の意味は、行程のリスクが下山の局面でまとめて解放されるということです。だからこそ下山では、ロープで結ぶこと、確保、ペース管理を登頂したからといって緩めてはいけません。",

    "q.l19#4.p" to "撤退判断を事前に決めておく価値はどこにありますか。",
    "q.l19#4.o0" to "時間を節約できる",
    "q.l19#4.o1" to "判断を現場の疲労と感情から切り離し、出発前の理性的な判断に実行させる",
    "q.l19#4.o2" to "リーダーの権威が強まる",
    "q.l19#4.o3" to "仲間の口論を避けられる",
    "q.l19#4.e" to "低酸素、疲労、未練の中で決めれば、ほとんど必ず「進む」に傾きます。出発前に客観的な条件と決定権を決めておくのは、「冷静なときの自分」に「疲れたときの自分」の判断を委ねることです。",

    "q.l19#5.p" to "「撤退計画」を登攀計画に必ず書き込むべきなのはなぜですか。",
    "q.l19#5.o0" to "計画が整って見えるから",
    "q.l19#5.o1" to "撤退には装備・ルート・時間の予算が要り、その場の思いつきでは間に合わないから",
    "q.l19#5.o2" to "検査のため",
    "q.l19#5.o3" to "規則でそう決められているから",
    "q.l19#5.e" to "撤退そのものが実際の技術作業です。ビレイステーションを築き、懸垂下降し、暗闇を歩く必要があるかもしれません。計画に時間と器材を用意していなければ、撤退はリスクの高い即席作業になります。",

    "q.l19#6.p" to "隊の中でルートや天候について意見が分かれたとき、正しい扱いはどれですか。",
    "q.l19#6.o0" to "少数は多数に従う",
    "q.l19#6.o1" to "全員を説得できる新しい証拠が出るまで、最も保守的な意見を採る",
    "q.l19#6.o2" to "最も体力のある人が決める",
    "q.l19#6.o3" to "投票で決めたらそれ以上話さない",
    "q.l19#6.e" to "リスクの高い環境では、最も保守的な意見に優先権を与えるべきです。多数決は少数者の妥当な懸念を抑え込みます。事故の振り返りで最もよく出る言葉は「あのとき誰かが変だと思ったのに、誰も言わなかった」なのです。",

    "q.l19#7.p" to "「ガイドについていけば必ず安全」について、正しい認識はどれですか。",
    "q.l19#7.o0" to "ガイドについていけば絶対に安全",
    "q.l19#7.o1" to "ガイドはリスクを下げられるが、客観的危険は消せない。隊員も判断力を保つ必要がある",
    "q.l19#7.o2" to "ガイドは道案内だけで、安全は自分で確保する",
    "q.l19#7.o3" to "隊員は何も判断しなくてよい",
    "q.l19#7.e" to "ガイドの価値は経験と判断の質にありますが、雪崩や落石、天候が「誰かが連れて行く」という理由で消えるわけではありません。隊員がリスクを理解し、危険信号に気づき、自ら伝えることも、隊の安全能力の一部です。",

    "q.l19#8.p" to "登山における「ゴールクリープ（目標の後退）」とは何ですか。",
    "q.l19#8.o0" to "ルートのグレードを下げること",
    "q.l19#8.o1" to "登頂という目標のために、もともと決めた安全基準を少しずつ緩めていくこと",
    "q.l19#8.o2" to "途中で目標の山を変えること",
    "q.l19#8.o3" to "隊の人数を減らすこと",
    "q.l19#8.e" to "ゴールクリープはサミットフィーバーの典型的な現れです。引き返し時刻は次々に先送りされ、許容できる天候の窓はどんどん広がり、体の症状は我慢され続けます。見抜く唯一の方法は、基準を事前に数値化し、「緩める」ことを明示的で、仲間に説明を要する行為にすることです。",

    "q.l19#9.p" to "【複数選択】完全な登攀計画に含めるべき内容はどれですか。",
    "q.l19#9.o0" to "ルートとタイムテーブル（引き返し時刻を含む）",
    "q.l19#9.o1" to "撤退計画と代替ルート",
    "q.l19#9.o2" to "隊員の状態評価と役割分担",
    "q.l19#9.o3" to "通信手段、連絡先、緊急時の手順",
    "q.l19#9.o4" to "メディア向けの報道・拡散計画",
    "q.l19#9.e" to "四つとも欠かせません。とくに省かれやすいのが二番目と四番目です。順調なときには使わないからです。しかし計画の価値はまさに「順調でないとき」にあり、そのときには計画を作り直す時間はありません。",

    "q.l19#10.p" to "行程に「予備日」を用意するのはなぜですか。",
    "q.l19#10.o0" to "天候の窓が後ろにずれる、隊員の不調などの遅れに対応するため",
    "q.l19#10.o1" to "休む時間を増やすため",
    "q.l19#10.o2" to "費用を抑えるため",
    "q.l19#10.o3" to "行程をゆったり見せるため",
    "q.l19#10.e" to "高所の行程はほぼ必ず遅れます。天候が合わない、誰かに適応の日がもう一日要る、道中が想定より遅い。余裕のない計画は、遅れが出た瞬間に適応期間を削るか、1 日の行程を延ばすかを迫られ、どちらもリスクを大きく上げます。",

    "q.l19#11.p" to "【並べ替え】登攀計画を立てる合理的な手順はどれですか。",
    "q.l19#11.o0" to "目標とルートを決め、資料と過去の気象を集める",
    "q.l19#11.o1" to "隊の力量と時間を見積もり、適応のリズムを組む",
    "q.l19#11.o2" to "引き返し時刻と、数値化した撤退の条件を決める",
    "q.l19#11.o3" to "撤退計画と緊急手順をつくり、外部の連絡先に伝える",
    "q.l19#11.e" to "この順序は「まず目標、次に力量、それから赤線、最後に退路」という考え方を表しています。多くの人はこれを逆にします。先に目標を立て、退路は後回しにする。その結果、退路はいつも最後に置かれ、真剣に設計されることがありません。",

    "q.l19#12.p" to "「下山に必要な時間」が最も過小評価されやすいのはなぜですか。",
    "q.l19#12.o0" to "下りのほうが速いから",
    "q.l19#12.o1" to "下山時は体力を大きく消耗し、地形も悪くなり、確保の操作や器材の回収もあるから",
    "q.l19#12.o2" to "地図が不正確だから",
    "q.l19#12.o3" to "ガイドが急かすから",
    "q.l19#12.e" to "登りは 6 時間で済んだとしても、下山はそれより長くかかることが多いのです。体力が落ち、雪面は緩むか凍り、視界は悪くなり、懸垂下降や確保の回収も加わります。下山時間を登り時間で見積もるのは、最もよくある計画の誤りの一つです。",

    "q.l19#13.p" to "計画に通信と連絡の段取りを書くのはなぜですか。",
    "q.l19#13.o0" to "記録のため",
    "q.l19#13.o1" to "連絡が途絶えたとき、外部がどこを捜索すべきか、いつ捜索を始めるべきか知る必要があるから",
    "q.l19#13.o2" to "会社に報告するため",
    "q.l19#13.o3" to "許可の要件を満たすため",
    "q.l19#13.e" to "捜索救助で最大の困難は「どこにいるか分からない」ことです。行程計画、ルート、代替案、連絡時刻は、捜索時間を数日から数時間に縮める鍵となる情報です。そしてこれらの情報は、出発前にしか提供できません。",

    "q.l19#14.p" to "隊の規模は計画にどう影響しますか。",
    "q.l19#14.o0" to "規模は計画と関係ない",
    "q.l19#14.o1" to "人数が多いほど行軍は遅く、後方支援の負担も重く、適応のリズムも揃えにくい",
    "q.l19#14.o2" to "多いほど安全なので計画を変える必要はない",
    "q.l19#14.o3" to "多いほど速い",
    "q.l19#14.e" to "大人数の利点は人手と装備の共有ですが、代償は速度と柔軟性です。ペースは人それぞれで、隊は最も遅い人に合わせるしかありません。だから人数は計画のペース見積もりに織り込むべきで、あとから「人数が多いから遅い」と愚痴るものではありません。",

    "q.l19#15.p" to "空欄を埋めてください：高所の行程では、通常およそ（ ）% の予備日を用意することが勧められます。",
    "q.l19#15.a0" to "20",
    "q.l19#15.a1" to "30",
    "q.l19#15.a2" to "25",
    "q.l19#15.a3" to "20-30",
    "q.l19#15.a4" to "20〜30",
    "q.l19#15.a5" to "二十五",
    "q.l19#15.e" to "通常は 20〜30% の余裕を見ます。たとえば 10 日の行程なら、補給・休暇・許可を 12〜13 日で組んでおきます。保守的に見えるこの比率は、実際の遅れの発生頻度に対応した数字なのです。",

    // ---------- l20 救助と応急処置（16 問） ----------
    "q.l20#0.p" to "救助の第一原則はどれですか。",
    "q.l20#0.o0" to "できるだけ早く傷病者を動かす",
    "q.l20#0.o1" to "現場の安全を確保し、二人目の傷病者をつくらない",
    "q.l20#0.o2" to "まず現場を写真に記録する",
    "q.l20#0.o3" to "まず傷病者に水を飲ませる",
    "q.l20#0.e" to "落石や雪崩、クレバス、急斜面では、むやみに傷病者へ近づくと救助者も傷病者になり、使える人手が半分になります。現場のリスク評価は救助の第一歩であり、唯一省略できない段階です。",
    "q.l20#1.p" to "応急処置の正しい出発点はどれですか。",
    "q.l20#1.o0" to "まず現場の安全を確保し、それから傷病者の状態を評価する",
    "q.l20#1.o1" to "まず安全な場所へ動かしてから考える",
    "q.l20#1.o2" to "まず食料と水を探す",
    "q.l20#1.o3" to "まずロープシステムを組む",
    "q.l20#1.e" to "標準的な順序は、安全 → 評価 → 通報 → 処置 → 搬送です。安全評価を飛ばしていきなり傷病者に触れるのが、最もよくある救助の失敗です。",

    "q.l20#2.p" to "高所で予防が救助よりはるかに重要なのはなぜですか。",
    "q.l20#2.o0" to "救助費用が高いから",
    "q.l20#2.o1" to "救助は天候、酸素、人手に制約され、時間どおりに到達できないことが多いから",
    "q.l20#2.o2" to "救助隊が出動したがらないから",
    "q.l20#2.o3" to "山に電波がないから",
    "q.l20#2.e" to "高所環境は、救助する側とされる側の双方を弱らせます。ヘリは気流と標高に制限され、救助隊の到着には数時間かかり、その間に傷病者は低酸素と低温でより速く悪化します。この時間差が、あなたの唯一の救助資源です。",
    "q.l20#3.p" to "高所の救助がしばしば数時間から数日かかるのはなぜですか。",
    "q.l20#3.o0" to "救助隊が出動したがらないから",
    "q.l20#3.o1" to "天候、酸素、通信、人手に厳しく制約され、ヘリも気流と標高の影響を受けるから",
    "q.l20#3.o2" to "距離が遠すぎるから",
    "q.l20#3.o3" to "費用が高すぎるから",
    "q.l20#3.e" to "高所ではヘリは積載量と気流の条件で離陸が難しく、地上の救助隊は数時間かけて到達します。この時間差が意味するのは、高所ではまず自分自身が唯一の救助隊だということです。",

    "q.l20#4.p" to "出発前に行程計画と連絡先を残す効果はどれですか。",
    "q.l20#4.o0" to "形式を整えるだけ",
    "q.l20#4.o1" to "連絡が途絶えたとき、救助側がどこを捜索すべきか分かり、時間を大幅に縮められる",
    "q.l20#4.o2" to "あとで精算しやすい",
    "q.l20#4.o3" to "規則を守るため",
    "q.l20#4.e" to "捜索救助で最大の困難は「どこにいるか分からない」ことです。行程計画、ルート、代替案、連絡手段は、捜索時間を数日から数時間に縮める鍵となる情報です。",

    "q.l20#5.p" to "傷病評価で最初に対処すべきものはどれですか。",
    "q.l20#5.o0" to "骨折の固定",
    "q.l20#5.o1" to "気道と呼吸など、生命に関わる緊急の問題",
    "q.l20#5.o2" to "傷病の詳細な記録",
    "q.l20#5.o3" to "目に見える傷の処置",
    "q.l20#5.e" to "評価は「生命に関わるものを優先」という順序に従います。まず気道・呼吸・循環の緊急問題を解決し、そのあと骨折や創傷など、ただちに致命的でない損傷を扱います。順序を誤ると、ほかの処置の意味が大きく損なわれます。",
    "q.l20#6.p" to "高所で保温が応急処置の要になるのはなぜですか。",
    "q.l20#6.o0" to "傷病者が心地よくなるから",
    "q.l20#6.o1" to "動けなくなった傷病者は急速に低体温へ進み、傷病をさらに悪化させるから",
    "q.l20#6.o2" to "関連する規定があるから",
    "q.l20#6.o3" to "あとで搬送しやすくするため",
    "q.l20#6.e" to "寒さと低酸素の環境では、動けない傷病者は産熱能力を急速に失います。低体温はショックを悪化させ症状を覆い隠すため、地面からの遮断、風除け、濡れた衣類の交換は止血と同じくらい重要です。",

    "q.l20#7.p" to "通信が途絶えたとき、隊の緊急時の対応はどうあるべきですか。",
    "q.l20#7.o0" to "連絡が回復するまでその場で待つ",
    "q.l20#7.o1" to "集合地点、連絡途絶の期限、その後の行動を出発前に決めておく",
    "q.l20#7.o2" to "すぐ手分けして探す",
    "q.l20#7.o3" to "全員そのまま下山する",
    "q.l20#7.e" to "山で通信が途絶えるのは例外ではなく日常です。「何時に連絡が取れなければ何を始めるか」を事前に決めておけば、現場の混乱を避けられ、外部もいつ捜索を始めるべきか分かります。",

    "q.l20#8.p" to "応急処置と救助の訓練について、正しい姿勢はどれですか。",
    "q.l20#8.o0" to "チュートリアルを見て手順を覚えれば十分",
    "q.l20#8.o1" to "定期的に実技で反復する必要がある。読むだけでは実際の場面で動けない",
    "q.l20#8.o2" to "リーダーだけが身につければよい",
    "q.l20#8.o3" to "専門の救助隊だけが学ぶもの",
    "q.l20#8.e" to "応急処置も救助も高度に手順化された技能で、プレッシャー下では実際に訓練した水準まで落ちます。読書は枠組みをつくれますが、反復してこそ、慌てているときでも正しく動けるのです。",

    "q.l20#9.p" to "【並べ替え】傷病評価と処置の標準的な順序はどれですか。",
    "q.l20#9.o0" to "現場の安全を確保し、二人目の傷病者をつくらない",
    "q.l20#9.o1" to "意識、気道、呼吸、循環を評価する",
    "q.l20#9.o2" to "生命に関わる緊急の問題に対処する（止血、保温、固定）",
    "q.l20#9.o3" to "通報し、搬送の手配、または専門救助の到着を待つ",
    "q.l20#9.e" to "最も省略されやすいのは一番目と四番目です。緊張すると、人はまっすぐ傷病者へ向かってしまいます。しかし現場が安全でなければ救助者が二人目の傷病者になり、使える人手は半分になります。通報しなければ、その後の処置に後方支援がありません。",

    "q.l20#10.p" to "【複数選択】通報の際に伝えるべき重要情報はどれですか。",
    "q.l20#10.o0" to "正確な位置（座標または特定できる目標物）",
    "q.l20#10.o1" to "傷病者の人数、意識、呼吸の状態",
    "q.l20#10.o2" to "現場の地形と天候",
    "q.l20#10.o3" to "使える通信手段と連絡できる時刻",
    "q.l20#10.o4" to "傷病者の過去の登攀歴",
    "q.l20#10.e" to "この四つが、救助側が何を、どれだけ、どこから投入するかを決めます。位置が不正確なら数時間を無駄にし、傷病が分からなければ装備を用意できず、天候を知らなければ救助隊自身が危険に陥ります。通報は事前に練習しておくべきコミュニケーション技能です。",

    "q.l20#11.p" to "高所でのヘリ救助が難しいことが多いのはなぜですか。",
    "q.l20#11.o0" to "費用が高すぎるから",
    "q.l20#11.o1" to "空気が薄いと揚力と積載能力が落ち、しかも気流が乱れ、飛べる時間帯が短いから",
    "q.l20#11.o2" to "パイロットが行きたがらないから",
    "q.l20#11.o3" to "標高が高いと航路がないから",
    "q.l20#11.e" to "ヘリの揚力は空気から生まれ、高所では空気が薄い——これは吊り上げられる重量と飛べる高度を直接制限します。加えて山の気流は乱れ、天候も変わりやすく、飛べる時間は数十分しかないこともあります。だから「救助を前提にした計画」は成り立たないのです。",

    "q.l20#12.p" to "【組み合わせ】応急処置とその適した場面を対応させてください。",
    "q.l20#12.l0" to "保温",
    "q.l20#12.l1" to "止血",
    "q.l20#12.l2" to "固定",
    "q.l20#12.l3" to "酸素投与",
    "q.l20#12.r0" to "高所の傷病者には誰にでも優先して行う。低体温によるショック悪化を防ぐ",
    "q.l20#12.r1" to "開放創や四肢の出血があるときの第一処置",
    "q.l20#12.r2" to "骨折や関節損傷が疑われるとき。搬送による二次損傷を避ける",
    "q.l20#12.r3" to "呼吸困難、血中酸素が明らかに低い、肺水腫が疑われるとき",
    "q.l20#12.e" to "四つとも高所では「基本動作」であって専門操作ではありません。共通点は、複雑な器材を要しないのに、正しい順序の判断を要するということです。たとえば保温は一般の応急処置では後回しにされがちですが、高所では優先項目になります。",

    "q.l20#13.p" to "救助において「救助自体のリスク」を評価すべきなのはなぜですか。",
    "q.l20#13.o0" to "救助は疲れるから",
    "q.l20#13.o1" to "救助行動がさらに多くの人を危険にさらし、全体の生存確率を下げるから",
    "q.l20#13.o2" to "保険が必要だから",
    "q.l20#13.o3" to "規定で求められているから",
    "q.l20#13.e" to "救助の判断の本質は資源配分です。傷病者に近づこうとして救助者二人もけがをすれば、使える人手は「1 人負傷・2 人救助」から「3 人負傷・救助 0」に変わります。冷酷ではなく、全体の生存確率を最大化するための必要な計算なのです。",

    "q.l20#14.p" to "どういう場合に自助をやめ、専門救助の到着を待つべきですか。",
    "q.l20#14.o0" to "力がある限り自助を続けるべき",
    "q.l20#14.o1" to "自助が二次損傷を招くおそれがある、または環境条件が隊の能力を超えているとき",
    "q.l20#14.o2" to "まったく力が出なくなったときだけやめる",
    "q.l20#14.o3" to "自助は決してやめるべきではない",
    "q.l20#14.e" to "自助の価値は時間を稼ぐことであって、危険を冒すことではありません。続ければ傷病者や救助者にさらに重い損傷が起きる、あるいは吹雪で動くリスクがとどまるリスクを上回るなら、現状を安定させて後方支援を待つほうがよい判断です。",

    "q.l20#15.p" to "空欄を埋めてください：傷病評価の SAMPLE の E は（ ）を表します。",
    "q.l20#15.a0" to "出来事",
    "q.l20#15.a1" to "Event",
    "q.l20#15.a2" to "event",
    "q.l20#15.a3" to "事故",
    "q.l20#15.e" to "E は Event（出来事）、つまり屋外事故がどんな経過で起きたかです。この項目の価値は過小評価されがちです。事故の機序（どう落ちたか、頭を打ったか、どれだけ埋まったか）は、起こりうる損傷の種類を直接指し示す、傷病判断の重要な手がかりになります。",

    // ---------- l21 ウェアと装備の細部（10 問） ----------
    "q.l21#0.p" to "三層のレイヤリングで、ベースレイヤーの主な役割はどれですか。",
    "q.l21#0.o0" to "風雪を遮る",
    "q.l21#0.o1" to "汗を肌から運び出し、ドライに保つ",
    "q.l21#0.o2" to "主な保温を担う",
    "q.l21#0.o3" to "予備の物を収納する",
    "q.l21#0.e" to "ベースレイヤーの核心は汗の処理です。肌に密着しているため、ここが湿ったままだと外に何枚着ても熱は奪われ続けます。だからベースレイヤーは「第二の皮膚」と呼ばれます。",

    "q.l21#1.p" to "フリースが湿った環境でダウンより信頼できるのはなぜですか。",
    "q.l21#1.o0" to "フリースのほうが厚いから",
    "q.l21#1.o1" to "ポリエステル繊維は本来疎水性で、濡れても保温できるから",
    "q.l21#1.o2" to "フリースのほうが安いから",
    "q.l21#1.o3" to "ダウンは中に着られないから",
    "q.l21#1.e" to "フリースはプラスチック（ポリエステル）繊維でできており、ほとんど水を吸いません。だから濡れても空気の層を保ち、保温できます。ダウンは湿気を吸うと潰れて保温力を失うため、厳重に防湿して保管する必要があります。",

    "q.l21#2.p" to "高所の極寒用ダウンジャケットに推奨されるフィルパワーはどれですか。",
    "q.l21#2.o0" to "500 以下",
    "q.l21#2.o1" to "600 程度",
    "q.l21#2.o2" to "800 以上",
    "q.l21#2.o3" to "フィルパワーは重要でない",
    "q.l21#2.e" to "フィルパワーが高いほど、同じ重量のダウンがより多くの空気を抱え、保温効率が上がります。800 以上が高所行の一般的な推奨で、あわせてフード付き・化繊中綿でないものを選びます。",

    "q.l21#3.p" to "ハードシェルの核心的な機能はどれですか。",
    "q.l21#3.o0" to "主な保温を担う",
    "q.l21#3.o1" to "防水・防風・透湿で、しかもヘルメットに対応する",
    "q.l21#3.o2" to "汗を排出する",
    "q.l21#3.o3" to "負荷を増やして鍛える",
    "q.l21#3.e" to "シェルは外からの雨・風・雪を防ぎつつ、体が生む湿気を外へ逃がします。透湿性が悪いと汗の水蒸気が内側で結露し、自分で湿った環境をつくることになります。",

    "q.l21#4.p" to "手袋の構成のうち、タッチパネル操作専用のものはどれですか。",
    "q.l21#4.o0" to "薄手のフリース手袋",
    "q.l21#4.o1" to "防風・耐摩耗手袋で、タッチ感度の高いモデル",
    "q.l21#4.o2" to "厚手の防寒ガイド手袋",
    "q.l21#4.o3" to "登頂用手袋",
    "q.l21#4.e" to "高所でスマホや GPS、カメラを操作するには、防風性とタッチ感度を兼ねた手袋が要ります。手袋を外して操作するのは凍傷の最もよくある誘因の一つです。専用の一組を余分に持つほうが賢明です。",

    "q.l21#5.p" to "手足用の携帯カイロの使い方について、正しい記述はどれですか。",
    "q.l21#5.o0" to "靴下の外側に自由に貼ってよい",
    "q.l21#5.o1" to "手袋やブーツ内など密閉空間でのみ使う。通気のよい場所では約 74℃ まで上がることがある",
    "q.l21#5.o2" to "肌に近いほど効果が高い",
    "q.l21#5.o3" to "帽子の外側に貼ってよい",
    "q.l21#5.e" to "カイロは空気を遮ることで温度を保ちます。通気のよい場所では反応が激しくなり、約 74℃ まで上がってやけどを起こすことがあります。だから密閉空間（手袋、ブーツ内）に置くべきで、肌に直接貼ったり露出した場所に使ったりしてはいけません。",

    "q.l21#6.p" to "フード付きの保温着やダウンが勧められるのはなぜですか。",
    "q.l21#6.o0" to "見た目がよいから",
    "q.l21#6.o1" to "汎用性が高く、頭からの放熱を大きく減らせるから",
    "q.l21#6.o2" to "収納しやすいから",
    "q.l21#6.o3" to "フード付きのほうが軽いから",
    "q.l21#6.e" to "頭は放熱の大きい部位で、フードは最も軽く、体幹に最も近い保温手段です。フード付きならキャンプでも休憩でも急な降温でもすぐ使えます。フードなしだと別に帽子を持つ必要があり、かえって面倒で重くなります。",

    "q.l21#7.p" to "【複数選択】ダウンの使用と保管について、正しいのはどれですか。",
    "q.l21#7.o0" to "厳重に防湿する。湿気を吸うと急速に保温力を失う",
    "q.l21#7.o1" to "収納時は乾燥を保つ",
    "q.l21#7.o2" to "極寒ではフード付き・化繊中綿でないものを選ぶ",
    "q.l21#7.o3" to "フィルパワーが高いほど同じ重量で暖かい",
    "q.l21#7.o4" to "省スペースのため長期間は圧縮袋で保管する",
    "q.l21#7.e" to "ダウンは空気を閉じ込めて保温し、湿気を吸うと潰れます。だから湿った環境では疎水性のポリエステルであるフリースを主力の中間着にし、ダウンは乾燥した環境での核心的な保温として残すのがよいのです。",

    "q.l21#8.p" to "高所向け日焼け止めの参考仕様はどれですか。",
    "q.l21#8.o0" to "SPF 15、普通の乳液で十分",
    "q.l21#8.o1" to "酸化亜鉛を多く含み、SPF 50 レベル",
    "q.l21#8.o2" to "SPF 30 以下のほうが肌にやさしい",
    "q.l21#8.o3" to "日焼け止め成分が入っていれば数値は問わない",
    "q.l21#8.e" to "高所は紫外線が強く、雪面の反射でもう一度浴びます。普通の日焼け止めではすぐ足りなくなります。酸化亜鉛を多く含む SPF 50 が一般的な推奨で、しかも定期的に塗り直す必要があります。汗、拭き取り、摩擦で効果は落ちていくからです。",

    "q.l21#9.p" to "屋外向けリップクリームを選ぶ要点はどれですか。",
    "q.l21#9.o0" to "安いほどよい",
    "q.l21#9.o1" to "亜鉛を多く含み、ある程度汗に強く、SPF 30〜50",
    "q.l21#9.o2" to "保湿できれば十分",
    "q.l21#9.o3" to "メントール入りで清涼感があるとよい",
    "q.l21#9.e" to "唇の皮膚は薄く、メラニンによる防御がほとんどないため、高所では日焼けと乾燥割れを起こしやすくなります。亜鉛が物理的な防御を与え、汗への強さが汗や飲食のあとも唇に残ることを保証します。最も見落とされやすく、最も体験を左右する小さな装備です。",

    // ---------- l22 技術装備と通信（10 問） ----------
    "q.l22#0.p" to "クレバス救助システムを組むための最も基本的な器材はどれですか。",
    "q.l22#0.o0" to "プルージック用のスリング（補助ロープ）",
    "q.l22#0.o1" to "双眼鏡",
    "q.l22#0.o2" to "予備の寝袋",
    "q.l22#0.o3" to "トレッキングポール",
    "q.l22#0.e" to "プルージックのスリングは摩擦結びをつくるためのもので、3:1 引き上げシステムの中核です。これがなければ 1:1 の手引きしかなく、人が一人で相棒をクレバスから引き上げるのはほぼ不可能です。",

    "q.l22#1.p" to "高所の山域で、最も信頼できる救助要請の手段はどれですか。",
    "q.l22#1.o0" to "携帯電話の電波",
    "q.l22#1.o1" to "衛星電話または GPS トラッカー",
    "q.l22#1.o2" to "大声で助けを呼ぶ",
    "q.l22#1.o3" to "火を焚いて煙を上げる",
    "q.l22#1.e" to "山域のほとんどの場所に携帯の電波はありません。衛星電話は通話と SMS ができ、GPS トラッカーは外部に位置を知らせられます。どちらも出発前に用意しておくべき装備です。",

    "q.l22#2.p" to "予備ヘッドランプの明るさの目安はどれですか。",
    "q.l22#2.o0" to "100 ルーメン未満",
    "q.l22#2.o1" to "200 ルーメンで十分",
    "q.l22#2.o2" to "400 ルーメン以上",
    "q.l22#2.o3" to "明るさは重要でない",
    "q.l22#2.e" to "ヘッドランプは夜間のテント内の移動と、日の出前の出発（登頂はたいてい未明）に使います。風雪、霧、ルートの確認が必要な場面では、十分な明るさが判断の質に直結します。防風・防水モデルは悪条件で明らかに有利です。",

    "q.l22#3.p" to "高山用ハーネスを選ぶうえでの重要な条件はどれですか。",
    "q.l22#3.o0" to "サイズを問わず軽いほどよい",
    "q.l22#3.o1" to "腰と脚のサイズに余裕があり、最も外側の衣類の上から着けられる",
    "q.l22#3.o2" to "ギアループが複数必要",
    "q.l22#3.o3" to "色が目立つこと",
    "q.l22#3.e" to "高所では厚着をしていることが多く、その状態でもハーネスが正しくフィットしなければなりません。厚着の上から無理に締めるために最長まで緩めたハーネスは、よくある危険な誤設定です。",

    "q.l22#4.p" to "高度計ウォッチの「ストームアラート」は何を根拠に判断しますか。",
    "q.l22#4.o0" to "衛星の雲画像",
    "q.l22#4.o1" to "短時間での気圧の急降下",
    "q.l22#4.o2" to "風速の測定",
    "q.l22#4.o3" to "気温の急低下",
    "q.l22#4.e" to "気圧の急降下は天候悪化の前触れです。高度計ウォッチは気圧の変化を監視し続けて警告します。高所ではこれが非常に実用的で、天候の窓の変化こそ行程を決める鍵となる変数だからです。",

    "q.l22#5.p" to "【組み合わせ】カラビナの形状と最も適した用途を対応させてください。",
    "q.l22#5.l0" to "HMS（洋ナシ型）",
    "q.l22#5.l1" to "D 型",
    "q.l22#5.l2" to "X 型",
    "q.l22#5.l3" to "B 型",
    "q.l22#5.r0" to "ゲート開口が広く、イタリアンヒッチを組んで懸垂下降に使える。最も汎用",
    "q.l22#5.r1" to "プーリーと組み合わせて救助システムに使うことが多い",
    "q.l22#5.r2" to "対称形で、シンプルなロッキング。クリップしやすい",
    "q.l22#5.r3" to "最も基本的なカラビナ。各種の一時的な連結に使う",
    "q.l22#5.e" to "形ごとに得意分野があります。HMS は開口が広いのでヒッチと懸垂下降に使え、D 型は強度が高くプーリーを掛けやすく、X 型は対称で扱いやすく、B 型は最も汎用な基本形です。選ぶ基準は「どれが強いか」ではなく、機構が用途に合うかどうかです。",

    "q.l22#6.p" to "アッセンダーを使うとき、教本が特に戒めているのはどれですか。",
    "q.l22#6.o0" to "湿った環境で使うこと",
    "q.l22#6.o1" to "アッセンダーを固定端（結び目）に近づけすぎること",
    "q.l22#6.o2" to "片手で操作すること",
    "q.l22#6.o3" to "雪面で使うこと",
    "q.l22#6.e" to "アッセンダーを結び目や固定端にぴったり寄せると、それ以上上がれず、しかも素早く外せなくなります。その場で身動きが取れなくなるのです。素早い調整が必要な場面でこの「詰まり」は非常に危険なので、余裕のあるうちに処理します。",

    "q.l22#7.p" to "固定ロープとロープ隊の使い分けについて、正しい記述はどれですか。",
    "q.l22#7.o0" to "固定ロープは常にロープ隊より安全",
    "q.l22#7.o1" to "人数が多い隊では固定ロープ、小規模な隊やテクニカルな山ではロープ隊のほうが効率的",
    "q.l22#7.o2" to "ロープ隊は雪面にしか使えない",
    "q.l22#7.o3" to "固定ロープは下降にしか使わない",
    "q.l22#7.e" to "固定ロープは全体の安全性を高めますが、人手と器材がより必要で、設置にも時間がかかります。小人数で機動的な隊や、テクニカルな山では、ロープ隊のほうが効率的です。「最良は一つではない、合うかどうかがすべて」という典型の判断です。",

    "q.l22#8.p" to "【複数選択】高所の通信・ナビゲーション器材に当たるものはどれですか。",
    "q.l22#8.o0" to "衛星電話",
    "q.l22#8.o1" to "トランシーバー",
    "q.l22#8.o2" to "GPS トラッカー",
    "q.l22#8.o3" to "気圧計付き高度計ウォッチ",
    "q.l22#8.o4" to "双眼鏡",
    "q.l22#8.e" to "四つは役割が違います。衛星電話は外部への救助要請、トランシーバーは隊内の連携、GPS トラッカーは外部への位置共有、高度計ウォッチは気圧と標高の傾向。高所のリスクはまさに「助けを呼べない」「自分がどこにいるか分からない」にあり、これらの器材はその二つに直接対抗します。",

    "q.l22#9.p" to "ヘルメットはなぜヘッドランプを取り付けられなければならないのですか。",
    "q.l22#9.o0" to "見た目を揃えるため",
    "q.l22#9.o1" to "登頂は通常日の出前に出発するので、ヘッドランプを頭に安定して固定する必要があるから",
    "q.l22#9.o2" to "ヘッドランプを軽くするため",
    "q.l22#9.o3" to "ヘルメットの強度を上げるため",
    "q.l22#9.e" to "登頂日は未明に出発することが多く、ヘッドランプが唯一の光源です。ヘルメットをかぶっているときは、ヘルメットに固定しないと安定して照らせません。移動中にランプが揺れたり外れたりすれば、足元が見えなくなります。テクニカルな地形では現実のリスクです。",

    // ---------- m01 高所環境の科学（13 問） ----------
    "q.m01#0.p" to "標高が 1,000 m 上がるごとに、気温は平均でどれくらい下がりますか。",
    "q.m01#0.o0" to "約 1.5℃",
    "q.m01#0.o1" to "約 3℃",
    "q.m01#0.o2" to "約 6.5℃",
    "q.m01#0.o3" to "約 10℃",
    "q.m01#0.e" to "1,000 m 上がるごとに平均約 6.5℃ 下がります。これは大気の気温減率です。雪線の高さを説明し、5,000 m 級の山が夏でも万年雪を抱く理由でもあります。",

    "q.m01#1.p" to "高所の低酸素の根本的な原因は何ですか。",
    "q.m01#1.o0" to "空気中の酸素の割合が低くなるから",
    "q.m01#1.o1" to "気圧が下がり、吸い込む空気の酸素分圧が下がるから",
    "q.m01#1.o2" to "空気中の酸素が紫外線で分解されるから",
    "q.m01#1.o3" to "標高が高いほど空気が薄くなり、酸素が他の気体に置き換わるから",
    "q.m01#1.e" to "非常によくある誤解です。高所でも空気中の酸素の割合は約 21% で、比率は変わりません。変わるのは気圧です。気圧が下がれば同じ体積の空気に含まれる酸素分子の数が減り、酸素分圧が下がるため、体に十分な酸素が入らなくなります。",

    "q.m01#2.p" to "【複数選択】高所環境の典型的な特徴はどれですか。",
    "q.m01#2.o0" to "気圧が低く、酸素分圧も低い",
    "q.m01#2.o1" to "気温が低く、昼夜の寒暖差が大きい",
    "q.m01#2.o2" to "紫外線が著しく強い",
    "q.m01#2.o3" to "空気が極端に乾燥している",
    "q.m01#2.o4" to "空気中の酸素の割合が著しく低い",
    "q.m01#2.e" to "四つとも正しく、しかも互いに増幅し合います。低温と低酸素は産熱の困難と酸素不足を同時に押しつけ、乾燥と強い紫外線は気道・皮膚・目を傷めやすくします。装備と行程はこの四つすべてをカバーしなければなりません。",

    "q.m01#3.p" to "海面の気圧は約 1,013 hPa です。5,000 m の気圧はおよそいくらですか。",
    "q.m01#3.o0" to "約 900 hPa",
    "q.m01#3.o1" to "約 700 hPa",
    "q.m01#3.o2" to "約 540 hPa",
    "q.m01#3.o3" to "約 300 hPa",
    "q.m01#3.e" to "5,000 m の気圧は海面のおよそ半分です。つまり一回の呼吸で取り込める酸素分子は約半分になり、体は呼吸と心拍を速めて代償します。高所で心拍が速く、行動能力が落ちる物理的な理由がここにあります。",

    "q.m01#4.p" to "空欄を埋めてください：標高が 1,000 m 上がるごとに、気温は平均で約（ ）℃ 下がります。",
    "q.m01#4.a0" to "6.5",
    "q.m01#4.a1" to "六点五",
    "q.m01#4.e" to "6.5℃／1,000 m。この数字は行程計画で実用的です。3,000 m のベースキャンプから 5,000 m へ上がれば、気温はさらに約 13℃ 低くなります。ダウンと寝袋の厚さはこれで決まります。",

    "q.m01#5.p" to "【並べ替え】高所の低酸素の因果の連鎖を、起こる順に並べてください。",
    "q.m01#5.o0" to "気圧が下がり、吸気の酸素分圧が下がる",
    "q.m01#5.o1" to "動脈血の酸素飽和度が下がる",
    "q.m01#5.o2" to "体が代償的に呼吸と心拍を速める",
    "q.m01#5.o3" to "低酸素が続くと高山病に進展しうる",
    "q.m01#5.e" to "この連鎖が高所医学の骨格です。環境（気圧が低い）→ 生理（血中酸素が低い）→ 代償（呼吸と心拍が速い）→ 代償不全（高山病）。これを理解すれば、AMS、HACE、HAPE はばらばらの知識ではなく、同じ連鎖の異なる段階の産物になります。",

    "q.m01#6.p" to "新雪の表面の反射率はおよそどれくらいですか。",
    "q.m01#6.o0" to "約 20%",
    "q.m01#6.o1" to "約 40%",
    "q.m01#6.o2" to "約 60%",
    "q.m01#6.o3" to "約 80〜90%",
    "q.m01#6.e" to "新雪は太陽放射の約 80〜90% を反射します。つまり雪面での紫外線曝露はほぼ「二重」です。上からの直射に、雪面からの反射が加わります。雪山で雪眼や重度の日焼けが多い理由です。",

    "q.m01#7.p" to "高所で日焼け対策が「やったほうがよい」ではなく「必須」なのはなぜですか。",
    "q.m01#7.o0" to "高所では太陽が地球に近いから",
    "q.m01#7.o1" to "紫外線は標高とともに強まり、しかも雪面が紫外線を顔へ反射するから",
    "q.m01#7.o2" to "高原はオゾン層が薄いので可視光が強いから",
    "q.m01#7.o3" to "低温が皮膚の抵抗力を弱めるから",
    "q.m01#7.e" to "紫外線は 1,000 m 上がるごとに約 10〜12% 強まり、雪面がさらに約 80〜90% を反射します。両者が重なると、同じ緯度の低地より曝露量がはるかに大きくなります。日焼け止め、リップ、UV400 のゴーグルは必需品であって選択肢ではありません。",

    "q.m01#8.p" to "高所の乾燥がもたらす、最も見落とされやすい直接の結果はどれですか。",
    "q.m01#8.o0" to "肌の調子がよくなる",
    "q.m01#8.o1" to "呼吸と発汗による目に見えない水分喪失が、脱水と高山病の症状を悪化させる",
    "q.m01#8.o2" to "食欲が増す",
    "q.m01#8.o3" to "睡眠が深くなる",
    "q.m01#8.e" to "高所の乾燥に速い呼吸が加わると、気道から水分が奪われ続けます。しかもこの喪失は喉の渇きとして感じられないことが多いのです。脱水は血液を粘らせ、低酸素感と頭痛を悪化させます。だから規則的な水分補給は高所適応の一部であって、付随作業ではありません。",

    "q.m01#9.p" to "【複数選択】高所環境が直接引き起こす損傷はどれですか。",
    "q.m01#9.o0" to "日焼け",
    "q.m01#9.o1" to "雪眼",
    "q.m01#9.o2" to "脱水",
    "q.m01#9.o3" to "唇のひび割れ",
    "q.m01#9.o4" to "足首の捻挫",
    "q.m01#9.e" to "四つとも環境性の損傷で、共通点は「ほぼ完全に予防できる」ことです。雪崩のように予測が難しいものではなく、装備と習慣だけで決まります。だからこうした損傷が隊で起きたときは、たいてい準備の段階に問題があったということです。",

    "q.m01#10.p" to "高所の空気の成分について、正しい記述はどれですか。",
    "q.m01#10.o0" to "酸素の割合は標高とともに下がる",
    "q.m01#10.o1" to "酸素の割合はほぼ変わらず、気圧の低下が酸素分圧を下げる",
    "q.m01#10.o2" to "窒素の割合が標高とともに上がる",
    "q.m01#10.o3" to "標高が高いほど、酸素が他の気体に押し出される",
    "q.m01#10.e" to "空気の成分比は対流圏内ではほぼ一定です（酸素約 21%、窒素約 78%）。標高で変わるのは気圧、つまり「同じ一息に何個の分子が入っているか」です。この違いを整理しておけば、装備や生理の多くの問題が理解しやすくなります。",

    "q.m01#11.p" to "5,000 m 級の山が夏でも雪を保つのはなぜですか。",
    "q.m01#11.o0" to "高い場所は太陽から遠いから",
    "q.m01#11.o1" to "高所の気温が同じ緯度の低地より著しく低く、降水が雪の形で存在するから",
    "q.m01#11.o2" to "山頂は風が強いので溶けないから",
    "q.m01#11.o3" to "積雪が氷に圧縮されると二度と溶けないから",
    "q.m01#11.e" to "1,000 m ごとに約 6.5℃ 下がるという法則により、5,000 m の夏の気温はなお氷点下です。同じ山でも冬と夏で雪の状態が違い、それが登攀の難度に直結する理由でもあります。雪線が動けば、ルートも変わるのです。",

    "q.m01#12.p" to "標高 3,000 m のベースキャンプから 5,000 m のキャンプへ上がるとき、平均減率で計算すると気温はおよそ何℃ 下がりますか。",
    "q.m01#12.a0" to "13",
    "q.m01#12.e" to "13℃。計算は、標高差 2,000 m、1,000 m あたり 6.5℃ なので 2 × 6.5 = 13℃ です。この見積もりは出発前に非常に実用的で、保温着と寝袋の厚さを直接決めます。",

    // ---------- m02 体力と栄養（10 問） ----------
    "q.m02#0.p" to "高所登攀で最も必要とされる体力はどれですか。",
    "q.m02#0.o0" to "爆発力と短距離ダッシュ能力",
    "q.m02#0.o1" to "長時間持続して出力できる有酸素持久力",
    "q.m02#0.o2" to "最大握力",
    "q.m02#0.o3" to "柔軟性",
    "q.m02#0.e" to "高所登山は典型的な長時間・低強度の運動です。1 日に 6〜10 時間歩き、傾斜は急ではないが途切れません。低酸素では無酸素能力が大きく削られるため、歩き切る力を支えるのは有酸素の基礎と安定したペース配分です。",

    "q.m02#1.p" to "出発前のトレーニングとして、比較的合理的なのはどれですか。",
    "q.m02#1.o0" to "出発 1 週前に量を増やして追い込む",
    "q.m02#1.o1" to "2〜3 週前から徐々に減量し、回復した状態で山に入る",
    "q.m02#1.o2" to "出発前日まで最大強度で追い込む",
    "q.m02#1.o3" to "まったく練習せず、現場の適応に任せる",
    "q.m02#1.e" to "トレーニングの効果は回復期に現れます。疲労を抱えたまま山に入ると、パフォーマンスと高所適応力の両方が削られます。しかも適応そのものが体力を消費します。事前の減量は、練習の成果を実際に変換するための鍵となる一歩です。",

    "q.m02#2.p" to "高所では食事を何中心にすべきですか。",
    "q.m02#2.o0" to "高脂肪食",
    "q.m02#2.o1" to "炭水化物",
    "q.m02#2.o2" to "高タンパク食",
    "q.m02#2.o3" to "流動食だけ",
    "q.m02#2.e" to "炭水化物は低酸素下で代謝効率が高く、酸素消費も少なくて済みます。体も高所では本能的に炭水化物を好みます。「高所では高カロリーの脂肪を多く」という直感とは逆ですが、背景には酸素利用効率という現実の制約があります。",

    "q.m02#3.p" to "水分が足りているか判断する、実用的な目安はどれですか。",
    "q.m02#3.o0" to "喉の渇きの程度",
    "q.m02#3.o1" to "尿が淡い色を保っていること",
    "q.m02#3.o2" to "毎日決まった量の 1 L を飲む",
    "q.m02#3.o3" to "体重の変化",
    "q.m02#3.e" to "高所では喉の渇きは当てになりません。寒さも低酸素もそれを鈍らせます。尿の色とにおいのほうが日常的で分かりやすい指標です。淡ければ水分はほぼ足りており、濃くなりにおいが強ければ補水が必要です。",

    "q.m02#4.p" to "高所で飲酒を避けるべきなのはなぜですか。",
    "q.m02#4.o0" to "太るから",
    "q.m02#4.o1" to "アルコールが呼吸の駆動を抑え、夜間の低酸素を悪化させるから",
    "q.m02#4.o2" to "紫外線による損傷を加速するから",
    "q.m02#4.o3" to "山に冷蔵庫がないから",
    "q.m02#4.e" to "アルコールと鎮静系薬剤は呼吸中枢を抑えます。高所の夜はもともと周期性呼吸（呼吸の間欠）が起きやすく、そこに呼吸抑制が重なると血中酸素がはっきり下がります。高山病が夜に悪化する重要な仕組みの一つです。",

    "q.m02#5.p" to "【複数選択】高所の行動中にエネルギーを補給する方法として正しいのはどれですか。",
    "q.m02#5.o0" to "少量を頻回に。空腹になるまで待たない",
    "q.m02#5.o1" to "消化しやすく、水分を適度に含むものを選ぶ",
    "q.m02#5.o2" to "炭水化物を中心にする",
    "q.m02#5.o3" to "回数を減らすため一度にたくさん食べる",
    "q.m02#5.e" to "少量頻回は消化の負担を軽くし、血糖値も安定させます。一度にたくさん食べると、低酸素下では膨満感や吐き気を起こしやすくなります。食欲低下そのものが高山病のよくある症状なので、大食いで補おうとするのは逆効果です。",

    "q.m02#6.p" to "高所で食欲が落ちたとき、正しい対応はどれですか。",
    "q.m02#6.o0" to "食べずに、食欲が出るのを待つ",
    "q.m02#6.o1" to "積極的に食べる。高炭水化物で消化のよいものを選ぶ",
    "q.m02#6.o2" to "コーヒーを大量に飲んで食事の代わりにする",
    "q.m02#6.o3" to "電解質だけ補給する",
    "q.m02#6.e" to "食欲低下は高山反応の一部で、エネルギー摂取不足はさらに適応力を削り、悪循環になります。正解は積極的に、少量ずつ、頻回に食べることです。これは「食欲があるか」の問題ではなく、必要な対処なのです。",

    "q.m02#7.p" to "高所のトレーニングと体力の関係について、正しい記述はどれですか。",
    "q.m02#7.o0" to "体力があれば高山病にならない",
    "q.m02#7.o1" to "体力はパフォーマンスを上げるが、適応の過程を代替できない",
    "q.m02#7.o2" to "体力のない人は高所に行くべきでない",
    "q.m02#7.o3" to "体力があるほど必要な適応時間は短い",
    "q.m02#7.e" to "体力と高所適応は二本の別の線です。体力のある人は同じ標高でも余裕を感じますが、生理的な適応にはやはり「日」単位の時間が要ります。「体力があるから高山病にならない」を根拠にするのは、多くの事故の背後にある共通の論理です。",

    "q.m02#8.p" to "【並べ替え】合理的な登攀前の準備を時系列に並べてください。",
    "q.m02#8.o0" to "基礎体力のトレーニング（2〜3 か月前）",
    "q.m02#8.o1" to "徐々に減量し、回復を確保する（出発 2〜3 週前）",
    "q.m02#8.o2" to "装備を点検し、行程と保険を確認する（出発 1 週前）",
    "q.m02#8.o3" to "計画どおりに適応しながら上がる（行程中）",
    "q.m02#8.e" to "この順序自体が方法論です。練習は早く、回復は確保し、準備は細かく、適応はゆっくり。四つのうち乱れやすいのは三番目と四番目です。装備点検は念入りなのに、山では先を急ぎたくて適応時間を削ってしまう——よくあるパターンです。",

    "q.m02#9.p" to "水分の過剰摂取（短時間に大量の水を飲む）は高所でどんな問題を起こしえますか。",
    "q.m02#9.o0" to "まったく影響がない",
    "q.m02#9.o1" to "血液の電解質が薄まり、重い場合は低ナトリウム血症を起こす",
    "q.m02#9.o2" to "肺水腫を効果的に予防できる",
    "q.m02#9.o3" to "食事の代わりになる",
    "q.m02#9.e" to "「水を多く」は「がむしゃらに飲む」ではありません。短時間に大量の水だけを入れて電解質を補わないと、血中ナトリウムが薄まり、頭痛、吐き気、意識の変化を起こすことがあります。これらの症状は高山病とよく似ており、誤判断のもとになります。均等で適量な補水が正解です。",

    // ---------- m03 低環境負荷（10 問） ----------
    "q.m03#0.p" to "「低インパクト（LNT）原則」の中核的な意味はどれですか。",
    "q.m03#0.o0" to "装備を軽くして体への負担を減らす",
    "q.m03#0.o1" to "人の活動が山野の環境に与える影響を最小にする",
    "q.m03#0.o2" to "安全のため登攀の難度を下げる",
    "q.m03#0.o3" to "隊の人数を減らす",
    "q.m03#0.e" to "低インパクト原則は、登山・アウトドア活動が掲げる環境保護の原則です。問うのは「あなたの荷物が軽いか」ではなく、「山野があなたによってどれだけ変わったか」です。ゴミ、踏み跡、火の使用、野生動物への干渉がすべて含まれます。",

    "q.m03#1.p" to "キャンプを離れるとき、ゴミについて正しいのはどれですか。",
    "q.m03#1.o0" to "生ゴミはその場に埋めればよい",
    "q.m03#1.o1" to "トイレットペーパーなど衛生用品も含め、すべて持ち帰る",
    "q.m03#1.o2" to "プラスチックごみだけ持ち帰る",
    "q.m03#1.o3" to "まとめて焼却する",
    "q.m03#1.e" to "教本の要求は明確です。出たゴミは袋にまとめて持ち帰り、キャンプと活動区域を点検し、トイレットペーパーなどの衛生用品も袋に入れて持ち帰ります。埋めても焼いても痕跡は残り、高所の低温環境では分解が極端に遅いからです。",

    "q.m03#2.p" to "野外での排泄物の処理は、場所の選び方としてどんな原則に従いますか。",
    "q.m03#2.o0" to "目立たない場所ほどよく、プライバシーを優先する",
    "q.m03#2.o1" to "水源、キャンプ、歩道から離す",
    "q.m03#2.o2" to "雪面が最も平らな場所を選ぶ",
    "q.m03#2.o3" to "流れで洗い流せるよう沢の近くにする",
    "q.m03#2.e" to "核心は水源を汚さず、後から来る人に踏まれないようにすることです。実際には水源と歩道から一定の距離をとり、浅い穴を掘って埋め、使った紙は持ち帰ります。雪線より上では袋に入れて持ち帰ります。低温ではほとんど分解しないからです。",

    "q.m03#3.p" to "食料とゴミを密閉して保管するのはなぜですか。",
    "q.m03#3.o0" to "湿気で傷むのを防ぐため",
    "q.m03#3.o1" to "動物が漁ったり近づいたりするのを防ぐため",
    "q.m03#3.o2" to "ザックの空間を節約するため",
    "q.m03#3.o3" to "重さを量りやすくするため",
    "q.m03#3.e" to "食べ物を漁る動物は、たいてい隊自身が「教えて」しまった結果です。一度キャンプと食べ物を結びつけると、その後のルートのリスクは恒久的に上がります。密閉保管は食料を守り、動物を守り、後続の隊も守ります。",

    "q.m03#4.p" to "野生動物の「敏感期」とは主に何を指しますか。",
    "q.m03#4.o0" to "日中に餌を探す時間帯",
    "q.m03#4.o1" to "交尾期と授乳期",
    "q.m03#4.o2" to "渡りの季節",
    "q.m03#4.o3" to "冬の休眠期",
    "q.m03#4.e" to "交尾期と授乳期の動物は干渉に特に敏感で、子を守る母獣が攻撃的になることもあります。だから活動域を避けるだけでなく、決まった水飲みの時間と場所も避けます。これは彼らを守ることであり、自分を守ることでもあります。",

    "q.m03#5.p" to "既存の歩道を歩き続けるべきなのはなぜですか。",
    "q.m03#5.o0" to "規定で決められているから",
    "q.m03#5.o1" to "踏み跡が長く残る新しい道をつくり、土砂の流出を招くから",
    "q.m03#5.o2" to "歩道のほうが歩きやすいから",
    "q.m03#5.o3" to "ガイドの印があるから",
    "q.m03#5.e" to "高所の植生は育ちが極端に遅く、一度の踏み跡が数年残ることがあります。並行する複数の「近道」は植生を分断し、雨の流出を強めて最終的にガリー（侵食溝）をつくります。ルートの劣化はたいていこうして始まります。",

    "q.m03#6.p" to "【複数選択】山から必ず持ち帰るべきゴミはどれですか。",
    "q.m03#6.o0" to "食品の包装",
    "q.m03#6.o1" to "果物の皮や生ゴミ",
    "q.m03#6.o2" to "使ったトイレットペーパー",
    "q.m03#6.o3" to "タバコの吸い殻",
    "q.m03#6.o4" to "テープや結束紐はその場で焼却してよい",
    "q.m03#6.e" to "四つとも持ち帰ります。最も誤解されやすいのが果物の皮と生ゴミです。「分解するだろう」に見えますが、低温で乾燥した高山環境では分解が非常に遅く、しかも動物を引き寄せ、その習性を変えてしまいます。",

    "q.m03#7.p" to "石や植物、化石を記念に持ち帰ることについて、正しい姿勢はどれですか。",
    "q.m03#7.o0" to "小さいものなら持ち帰ってよい",
    "q.m03#7.o1" to "自然物は持ち帰らず、写真だけを持ち帰る",
    "q.m03#7.o2" to "環境を壊さなければよい",
    "q.m03#7.o3" to "標本採集は研究に役立つ",
    "q.m03#7.e" to "「写真だけを持ち帰り、足跡だけを残す」は低インパクト原則の古典的な表現です。自然物はその土地の生態と地形の一部であり、どの隊も少しずつ持ち帰れば累積効果は非常に大きくなります。",

    "q.m03#8.p" to "登山が山域の環境に与える影響は、主にどう現れますか。",
    "q.m03#8.o0" to "ゴミによる汚染だけ",
    "q.m03#8.o1" to "植生の破壊、野生動物の行動圏の縮小、ゴミ汚染、そして外来文化が地元住民に与える影響",
    "q.m03#8.o2" to "主に騒音の問題",
    "q.m03#8.o3" to "影響は無視できる",
    "q.m03#8.e" to "教本は影響を生態と社会の二層に分けます。生態面では植生の破壊、動物の移動、ゴミ汚染。社会面では外来文化が地域の暮らしに与える影響です。これを理解してこそ、「マナー」がなぜ登山訓練の一部なのかが見えてきます。",

    "q.m03#9.p" to "【並べ替え】キャンプを離れるときの環境配慮の手順を、正しい順に並べてください。",
    "q.m03#9.o0" to "個人と共同の装備を片づける",
    "q.m03#9.o1" to "すべてのゴミを分別してまとめる",
    "q.m03#9.o2" to "排泄物を処理する（埋めるか持ち帰る）",
    "q.m03#9.o3" to "キャンプと活動区域を見回し、置き忘れがないか確認する",
    "q.m03#9.e" to "最後の「見回り」が最も飛ばされやすく、最も重要です。人は離れるとき、無意識に「自分のもの」だけを持ち帰ります。テントのペグ、ロープの端、落ちた食品の包装は、たいていこうして残ります。振り返って見るだけなら、コストはほぼゼロです。",

    // ---------- m04 天気と地形図（10 問） ----------
    "q.m04#0.p" to "天気が悪化していると判断する、最も確実な根拠はどれですか。",
    "q.m04#0.o0" to "今この瞬間、晴れているかどうか",
    "q.m04#0.o1" to "気圧、雲、風の変化の傾向",
    "q.m04#0.o2" to "出発前の天気予報",
    "q.m04#0.o3" to "同行者の感覚",
    "q.m04#0.e" to "「今」はスナップショットで、「傾向」が方向です。気圧が下がり続け、雲が厚く低くなり、風が強まる——この三つが同時に出れば、天気は悪化しているとほぼ断定できます。気圧計（高度計ウォッチ）を持つのが実用的な理由でもあります。",

    "q.m04#1.p" to "積乱雲の典型的な特徴と意味はどれですか。",
    "q.m04#1.o0" to "薄く一様で、天気は安定",
    "q.m04#1.o1" to "垂直に発達し、頂部がかなとこ状になる。雷雨と強い降水の前触れ",
    "q.m04#1.o2" to "層状に広がり、霧雨だけをもたらす",
    "q.m04#1.o3" to "糸を引くように広がり、好天を示す",
    "q.m04#1.e" to "積乱雲の垂直発達は対流が強いことを示し、頂部が高層の風でかなとこ状に押し流されていれば成熟段階に達しています。高所でこれに出会えば、雷、雹、強い降水が起こりえます。露出した稜線と高みから直ちに離れるべきです。",

    "q.m04#2.p" to "登山でよく使われる地形図の縮尺はどれですか。",
    "q.m04#2.o0" to "1:1,000 と 1:5,000",
    "q.m04#2.o1" to "1:50,000 と 1:10,000",
    "q.m04#2.o2" to "1:250,000 と 1:500,000",
    "q.m04#2.o3" to "どの縮尺でもよい",
    "q.m04#2.e" to "1:50,000 と 1:10,000 が登山の常用縮尺です。前者は範囲が広く行程計画に向き、後者は細部が豊かでテクニカルな地形に向きます。1:200,000 はたまに使い、1:10,000 はさらに少ない——1 枚の範囲が狭すぎて、すぐ図の外に出てしまうからです。",

    "q.m04#3.p" to "地形図で等高線が密なところは、何を表しますか。",
    "q.m04#3.o0" to "傾斜が緩い",
    "q.m04#3.o1" to "傾斜が急",
    "q.m04#3.o2" to "谷である",
    "q.m04#3.o3" to "氷河がある",
    "q.m04#3.e" to "等高線が密なほど、同じ水平距離での高低差が大きい、つまり急です。この判読力はルート計画で実用的で、出発前に急斜面の区間、平坦地、キャンプに使えそうな場所を書き込んでおけます。",

    "q.m04#4.p" to "地形図に閉じた等高線が現れたとき、何を意味しますか。",
    "q.m04#4.o0" to "湖",
    "q.m04#4.o1" to "独立した山体",
    "q.m04#4.o2" to "氷河",
    "q.m04#4.o3" to "崖",
    "q.m04#4.e" to "閉じた等高線は、山体のまわり全体に独立した下り斜面の輪郭があることを意味し、これが「独立峰」の定義の根拠になります。同心の閉曲線が複数あれば、山体が段階的に高くなっていることを表し、最も内側の輪が山頂部です。",

    "q.m04#5.p" to "【複数選択】コンパス（方位磁針）を使うときの注意点はどれですか。",
    "q.m04#5.o0" to "できるだけ水平に保つ",
    "q.m04#5.o1" to "磁性体に近づけない",
    "q.m04#5.o2" to "磁針の S 端を北と誤認しない",
    "q.m04#5.o3" to "活動地域の磁気偏角で補正する",
    "q.m04#5.o4" to "安定のためザックの金属バックルに近づける",
    "q.m04#5.e" to "四つとも教本が明示している注意点です。とくに「S 端を北と誤認する」と 180° の方向誤差になります。地形が複雑なとき、こうした誤りはまったく逆の方へ歩かせてしまい、しかも自分では気づきにくいのです。",

    "q.m04#6.p" to "磁気偏角とは何ですか。",
    "q.m04#6.o0" to "コンパス自体の製造誤差",
    "q.m04#6.o1" to "磁北と真北のずれ。補正が必要",
    "q.m04#6.o2" to "標高が上がることで生じる角度変化",
    "q.m04#6.o3" to "地図投影によるひずみ",
    "q.m04#6.e" to "磁針は磁北を指し、地図は通常は真北を基準にしています。両者にはずれがあります。磁気偏角は地域によって異なり、地図とコンパスを組み合わせて位置を出すときは必ず補正しなければなりません。さもないとルート全体がずれます。",

    "q.m04#7.p" to "地形図の整った格子線は何を表しますか。",
    "q.m04#7.o0" to "経緯線",
    "q.m04#7.o1" to "UTM（ユニバーサル横メルカトル図法）の格子線",
    "q.m04#7.o2" to "等高線",
    "q.m04#7.o3" to "行政境界",
    "q.m04#7.e" to "地図の格子線は経緯線ではなく、UTM の格子線です。これは重要な区別です。地球は楕円体なので経緯度の網目は緯度によって大きさが変わり、UTM の格子は等間隔で、距離と座標を直接測れるからです。",

    "q.m04#8.p" to "GPS だけに頼ってはいけないのはなぜですか。",
    "q.m04#8.o0" to "GPS の精度が足りないから",
    "q.m04#8.o1" to "機器の電池切れ、浸水、破損、電波途絶がありうるから",
    "q.m04#8.o2" to "GPS は都市でしか使えないから",
    "q.m04#8.o3" to "GPS は有料だから",
    "q.m04#8.e" to "GPS は優れた補助具ですが、前提は「機器が使えること」です。高所の低温では電池の減りが速く、浸水や落下もよくあります。地図とコンパスは電気を要りません。いまも登山訓練の必修であり続ける理由です。",

    "q.m04#9.p" to "視界が急速に悪化したとき（霧、ホワイトアウト）、最も優先すべきは何ですか。",
    "q.m04#9.o0" to "速度を上げて早く歩き切る",
    "q.m04#9.o1" to "自分の位置と向きを直ちに確認し、必要ならその場で待つ",
    "q.m04#9.o2" to "計画どおりまっすぐ進み続ける",
    "q.m04#9.o3" to "手分けしてルートを探す",
    "q.m04#9.e" to "ホワイトアウトの最も危険な点は、視覚的な参照がすべて失われることです。人は本能的に誤った方向へ進んでしまいます。まず位置を確認し、向きを記録し、必要ならその場で待つほうが、無理に歩くよりはるかに安全です。手分けして探すのは、なおさら避けるべきです。",

    // ---------- m05 入門の山（10 問） ----------
    "q.m05#0.p" to "「トレッキング型」と「テクニカル型」の山の核心的な違いはどれですか。",
    "q.m05#0.o0" to "標高の高低",
    "q.m05#0.o1" to "技術装備とそれに伴う技術操作が必要かどうか",
    "q.m05#0.o2" to "所在する国",
    "q.m05#0.o3" to "許可が必要かどうか",
    "q.m05#0.e" to "分かれ目は技術要件であって、高さではありません。5,895 m のキリマンジャロは技術装備を要しませんが、5,396 m のハバ雪山は雪線以上でアイゼンとピッケルが要ります。標高は難度の一つの次元にすぎないのです。",

    "q.m05#1.p" to "キリマンジャロの最高点は何と呼ばれますか。",
    "q.m05#1.o0" to "ウフル峰",
    "q.m05#1.o1" to "キボ峰",
    "q.m05#1.o2" to "マウェンジ峰",
    "q.m05#1.o3" to "シラ峰",
    "q.m05#1.e" to "最高点はウフル峰（Uhuru Peak、5,895 m）です。キリマンジャロは休眠火山で、キボ、マウェンジ、シラの三つの火山錐からなり、キボ峰が最も高く、その最高点がウフル峰です。",

    "q.m05#2.p" to "キリマンジャロの最も独特な点はどれですか。",
    "q.m05#2.o0" to "世界で最も登る人が少ない 5,000 m 峰である",
    "q.m05#2.o1" to "赤道近くにありながら氷河を持ち、途中で熱帯雨林から高山荒原まで複数の気候帯を通過する",
    "q.m05#2.o2" to "非常に高度な技術装備が必要",
    "q.m05#2.o3" to "年に 1 か月しか登れない",
    "q.m05#2.e" to "赤道＋氷河という組み合わせが、キリマンジャロを「垂直の気候回廊」にしています。1 日のうちに雨林から氷河まで歩くのです。現実的な問題も伴います。行程の幅が大きく標高の上昇が速いため、かえって高所適応が主要な課題になります。",

    "q.m05#3.p" to "奥太娜（アオタイナ）はどの雪山群に属しますか。",
    "q.m05#3.o0" to "四姑娘山",
    "q.m05#3.o1" to "三奥雪山",
    "q.m05#3.o2" to "貢嘎山",
    "q.m05#3.o3" to "梅里雪山",
    "q.m05#3.e" to "三奥雪山は奥太基（群山の父）、奥太美（群山の母）、奥太娜（群山の子）の三峰からなり、四川の黒水に位置します。奥太娜は三峰で最も易しく、「人生最初の雪山」として選ばれることが多い山です。",

    "q.m05#4.p" to "奥太娜の標高について、正確な記述はどれですか。",
    "q.m05#4.o0" to "すべての資料が 4,800 m で一致している",
    "q.m05#4.o1" to "公式標高は 5,211 m だが実測は約 4,800 m で、出典により差がある",
    "q.m05#4.o2" to "公式標高は 4,800 m、実測は 5,211 m",
    "q.m05#4.o3" to "標高データに議論はなかった",
    "q.m05#4.e" to "こうした差は山の資料ではよくあります。公式の公表値、実測値、時期による測量基準の違いが重なるからです。実用的な意味は、山のデータを引くときは出典を明記すべきだということです。一つの数字を絶対の真実として扱ってはいけません。",

    "q.m05#5.p" to "四姑娘山の大峰と二峰の標高はそれぞれいくらですか。",
    "q.m05#5.o0" to "5,025 m と 5,276 m",
    "q.m05#5.o1" to "5,276 m と 5,025 m",
    "q.m05#5.o2" to "5,025 m と 5,355 m",
    "q.m05#5.o3" to "4,850 m と 5,276 m",
    "q.m05#5.e" to "大峰 5,025 m、二峰 5,276 m。この二つは入門の組み合わせとしてよく使われます。まず大峰で高所経験を積み、それから二峰へ。二峰の最後の区間は簡単な器材の助けが要り、テクニカル登攀へのちょうどよい橋渡しになります。",

    "q.m05#6.p" to "【複数選択】最初の雪山を選ぶとき、最も比べる価値がある要素はどれですか。",
    "q.m05#6.o0" to "ルートの成熟度と登頂率",
    "q.m05#6.o1" to "ガイドと救助資源が信頼できるか",
    "q.m05#6.o2" to "標高の上げ方が合理的か",
    "q.m05#6.o3" to "自分がいま持っている体力と使える時間",
    "q.m05#6.o4" to "SNS での話題性",
    "q.m05#6.e" to "この四つが「この山は今の自分に合うか」という問いへの完全な答えになります。標高の数字だけを見ると誤判断しがちです。5,000 m でも上昇のリズムが合理的で後方支援が確実な山は、5,500 m で三日連続で詰め込む山より安全なことがあります。",

    "q.m05#7.p" to "入門の山で登頂に失敗する、最も多い原因はどれですか。",
    "q.m05#7.o0" to "技術難度が高すぎる",
    "q.m05#7.o1" to "高山病と天候。技術難度ではない",
    "q.m05#7.o2" to "装備不足",
    "q.m05#7.o3" to "人数が足りない",
    "q.m05#7.e" to "ここが最も過小評価される点です。入門の山での失敗は、ほとんどが「歩けなくなった」「天気が待ってくれない」であって、「難所が越えられない」ではありません。だから入門段階で本当に必要なのは、適応、ペース、体力であって、技術動作ではないのです。",

    "q.m05#8.p" to "山を選ぶときに「登頂率」を見るべきなのはなぜですか。",
    "q.m05#8.o0" to "景観の質を表すから",
    "q.m05#8.o1" to "ルートの難度、上昇のリズム、支援体制の現実的な水準を総合的に反映するから",
    "q.m05#8.o2" to "登山費用が決まるから",
    "q.m05#8.o3" to "安全とは関係ないから",
    "q.m05#8.e" to "登頂率は多くの要素の結果です。ルートが難しいか、上昇のリズムが合理的か、天候の窓が広いか、後方支援が確実か。単なる「標高」より、実際に何に直面するかをよく映します。",

    "q.m05#9.p" to "「入門レベルの雪山」に対する正しい姿勢はどれですか。",
    "q.m05#9.o0" to "入門レベル＝リスクなし",
    "q.m05#9.o1" to "入門は技術難度が低いというだけで、高所と天候のリスクは現実に存在する",
    "q.m05#9.o2" to "入門レベルならガイドは不要",
    "q.m05#9.o3" to "入門レベルなら体力づくりは不要",
    "q.m05#9.e" to "「入門」が示すのは技術的な敷居であって、リスクの総量ではありません。高所そのもの、急変する天候、体力の使い切りは、どの標高でも命に関わります。入門を「楽」と理解することが、準備不足の始まりです。",

    // ---------- m06 技術登攀への入口（10 問） ----------
    "q.m06#0.p" to "テクニカル登攀の三大基本システムはどれですか。",
    "q.m06#0.o0" to "装備、体力、天候",
    "q.m06#0.o1" to "制動、確保、移動",
    "q.m06#0.o2" to "上昇、下降、休息",
    "q.m06#0.o3" to "アイゼン、ピッケル、ロープ",
    "q.m06#0.e" to "制動は「バランスを崩したあとどうするか」、確保は「万一落ちたら誰が受け止めるか」、移動は「危険地形をどう歩くか」を解決します。この三つで閉じた環になり、どれが欠けてもテクニカル登攀は成立しません。",

    "q.m06#1.p" to "テクニカル登攀を学ぶ根本的な目的はどれですか。",
    "q.m06#1.o0" to "より難しいルートを登るため",
    "q.m06#1.o1" to "制御できない滑落を、制御できるリスクに変えるため",
    "q.m06#1.o2" to "資格を取るため",
    "q.m06#1.o3" to "速く歩くため",
    "q.m06#1.e" to "技術は山の高さを下げません。変えるのは「失敗したあとどうなるか」です。制動があれば滑落は不可逆な災害ではなくなり、確保があれば一回のミスが即墜落にはなりません。ここに技術の本当の価値があります。",

    "q.m06#2.p" to "技術動作を身につける最も効果的な方法はどれですか。",
    "q.m06#2.o0" to "解説動画を繰り返し見る",
    "q.m06#2.o1" to "確保のある場所で実地に反復し、条件反射になるまで練習する",
    "q.m06#2.o2" to "教本を読んで要点を覚える",
    "q.m06#2.o3" to "実際の急斜面で一度で覚える",
    "q.m06#2.e" to "技術動作はプレッシャー下で実行するもので、プレッシャーは人を訓練した水準まで引き戻します。緩い斜面、柔らかい雪、下方が開けている、インストラクターの確保がある——この四条件が揃った場所だけが、技術を本当に身につけられる場です。",

    "q.m06#3.p" to "「動画を見てもセルフアレストは身につかない」と言われるのはなぜですか。",
    "q.m06#3.o0" to "動画の画質が悪いから",
    "q.m06#3.o1" to "プレッシャー下で本能として実行する動作で、反復練習による条件反射が必要だから",
    "q.m06#3.o2" to "動画の技術が間違っているから",
    "q.m06#3.o3" to "セルフアレストは実は簡単だから",
    "q.m06#3.e" to "滑落後に残される反応時間は 1〜2 秒で、考える余地はありません。筋肉の記憶は反復回数でしか買えません。だからこそ正規な講習は「考えずにできるまで」を求めるのです。",

    "q.m06#4.p" to "技術装備の入門三点セットはどれですか。",
    "q.m06#4.o0" to "ヘルメット、手袋、ゴーグル",
    "q.m06#4.o1" to "ブーツに合うアイゼン、ピッケル、ハーネス",
    "q.m06#4.o2" to "テント、寝袋、マット",
    "q.m06#4.o3" to "GPS、トランシーバー、ヘッドランプ",
    "q.m06#4.e" to "アイゼンはグリップを、ピッケルは制動と支えを、ハーネスはあなたを確保システムにつなぎます。共通点は、組み合わせて、仲間とシステムを組んで初めて安全上の価値が生まれることです。単体の装備は誰も守れません。",

    "q.m06#5.p" to "技術動作を覚えたあと、最も重要になる能力は何ですか。",
    "q.m06#5.o0" to "登る速さ",
    "q.m06#5.o1" to "「いつ技術装備を使わないで済むか」を判断する力",
    "q.m06#5.o2" to "装備の手入れ",
    "q.m06#5.o3" to "体力のさらなる向上",
    "q.m06#5.e" to "テクニカル登攀で最も直感に反する点です。技術はより難しい地形に入る勇気を与えますが、本当の上手い人は技術を使って「登らずに済む余地」を買います。判断力は常に実行力より上位にあります。",

    "q.m06#6.p" to "【複数選択】テクニカル登攀の範疇に入るものはどれですか。",
    "q.m06#6.o0" to "氷の斜面の歩行と制動",
    "q.m06#6.o1" to "ロープで結んで氷河を通過する",
    "q.m06#6.o2" to "ビレイステーションの構築",
    "q.m06#6.o3" to "懸垂下降",
    "q.m06#6.o4" to "整備された歩道のトレッキング",
    "q.m06#6.e" to "四つともテクニカル登攀です。いずれも装備、システム、専門的な訓練の組み合わせを要します。一方、雪面を歩くだけ、整備された登山道を行くだけならテクニカル登攀ではありません。違いは、これらのシステムが必要かどうかにあります。",

    "q.m06#7.p" to "技術力が判断力の代わりにならないのはなぜですか。",
    "q.m06#7.o0" to "技術力は訓練できないから",
    "q.m06#7.o1" to "判断を誤れば本来入るべきでない地形に入り、技術が高くても挽回できないから",
    "q.m06#7.o2" to "判断力のほうが学びやすいから",
    "q.m06#7.o3" to "技術はロッククライミングにしか使えないから",
    "q.m06#7.e" to "技術は「すでに危険の中にいる」ときに使うもので、判断は「危険に入るかどうか」を決めます。多くの事故の振り返りが示すのは、問題は「動作を間違えた」ことではなく、「そもそもそこにいるべきでなかった」ことだという点です。",

    "q.m06#8.p" to "【並べ替え】テクニカル登攀の学習順序を、合理的な論理で並べてください。",
    "q.m06#8.o0" to "装備を知る：アイゼン、ピッケル、ハーネスの構造と使い方",
    "q.m06#8.o1" to "安全な場所で基本動作を反復する（セルフアレストなど）",
    "q.m06#8.o2" to "ロープシステムを学ぶ：結び、ロープ隊、ビレイステーション",
    "q.m06#8.o3" to "実際だが制御できるルートで総合的に使う",
    "q.m06#8.e" to "この順序の背景は「まず自分を守れるようになり、次に他人とつながり、最後に実際の環境へ入る」です。どの段階を飛ばしても能力に断層ができます。たとえば制動を練らないままロープで結んで氷河に入れば、リスクは隊全体に増幅されます。",

    "q.m06#9.p" to "このユニットで何が完了しましたか。",
    "q.m06#9.o0" to "高山登攀の訓練すべてを終えた",
    "q.m06#9.o1" to "環境科学と装備の基礎を固め、技術動作の学習に入る準備ができた",
    "q.m06#9.o2" to "8,000 m 級の準備が完了した",
    "q.m06#9.o3" to "救助能力の認定を取得した",
    "q.m06#9.e" to "5,000 m 入門ユニットの役割は「土台を固める」ことでした。環境科学、装備、ウェア、体力、環境配慮、天気とナビゲーション、そして最後にテクニカル登攀へ橋を架けます。次のユニットから、アイゼン、ピッケル、制動、ロープを本格的に学びます。",

    // ---------- m07 ビレイステーションの設計 ----------
    "q.m07#0.p" to "ビレイステーションの設計における中心的な考え方はどれですか。",
    "q.m07#0.o0" to "器材をできるだけ節約すること",
    "q.m07#0.o1" to "どの支点が破断しても、システム全体が崩壊しないこと",
    "q.m07#0.o2" to "できるだけ高い位置にステーションを構築すること",
    "q.m07#0.o3" to "天然の支点だけを使うこと",
    "q.m07#0.e" to "岩や雪の支点の信頼性は、絶対的な確実さとして保証できません。だからこそシステムの設計目標は「絶対的な強固さ」ではなく「破断を許容する」ことになります。この点を押さえると、以降のすべての原則（冗長性、均等化、ノーエクステンション）は、その具体的な展開にすぎないと分かります。",

    "q.m07#1.p" to "二つの支点のなす角が 90° のとき、各支点はおよそ何割の荷重を負担しますか。",
    "q.m07#1.o0" to "約 50%",
    "q.m07#1.o1" to "約 58%",
    "q.m07#1.o2" to "約 71%",
    "q.m07#1.o3" to "約 100%",
    "q.m07#1.e" to "これは教本の表にある重要な数値です。角度 0° で各点ほぼ 50%、60° で約 58%、90° で約 71%。角度が開くほど、同じ人間がぶら下がっても各点にかかる力は大きくなります。これが支点の選び方と配置を直接左右します。",

    "q.m07#2.p" to "力のかかり方から見て、支点どうしの角度はどう処理すべきですか。",
    "q.m07#2.o0" to "できるだけ小さくし、力の方向をそろえる",
    "q.m07#2.o1" to "できるだけ大きくし、別々の方向に分散させる",
    "q.m07#2.o2" to "必ず 90° を保つ",
    "q.m07#2.o3" to "角度は力のかかり方に影響しない",
    "q.m07#2.e" to "角度が小さいほど二点の分担は 50 対 50 に近づき、角度が開くと各点の負担は増えます。現場でよく言われる「スリングの角度は 60° 以内に」というのは、まさにこの数値から導かれた経験値です。",

    "q.m07#3.p" to "【複数選択】ビレイステーションを評価するとき、考慮すべき観点はどれですか。",
    "q.m07#3.o0" to "強固：各支点の強度が十分であること",
    "q.m07#3.o1" to "冗長：互いに独立した複数の支点があること",
    "q.m07#3.o2" to "均等：荷重が合理的に配分されていること",
    "q.m07#3.o3" to "非伸長：ある支点が破断しても衝撃的な伸びが生じないこと",
    "q.m07#3.o4" to "対称：配置が整っていて見た目のバランスがよいこと",
    "q.m07#3.e" to "この四項目がステーション評価の基本の枠組みです。とくに見落とされやすいのが「非伸長」です。支点どうしに緩みを残すと、一点が外れた瞬間に残りの点へ急激な衝撃荷重がかかります。衝撃力は静的荷重よりはるかに大きく、ここに気づかない人が少なくありません。",

    "q.m07#4.p" to "【組み合わせ】支点の種類と、対応する媒体・設置方法を結びつけてください。",
    "q.m07#4.l0" to "天然支点",
    "q.m07#4.l1" to "雪上の支点",
    "q.m07#4.l2" to "氷上の支点",
    "q.m07#4.r0" to "岩柱、大木、大きな岩——完全性と安定性の確認が必要",
    "q.m07#4.r1" to "スノーバー、デッドマン、T 字スロット——信頼性は雪質と埋設の質に大きく依存",
    "q.m07#4.r2" to "アイススクリュー——氷体が密実で、空洞や蜂窝状の部分がないことの確認が必要",
    "q.m07#4.e" to "三つの媒体には、三つのまったく異なる判断基準があります。事故の最も多い原因の一つが、岩場の経験をそのまま雪や氷の判断に持ち込むことです。たとえば「見た目は丈夫そう」は、雪の上ではほとんど根拠になりません。",

    "q.m07#5.p" to "次のうち「偽の冗長性」にあたるのはどれですか。",
    "q.m07#5.o0" to "強度の異なる二種類の器材を使う",
    "q.m07#5.o1" to "二つの支点が実際には同じクラック、同じ岩体に依存している",
    "q.m07#5.o2" to "支点どうしをスリングで結ぶ",
    "q.m07#5.o3" to "支点を三つ設置する",
    "q.m07#5.e" to "冗長性の本質は「独立して破断すること」です。二点が同じクラックを共有していれば、そのクラックが割れた瞬間に二点が同時に失われます。形の上では「二点」でも、実質は一点です。よくある、そして致命的な偽の冗長性です。",

    "q.m07#6.p" to "あらかじめ張って「非伸長」にするのはなぜですか。",
    "q.m07#6.o0" to "見た目が整うから",
    "q.m07#6.o1" to "ある支点が破断したとき、残りの点に突然の衝撃荷重がかかるのを避けるため",
    "q.m07#6.o2" to "スリングの長さを節約するため",
    "q.m07#6.o3" to "撤収を速くするため",
    "q.m07#6.e" to "衝撃荷重は静的荷重よりはるかに大きく、同じ人間でも急に力がかかる場合と静的につり下がる場合では桁が違います。緩みを残したステーションは「柔軟で余裕がある」ように見えて、実際には一度の破断をシステム全体への衝撃に増幅しています。",

    "q.m07#7.p" to "【並べ替え】ビレイステーションを構築する手順を、合理的な順序に並べてください。",
    "q.m07#7.o0" to "周囲を観察し、使えるうえで互いに独立した支点の位置を選ぶ",
    "q.m07#7.o1" to "一つずつ支点を設置し、各点そのものが強固であることを確認する",
    "q.m07#7.o2" to "スリングやロープで各点を連結し、角度を整えてあらかじめ張る",
    "q.m07#7.o3" to "システム全体を点検し、偽の冗長性も伸長もないことを確認する",
    "q.m07#7.e" to "この順序の背後には「まず位置を選び、次に単点を作り、それからシステムとして連結し、最後に再確認する」という流れがあります。確認を最後に置くのは形式ではありません。組み立て中は各点の作業に意識が向くぶん、全体の関係（二点が実は同源であるなど）を見落としやすいからです。",

    "q.m07#8.p" to "天然支点を使うとき、もっとも確認すべきことは何ですか。",
    "q.m07#8.o0" to "十分に大きいかどうか",
    "q.m07#8.o1" to "完全性——ぐらついていないか、風化していないか、本体から離れていないか",
    "q.m07#8.o2" to "見た目がよいかどうか",
    "q.m07#8.o3" to "スリングを掛けやすいかどうか",
    "q.m07#8.e" to "天然支点の危険は「大きく見えるが、すでに動いている」ことにあります。判断の要点は、本体と本当につながっているか、岩体に亀裂や風化の兆候がないかです。大きい、太い、目立つ、はいずれも強固さの証明にはなりません。",

    "q.m07#9.p" to "ビレイステーションはなぜできるだけ速く構築すべきですか。",
    "q.m07#9.o0" to "体力を節約するため",
    "q.m07#9.o1" to "構築している時間そのものが、リスクにさらされている時間だから",
    "q.m07#9.o2" to "同行者が急かすから",
    "q.m07#9.o3" to "装備を紛失しやすいから",
    "q.m07#9.e" to "ステーションを組むとき、あなたはしばしば無防備か、十分でない確保の状態にあります。この「露出時間」は短いほどよい。だからステーション評価では、強固・冗長・均等に加えて「効率」と「迅速さ」も見るのです。",

    "q.m07#10.p" to "雪上の支点の信頼性は、主に何によって決まりますか。",
    "q.m07#10.o0" to "器材のブランド",
    "q.m07#10.o1" to "雪質と埋設の質",
    "q.m07#10.o2" to "標高",
    "q.m07#10.o3" to "ロープの色",
    "q.m07#10.e" to "同じスノーバーやデッドマンでも、深い雪、湿った雪、スノーブリッジの縁では支持力が大きく違います。雪の支点は、その場で雪層の構造を判断する必要があり、決まった手順をそのまま当てはめるわけにはいきません。だからこそ雪上の確保は、技術度の高い部分の一つなのです。",

    "q.m07#11.p" to "ビレイステーションが単一の支点しかない場合、最大の問題は何ですか。",
    "q.m07#11.o0" to "かかる力が大きすぎる",
    "q.m07#11.o1" to "破断を許容する余地がまったくない——その点の破断がそのままシステムの破断になる",
    "q.m07#11.o2" to "操作しにくい",
    "q.m07#11.o3" to "見た目がよくない",
    "q.m07#11.e" to "単点のステーションは「命を、不確実な一つの要素に完全に預ける」ことを意味します。現実には単点しか取れない場面（信頼できるアイススクリューが一本だけ、など）もあります。その場合の作法は、それを可能なかぎり確実に仕上げ、その上に身を置く時間を最小にすることです。",

    // ---------- m08 5,000 m 級の目標峰 ----------
    "q.m08#0.p" to "崗什卡（ガンシカ）主峰の標高はいくらですか。",
    "q.m08#0.o0" to "5,005 m",
    "q.m08#0.o1" to "5,150 m",
    "q.m08#0.o2" to "5,254.5 m",
    "q.m08#0.o3" to "5,396 m",
    "q.m08#0.e" to "主峰は 5,254.5 m です。この数値の階層に注目してください。三峰 5,005 m < 衛峰 5,150 m < 主峰 5,254.5 m。三つの高度が三つの難度に対応しており、だからこそ崗什卡は「段階的に進む」目標としてよく選ばれます。",

    "q.m08#1.p" to "崗什卡三峰の標高と位置づけはどれですか。",
    "q.m08#1.o0" to "5,005 m、初級テクニカル、初心者の登頂率は約 95%",
    "q.m08#1.o1" to "5,254 m、高難度テクニカル",
    "q.m08#1.o2" to "5,150 m、純粋なトレッキング",
    "q.m08#1.o3" to "5,396 m、氷河型",
    "q.m08#1.e" to "三峰は 5,005 m で初級テクニカルに分類されます。初心者の登頂率が約 95% ということは、ルートの難度が管理しやすく、後方支援も成熟しているということです。初めて本格的に技術装備を身につける場として、よく適しています。",

    "q.m08#2.p" to "崗什卡主峰の地理的な意味は何ですか。",
    "q.m08#2.o0" to "崑崙山脈の最高峰",
    "q.m08#2.o1" to "祁連山脈東段の最高峰",
    "q.m08#2.o2" to "青藏高原の最高峰",
    "q.m08#2.o3" to "横断山脈の最高峰",
    "q.m08#2.e" to "崗什卡は祁連山脈東段の最高峰で、青海省海北州門源県にあります。国内でも都市からもっとも近い高所雪山の一つであり、この交通の便のよさが、訓練峰としての普及度を直接押し上げています。",

    "q.m08#3.p" to "崗什卡三峰の歩行距離とおよその所要時間はどれですか。",
    "q.m08#3.o0" to "約 3 km／2 時間",
    "q.m08#3.o1" to "約 10 km／6 時間",
    "q.m08#3.o2" to "約 25 km／2 日",
    "q.m08#3.o3" to "約 1 km／30 分",
    "q.m08#3.e" to "約 10 km、約 6 時間です。この強度は最初のテクニカル登攀の目標としてちょうどよく、長時間の消耗で押し切るのではなく、技術操作と判断に力を注げる配分になっています。",

    "q.m08#4.p" to "哈巴雪山（ハバ雪山）の標高はいくらですか。",
    "q.m08#4.o0" to "5,005 m",
    "q.m08#4.o1" to "5,254 m",
    "q.m08#4.o2" to "5,396 m",
    "q.m08#4.o3" to "5,642 m",
    "q.m08#4.e" to "哈巴雪山は 5,396 m、雲南省香格里拉にあります。その価値は、雪線より上に本物の氷の斜面があり、アイゼンとピッケルを要する一方で、6,000 m 級のような厳しい高所順応の負担を伴わない点にあります。",

    "q.m08#5.p" to "哈巴雪山が登攀者に求める技術的なポイントは、主にどこに現れますか。",
    "q.m08#5.o0" to "フリークライミングの能力が必要",
    "q.m08#5.o1" to "雪線より上に氷の斜面があり、アイゼンとピッケルが必要",
    "q.m08#5.o2" to "潜水の能力が必要",
    "q.m08#5.o3" to "技術装備はまったく不要",
    "q.m08#5.e" to "哈巴のキーワードは「雪線より上に氷の斜面がある」ことです。つまりアイゼンで氷の上を安定して移動し、ピッケルで支持と制動を行える必要があります。これはまさに、5,000 m 級ステップの直前の数課で扱ってきた内容です。",

    "q.m08#6.p" to "エルブルス山の標高と位置づけはどれですか。",
    "q.m08#6.o0" to "5,642 m、ヨーロッパ最高峰",
    "q.m08#6.o1" to "5,895 m、アフリカ最高峰",
    "q.m08#6.o2" to "5,254 m、祁連山脈の最高峰",
    "q.m08#6.o3" to "6,178 m、崑崙山脈の高峰",
    "q.m08#6.e" to "エルブルス山は 5,642 m、ヨーロッパ最高峰で、ロシアのコーカサス山脈にあります。登攀体系のなかでの位置は独特です。高度は 5,000 m 級でありながら、氷河の行進とアンザイレンが必要で、トレッキング型からテクニカル型への典型的な渡り場になります。",

    "q.m08#7.p" to "エルブルスが登攀者に求める基本条件は何ですか。",
    "q.m08#7.o0" to "体力だけでよい",
    "q.m08#7.o1" to "アイゼンとピッケルが必要で、氷河行進とアンザイレンが基本条件",
    "q.m08#7.o2" to "人工酸素が必要",
    "q.m08#7.o3" to "フリークライミングの能力が必要",
    "q.m08#7.e" to "エルブルスのルートは氷河を通過するため、アンザイレン、クレバスへの意識、アイゼンの操作がすべて基本条件になります。キリマンジャロと並べて語られることが多いのも、同じ 5,000 m 級でありながら、一方は純粋なトレッキング、他方は本物の技術操作を要するからです。",

    "q.m08#8.p" to "【複数選択】トレッキング型からテクニカル型へ移るとき、優先して補うべき能力はどれですか。",
    "q.m08#8.o0" to "技術装備の正しい使い方（アイゼン、ピッケル、ハーネス）",
    "q.m08#8.o1" to "滑落制動などの基本技術動作",
    "q.m08#8.o2" to "アンザイレンでの行進と基礎的な確保システム",
    "q.m08#8.o3" to "「どこで続けるのをやめるか」を判断する力",
    "q.m08#8.o4" to "より高価な装備を買うこと",
    "q.m08#8.e" to "前三項は「能力」、第四項は「制約」です。多くの人は前三項だけを補い、その結果、技術が上達するほど大胆に歩けるようになり、かえってリスクを上げてしまいます。技術の訓練と判断の訓練は同時に進める必要があり、このステップで技術課と山峰課を並べている理由もそこにあります。",

    "q.m08#9.p" to "【並べ替え】次の目標峰を、難度の低い順に並べてください。",
    "q.m08#9.o0" to "奥太娜（トレッキング型、技術難度ゼロ）",
    "q.m08#9.o1" to "崗什卡三峰（初級テクニカル）",
    "q.m08#9.o2" to "哈巴雪山／エルブルス（混合型、アイゼンとアンザイレンが必要）",
    "q.m08#9.o3" to "玉珠峰南坡（6,000 m 級の混合型）",
    "q.m08#9.e" to "この道筋の要点は「一度に新しい変数を一つだけ加える」ことです。技術ゼロ → 技術装備に触れる → 実際の氷の斜面で使う → 高所を上乗せする。多くの人の問題は飛び級ではなく、難度と標高を同時に最大まで引き上げてしまい、自分がどこで躓いているのか分からなくなることです。",

    "q.m08#10.p" to "「三峰 → 主峰」が合理的な進階の道筋になるのはなぜですか。",
    "q.m08#10.o0" to "三峰が主峰にもっとも近いから",
    "q.m08#10.o1" to "同じ山の別ルートなら「技術難度」と「環境難度」という二つの変数を切り分けられるから",
    "q.m08#10.o2" to "主峰のほうが安いから",
    "q.m08#10.o3" to "三峰のほうが道に迷いやすいから",
    "q.m08#10.e" to "同じ山で進む利点は、天気、交通、後方支援、ガイドといった「環境の変数」がほぼ変わらないことです。だから難度の上昇がどこから来ているのかを明確に感じ取れます。逆に毎回山を変えると、問題が起きたときに技術不足なのか順応不足なのか分からなくなります。",

    "q.m08#11.p" to "5,000 m 級の進階目標を選ぶとき、正しい姿勢はどれですか。",
    "q.m08#11.o0" to "いちばん高い山を選び、一気に仕上げる",
    "q.m08#11.o1" to "「一度に新しい難度を一つだけ加える」原則で選び、信頼できる後方支援を優先して確保する",
    "q.m08#11.o2" to "いちばん安いものを選ぶ",
    "q.m08#11.o3" to "登頂率だけを見て、技術要件は見ない",
    "q.m08#11.e" to "登攀能力の伸びは累積的で、一度の「飛び級」はリスクを増幅させます。信頼できる後方支援（ガイド、救助、撤退計画）は、入門段階に共通する安全の土台です。それは誤りを防いではくれませんが、誤りが致命的にならないようにしてくれます。",

    // ---------- m09 高所の薬 ----------
    "q.m09#0.p" to "高所の薬には、二つの基本的な目標があります。どれですか。",
    "q.m09#0.o0" to "高所病を治すこと、下降の代わりになること",
    "q.m09#0.o1" to "順応の速度を上げること、下山までの時間を稼ぐこと",
    "q.m09#0.o2" to "体力を上げ、持久力を高めること",
    "q.m09#0.o3" to "風邪を予防し、睡眠を改善すること",
    "q.m09#0.e" to "この二つの区別が非常に重要です。アセタゾラミドは前者（順応を速める）、デキサメタゾンとニフェジピンは後者（時間を稼ぐ）に属します。「時間を稼ぐ」薬を「治った」根拠にしてしまうのが、高所病の対応でもっとも危険な誤判断です。",

    "q.m09#1.p" to "デキサメタゾンは身体の順応過程に影響しますか。",
    "q.m09#1.o0" to "する。順応を速める",
    "q.m09#1.o1" to "しない。順応性にはまったく影響しない",
    "q.m09#1.o2" to "する。順応を遅らせる",
    "q.m09#1.o3" to "長期服用のときだけ影響する",
    "q.m09#1.e" to "教本ははっきり書いています。デキサメタゾンは脳浮腫の症状を和らげるだけで、順応性にはまったく影響せず、肺浮腫への治療作用もありません。つまり純粋に「時間を買う」薬であり、買った時間は下降に使わなければならないということです。",

    "q.m09#2.p" to "ニフェジピンでもっとも警戒すべき副作用は何ですか。",
    "q.m09#2.o0" to "眠気を催す",
    "q.m09#2.o1" to "血圧が急に下がり、急に立ち上がると失神することがある",
    "q.m09#2.o2" to "耳鳴りを起こす",
    "q.m09#2.o3" to "食欲を落とす",
    "q.m09#2.e" to "この副作用は現場で危険です。急斜面や夜間にテントを出るときに起立性低血圧で失神すれば、高所病そのものより直接的な結果になりかねません。教本は、ニフェジピンはトレッカーには役立つ場合があるが、登攀者にとって最良の選択ではない、とも述べています。",

    "q.m09#3.p" to "高所の薬について、正しい姿勢はどれですか。",
    "q.m09#3.o0" to "用量を覚えておけば自分で使ってよい",
    "q.m09#3.o1" to "薬の判断であり、医師の評価を受けたうえで指示に従って使う必要がある",
    "q.m09#3.o2" to "同行者どうしで分け合ってよい",
    "q.m09#3.o3" to "副作用は使用に影響しない",
    "q.m09#3.e" to "これらの薬には明確な適応、禁忌、副作用があります（ニフェジピンは降圧、アスピリンは出血リスク、デキサメタゾンはステロイド）。これは「高所の常識」ではなく医学的介入です。本課で「医師の指示」を繰り返している理由もここにあります。",

    "q.m09#4.p" to "デキサメタゾンを服用して症状が和らぎました。このときどうすべきですか。",
    "q.m09#4.o0" to "予定どおり上昇を続ける",
    "q.m09#4.o1" to "それでも上昇は続けず、できるだけ早く下山する",
    "q.m09#4.o2" to "用量を増やして上昇を続ける",
    "q.m09#4.o3" to "すぐに服薬をやめて観察する",
    "q.m09#4.e" to "薬は症状を消しますが、脳浮腫の原因（低酸素）はそのまま残っています。教本の結論は明確です。服薬で症状が和らいでも、標高を上げるべきではありません。原因を本当に取り除ける動作は下降だけです。",

    "q.m09#5.p" to "高山病の頭痛を和らげる目的でアスピリンを使う場合、どのような用法になりますか。",
    "q.m09#5.o0" to "痛くなってから飲む",
    "q.m09#5.o1" to "前もって始め、規則的に服用する予防的な用法",
    "q.m09#5.o2" to "就寝前にだけ服用する",
    "q.m09#5.o3" to "下降したあとにだけ服用する",
    "q.m09#5.e" to "教本の用法は、標高を上げる 1 日前から 1 日 3 回、1 回 320 mg、順応の過程が終わるまで、というものです。「痛くなってから飲む」のではなく、予防的に規則服用します。この二つの考え方はまったく別物です。",

    "q.m09#6.p" to "アセタゾラミドとデキサメタゾンの根本的な違いはどこにありますか。",
    "q.m09#6.o0" to "一方は安く、一方は高い",
    "q.m09#6.o1" to "一方は順応の速度を上げ、一方は症状を和らげるだけ",
    "q.m09#6.o2" to "一方は内服、一方は注射",
    "q.m09#6.o3" to "両者の作用はまったく同じ",
    "q.m09#6.e" to "この違いが、その後のすべての判断を決めます。飲んだのがアセタゾラミドなら、症状の改善は身体が実際に順応しつつあると理解できます。飲んだのがデキサメタゾンなら、改善は隠されただけです。どちらの場合に上昇を続けてよいか、答えは正反対になります。",

    "q.m09#7.p" to "【複数選択】高所の薬について、正しい認識はどれですか。",
    "q.m09#7.o0" to "薬は下降の代わりにはならない",
    "q.m09#7.o1" to "用量と投与の時機は医師の指導が必要",
    "q.m09#7.o2" to "薬ごとに狙う病態が異なり、混同してはいけない",
    "q.m09#7.o3" to "症状が薬で隠されると、判断はかえって難しくなる",
    "q.m09#7.o4" to "症状が和らげば、安心して上昇を続けてよい",
    "q.m09#7.e" to "この四つはすべて重要な認識です。とくに見落とされやすいのが「症状が隠されると判断が難しくなる」という点です。薬で症状が消えると、もっとも直接的な病状の指標を失います。残るのは歩容、意識、呼吸といったより客観的な指標だけなので、投薬後はむしろこの三つを厳しく見る必要があります。",

    "q.m09#8.p" to "「どの薬も飲まず、できるだけ早く下降する」がしばしば最も確実な選択になるのはなぜですか。",
    "q.m09#8.o0" to "薬がどれも効かないから",
    "q.m09#8.o1" to "下降は原因を直接取り除くが、薬は間接的な手段にすぎないから",
    "q.m09#8.o2" to "薬が高すぎるから",
    "q.m09#8.o3" to "薬が持ち運びにくいから",
    "q.m09#8.e" to "高所病の原因は低酸素であり、その低酸素は標高から直接もたらされます。下降は原因そのものを取り除きますが、薬は原因に対する身体の反応を変えるだけです。条件が許すかぎり、下降はつねに優先度がもっとも高い処置です。",

    "q.m09#9.p" to "【並べ替え】同行者に重い高所病を疑う症状が出たとき、合理的な処置の順序はどれですか。",
    "q.m09#9.o0" to "ただちに上昇を止め、意識・歩容・呼吸を評価する",
    "q.m09#9.o1" to "下山を手配する（少なくとも 1,000 m 下降）。必要なら酸素を投与する",
    "q.m09#9.o2" to "医療の監視下で、対応する薬（デキサメタゾンなど）を投与する",
    "q.m09#9.o3" to "すぐに下山できない場合は高圧酸素室を使い、救助を要請する",
    "q.m09#9.e" to "この順序は優先度を表しています。まず評価し、次に下降し、薬で補助し、最後に時間を稼ぐ手段です。現実にもっとも多い誤りは順序を逆にすること——薬を探すことに追われ、確定した治療である下降を忘れてしまうのです。",

    "q.m09#10.p" to "「あらかじめ医師と投薬計画を相談しておく」ことが、高所の行程でとくに重要なのはなぜですか。",
    "q.m09#10.o0" to "山では薬が買えないから",
    "q.m09#10.o1" to "山では専門的な意見をその場で得られず、嘔吐などで投与経路が変わることもあるから",
    "q.m09#10.o2" to "薬が期限切れになるから",
    "q.m09#10.o3" to "ガイドがそう指示するから",
    "q.m09#10.e" to "高所の現場には医師もいなければ検査手段もありません。さらに厄介なのは、患者が嘔吐していて内服できない場合があることです。つまり投薬計画は、用量、時機、投与経路、禁忌まで含めて、出発前に医師と詰めておかなければなりません。",

    "q.m09#11.p" to "【組み合わせ】薬と、その主な作用を結びつけてください。",
    "q.m09#11.l0" to "アセタゾラミド",
    "q.m09#11.l1" to "デキサメタゾン",
    "q.m09#11.l2" to "ニフェジピン",
    "q.m09#11.r0" to "順応の速度を上げる。予防に用いる",
    "q.m09#11.r1" to "頭蓋内圧を下げ、脳浮腫を和らげる",
    "q.m09#11.r2" to "肺動脈の収縮を和らげる。肺浮腫に用いる",
    "q.m09#11.e" to "三枚の札がそれぞれ別の区間を担います。アセタゾラミドは「順応」、デキサメタゾンは「脳」、ニフェジピンは「肺」です。まず患者がどの状況なのかを見分け、それからどの札を使うかを決める——すべての薬を「高所の薬」として一括りにしてはいけません。",

    // ---------- m10 天候の窓 ----------
    "q.m10#0.p" to "「天候の窓」とは何ですか。",
    "q.m10#0.o0" to "予報のなかで降水確率がいちばん低い日",
    "q.m10#0.o1" to "目標を安全に達成できる時間帯",
    "q.m10#0.o2" to "日照時間がいちばん長い時間帯",
    "q.m10#0.o3" to "風がもっとも弱い時間",
    "q.m10#0.e" to "天候の窓は複合的な概念で、「天候が許す」と「隊に完遂する力がある」の二条件を同時に満たす時間を指します。だから同じ気象条件でも、強い隊と弱い隊では窓の幅がまったく違います。窓は絶対ではなく相対なのです。",

    "q.m10#1.p" to "山岳地帯の天気予報の精度が相対的に限られるのはなぜですか。",
    "q.m10#1.o0" to "気象観測点が少なすぎるから",
    "q.m10#1.o1" to "地形が複雑で局地差が非常に大きく、同じ地域でも標高や斜面方位によって天気がまったく変わりうるから",
    "q.m10#1.o2" to "予報士が熱心でないから",
    "q.m10#1.o3" to "高所には気象データがないから",
    "q.m10#1.e" to "山岳地形による持ち上げ、遮へい、回り込みが、天気を小さいスケールで激しく分化させます。数キロ離れただけで別世界ということが普通にあります。だから地域予報はあくまで「背景」であり、判断の根拠になるのは現場の観察です。",

    "q.m10#2.p" to "雲が明らかに厚くなり、雲底が下がってきたとき、ふつう何を意味しますか。",
    "q.m10#2.o0" to "天気が回復する",
    "q.m10#2.o1" to "天気が悪化し、視界が急速に悪くなる可能性がある",
    "q.m10#2.o2" to "もうすぐ晴れる",
    "q.m10#2.o3" to "とくに意味はない",
    "q.m10#2.e" to "雲底が下がるのは湿度が上がり、持ち上げ凝結高度が下がっているということで、降水系の前兆であることが多いものです。山では同時に視界が急速に狭まることも意味し、それ自体が独立したリスクになります。",

    "q.m10#3.p" to "気圧は「数値」より「トレンド」のほうが意味を持つのはなぜですか。",
    "q.m10#3.o0" to "数値はいつも誤っているから",
    "q.m10#3.o1" to "天気の変化は気圧の変化の向きに駆動され、しかも標高によって基準値がそもそも違うから",
    "q.m10#3.o2" to "トレンドのほうが覚えやすいから",
    "q.m10#3.o3" to "数値の変動が大きすぎるから",
    "q.m10#3.e" to "同じ気圧の値でも、標高や場所が違えば意味はまったく異なり、単独で見ても参照系がありません。一方「下がり続けている」というトレンドは、どこでも同じ一つのことを指します。天気が悪化している、ということです。",

    "q.m10#4.p" to "ビューフォート風力階級の実用的な価値は、主にどこにありますか。",
    "q.m10#4.o0" to "風が専門的に見えること",
    "q.m10#4.o1" to "風速を体感でき伝達できる階級に置き換え、行動できるかどうかの判断と共有を助けること",
    "q.m10#4.o2" to "降水量を測ること",
    "q.m10#4.o3" to "気温を判断すること",
    "q.m10#4.e" to "風力は「言葉にできる」情報です。隊には「いま続行できるか」を判断する共通言語が必要です。ビューフォート階級は抽象的な風速を観察可能な現象（木の葉、雪粒、体感）に変え、判断を隊のなかで素早く共有できるようにします。",

    "q.m10#5.p" to "【複数選択】天気が悪化しつつあることを示す現場のサインはどれですか。",
    "q.m10#5.o0" to "気圧が下がり続けている",
    "q.m10#5.o1" to "雲が急速に厚くなり、雲底が下がっている",
    "q.m10#5.o2" to "風が明らかに強まり、向きが頻繁に変わる",
    "q.m10#5.o3" to "遠方に垂直に発達した積乱雲が見える",
    "q.m10#5.o4" to "気圧が上がり続け、風が次第に弱まっている",
    "q.m10#5.e" to "この四つが教本の体系で主要な悪化のサインです。共通する性質は「瞬間値」ではなく「トレンド」であること。だからこそ定時に観察する習慣がものを言います。比較があってはじめて、トレンドは意味を持ちます。",

    "q.m10#6.p" to "雷雨が発生したとき、もっとも避けるべき行動はどれですか。",
    "q.m10#6.o0" to "行進を止めて下山する",
    "q.m10#6.o1" to "尾根、山頂、開けた水面など、露出した場所にとどまる",
    "q.m10#6.o2" to "金属装備をまとめる",
    "q.m10#6.o3" to "低い姿勢でしゃがんで待つ",
    "q.m10#6.e" to "雷雨でもっとも危険なのは「周囲でもっとも高い目標になる」ことです。尾根や山頂はまさに最も露出した場所で、雷が近づいたらできるだけ早く離れなければなりません。同時に金属装備はまとめ、身体から距離を取ります。",

    "q.m10#7.p" to "頂上アタックが明け方の出発に組まれることが多いのはなぜですか。",
    "q.m10#7.o0" to "人混みを避けるため",
    "q.m10#7.o1" to "早朝はふつう一日で最も安定した時間帯で、午後は対流が強まり天気が悪化しやすいから",
    "q.m10#7.o2" to "明け方は体力が最もあるから",
    "q.m10#7.o3" to "日中は暑すぎるから",
    "q.m10#7.e" to "背景には天気の日変化があります。日中は日射が地面を温めて対流を生み、雲量と降水確率は午後に上がります。高強度で最重要の行進区間を明け方に置くことは、より寛容な天候の窓を確保する行為なのです。",

    "q.m10#8.p" to "天候の窓とターンアラウンドタイムの関係はどれですか。",
    "q.m10#8.o0" to "両者に関係はない",
    "q.m10#8.o1" to "ターンアラウンドタイムは天候の窓から設定すべきで、窓が狭くなれば繰り上がる",
    "q.m10#8.o2" to "ターンアラウンドタイムはつねに固定である",
    "q.m10#8.o3" to "天気がよければターンアラウンドタイムは不要である",
    "q.m10#8.e" to "ターンアラウンドタイムは固定の数字ではなく、その日の天候の窓から逆算するものです。登頂に何時間、下降に何時間、窓は何時から狭くなるのか——そこから「遅くとも何時に向きを変えるか」が導かれます。",

    "q.m10#9.p" to "【並べ替え】日常的な天気判断の手順を、合理的な順序に並べてください。",
    "q.m10#9.o0" to "出発前に地域予報と気圧のトレンドを確認する",
    "q.m10#9.o1" to "行進中に雲、風、視界の変化を定時に観察する",
    "q.m10#9.o2" to "現場の観察と予報を突き合わせ、トレンドの向きを判断する",
    "q.m10#9.o3" to "トレンドに応じて行程を調整するか、早めに引き返す",
    "q.m10#9.e" to "要点は第三段階です。多くの人は第二段階で止まり、「天気が変わりつつある気がする」と感じたまま、それを明確な判断と行動に変えません。観察が意思決定に結びつかなければ、観察しなかったのと同じです。",

    "q.m10#10.p" to "天候の窓が狭くなったとき、最初に放棄を検討すべきものは何ですか。",
    "q.m10#10.o0" to "安全装備",
    "q.m10#10.o1" to "登頂という目標そのもの",
    "q.m10#10.o2" to "隊のメンバー",
    "q.m10#10.o3" to "通信機器",
    "q.m10#10.e" to "これは優先順位の問題です。窓が「登頂」と「安全な下降」の両方を収めきれないなら、残すべきは安全な下降であり、捨てるべきは登頂です。この優先順位は山の上で場当たり的に考えるのではなく、出発前に決めておかねばなりません。",

    "q.m10#11.p" to "ホワイトアウトについて、正しい認識はどれですか。",
    "q.m10#11.o0" to "視界が悪いだけで危険はない",
    "q.m10#11.o1" to "視覚の参照をすべて失い、人は本能的に誤った方向へ進むため、まず位置の確認を優先する",
    "q.m10#11.o2" to "降水をもたらす",
    "q.m10#11.o3" to "夜間にしか起こらない",
    "q.m10#11.e" to "ホワイトアウトの本当の危険は「見えないこと」ではなく、「よく見えていると思い込むこと」にあります。視覚の参照を失うと方向感覚は体系的にずれます。だから最初にすべきは、歩き続けることではなく、位置と向きを確認し記録することです。",

    // ---------- m11 6,000 m 級の目標峰 ----------
    "q.m11#0.p" to "玉珠峰の標高と位置はどれですか。",
    "q.m11#0.o0" to "6,178 m、青海省ゴルムド、崑崙山脈東段",
    "q.m11#0.o1" to "6,206 m、チベット当雄、ニェンチェンタンラ山脈",
    "q.m11#0.o2" to "6,119 m、ネパール・クンブ",
    "q.m11#0.o3" to "6,189 m、ネパール・クンブ",
    "q.m11#0.e" to "玉珠峰は 6,178 m、青海省ゴルムド境内の崑崙山脈東段にあります。南坡のルートは比較的穏やかで交通の便もよく、6,000 m 級の最初の一歩として多くの人が選びます。",

    "q.m11#1.p" to "啓孜峰（チーズィ峰）の標高と所属山脈はどれですか。",
    "q.m11#1.o0" to "6,178 m、崑崙山脈",
    "q.m11#1.o1" to "6,206 m、ニェンチェンタンラ山脈",
    "q.m11#1.o2" to "6,119 m、ヒマラヤ山脈",
    "q.m11#1.o3" to "6,189 m、カラコルム山脈",
    "q.m11#1.e" to "啓孜峰は 6,206 m、チベット当雄のニェンチェンタンラ山脈にあります。特長は雪の斜面が安定していて交通が便利なこと。安定した雪面は雪崩やクレバスのリスクを相対的に抑えられるため、進階の訓練に向いています。",

    "q.m11#2.p" to "ロブチェ東峰の標高と位置はどれですか。",
    "q.m11#2.o0" to "6,119 m、ネパール・クンブ地区",
    "q.m11#2.o1" to "6,189 m、ネパール・クンブ地区",
    "q.m11#2.o2" to "6,206 m、チベット当雄",
    "q.m11#2.o3" to "6,178 m、青海省ゴルムド",
    "q.m11#2.e" to "ロブチェ東峰は 6,119 m、ネパール・クンブ地区にあり、エベレストのトレッキングルートのすぐ脇に位置します。この立地は順応の条件と後方支援が成熟していることを意味し、雪の斜面はやや急で、より高い標高へ移るための良い足がかりになります。",

    "q.m11#3.p" to "島峰（イムジャ・ツェ）の最も典型的な技術的特徴は何ですか。",
    "q.m11#3.o0" to "技術装備はまったく不要",
    "q.m11#3.o1" to "アンザイレンとクレバス行進が必要",
    "q.m11#3.o2" to "人工酸素が必要",
    "q.m11#3.o3" to "フリークライミングの能力が必要",
    "q.m11#3.e" to "島峰は 6,189 m で、6,000 m 級の典型的なテクニカル峰です。アンザイレンが必要で、クレバスへの対応も求められます。7,000 m 級の準備としてよく選ばれる理由もここにあり、「氷河行進＋アンザイレン」というシステムを実際に使うからです。",

    "q.m11#4.p" to "6,000 m 級が 5,000 m 級に比べて、もっとも顕著に上がるリスクは何ですか。",
    "q.m11#4.o0" to "落石",
    "q.m11#4.o1" to "高所順応の負担（高所病のリスク）",
    "q.m11#4.o2" to "虫",
    "q.m11#4.o3" to "装備の重量",
    "q.m11#4.e" to "標高が 6,000 m に上がると、高所病の発生率と重症度は明らかに上がります。6,000 m ステップで高所病を中心章に据えている理由もここにあります。技術的には段階を踏むだけかもしれませんが、生理的な段差は実在します。",

    "q.m11#5.p" to "【複数選択】6,000 m 級に入る前に、すでに身につけているべき内容はどれですか。",
    "q.m11#5.o0" to "アイゼンとピッケルの基本的な使い方",
    "q.m11#5.o1" to "基礎的なロープワークとアンザイレンでの行進",
    "q.m11#5.o2" to "高所病の識別と対応の原則",
    "q.m11#5.o3" to "クレバスリスクについての基本的な理解",
    "q.m11#5.o4" to "WI5 の氷瀑を単独でリードできる能力",
    "q.m11#5.e" to "この四項目は、それぞれ 5,000 m の入門と進階の二つのステップに対応します。6,000 m ステップは学び直しではなく、すでに身につけた内容をより厳しい環境で使う場面です。基礎が固まらないまま 6,000 m に上がれば、リスクは何倍にも膨らみます。",

    "q.m11#6.p" to "「玉珠峰の南坡」が 6,000 m 級の最初の一歩とされることが多いのはなぜですか。",
    "q.m11#6.o0" to "いちばん安いから",
    "q.m11#6.o1" to "ルートが比較的穏やかで交通と後方支援が成熟しており、意識を順応に集中できるから",
    "q.m11#6.o2" to "危険がまったくないから",
    "q.m11#6.o3" to "ガイドが不要だから",
    "q.m11#6.e" to "最初の一歩の価値は「新しい変数を一つだけ増やす」ことにあります。南坡のルートは技術難度を管理可能な範囲に抑え、本当の課題である高所順応に集中させてくれます。技術的な敷居がすでに高い 6,000 m を選ぶと、どこに問題があるのか切り分けられません。",

    "q.m11#7.p" to "【並べ替え】次の目標峰を、標高の低い順に並べてください。",
    "q.m11#7.o0" to "ロブチェ東峰（6,119 m）",
    "q.m11#7.o1" to "玉珠峰（6,178 m）",
    "q.m11#7.o2" to "島峰（6,189 m）",
    "q.m11#7.o3" to "啓孜峰（6,206 m）",
    "q.m11#7.e" to "この四座の標高差は実はごくわずかです（6,119〜6,206 m、90 m 未満）。これは一つのことを示しています。6,000 m の帯では、山を選ぶ基準は標高ではなく、ルートの種類、後方支援の条件、そして自分の弱点だということです。",

    "q.m11#8.p" to "6,000 m 級では、なぜ「クレバスは存在するものとして扱う」必要があるのですか。",
    "q.m11#8.o0" to "クレバスが音を立てるから",
    "q.m11#8.o1" to "氷河のスノーブリッジは新雪に完全に覆われ、見た目は普通の雪面と変わらないから",
    "q.m11#8.o2" to "クレバスは夜にしか現れないから",
    "q.m11#8.o3" to "クレバスは容易に見分けられるから",
    "q.m11#8.e" to "ここがクレバスの最も恐ろしい点です。落石のように明らかな前兆を持ちません。だから 6,000 m 級の正しい心構えは「どこにでもあるものとして扱う」ことです。アンザイレンと装備でリスクを管理し、「見た目が安全」で判断してはいけません。",

    "q.m11#9.p" to "6,000 m 級で山を選ぶとき、標高より注目すべき指標は何ですか。",
    "q.m11#9.o0" to "山の知名度",
    "q.m11#9.o1" to "ルートの種類（トレッキング型／混合型／テクニカル型）、後方支援の条件、上昇のペース",
    "q.m11#9.o2" to "登山費用",
    "q.m11#9.o3" to "SNS での話題度",
    "q.m11#9.e" to "同じ標高帯の山でも、技術難度と順応の負担は大きく異なることがあります。「ルートの種類＋後方支援＋上昇ペース」の三つを組み合わせて見てはじめて、「この山は今の自分に適しているか」という答えが出ます。",

    "q.m11#10.p" to "「6,000 m 級の技術的な敷居」について、正しい認識はどれですか。",
    "q.m11#10.o0" to "技術的な敷居は低く、主に体力で決まる",
    "q.m11#10.o1" to "技術的な敷居は高くはないが、ゼロからでは駄目で、氷河行進の能力は必須",
    "q.m11#10.o2" to "クライミングの基礎が必須",
    "q.m11#10.o3" to "人工酸素の使い方を習得している必要がある",
    "q.m11#10.e" to "6,000 m 級の典型的な姿はこうです。技術難度は中程度だが、すでにアンザイレンができ、クレバスリスクを判断でき、氷河の上を自律して行進できなければなりません。「システムで自分を守れる」出発点であり、「人がどうやるかを見ている」段階ではありません。",

    "q.m11#11.p" to "高所の山で「最適な登攀シーズン」が行程にとって決定的なのはなぜですか。",
    "q.m11#11.o0" to "オフシーズンは入山料が安いから",
    "q.m11#11.o1" to "登攀できる窓が季節的な気象パターンに強く依存し、季節を外すと窓がほとんど存在しないことさえあるから",
    "q.m11#11.o2" to "季節が雪の色に影響するから",
    "q.m11#11.o3" to "ガイドが繁忙期しか働かないから",
    "q.m11#11.e" to "窓が生まれる理由は山によって異なります。モンスーンの降水を避ける山もあれば、冬季の極端な低温と強風を避ける山もあります。「なぜこの季節なのか」を理解することは、「何月に行くか」を覚えるよりはるかに重要です。気候変動によって、その法則自体がずれつつあるからです。",

    // ---------- m12 機械的優位のシステム ----------
    "q.m12#0.p" to "3:1 の Z システム（Z-drag）は、なぜ三倍の引力を得られるのですか。",
    "q.m12#0.o0" to "より太いロープを使うから",
    "q.m12#0.o1" to "摩擦結びとプーリーの組み合わせで、引く行程を三倍に増幅するから",
    "q.m12#0.o2" to "重力が助けてくれるから",
    "q.m12#0.o3" to "プーリー自体が自動的に力を軽減するから",
    "q.m12#0.e" to "機械的優位の本質は「行程と引き換えに力を得る」ことです。ロープを 3 m 引くと、引かれる物体は 1 m 上がる。代償は引き上げ速度が落ちることですが、クレバス救助ではこの代償は十分に受け入れられます。",

    "q.m12#1.p" to "救助システムにおけるプーリーの主な役割は何ですか。",
    "q.m12#1.o0" to "追加の強度を与える",
    "q.m12#1.o1" to "ロープの摩擦損失を減らし、システムの効率を上げる",
    "q.m12#1.o2" to "ロープを固定する",
    "q.m12#1.o3" to "ロープを摩耗から守る",
    "q.m12#1.e" to "摩擦は機械的優位の隠れた敵です。屈曲点を通るたびに力の一部が失われます。プーリーは滑り摩擦を転がり摩擦に変え、理論上の 3:1 を実際の 3:1 に近づけます。",

    "q.m12#2.p" to "プーリーがなければ、救助システムは組めませんか。",
    "q.m12#2.o0" to "まったく組めない",
    "q.m12#2.o1" to "カラビナで代用できるが、摩擦損失が明らかに増えて効率が落ちる",
    "q.m12#2.o2" to "ロープで直接代用でき、効率は同じ",
    "q.m12#2.o3" to "装備が届くまで待たなければならない",
    "q.m12#2.e" to "プーリーの代わりにカラビナを使うことはできます。だからこそ多くの隊が「予備のカラビナ」を必携品にしています。違いは、実際に得られる機械的優位が理論値より明らかに低くなること。これを知っておけば、装備が揃わないときに心と体力の準備ができます。",

    "q.m12#3.p" to "【複数選択】教本が挙げる、アンザイレン救助の一般的な装備はどれですか。",
    "q.m12#3.o0" to "スノーバーまたはアイススクリュー 2〜3 本",
    "q.m12#3.o1" to "カラビナ 2〜5 個とスリング 2〜5 本",
    "q.m12#3.o2" to "制動プーリー 1 個",
    "q.m12#3.o3" to "摩擦結び 2〜3 個とアッセンダー 1 個",
    "q.m12#3.o4" to "携帯ストーブ 1 台とガス缶",
    "q.m12#3.e" to "このリストの特徴は「アンザイレンの各員が十分な救助装備を用意すべき」という点です。つまり救助装備は隊で共有する公共物ではなく、各人の標準装備です。墜落が起きた瞬間、あなたが身につけているものが唯一使える装備だからです。",

    "q.m12#4.p" to "アッセンダーの制動原理は何ですか。",
    "q.m12#4.o0" to "ばねでロープを挟み込む",
    "q.m12#4.o1" to "鋼の歯とロープの間に生じる逆方向の摩擦で制動する",
    "q.m12#4.o2" to "磁力で吸着する",
    "q.m12#4.o3" to "ロープ自身の重さを利用する",
    "q.m12#4.e" to "原理を理解することは使い方に直結します。鋼の歯がロープの繊維を「噛む」仕組みなので、力を入れすぎるとロープを傷め、ひどい場合は受力点で繊維を切断します。教本が補助的な制動方法との併用を強調している理由もここにあります。",

    "q.m12#5.p" to "アッセンダーを力任せに扱うと、どんな結果になりますか。",
    "q.m12#5.o0" to "まったく影響はない",
    "q.m12#5.o1" to "鋼の歯がロープを傷める",
    "q.m12#5.o2" to "アッセンダーが固着する",
    "q.m12#5.o3" to "アッセンダーが外れる",
    "q.m12#5.e" to "アッセンダーは鋼の歯とロープの逆方向摩擦で制動するため、力を入れすぎるとシースに傷が残り、それが積み重なれば破断点になりえます。多くの人が習慣的にアッセンダーを強く引き上げていますが、それは習慣と引き換えにリスクを買う動作です。",

    "q.m12#6.p" to "【並べ替え】3:1 の Z システムを組むとき、合理的な順序はどれですか。",
    "q.m12#6.o0" to "ステーションが確実であることを確認し、墜落者の体重をステーションに移す",
    "q.m12#6.o1" to "受力側のロープにメインの摩擦結びを付け、バックアップの結びも加える",
    "q.m12#6.o2" to "摩擦結びにプーリーまたはカラビナを連結し、Z 字の経路を作る",
    "q.m12#6.o3" to "システム全体を確認してから引き上げを始め、引いた分だけ都度張り直す",
    "q.m12#6.e" to "第一段階はすべての土台です。先に体重を移さなければ、両手は制動を維持するために塞がれたままになります。そして最後の「引いた分だけ都度張り直す」は省略されがちで、その結果しばらく引いては滑り戻るを繰り返すことになります。",

    "q.m12#7.p" to "【組み合わせ】救助器材と、システム内での役割を結びつけてください。",
    "q.m12#7.l0" to "摩擦結び（プルージック）",
    "q.m12#7.l1" to "プーリー",
    "q.m12#7.l2" to "制動プーリー",
    "q.m12#7.l3" to "アッセンダー",
    "q.m12#7.r0" to "一方向にのみ把持し、システムが前進しても後退しないようにする",
    "q.m12#7.r1" to "摩擦損失を減らし、効率を上げる",
    "q.m12#7.r2" to "一方向にのみロックでき、送り出しと張りを制御する",
    "q.m12#7.r3" to "ロープを伝って上昇でき、システムの固定にも使える",
    "q.m12#7.e" to "四者はシステム内で役割が異なります。摩擦結びが「一方向性」を、プーリーが摩擦の低減を、制動器が制御を、アッセンダーが移動能力を担います。どれか一つ欠けると、システムは効率が落ちるか、制御できなくなります。",

    "q.m12#8.p" to "メインの摩擦結びとは別に、バックアップの結びを置くのはなぜですか。",
    "q.m12#8.o0" to "見た目のため",
    "q.m12#8.o1" to "結びは凍結、泥汚れ、ロープ径の不一致で効かなくなることがあり、そうなるとシステムは一瞬で機械的優位を失うから",
    "q.m12#8.o2" to "規範がそう定めているから",
    "q.m12#8.o3" to "ロープのよじれを防ぐため",
    "q.m12#8.e" to "摩擦結びは摩擦で働き、摩擦は多くの要因に左右されます。メインの結びが滑れば、墜落者は何の前触れもなく再び落下します。バックアップの結びは、その一瞬を受け止めるためのものです。",

    "q.m12#9.p" to "2:1 と 3:1 のシステムを比べたとき、選択の根拠は何ですか。",
    "q.m12#9.o0" to "2:1 がつねに優れている",
    "q.m12#9.o1" to "人力、ロープ長、地形の条件で選ぶ。機械的優位が大きいほど、必要なロープ長は長く、速度は遅くなる",
    "q.m12#9.o2" to "3:1 がつねに優れている",
    "q.m12#9.o3" to "両者はまったく同じ",
    "q.m12#9.e" to "機械的優位は無条件に良いわけではありません。3:1 はより多くのロープ長を必要とし、クレバス救助ではロープ長が限られていることが多い。だから実際の選択は「理論上の最適」ではなく「使えるロープ長と人力で完遂できるほう」になります。",

    "q.m12#10.p" to "機械的優位のシステムが判断の代わりにならないのはなぜですか。",
    "q.m12#10.o0" to "システムは壊れることがあるから",
    "q.m12#10.o1" to "システムは人力を増幅するだけで、引くべきか、どの方向へ引くかは判断できないから",
    "q.m12#10.o2" to "システムが重すぎるから",
    "q.m12#10.o3" to "多くの人手が必要だから",
    "q.m12#10.e" to "救助現場の本当の難しさは力学ではなく判断です。どこへ引くか、どのエッジを越えるか、傷病者が耐えられるか。システムは道具で、方向は人が決める。方向を誤れば、力が強いほど危険になります。",

    "q.m12#11.p" to "摩擦結びが効かなくなる一般的な原因に当てはまらないものはどれですか。",
    "q.m12#11.o0" to "ロープ径の不一致",
    "q.m12#11.o1" to "凍結や泥汚れ",
    "q.m12#11.o2" to "巻き数が不足している",
    "q.m12#11.o3" to "メインロープの色が薄い",
    "q.m12#11.e" to "ロープ径、清潔さ、巻き数はいずれも摩擦に直接影響しますが、色は力学とまったく関係ありません。これは同時に、摩擦結びの信頼性は外観からは判断できないことを示しています。事前の組み合わせ確認と現場でのテストに頼るしかありません。",

    "q.m12#12.p" to "システムで普通のプーリーではなく「制動プーリー」を使うことが多いのはなぜですか。",
    "q.m12#12.o0" to "軽いから",
    "q.m12#12.o1" to "一方向にロックでき、放出を制御しながらシステムの後退を防げるから",
    "q.m12#12.o2" to "安いから",
    "q.m12#12.o3" to "色が目立つから",
    "q.m12#12.e" to "救助では「引きながら調整する」場面がよくあります。普通のプーリーは両方向に自由なので、手を離せば後退します。一方向ロックの部品は「位置を保つ」ことをシステム自身の能力に変えます。器材の選択が操作の安全性を左右する一例です。",

    "q.m12#13.p" to "空欄を埋めてください。Z システムの機械的優位の比は（ ）:1 です。",
    "q.m12#13.a0" to "3",
    "q.m12#13.a1" to "三",
    "q.m12#13.e" to "3:1 です。この数字の実用的な価値は容量の見積もりにあります。成人一人と装備で 80〜100 kg になることがあり、3:1 でもなお約 30 kg の引力を要します。想像よりはるかに重労働で、救助が複数人の協力を要する理由もここにあります。",

    "q.m12#14.p" to "【複数選択】システム完成後の点検に含めるべきものはどれですか。",
    "q.m12#14.o0" to "摩擦結びの巻き数と受力方向が正しいか",
    "q.m12#14.o1" to "プーリーやカラビナのロックが閉じているか",
    "q.m12#14.o2" to "連結点がハーネスの正しい位置に付いているか",
    "q.m12#14.o3" to "バックアップが設置され、ロープの噛み込みがないか",
    "q.m12#14.o4" to "ロープと同行者の色が揃っているか",
    "q.m12#14.e" to "この四項目は四種類の典型的なミスに対応します。結びの向きが逆、ゲートが未ロック、誤ったギアランドへの連結、バックアップの欠落。救助システムのミスは「知らない」ことより「緊張と暗闇のなかで一手抜けた」ことから起きます。だから記憶ではなくチェックリストに頼ります。",

    "q.m12#15.p" to "救助システムはなぜ出発前に反復練習しておく必要があるのですか。",
    "q.m12#15.o0" to "考核のため",
    "q.m12#15.o1" to "実際の救助では、高所・低温・暗闇のなかで一連の複雑な操作を本能でこなす必要があるから",
    "q.m12#15.o2" to "器材に慣れるため",
    "q.m12#15.o3" to "規範が練習時間を定めているから",
    "q.m12#15.e" to "救助現場の条件はほとんどつねに最悪です。風が強く、手は冷え、光は乏しく、同行者は悪化している。そんな状況でできるのは、以前に何度も繰り返した操作だけです。その場で覚えることなど不可能です。",

    // ---------- m13 セルフレスキュー能力 ----------
    "q.m13#0.p" to "7,000 m 級で「セルフレスキュー能力」が必須条件とされるのはなぜですか。",
    "q.m13#0.o0" to "同行者が救助したがらないから",
    "q.m13#0.o1" to "高所環境では同行者が間に合わないことがあり、自分の状況は自分で処理できなければならないから",
    "q.m13#0.o2" to "救助装備が足りないから",
    "q.m13#0.o3" to "規則が定めているから",
    "q.m13#0.e" to "標高が上がるほど、救助の代償は大きく、時間は長くなります。相棒もまた自分の高所病と闘っているかもしれませんし、天気が一切の移動を許さないこともあります。外部救助に完全に委ねることは、保証されない前提を受け入れることです。",

    "q.m13#1.p" to "摩擦結びによる自己登攀の基本原理は何ですか。",
    "q.m13#1.o0" to "腕力で引き上げる",
    "q.m13#1.o1" to "二つの結びを交互に使い、一方が体重を受けている間に他方を上へ送る",
    "q.m13#1.o2" to "アッセンダー一つで完了する",
    "q.m13#1.o3" to "脚でロープを挟む",
    "q.m13#1.e" to "結び一つでは位置を固定できるだけで移動できません。だから二つを交互に使います。下が体重を受けたら上を送り、上が受けたら下を送る。この「交互」の動作は安全な場所で身につけておく必要があります。いちばん必要なときに、登れるかどうかを決めるからです。",

    "q.m13#2.p" to "摩擦結びで登攀するとき、なぜつねに少なくとも一つの結びが体重を受けている必要がありますか。",
    "q.m13#2.o0" to "力を節約するため",
    "q.m13#2.o1" to "二つ同時に緩めると、そのまま出発点まで滑り落ち、場合によっては墜落するから",
    "q.m13#2.o2" to "ロープを整えておくため",
    "q.m13#2.o3" to "上昇速度を上げるため",
    "q.m13#2.e" to "これが「三点支持」の原則をロープの上で実践した姿です。どんなときも確実な支持点を一つ残す。クレバスのなかでは、一度の滑落が体力を奪うだけでなく、ロープがさらに雪庇を切り込ませ、救助全体の難度を押し上げることがあります。",

    "q.m13#3.p" to "【並べ替え】アンザイレン救助の四段階を、正しい順序に並べてください。",
    "q.m13#3.o0" to "ただちに自己制動し、自分の体勢を安定させる",
    "q.m13#3.o1" to "独立したビレイステーションを構築する",
    "q.m13#3.o2" to "体重をステーションに移す",
    "q.m13#3.o3" to "3:1 システムで引き上げる",
    "q.m13#3.e" to "この四段階は 6,000 m ステップで学んだ内容です。ここで強調したいのは「プレッシャーの下で実行できること」。実戦と練習の最大の違いは、実戦では最初の三段階を数十秒で終えなければならないのに、練習では五分かけていた、という点にあります。",

    "q.m13#4.p" to "隊が雷雨に遭遇したとき、隊員どうしはどれくらい離れるべきですか。",
    "q.m13#4.o0" to "ぴったり寄り添う",
    "q.m13#4.o1" to "約 50 m",
    "q.m13#4.o2" to "約 500 m",
    "q.m13#4.o3" to "制限はない",
    "q.m13#4.e" to "教本は互いに 50 m ほど離れることを勧めています。狙いは、一発の落雷で複数人が同時に被災するのを避け、応急処置ができる人を残すことです。この数字の背後には「すべての賭け金を一か所に置かない」という考え方があります。",

    "q.m13#5.p" to "雷雨のとき、危険を減らす唯一有効な方法は何ですか。",
    "q.m13#5.o0" to "ピッケルなどの金属装備を捨てる",
    "q.m13#5.o1" to "できるだけ早く制高点と露出した区域から離れ、低い姿勢を保つ",
    "q.m13#5.o2" to "しゃがんで膝を抱える",
    "q.m13#5.o3" to "ファスナーをすべて開ける",
    "q.m13#5.e" to "教本はよくある方法をはっきり否定しています。ピッケルやテントポールのような小型の金属物が落雷を引き寄せるという証拠はないので、それらを捨てることに時間を使うべきではありません。有効なのは自分の位置を変えること——「周囲でもっとも高い目標」から「目立たない一部」になることです。",

    "q.m13#6.p" to "雷鳴が聞こえたとき、落雷地点は自分からどれくらいの距離以内ですか。",
    "q.m13#6.o0" to "約 3 km",
    "q.m13#6.o1" to "約 10〜16 km",
    "q.m13#6.o2" to "約 30 km",
    "q.m13#6.o3" to "約 50 km",
    "q.m13#6.e" to "雷鳴が聞こえるということは、落雷が 10〜16 km 以内にあり、すでに反応を要する範囲に入っているということです。一方、稲光が見えれば距離は約 24 km 以内。二つの数字は二つの異なる対応レベルに対応します。",

    "q.m13#7.p" to "稲光と雷鳴の時間差から、落雷までの距離をどう見積もりますか。",
    "q.m13#7.o0" to "秒数 × 0.34 ＝ 距離（km）",
    "q.m13#7.o1" to "秒数 ÷ 0.34 ＝ 距離（km）",
    "q.m13#7.o2" to "秒数 × 3.4 ＝ 距離（km）",
    "q.m13#7.o3" to "見積もれない",
    "q.m13#7.e" to "音は空気中を約 0.34 km/秒 で伝わります。だから稲光を見てから数えた秒数の一秒が、約 0.34 km に相当します。この方法の実用価値は、道具が一切なくても雷雨が近づいているか遠ざかっているかを判断できることです。",

    "q.m13#8.p" to "小型の金属装備（ピッケル、テントポール）は落雷を引き寄せますか。",
    "q.m13#8.o0" to "引き寄せる。ただちに捨てるべき",
    "q.m13#8.o1" to "引き寄せるという証拠はない。捨てることに時間を使うべきではない",
    "q.m13#8.o2" to "引き寄せるが、高い場所だけ",
    "q.m13#8.o3" to "濡れているときだけ",
    "q.m13#8.e" to "これは典型的な高所の俗説です。教本の姿勢は明快で、証拠はなく、貴重な時間を装備を捨てることに使うな、というものです。本当に必要なのは露出した位置から早く離れること。それが決定的な変数です。",

    "q.m13#9.p" to "雷雨のとき、もっともよい避難場所はどこですか。",
    "q.m13#9.o0" to "山頂",
    "q.m13#9.o1" to "山頂や尾根から離れた林の中央。ただし木に寄りかかってはいけない",
    "q.m13#9.o2" to "草地の中央",
    "q.m13#9.o3" to "テントの中",
    "q.m13#9.e" to "林の中央の特徴は、周囲により高い目標があり、しかも自分は導体に直接寄りかかっていないことです。反例は「開けた尾根にテントを張る」こと。教本はこれを極端に愚かだと断じています。自分から進んでその場でもっとも高い位置に泊まることになるからです。",

    "q.m13#10.p" to "積雲が発達しつつあるときに、尾根でテント泊を選んではいけないのはなぜですか。",
    "q.m13#10.o0" to "風が強いから",
    "q.m13#10.o1" to "積雲が積乱雲に発達すれば落雷を意味し、尾根はまさに最も露出した位置だから",
    "q.m13#10.o2" to "視界が悪いから",
    "q.m13#10.o3" to "地面が平坦でないから",
    "q.m13#10.e" to "積雲から積乱雲への発達は、しばしば一、二時間で進みます。尾根にテントを張ることは、雷雨の通り道の最先端に身を置くこと——しかも全装備とテントを抱え、ほとんど迅速に退避できない状態で。",

    "q.m13#11.p" to "落雷で人が倒れたとき、最初に行う処置は何ですか。",
    "q.m13#11.o0" to "まず外傷の有無を調べる",
    "q.m13#11.o1" to "ただちに呼吸と心拍を確認し、必要なら心肺蘇生を行い、できるだけ早く医療機関へ搬送する",
    "q.m13#11.o2" to "まず乾いた衣類に着替えさせる",
    "q.m13#11.o3" to "まず低い場所へ移動する",
    "q.m13#11.e" to "落雷は心停止や内傷を起こしうる一方、外見には異常が見えないことがあります。だから呼吸と心拍の確認を他の処置より優先し、しかも意識が清明でも必ず受診させます。電流の心臓への影響は遅れて現れることがあるからです。",

    "q.m13#12.p" to "【複数選択】セルフレスキュー能力には、ふつう何が含まれますか。",
    "q.m13#12.o0" to "摩擦結びによる自己登攀",
    "q.m13#12.o1" to "自己制動と自己確保",
    "q.m13#12.o2" to "相棒の助けなしで確保を構築すること",
    "q.m13#12.o3" to "いつ現場で待つべきか、いつ自力で脱出すべきかの判断",
    "q.m13#12.o4" to "無確保でフリークライミングできること",
    "q.m13#12.e" to "前三項は能力、第四項は判断です。とくに「いつ現場で待ち、いつ自力で脱出するか」を重視してください。すべての状況で自力脱出が正解とは限りません。すでに負傷していたり天気が悪化していたりすれば、むやみに動くよりその場で救助を待つほうが安全なことがあります。",

    "q.m13#13.p" to "「相棒が助けに来るのを待つ」を主要な安全戦略にできないのはなぜですか。",
    "q.m13#13.o0" to "相棒が助けたがらないから",
    "q.m13#13.o1" to "相棒自身も危険な状態、負傷、あるいは行動不能になっていることがあるから",
    "q.m13#13.o2" to "救助装備が足りないから",
    "q.m13#13.o3" to "規則が認めていないから",
    "q.m13#13.e" to "アンザイレンの意味は互いに守ることですが、相棒に必ず余力があると仮定はできません。高所では、一人が二人分の窮地に対応するのはしばしば能力を超えます。だからセルフレスキューは「必須」、相互救助は「加点」なのです。",

    // ---------- m14 危険の判断と意思決定 ----------
    "q.m14#0.p" to "危険の判断が本当に答えるべき問いは何ですか。",
    "q.m14#0.o0" to "危険があるかどうか",
    "q.m14#0.o1" to "このリスクは受け入れられるか、その根拠は何か",
    "q.m14#0.o2" to "危険はどれくらい大きいか",
    "q.m14#0.o3" to "同行者が怖がるかどうか",
    "q.m14#0.e" to "「危険があるか」の答えはほとんどつねに「ある」です。リスクゼロの山岳活動は存在しません。だから本当の判断は「得られるものと比べて、このリスクを引き受ける価値があるか、なぜそう考えられるのか」になります。これは判断が言葉にでき、議論できるものでなければならないことを意味します。",

    "q.m14#1.p" to "「事故の連鎖」とは何ですか。",
    "q.m14#1.o0" to "一つの事故の死傷者数",
    "q.m14#1.o1" to "複数の小さなミスが順に積み重なり、最終的に事故に至る過程",
    "q.m14#1.o2" to "救助のタイムライン",
    "q.m14#1.o3" to "装備が壊れていく連鎖",
    "q.m14#1.e" to "この概念の最も価値ある点は、事故を「不運」から「介入できる過程」に変えることです。連鎖のどの環で別の選択をしても、結果は変わります。",

    "q.m14#2.p" to "事故の連鎖を断ち切る最も有効な方法は何ですか。",
    "q.m14#2.o0" to "どの環であれ、より保守的な選択をする",
    "q.m14#2.o1" to "最後の環だけに注目する",
    "q.m14#2.o2" to "装備を増やす",
    "q.m14#2.o3" to "隊の体力を上げる",
    "q.m14#2.e" to "どの環でも構いません。朝早く出発する、時刻が来たら撤回する、時間を稼ぐために確保を簡略化しない。だからこそ「余裕を残す」は「後で取り戻す」より有効です。余裕は連鎖の早い段階に働き、取り戻しは最後の環で起きるからです。",

    "q.m14#3.p" to "【複数選択】よくある意思決定の偏りはどれですか。",
    "q.m14#3.o0" to "サンクコスト（埋没費用）",
    "q.m14#3.o1" to "隊のプレッシャー",
    "q.m14#3.o2" to "目標への執着",
    "q.m14#3.o3" to "リスクの正常化",
    "q.m14#3.o4" to "装備ブランドへの迷信",
    "q.m14#3.e" to "四つは重なって働きます。すでに多くを投入した（サンクコスト）＋仲間がみな上へ向かっている（隊のプレッシャー）＋あと少しだ（目標への執着）＋前回もこれで大丈夫だった（リスクの正常化）。この四つが同時に現れると、判断はほぼ必ず冒険側に傾きます。",

    "q.m14#4.p" to "サンクコストは登山の判断にどう影響しますか。",
    "q.m14#4.o0" to "慎重にさせる",
    "q.m14#4.o1" to "すでに多くの時間と費用を投じたので、撤退すべきだと認めたくなくなる",
    "q.m14#4.o2" to "体力を上げる",
    "q.m14#4.o3" to "影響しない",
    "q.m14#4.e" to "サンクコストの特徴は回収不能であることですが、心理的には「さらに投入する理由」に変わってしまいます。山の上で目標への執着と重なると、「理性的な撤退」が「諦め」にすり替わります。人は「諦める」ことに生理的な抵抗を持つからです。",

    "q.m14#5.p" to "「リスクの正常化」とは何ですか。",
    "q.m14#5.o0" to "危険を受け入れられる範囲に抑えること",
    "q.m14#5.o1" to "ある条件を何度も安全に通過するうちに、無意識にその条件を「安全」に分類し直してしまうこと",
    "q.m14#5.o2" to "リスク評価の方法を学ぶこと",
    "q.m14#5.o3" to "標準化されたリスク等級を使うこと",
    "q.m14#5.e" to "リスクの正常化はゆっくり進むので、本人はほとんど気づけません。同じ人が最初にある急斜面を渡るときは非常に慎重だったのに、十回目にはロープを結ばなくなっている。斜面は変わっておらず、変わったのは判断のほうです。",

    "q.m14#6.p" to "高リスク環境で「少数が多数に従う」ことに問題があるのはなぜですか。",
    "q.m14#6.o0" to "効率が悪すぎるから",
    "q.m14#6.o1" to "多数決では少数者の妥当な懸念が押しつぶされるから",
    "q.m14#6.o2" to "投票が公平とは限らないから",
    "q.m14#6.o3" to "隊の人数が揃わないから",
    "q.m14#6.e" to "危険のサインは一人か二人しか気づかないことが多く（雪層の亀裂を見た、など）、しかもその観察は「少数が持ち、しかし真なら致命的」な情報です。その採否を投票で決めることは、低確率・高影響のシグナルを体系的に無視することになります。",

    "q.m14#7.p" to "なぜ「最も保守的な意見を優先する」のですか。",
    "q.m14#7.o0" to "保守的な人が先輩だから",
    "q.m14#7.o1" to "不確実な状況では、保守的な選択の誤りの代償が、冒険的な選択の誤りの代償よりはるかに小さいから",
    "q.m14#7.o2" to "規則がそう定めているから",
    "q.m14#7.o3" to "全員を納得させるため",
    "q.m14#7.e" to "これは非対称な代償の典型例です。保守的なら空振りで終わるかもしれませんが、冒険的なら死に至るかもしれません。代償が非対称なとき、意思決定は代償が制御可能な側に倒すべきです。そしてその倒し方は、出発前に決めておかなければ現場では実行できません。",

    "q.m14#8.p" to "【組み合わせ】意思決定の偏りと、その典型的な表れを結びつけてください。",
    "q.m14#8.l0" to "サンクコスト",
    "q.m14#8.l1" to "隊のプレッシャー",
    "q.m14#8.l2" to "目標への執着",
    "q.m14#8.l3" to "リスクの正常化",
    "q.m14#8.r0" to "ここまで来たのに、今帰るのは惜しすぎる",
    "q.m14#8.r1" to "みんな続けたがっている。撤回と言い出しにくい",
    "q.m14#8.r2" to "あと最後の一区間だけだ",
    "q.m14#8.r3" to "前回もこのやり方で何も起きなかった",
    "q.m14#8.e" to "興味深いのは、この四つの言葉が事故の振り返りで極めて頻繁に現れ、しかも口にするのは経験豊富な登攀者が多いことです。これはこれらが「初心者の問題」ではなく、人の認知構造の問題であることを示しています。",

    "q.m14#9.p" to "「経験が豊富」が「判断が正確」と等しくないのはなぜですか。",
    "q.m14#9.o0" to "経験は人を遅くするから",
    "q.m14#9.o1" to "経験はリスクの受容度を少しずつ引き上げてしまうから",
    "q.m14#9.o2" to "経験は重要でないから",
    "q.m14#9.o3" to "熟練者は頑固だから",
    "q.m14#9.e" to "経験がもたらすのは「慣れ」であり、慣れは警戒心を下げます。だから経験豊富な隊ほど外部の制約（固定したターンアラウンドタイム、数値化した天候の基準）を必要とします。鈍った直感と戦うために、規則を使うのです。",

    "q.m14#10.p" to "【並べ替え】撤退を決める合理的な流れはどれですか。",
    "q.m14#10.o0" to "出発前に合意した客観的なシグナル（時刻、天気、隊員の状態）を確認する",
    "q.m14#10.o1" to "実際の状況がそのいずれかに触れていないかを照合する",
    "q.m14#10.o2" to "あらかじめ指名された決定者が撤退を宣言する",
    "q.m14#10.o3" to "撤退を実行し、後方に連絡する",
    "q.m14#10.e" to "この流れの価値は「まず基準を見て、それから状況を見る」ことにあります。逆にして状況を先に見ると、基準は現場の感情によって少しずつ書き換えられ、最後は「もう少し様子を見よう」になります。",

    "q.m14#11.p" to "あらかじめ「誰に撤退を言う権限があるか」を決めておくのはなぜですか。",
    "q.m14#11.o0" to "責任を追及しやすくするため",
    "q.m14#11.o1" to "現場では、隊の空気に逆らって行動できる人を自発的に生み出すのが難しいから",
    "q.m14#11.o2" to "隊長の威信を上げるため",
    "q.m14#11.o3" to "手順を記録するため",
    "q.m14#11.e" to "撤退は全隊の期待を否定する行為で、集団の空気のなかでは自発的に言い出しにくいものです。「撤退を言う」ことを個人の勇気ではなく、あらかじめ与えられた職責に変えることで、はじめて実際に起こせるようになります。",

    "q.m14#12.p" to "どのような場合に行程の中止を検討すべきですか。",
    "q.m14#12.o0" to "登頂の可能性があるかぎり中止すべきではない",
    "q.m14#12.o1" to "あらかじめ合意した客観的シグナルのいずれかに触れたとき",
    "q.m14#12.o2" to "隊員が負傷したときだけ",
    "q.m14#12.o3" to "体力が最も低い人が決める",
    "q.m14#12.e" to "「触れたら中止」が数値基準のすべての意味です。判断を「やるかどうか」から「触れたかどうか」に変えます。前者は議論と説得が必要ですが、後者は事実の確認だけで済む。だから現場で実行できるのです。",

    "q.m14#13.p" to "目標への執着に対抗する最も有効な方法は何ですか。",
    "q.m14#13.o0" to "個人の意志力に頼る",
    "q.m14#13.o1" to "出発前に基準を数値化し、「緩める」ことを同行者に説明すべき明示的な行為にする",
    "q.m14#13.o2" to "目標を設定しない",
    "q.m14#13.o3" to "装備を多く持つ",
    "q.m14#13.e" to "心理的な偏りは「気をつけよう」と自分に言い聞かせても避けられません。有効なのは、初期状態を「時刻が来たら撤退」に設定し、続けたい側が理由を述べる仕組みにすることです。これで立証責任が反転します。",

    "q.m14#14.p" to "「反対がない」が「全員の同意」と等しくないのはなぜですか。",
    "q.m14#14.o0" to "聞こえていない可能性があるから",
    "q.m14#14.o1" to "沈黙は隊の雰囲気を壊したくないだけで、本当の懸念が表明されていないことがあるから",
    "q.m14#14.o2" to "誰かが寝ているかもしれないから",
    "q.m14#14.o3" to "反対しても無効だから",
    "q.m14#14.e" to "だからよい隊は意識的に「反対を作り出します」。リーダーが「続けるべきでないと思う人は」と明確に問う、あるいは全員に順番に意見を言わせる。山の上での沈黙は同意ではなく、表明がなかったというだけです。",

    "q.m14#15.p" to "空欄を埋めてください。不確実な状況での意思決定では、最も（ ）意見を優先して採るべきです。",
    "q.m14#15.a0" to "保守的な",
    "q.m14#15.e" to "「保守優先」は現場でそのまま実行できる規則です。誰の論拠が強いかを判断する必要はなく、どの選択がより保守的かだけを見ます。代償は空振りに終わることですが、それは払う価値のある代償です。",

    "q.m14#16.p" to "シナリオ：7,000 m の登頂日、天候が悪化する",
    "q.m14#16.c" to "あなたたちは 7,000 m の登頂日、午前 3 時に出発しました。午前 8 時、頂上まで約 2 時間の地点に達しています。このとき風速が明らかに強まり、雲が西から急速に押し寄せ、気温が下がってきました。隊の一人に持続する咳が出はじめ、歩く速度が明らかに落ちています。",
    "q.m14#16.e" to "このシナリオの核心は個々の答えではなく順序です。まず事実を照合する → 危険のサインを識別する → 心理的な抵抗に対抗する → 撤退を適切に実行する。四段階のうち最も誤りやすいのは第一段階（飛ばされる）と第三段階（感情に乗っ取られる）です。",
    "q.m14#16.s0.p" to "第 1 段階：この瞬間、まず行うべき判断は何ですか。",
    "q.m14#16.s0.o0" to "隊の状態と天候のトレンドを確認し、出発前に合意した折り返しのシグナルと照合する",
    "q.m14#16.s0.o1" to "天候が悪化する前に登頂するため速度を上げる",
    "q.m14#16.s0.o2" to "その場で天候の回復を待つ",
    "q.m14#16.s0.o3" to "速度の遅い隊員だけ下山させる",
    "q.m14#16.s0.e" to "どんな意思決定も「事実の照合」から始まります。隊員の状態はどうか、天候は回復に向かっているのか悪化しているのか、あらかじめ定めたシグナルに触れていないか。この段階を飛ばして結論を出すのは、感情に判断を明け渡すことです。",
    "q.m14#16.s1.p" to "第 2 段階：隊員に持続する咳が出ています。最も合理的な対応はどれですか。",
    "q.m14#16.s1.o0" to "冷気に刺激されただけなので、そのまま歩かせる",
    "q.m14#16.s1.o1" to "高所では肺浮腫に関わる所見の可能性を強く警戒し、上昇を止めてできるだけ早く下山させる",
    "q.m14#16.s1.o2" to "咳止めを飲ませてから続行する",
    "q.m14#16.s1.o3" to "10 分休ませてから続行する",
    "q.m14#16.s1.e" to "7,000 m では、安静時や軽い動作での持続する咳は強い警戒を要するサインです。この標高では「もう少し様子を見る」の代償が、ただちに下山する代償をはるかに上回ることがあります。",
    "q.m14#16.s2.p" to "第 3 段階：頂上まで 2 時間という地点まで来て撤退を決めました。最大の心理的な抵抗は何ですか。",
    "q.m14#16.s2.o0" to "体力が足りないこと",
    "q.m14#16.s2.o1" to "サンクコストと目標への執着——「ここまで来たのに」",
    "q.m14#16.s2.o2" to "装備の問題",
    "q.m14#16.s2.o3" to "ルートに不慣れなこと",
    "q.m14#16.s2.e" to "ここにこそターンアラウンドタイムの意味があります。決定を理性的な状態のうちに済ませておくのです。「あと少し」が現れたとき、必要なのは再判断ではなく、あらかじめ決めた規則との照合です。",
    "q.m14#16.s3.p" to "第 4 段階：下山の間、隊はどう動くべきですか。",
    "q.m14#16.s3.o0" to "体力のある人が先に下り、キャンプで準備する",
    "q.m14#16.s3.o1" to "全員一緒に下り、最も状態のよい人が先頭でペースを管理し、隊員の状態を後方に伝える",
    "q.m14#16.s3.o2" to "速度を上げるため分かれて下山する",
    "q.m14#16.s3.o3" to "状態の悪い隊員を一人でゆっくり歩かせる",
    "q.m14#16.s3.e" to "高所では隊が分散した瞬間に相互の気づかいが失われ、しかも下山の区間こそ事故が集中します。隊でまとまって動く、ペースを管理する人がいる、後方が状況を知っている。この三つはどれも欠かせません。",

    // ---------- m15 天候の窓と雲の判読 ----------
    "q.m15#0.p" to "雲の判読の最も中心的な価値は何ですか。",
    "q.m15#0.o0" to "登山が専門的に見えること",
    "q.m15#0.o1" to "天気の変化に対する「余裕時間」を得られること",
    "q.m15#0.o2" to "気象予報の代わりになること",
    "q.m15#0.o3" to "標高を測ること",
    "q.m15#0.e" to "天気予報は一日前から分かりますが、山の天気は小さいスケールで急速に変わります。雲は「いま、あなたの頭の上にある予報」です。与えてくれる余裕は一、二時間かもしれませんが、その一、二時間こそ撤退するかどうかを決める窓になります。",

    "q.m15#1.p" to "積雲が垂直に発達していることは何を示しますか。",
    "q.m15#1.o0" to "天気が安定している",
    "q.m15#1.o1" to "対流が強く、積乱雲へ発達する可能性がある",
    "q.m15#1.o2" to "まもなく気温が下がる",
    "q.m15#1.o3" to "地上の風が弱まる",
    "q.m15#1.e" to "積雲そのものは危険ではありませんが、「いま育っている」というサインです。見るべき点は積雲かどうかではなく、大きくなっているか、高くなっているか、暗くなっているか。この過程そのものが、天気がエネルギーを蓄えている姿です。",

    "q.m15#2.p" to "積乱雲のかなとこ型の雲頂は何を意味しますか。",
    "q.m15#2.o0" to "まだ形成段階である",
    "q.m15#2.o1" to "成熟段階に達しており、落雷、雹、強い降水が起こりうる",
    "q.m15#2.o2" to "まもなく消滅する",
    "q.m15#2.o3" to "上空の風が強いだけ",
    "q.m15#2.e" to "かなとこ型の頂は、雲頂が上空の風に流されて平らになった形で、上昇流が対流圏界面に達してそれ以上高く上がれなくなったことを示します。まさに雷雨の成熟段階の印です。かなとこ型を見たら、反応できる時間はもうわずかです。",

    "q.m15#3.p" to "積雲の発生は一日のうちいつに集中しますか。",
    "q.m15#3.o0" to "明け方",
    "q.m15#3.o1" to "午前",
    "q.m15#3.o2" to "午後",
    "q.m15#3.o3" to "深夜",
    "q.m15#3.e" to "理由は日射です。地面が日中に温められ、上昇流と対流が生まれます。これが「早出発・早下山」という経験則の背後にある物理的な仕組みであり、単なる言い伝えではありません。",

    "q.m15#4.p" to "レンズ雲（茸状、皿状）はふつう何を予告しますか。",
    "q.m15#4.o0" to "無風の天気",
    "q.m15#4.o1" to "強風",
    "q.m15#4.o2" to "まもなくの降雨",
    "q.m15#4.o3" to "気温の上昇",
    "q.m15#4.e" to "レンズ雲は気流が尾根を越えるときにできる定在波の雲で、その存在自体が上空の風速が大きいことを示します。山では、露出した尾根に極めて強い突風が吹くという意味であり、突風はバランスを崩す直接の原因になります。",

    "q.m15#5.p" to "巻雲（糸を引いたような高空の薄雲）が明らかに増えてきたとき、ふつう何を予告しますか。",
    "q.m15#5.o0" to "気象系が近づいている",
    "q.m15#5.o1" to "厳寒が終わろうとしている",
    "q.m15#5.o2" to "まもなく無風になる",
    "q.m15#5.o3" to "紫外線が弱まる",
    "q.m15#5.e" to "巻雲はしばしば気象系の最先端、いわば先遣隊です。現れた時点で天気はまだ変わっていませんが、変化が進行中であることを意味します。これは非常に有用な余裕時間で、とくに早めに戻る必要のある行程では効きます。",

    "q.m15#6.p" to "層雲が垂れ込め、雲底が明らかに下がってきたとき、最も直接的な影響は何ですか。",
    "q.m15#6.o0" to "気温が上がる",
    "q.m15#6.o1" to "視界が急速に悪化し、地形の判断が難しくなる",
    "q.m15#6.o2" to "風が弱まる",
    "q.m15#6.o3" to "降水が止む",
    "q.m15#6.e" to "層雲の低下がもたらすのは「雨」ではなく「見えないこと」です。そして視界を失うこと自体が独立したリスクになります。ルートから外れているかもしれず、雪庇に近づいているかもしれず、撤退の分岐を見落とすかもしれない。",

    "q.m15#7.p" to "【複数選択】天気が悪化しつつあることを示す雲の変化はどれですか。",
    "q.m15#7.o0" to "雲量が急速に増え、雲層が厚くなる",
    "q.m15#7.o1" to "雲底が下がり続ける",
    "q.m15#7.o2" to "雲の色が暗くなり、垂直方向の発達が明らかになる",
    "q.m15#7.o3" to "かなとこ型の雲頂が現れる",
    "q.m15#7.o4" to "雲量が減りはじめ、空が次第に晴れてくる",
    "q.m15#7.e" to "この四項目は実は同じ過程の異なる段階です。雲量が増える → 雲底が下がる → 雲体が暗く発達する → かなとこ型が現れる。順に識別できれば、「変天」を一瞬の出来事から、事前に警告できる過程に変えられます。",

    "q.m15#8.p" to "山の雲が平地より激しく発達するのはなぜですか。",
    "q.m15#8.o0" to "標高が高く気温が低いから",
    "q.m15#8.o1" to "地形が空気を持ち上げることを強制し、対流を強めるから",
    "q.m15#8.o2" to "紫外線が強いから",
    "q.m15#8.o3" to "空気が薄いから",
    "q.m15#8.e" to "風が山体に当たって強制的に持ち上げられます。坂を押し上げられるようなもので、持ち上げはそのまま冷却と凝結を生みます。だから平地より速く、より局地的に雲ができます。山の天気がごく短時間で一変しうる理由もここにあります。",

    "q.m15#9.p" to "雲が「発達している」のか「消えつつある」のかをどう見分けますか。",
    "q.m15#9.o0" to "雲の色を見る",
    "q.m15#9.o1" to "雲の体積、高さ、縁の輪郭が増えているか、硬くなっているかを連続して観察する",
    "q.m15#9.o2" to "気温を見る",
    "q.m15#9.o3" to "積雪の深さを見る",
    "q.m15#9.e" to "要点は「連続した観察」です。一度見ただけでは状態しか分からず、二度比べてはじめてトレンドが出ます。発達中の雲は体積が増え、雲頂が上がり、縁がぼやけた状態からくっきりした状態へ変わります。消えつつある場合は逆です。だから定時に見上げる習慣は、コストほぼゼロで価値が高いのです。",

    "q.m15#10.p" to "【組み合わせ】雲の型と、その天気の意味を結びつけてください。",
    "q.m15#10.l0" to "積乱雲（かなとこ型の頂）",
    "q.m15#10.l1" to "レンズ雲",
    "q.m15#10.l2" to "巻雲",
    "q.m15#10.l3" to "低層の層雲",
    "q.m15#10.r0" to "雷雨、雹、強い降水",
    "q.m15#10.r1" to "上空の強風、尾根では猛烈な突風",
    "q.m15#10.r2" to "気象系がまもなく近づく",
    "q.m15#10.r3" to "視界の低下、地形判断が難しくなる",
    "q.m15#10.e" to "この四つの雲は、山で最もよく出会う四種類の天気情報をカバーします。一点お伝えしておきます。雲の判読は図を見て練習する必要があり、本アプリはいまのところ文章記述の設問しかありません。画像による雲の識別問題は、画像の取り込み経路が整ってから追加します。",

    "q.m15#11.p" to "雲の判読を気圧のトレンドと組み合わせねばならないのはなぜですか。",
    "q.m15#11.o0" to "データを揃えるため",
    "q.m15#11.o1" to "雲は現在の状態を映し、気圧のトレンドは変化の向きを映すから",
    "q.m15#11.o2" to "気圧計のほうが正確だから",
    "q.m15#11.o3" to "標高を計算するため",
    "q.m15#11.e" to "両者は次元が違います。雲は「いま何があるか」を、気圧は「どちらへ向かっているか」を教えてくれます。雲だけ見ると「悪化しつつある」を「一時的な曇り」と読み違えやすい。トレンドを加えてはじめて判断が完結します。",

    "q.m15#12.p" to "ホワイトアウトの主な成因は何ですか。",
    "q.m15#12.o0" to "降雪が多すぎること",
    "q.m15#12.o1" to "雲、霧、雪面の色が近づき、地面と空の境界が消えること",
    "q.m15#12.o2" to "気温が低すぎること",
    "q.m15#12.o3" to "紫外線が強すぎること",
    "q.m15#12.e" to "ホワイトアウトは「雪が多い」のではなく「コントラストがない」状態です。雪面と雲の明るさが近づくと地平線が消え、距離と傾斜の知覚が完全に狂います。これが普通の降雪よりはるかに危険な理由です。",

    "q.m15#13.p" to "「ところにより雨」といった予報が山では意味を持ちにくいのはなぜですか。",
    "q.m15#13.o0" to "予報が不正確だから",
    "q.m15#13.o1" to "山の天気の変化のスケールが予報のグリッドよりはるかに小さく、現場の状況がまったく違いうるから",
    "q.m15#13.o2" to "登山者は予報を見ないから",
    "q.m15#13.o3" to "降水は重要でないから",
    "q.m15#13.e" to "予報のグリッドは数十キロ単位であることも多く、同じ尾根の両側で天気がまったく違うことがあります。予報が与えるのは「背景のリスク」であり、「今日歩けるか」を決めるのは現場の判断です。両者は互いの代わりになりません。",

    "q.m15#14.p" to "予報が「晴れ」なのに、現場で積雲が急速に垂直発達しているとき、どちらを信じるべきですか。",
    "q.m15#14.o0" to "予報を信じ、計画どおり進む",
    "q.m15#14.o1" to "現場の観察を信じ、悪化する前提で判断する",
    "q.m15#14.o2" to "両者を平均する",
    "q.m15#14.o3" to "もう一時間観察してから決める",
    "q.m15#14.e" to "予報の有効時間もスケールも粗いのに対し、現場の観察は「いま、ここ」です。両者が衝突するときは現場の証拠が優先されます。これが天気判断の体系全体の基本姿勢でもあります。予報は背景を定め、現場が行動を定める。",

    "q.m15#15.p" to "空欄を埋めてください。稲光を見てから数えた秒数は、1 秒あたり約（ ）km の距離に相当します。",
    "q.m15#15.a0" to "0.34",
    "q.m15#15.a1" to ".34",
    "q.m15#15.a2" to "ゼロ点三四",
    "q.m15#15.e" to "0.34 km/秒 は音が空気中を伝わる速さです。この換算によって「秒を数える」が使える判断道具になります。道具が一切なくても、雷雨が近づいているのか遠ざかっているのかが分かります。",

    "q.m15#16.p" to "【複数選択】ただちに下山を真剣に検討すべき状況はどれですか。",
    "q.m15#16.o0" to "積雲がかなとこ型の積乱雲に発達した",
    "q.m15#16.o1" to "「whumpf」という雪層の沈み込む音がした",
    "q.m15#16.o2" to "視界が急速に悪化し、位置が分からなくなった",
    "q.m15#16.o3" to "隊に進行性に悪化する高所症状が出た",
    "q.m15#16.o4" to "隊員が少し疲れたと言い、10 分休みたいと言った",
    "q.m15#16.e" to "この四項目は天気、雪層、ナビゲーション、生理の四つの次元から来ています。共通点は「いずれも進行性」であること。つまり今の代償は 10 分後の代償よりはるかに小さい。撤退の決定が早いほど、代償は小さく済みます。",

    "q.m15#17.p" to "図の上で「Freezing Level（零度層）」を表す曲線をクリックしてください。",
    "q.m15#17.c" to "この予報は、同じ山の異なる高度の天気を層に分けて示しています。凡例の紫の曲線が零度層、つまり雨と雪の境界がある高度です。",
    "q.m15#17.e" to "零度層の曲線は、この予報でもっとも価値ある情報の一つです。雨雪の境界がいまどの高度にあるかを示します。曲線が上がれば暖湿気流が強まり降水が雪から雨へ変わることを、下がれば寒気が入って高い所が降雪に変わることを意味します。自分のいる高度で雪に遭うかどうかは、気温の数字よりこの曲線を見るほうが直接的です。",

    "q.m15#18.p" to "これは登攀シーズンが早く終わるときの、同じ山の予報です。Fri 25 の三つの時間帯（AM／PM／night）の降雪量はそれぞれ何センチですか。三つの合計を入力してください。",
    "q.m15#18.a0" to "280",
    "q.m15#18.e" to "58 + 88 + 134 = 280 cm です。一日で 2.8 m 近い降雪は、ルートが完全に埋まり、雪崩リスクが急上昇し、キャンプが潰される可能性もあることを意味します。この量級はもはや「登頂できるか」ではなく「安全に撤退できるか」の問題です。サイクロンによって登攀シーズンが早く終わる典型例でもあります。",

    "q.m15#19.p" to "シナリオ：高所の気象予報を読み解く",
    "q.m15#19.c" to "ガイドがマナスルの気象予報を二部、あなたの前に置きました。一つは正常な登攀の窓、もう一つはシーズンが早く終わったときの記録です。数字を覚えるより、これを読めることのほうが重要です。",
    "q.m15#19.e" to "気象判断の着地点は「明日の天気は何か」ではなく、「この窓で行動できるか」です。同じ画面でも、一方は続行できることを示し、一方は終わらせねばならないことを示します。違いは図が読めるかどうかではなく、どんな条件で止めるべきかを知っているかどうかです。",
    "q.m15#19.s0.p" to "第 1 段階：正常な窓の予報で、頂上高度（8,163 m）の行にあるピンクの四角は何を表しますか。",
    "q.m15#19.s0.o0" to "その時間帯の予想降雪量",
    "q.m15#19.s0.o1" to "その時間帯の降雨量",
    "q.m15#19.s0.o2" to "その時間帯の体感温度",
    "q.m15#19.s0.o3" to "その時間帯の風速",
    "q.m15#19.s0.e" to "ピンクは降雪、青は降雨を表します。この予報が高度ごとに降水の形式を分けて示しているのは、核心の問いが「自分のいる高度では雪か雨か」だからです。最上部の行はピンクの四角が小さくまばらで、頂上に散発的な降雪はあるが量は多くないことを示しています。",
    "q.m15#19.s1.p" to "第 2 段階：シーズン終了時の予報と比べて、最も顕著な変化は何ですか。",
    "q.m15#19.s1.o0" to "気温が下がっただけ",
    "q.m15#19.s1.o1" to "降雪量と風速が同時に激増し、降水がすべての高度層を覆った",
    "q.m15#19.s1.o2" to "降雨が降雪に取って代わった",
    "q.m15#19.s1.o3" to "零度層の高度が大きく上がった",
    "q.m15#19.s1.e" to "降雪は「散発的な 1〜4 cm」から「一日 280 cm」へ、風速は 25〜30 km/h から 55〜60 km/h へ上がり、しかも降水帯が 8,163 m から 1,500 m までのすべての高度層を貫いています。この三つが同時に現れるのが、気象系が正面から通過するときの署名です。",
    "q.m15#19.s2.p" to "第 3 段階：自分の隊がこうした予報の窓にいるとしたら、正しい判断はどれですか。",
    "q.m15#19.s2.o0" to "天気が完全に悪化する前に、登頂を急ぐ",
    "q.m15#19.s2.o1" to "ただちに登頂の試みを中止し、計画に従って下山し、退去の準備をする",
    "q.m15#19.s2.o2" to "高所キャンプで天候の回復を待つ",
    "q.m15#19.s2.o3" to "隊を二組に分け、一組が登頂、一組が待機する",
    "q.m15#19.s2.e" to "予報が示しているのが一時的な変動ではなく気象系の正面通過なら、「通り過ぎるのを待つ」ことは高所で数日間さらされることを意味し、キャンプの補給もテントの状態も持ちません。多くの登攀シーズンが「登り切った」ではなく「撤退せざるをえなかった」で終わる理由もここにあります。その判断に必要な情報は、まさにこの二枚の図が与えてくれます。",

    "q.m15#20.p" to "シナリオ：時間別の予報を読み解く",
    "q.m15#20.c" to "これは貢嘎山（7,556 m）のある日の時間別予報です。情報密度は 16 日間の概況よりはるかに高いですが、行を読み違えやすくもあります。要点は、各行が何を言っているのかを知ることです。",
    "q.m15#20.e" to "時間別予報は、概況では答えられない問いに答えます。どの時間帯なら行動できるのか。零度層が降水の形式を決め、体感温度が人に耐えられるかを決め、風速と日照が窓の広さを決めます。いくつかを重ねて見てはじめて、実行できる判断になります。",
    "q.m15#20.s0.p" to "第 1 段階：表の Freeze の行は零度層の高度が 4895〜5304 m にあることを示し、貢嘎の頂上は 7556 m です。この組み合わせは何を意味しますか。",
    "q.m15#20.s0.o0" to "山の降水はすべて雪の形で現れる",
    "q.m15#20.s0.o1" to "頂上では降雨がある",
    "q.m15#20.s0.o2" to "零度層より下でも雪が降る",
    "q.m15#20.s0.o3" to "これでは降水の形式は判断できない",
    "q.m15#20.s0.e" to "零度層は雨と雪の境界です。それが 4,900〜5,300 m で安定しているのに対し、登攀ルートはすべてこの高度より上にあります。つまりルート全体が零度層より上で、どんな降水も雪として降ります。「自分はどんな形の降水に遭うのか」が一つの数で分かる。これが零度層が気温の数字より使いやすい理由です。",
    "q.m15#20.s1.p" to "第 2 段階：Feels °C の行は -18〜-21 を示し、Max / Min °C は -10〜-11 しかありません。この差は主に何から来ますか。",
    "q.m15#20.s1.o0" to "天気予報の誤差",
    "q.m15#20.s1.o1" to "風冷効果——風速が大きいほど体感温度が下がる",
    "q.m15#20.s1.o2" to "標高による気温差",
    "q.m15#20.s1.o3" to "湿度変化の影響",
    "q.m15#20.s1.e" to "同じ時間帯の風速は 20〜30 km/h です。風が露出した皮膚を通ると放熱が促進されるため、体感（Feels）は実測気温より 10℃ 近く低くなります。高所で耐えられるかどうかは体感温度で決まり、気温ではありません。同じ -10℃ でも、風があるのとないのではまったく別物です。",
    "q.m15#20.s2.p" to "第 3 段階：この予報（風速 20〜30 km/h、散発的な降雪 2／1／1 cm、体感約 -20℃、日照 6:56〜19:15）を総合すると、この窓の判断はどれですか。",
    "q.m15#20.s2.o0" to "天候が悪く、行動は完全に断念すべき",
    "q.m15#20.s2.o1" to "相対的に行動可能な窓で、主な課題は降水ではなく低温と風冷",
    "q.m15#20.s2.o2" to "降水が多く、雪崩リスクがある",
    "q.m15#20.s2.o3" to "データが不足し、判断できない",
    "q.m15#20.s2.e" to "風速 20〜30 km/h はまだ行動可能な範囲で、降雪量も数センチとわずかです。本当の圧力は -20℃ 前後の体感で、防ぐべきは凍傷と低体温です。この種の窓の判断は「降水も風も問題なし、問題は気温と曝露時間」という構図になります。だから曝露時間を短縮し、末端の保温を強化し、ターンアラウンドタイムも前倒しにします。",

    "q.m15#21.p" to "同じ貢嘎の予報で、実測気温は約 -11℃、体感は最低 -21℃ でした。差は何℃ですか。",
    "q.m15#21.a0" to "10",
    "q.m15#21.e" to "10℃ です。計算は -11 -（-21）＝ 10。この差自体が判断の材料になります。着る量は気温ではなく体感に合わせて準備する。だから -10℃ で凍傷になる人がいるわけで、その人は気温に合わせて着ていたのです。",

    "q.m15#22.p" to "この予報が風速を緑の丸で示しているのは、何を表す可能性が最も高いですか。",
    "q.m15#22.o0" to "その時間帯の風速が登攀に適した範囲にある",
    "q.m15#22.o1" to "その時間帯の風速が危険な水準に達している",
    "q.m15#22.o2" to "その時間帯に降雨がある",
    "q.m15#22.o3" to "その時間帯の風速データが欠けている",
    "q.m15#22.e" to "専門の登山気象サービスは、ふつう風速が行動に与える影響で色分けします。20〜30 km/h が緑なら「行動できる」範囲で、それ以上では黄や赤に変わります。\nただし色はあくまで提供者の提案であり、あなたの判断基準ではありません。同じ風速でも、ルートや隊によって耐えられる範囲は違います。数字を読むほうが、色を読むより重要です。",

    "q.m15#23.p" to "この専門画面は 8000／6000／4000／2000 m を四行に分けて並べ、気温を示しています。この設計の主な価値は何ですか。",
    "q.m15#23.o0" to "自分のいる高度の予報を直接読め、低地のデータから外挿する必要がない",
    "q.m15#23.o1" to "画面が豊かに見える",
    "q.m15#23.o2" to "四行の間に関連がないことを示す",
    "q.m15#23.o3" to "紙の表に印刷しやすくするためだけ",
    "q.m15#23.e" to "普通の天気予報はある地点のデータで、多くは最寄りの都市や空港のものです。山の状況は自分で気温減率から推算する必要があり、この段階で計算を誤りやすく、地形の細部も失われます。\n専門の登山気象サービスは逆をやります。まず山を高度で層に切り、層ごとに予報を出します。あなたは「明日自分がいる高度」の行を探して、そのまま読めばよい。気象サービスが使えるかどうかの簡単な基準にもなります。高度で層分けしているかどうか、です。",

    "q.m15#24.p" to "図の「Cloud base (m)」の行は多くの時間帯で空欄（—）になっています。正しい理解はどれですか。",
    "q.m15#24.o0" to "その時間帯の雲底高度はゼロ、つまり雲が地面に接している",
    "q.m15#24.o1" to "その時間帯の雲底データが提供されておらず、「雲底 0」と見なしてはいけない",
    "q.m15#24.o2" to "その時間帯に雲がまったくないことを示す",
    "q.m15#24.o3" to "雲底高度が山頂より高いことを示す",
    "q.m15#24.e" to "気象表の「空」と「ゼロ」はまったく別のことです。空欄はその項目についてその時間帯のデータがないことを示し、対象外なのか、意味のある推定が出せないのかは分かりませんが、いずれにせよ「値がゼロ」ではありません。\n空欄をゼロと読むと、「雲が地面に接し、視界が最悪」という事実と無関係な結論になります。気象表を読むときは、まずこの二つを区別してください。予報を見るときに最も間違えやすく、最も注意を促されない細部です。",

    "q.m15#25.p" to "この画面の風速の行には、数字のほかに矢印の記号が付いています。矢印は何を表す可能性が最も高いですか。",
    "q.m15#25.o0" to "風速の変化のトレンド",
    "q.m15#25.o1" to "風の向き",
    "q.m15#25.o2" to "降水確率",
    "q.m15#25.o3" to "気温の上下",
    "q.m15#25.e" to "高所では風速と風向を一緒に見る必要があります。同じ 30 km/h でも、風上側の斜面と風下側では体感がまったく違い、雪層への影響も異なります。風は雪を風下の斜面へ運び、スラブを作ります。雪崩判断で最も重要な情報の一つです。\n風速の数字だけを見て風向を見ないのは、情報の半分を捨てるのと同じです。専門画面が数字の隣に矢印を置くのは、この二つを切り離して読めないからです。",

    "q.m15#26.p" to "この 16 日間の予報図では、赤い印（Snow）が約 6000 m の帯に集中し、青い印（Rain）は 5000 m 以下に現れています。これは何を示しますか。",
    "q.m15#26.o0" to "雨雪の境界がおよそ 5,500〜6,000 m にある",
    "q.m15#26.o1" to "山では雪だけが降り、雨は降らない",
    "q.m15#26.o2" to "降雨が頂上まで続く",
    "q.m15#26.o3" to "この図からは判断できない",
    "q.m15#26.e" to "この図は「どこで何時に何が降るか」ではなく、「降水がどの高度帯に落ちるか」を直接答えます。登山者にとって、まさにこれが最重要の情報です。\n赤が 6,000 m の帯に、青がすべて 5,000 m 以下に出ていることは、雨雪の境界がおおよそ 5,500〜6,000 m にあることを示します。さらに凡例の紫の零度層の曲線（約 6,000 m から約 4,800 m へ下降）を合わせると、この境界が予報期間中さらに下がり続けることも読み取れます。もともと雨だった高度帯が、次第に雪へ変わるのです。\n同じ降水量でも、雨か雪かで行程への影響はまったく違います。",

    "q.m15#27.p" to "同じ図の時間別予報で、午後 5 時に稲妻のアイコンが現れています。高所でこのシグナルは何を意味しますか。",
    "q.m15#27.o0" to "アイコンが見栄えのためだけで、特別な対応は不要",
    "q.m15#27.o1" to "雷雨のリスクがあり、行程を午前に組み、午後には尾根と露出した区域から離れるべき",
    "q.m15#27.o2" to "まもなく大雨になるので、レインウェアを用意すればよい",
    "q.m15#27.o3" to "風速が危険な水準まで上がることを示す",
    "q.m15#27.e" to "高所の午後の雷雨はよくあり、危険でもあります。地形の持ち上げによって積雲が午後に急成長します。だから「早出発」は雪面が固いうちに歩くためだけでなく、雷雨が形作られる前に露出した地形を離れるためでもあります。\n雷雨に遭ったときの要点は、山頂、尾根、孤立した大木、水面から離れること。地面に平らに伏せないこと。隊は互いに約 50 m 離れ、一発の落雷で複数が被災するのを避けること。落雷までの距離は「稲光と雷鳴の秒数差 × 0.34」でキロ数を見積もれます。",

    "q.m15#28.p" to "二種類の地形データ源における「山頂のランドマークがあるかどうか」について、正しい取捨はどれですか。",
    "q.m15#28.o0" to "ランドマークがあれば必ず正確なので、ある図だけを信じるべき",
    "q.m15#28.o1" to "ランドマークは素早い位置確認と共有に便利だが、地形を精確に判断するには等高線に戻る必要がある",
    "q.m15#28.o2" to "ランドマークのない図には使用価値がない",
    "q.m15#28.o3" to "ランドマークは判読を妨げるだけなので無視すべき",
    "q.m15#28.e" to "ムスタグアタのこの Google マップでは、山頂が赤いランドマークで直接示されています。位置確認と共有には便利で、目標がどこかを即座に知ることができ、同行者にもどの位置かを伝えられます。\nしかしランドマークは「この斜面がどれくらい急か、どこにキャンプを置けるか」を解決しません。精確な地形判断はやはり等高線に頼る必要があり、ランドマーク自体はその判断に関与しません。\nより実際的なのは、ランドマークで素早く位置を掴み、高精度の等高線（たとえば SRTM の版）で傾斜と地形の細部を読むこと。それぞれが別の仕事を担います。",

    // ---------- m16 雪崩判断の応用と地形判読 ----------
    "q.m16#0.p" to "雪崩の応用的な判断では、どの三つのスケールを統合する必要がありますか。",
    "q.m16#0.o0" to "気温、風速、降水",
    "q.m16#0.o1" to "地域予報、地形、雪層",
    "q.m16#0.o2" to "標高、傾斜、日照",
    "q.m16#0.o3" to "隊の人数、装備、時間",
    "q.m16#0.e" to "三つのスケールは三つの異なる問いに答えます。予報は「今日全体のリスクはどれくらいか」、地形は「この斜面は雪を溜めて滑りうるか」、雪層は「いま安定しているか」。予報だけを見るのは、地域平均で足元の一斜面を判断するようなものです。",

    "q.m16#1.p" to "雪崩の危険度階級のうち、事故が最も集中するのはどのレベルですか。",
    "q.m16#1.o0" to "1（低）",
    "q.m16#1.o1" to "3（かなり危険）",
    "q.m16#1.o2" to "5（極めて危険）",
    "q.m16#1.o3" to "差はない",
    "q.m16#1.e" to "レベル 5 では誰もが避けるので、事故はかえって少なくなります。レベル 3 では地形が「行けそう」に見えるため、多くの人が雪崩地形に入ります。最も危険なのは極端な条件ではなく、過小評価された中程度の条件なのです。",

    "q.m16#2.p" to "大半の雪崩が集中して発生する傾斜帯はどこですか。",
    "q.m16#2.o0" to "10°〜25°",
    "q.m16#2.o1" to "34°〜45°",
    "q.m16#2.o2" to "55°〜70°",
    "q.m16#2.o3" to "規則性はない",
    "q.m16#2.e" to "約 96% の雪崩は 30°〜50° で発生し、その大半が 34°〜45° に集中します。この角度は登攀ルートが最もよく通る帯でもあります。滑るには十分に急で、雪が溜まるには十分に緩い。",

    "q.m16#3.p" to "【複数選択】雪崩地形を通過するときの正しい作法はどれですか。",
    "q.m16#3.o0" to "間隔を開け、一人ずつ通過する",
    "q.m16#3.o1" to "安全な位置に観察者を配置する",
    "q.m16#3.o2" to "撤退ルートをあらかじめ計画する",
    "q.m16#3.o3" to "隊全員で同時に素早く通過し、曝露時間を短縮する",
    "q.m16#3.e" to "前三項はリスクを個人一人分に限定し、万一のときの退路を確保します。「全員同時通過」は正反対で、リスクを「一人埋まるかもしれない」から「全員埋まるかもしれない」に拡大する、最も選ぶべきでない選択肢です。",

    "q.m16#4.p" to "観察者はどこに立つべきですか。",
    "q.m16#4.o0" to "通過中の斜面の上",
    "q.m16#4.o1" to "通過者がよく見え、自身も安全な位置",
    "q.m16#4.o2" to "斜面の最高点",
    "q.m16#4.o3" to "谷底",
    "q.m16#4.e" to "観察者には二つの任務があります。通過者を見送る（埋まった位置を知る）ことと、事故が起きた瞬間に行動すること。斜面の上や谷底に立つと、自分が二人目の被災者になります。観察者自身の安全は職務を果たす前提条件です。",

    "q.m16#5.p" to "スノーピット（雪坑）を掘って観察する目的は何ですか。",
    "q.m16#5.o0" to "休憩のため",
    "q.m16#5.o1" to "雪層の構造、弱層の位置、硬さの違いを直接見るため",
    "q.m16#5.o2" to "気温を測るため",
    "q.m16#5.o3" to "写真を記録するため",
    "q.m16#5.e" to "雪崩は「弱層＋その上のスラブ」の組み合わせで起こり、その構造は切り出さないと見えません。雪坑は見えない内部構造を可視の証拠に変えます。これが「リスクを推測する」から「リスクを観察する」への鍵となる一歩です。",

    "q.m16#6.p" to "「前の人のトレースを辿る」のが危険なのはなぜですか。",
    "q.m16#6.o0" to "トレースが不明瞭だから",
    "q.m16#6.o1" to "トレースは数時間前のもので、雪層の条件がすでに変わっている可能性があるから",
    "q.m16#6.o2" to "道を間違えるから",
    "q.m16#6.o3" to "トレースが歩行の邪魔になるから",
    "q.m16#6.e" to "雪層の条件は気温、風、降雪によって変化し続け、数時間で「ぎりぎり安定」から「いつ崩れてもおかしくない」に変わりえます。トレースが証明するのは「そのとき誰かが通れた」ことだけで、「いま安全だ」ことではありません。",

    "q.m16#7.p" to "風による雪の堆積（wind loading）は雪崩リスクにどう影響しますか。",
    "q.m16#7.o0" to "風が雪を平らにしてリスクを下げる",
    "q.m16#7.o1" to "風が雪を風下の斜面に運んで積もらせ、追加のスラブと弱層を作り、リスクを大きく上げる",
    "q.m16#7.o2" to "風は雪崩と関係ない",
    "q.m16#7.o3" to "風は視界にだけ影響する",
    "q.m16#7.e" to "風は最も過小評価されている「雪崩の作り手」です。短時間で大量の雪を風下の斜面に運び、厚いスラブを積み上げ、内部に弱層を作ります。だから雪が降っていなくても、強風のあとには新たな雪崩危険が生まれます。",

    "q.m16#8.p" to "雪庇（コーニス）の主な危険は何ですか。",
    "q.m16#8.o0" to "視界を妨げる",
    "q.m16#8.o1" to "いつ崩れてもおかしくなく、崩れた際に下の斜面の雪崩を誘発することもある",
    "q.m16#8.o2" to "雪面と色が違う",
    "q.m16#8.o3" to "進行ルートを妨げる",
    "q.m16#8.e" to "雪庇の危険は二重です。上に立てば一緒に崩れ落ちるかもしれませんし、下から通過するときに大量の雪ごと落ちてくるかもしれません。だからふつうは庇の稜線から離れた側を巻き、庇の上では決して休みません。",

    "q.m16#9.p" to "【並べ替え】雪崩地形を通過する一連の流れはどれですか。",
    "q.m16#9.o0" to "出発前にその日の雪崩予報を見て、避けるべき斜面を洗い出す",
    "q.m16#9.o1" to "取り付く前に現場のサイン（亀裂、沈み込み音、風成雪面）を観察する",
    "q.m16#9.o2" to "観察者、通過順、撤退ルートを決める",
    "q.m16#9.o3" to "一人ずつ通過し、間隔を保って安全な地点で合流する",
    "q.m16#9.e" to "前三段階はすべて「入る前」に終わります。ここが雪崩安全の実質的な重心です。斜面に踏み出したあとに残された選択肢はわずかで、ほとんどの事故の根本原因は「最初の二段階をやっていない」ことにあります。",

    "q.m16#10.p" to "雪崩救助はなぜ同行者がただちに行わなければならないのですか。",
    "q.m16#10.o0" to "専門救助は費用が高いから",
    "q.m16#10.o1" to "埋まった人の生存可能時間は十数分しかないから",
    "q.m16#10.o2" to "専門救助が山に来たがらないから",
    "q.m16#10.o3" to "同行者のほうが地形に詳しいから",
    "q.m16#10.e" to "生存できる時間が十数分ということは、「助けられるのは隣にいる同行者だけ」ということです。雪崩の三点セットを必ず携行し、使い方を体に覚えさせる必要がある理由もここにあります。持っていても使えなければ、持っていないのと同じです。",

    "q.m16#11.p" to "【組み合わせ】雪崩の危険度階級と、その意味を結びつけてください。",
    "q.m16#11.l0" to "レベル 1",
    "q.m16#11.l1" to "レベル 3",
    "q.m16#11.l2" to "レベル 4",
    "q.m16#11.l3" to "レベル 5",
    "q.m16#11.r0" to "低：自然誘発も人為誘発も少ない",
    "q.m16#11.r1" to "かなり危険：人為的に誘発しうるうえ、最も過小評価されやすい",
    "q.m16#11.r2" to "高：自然誘発が起こりうる。雪崩地形を避けるべき",
    "q.m16#11.r3" to "極めて危険：大規模な自然雪崩が起こる可能性が高い",
    "q.m16#11.e" to "階級の数字の背後には「誘発の可能性」と「結果の規模」の組み合わせがあります。入門者が最もやりがちな誤りは、レベル 3 を「まあ大丈夫」と受け取ること。そこがまさに事故の最も集中するレベルなのです。",

    "q.m16#12.p" to "雪崩エアバッグの働きと限界は、それぞれ何ですか。",
    "q.m16#12.o0" to "完全に埋まるのを防げる。限界はない",
    "q.m16#12.o1" to "埋まる深さが浅くなる確率を上げる。ただしビーコン、プローブ、ショベルの代わりにはならず、外傷も防げない",
    "q.m16#12.o2" to "スキー場でしか使わない",
    "q.m16#12.o3" to "自動で救助を要請できる",
    "q.m16#12.e" to "エアバッグの原理は「体積を増やして雪面に浮きやすくする」ことで、生存率は上げられますが保証はありません。しかも雪崩による死因のかなりの部分は窒息ではなく外傷です。この点が、エアバッグを唯一の頼りにできない理由です。",

    "q.m16#13.p" to "「あまり急に見えない」斜面がかえって危険なのはなぜですか。",
    "q.m16#13.o0" to "雪がより深いから",
    "q.m16#13.o1" to "34°〜45° がまさに雪崩の最も集中する帯であり、人の目は傾斜を過小評価しやすいから",
    "q.m16#13.o2" to "通る人が少ないから",
    "q.m16#13.o3" to "傾斜が急に変わるから",
    "q.m16#13.e" to "参照物のない場所では傾斜の見積もり誤差が大きく、35° を 25° と見てしまうことがよくあります。そして 30°〜35° はまさに「歩けそうに見えて、実際は滑る」帯です。クリノメーターと地形図がこの偏りの解毒剤になります。",

    "q.m16#14.p" to "【複数選択】雪崩地形に入る前に、隊が済ませておくべき準備はどれですか。",
    "q.m16#14.o0" to "全員がビーコン、プローブ、ショベルを使えることを確認する",
    "q.m16#14.o1" to "通過順と観察者を明確にする",
    "q.m16#14.o2" to "集合地点と撤退ルートを取り決める",
    "q.m16#14.o3" to "ビーコンが送信状態にあることを確認する",
    "q.m16#14.o4" to "何度も強く足踏みして雪層の安定性を試す",
    "q.m16#14.e" to "この四項目はいずれも「入る前の最終確認」で、すべて数分で済みます。重要なのは、斜面に踏み出した瞬間に残る選択肢が「起きないことを祈る」だけになるからです。",

    "q.m16#15.p" to "雪層から「whumpf」という沈み込む音がしました。正しい反応はどれですか。",
    "q.m16#15.o0" to "雪が締まっただけなので、そのまま進む",
    "q.m16#15.o1" to "ただちに進行を止めて再評価する。弱層が壊れ始めている証拠だから",
    "q.m16#15.o2" to "速度を上げて通過する",
    "q.m16#15.o3" to "その場で 10 分休む",
    "q.m16#15.e" to "whumpf は弱層が崩れつつある直接の証拠で、ごく軽い荷重で局所的な破壊を誘発したことを意味します。そのまま進むのは「もう少し載せたら全部崩れるか」と問い続けるようなものです。",

    "q.m16#16.p" to "空欄を埋めてください。約 96% の雪崩は 30°〜50° の斜面で発生し、その大半が 34°〜（ ）° に集中します。",
    "q.m16#16.a0" to "45",
    "q.m16#16.a1" to "四十五",
    "q.m16#16.e" to "34°〜45° です。この帯を覚えておく価値は、雪崩の多発帯であると同時に、登攀ルートが最もよく通る傾斜でもあることです。二つの事実が重なるからこそ、雪崩は高山登攀の主要な客観的危険の一つになるのです。",

    "q.m16#17.p" to "シナリオ：雪崩地形の一区間を通過する",
    "q.m16#17.c" to "ルートは 35° ほどの雪斜面を約 200 m 通過する必要があります。その日の雪崩予報は「かなり危険（レベル 3）」、直近に 30 cm の新雪、風向は北西、斜面は南東向きです。",
    "q.m16#17.e" to "このシナリオが試すのは雪崩判断の一連の流れです。地形と雪況を読む → 入る前に準備を終える → 隊形で結果を制御する。どれも難しくはありません。難しいのは、「行けそう」に見える斜面の前で、そのすべてを実行することです。",
    "q.m16#17.s0.p" to "第 1 段階：この斜面でもっとも警戒すべきものは何ですか。",
    "q.m16#17.s0.o0" to "落石",
    "q.m16#17.s0.o1" to "風で運ばれた雪が作るスラブと、斜面そのものの傾斜",
    "q.m16#17.s0.o2" to "高温",
    "q.m16#17.s0.o3" to "地表の植生",
    "q.m16#17.s0.e" to "35° は 34°〜45° の多発帯にちょうど入ります。北西の風は雪を風下の斜面（ここでは南東斜面）へ運び、追加のスラブを作ります。二つの要素が重なるのが、「行けそうに見えて実際は滑る」典型の組み合わせです。",
    "q.m16#17.s1.p" to "第 2 段階：斜面に取り付く前に、まず何をすべきですか。",
    "q.m16#17.s1.o0" to "そのまま通過を始める",
    "q.m16#17.s1.o1" to "まず現場のサインを観察し、観察者、通過順、撤退ルートを決める",
    "q.m16#17.s1.o2" to "まず斜面で強く足踏みして試す",
    "q.m16#17.s1.o3" to "隊全員で同時に素早く通過する",
    "q.m16#17.s1.e" to "準備はすべて「入る前」に終えるべきです。強く足踏みしても安定性は確認できず、むしろ限界に近づいている雪層をそのまま誘発しかねません。",
    "q.m16#17.s2.p" to "第 3 段階：通過するとき、隊形はどう組むべきですか。",
    "q.m16#17.s2.o0" to "一人ずつ通過し、残りは安全な地点で待つ",
    "q.m16#17.s2.o1" to "全員で手をつないで一緒に歩く",
    "q.m16#17.s2.o2" to "互いに見えるよう二人並行で歩く",
    "q.m16#17.s2.o3" to "一列になって密着して進む",
    "q.m16#17.s2.e" to "一人ずつ通せばリスクは個人一人分に限定され、観察者も一人を見送ることに集中できます。全員が同時に曝露すれば、結果は「一人埋まるかも」から「全員埋まるかも」に拡大します。",

    "q.m16#18.p" to "図の上で、マナスル峰の頂上があるおよその区域をクリックしてください。",
    "q.m16#18.c" to "これは NASA の SRTM 標高データから生成したマナスルの等高線地形図で、等高間隔は 50 m、図中の数字は各等高線の標高です。",
    "q.m16#18.e" to "峰頂は地形図の上で特徴がはっきりしています。閉じた等高線が内側へ層をなして収まり、標高の数字が段階的に上がっていく（7600 → 7750 → 7900 → 7950 …）。小さな閉曲線に幾重にも囲まれた点が最高所です。\n逆に、等高線が外へ開いていき数字が下がり続ける方向が、山体の下る方向です。どの側が登攀ルートの取る斜面かも、これで分かります。",

    "q.m16#19.p" to "同じ図で、北東から東側の等高線が極端に密です。これは何を示しますか。",
    "q.m16#19.o0" to "その側は極めて急で、氷崩落と落石の多発地帯である",
    "q.m16#19.o1" to "その側は緩斜面で、キャンプ適地である",
    "q.m16#19.o2" to "その側は標高が低く、リスクが小さい",
    "q.m16#19.o3" to "等高線が密なのは地形が平坦なことを示す",
    "q.m16#19.e" to "等高線が密なほど、同じ水平距離での標高変化が大きい、つまり傾斜が急です。図の北東側は 7950 m から 5750 m まで一気に下がり、数十本の等高線がごく短い水平距離に押し込まれています。典型的な急壁です。\nルート計画では、この読図力が二つのことに直結します。氷崩落や落石の地帯を通るかどうか、そしてアクシデント時に使える撤退地形があるかどうか。図のなかで相対的に緩く等高線の疎な区域こそ、キャンプを設けられる可能性が高い場所です。",

    "q.m16#20.p" to "シナリオ：二種類の地形データ源を比べる",
    "q.m16#20.c" to "ガイドが同じ山の地形図を二枚くれました。一つは Google マップ、もう一つは NASA の SRTM 標高データから生成したものです。どちらも間違ってはいませんが、答えられる問いの範囲が違います。",
    "q.m16#20.e" to "地形データの核心的な違いは、正確かどうかではなく等高間隔です。等高間隔が、どれだけ細かい傾斜変化を読み取れるかを決めます。直感的であることには価値があり、全体像を素早く掴むのに役立ちます。しかしある一区間が急かどうか、通過できるかを判断するには、数値化でき比較できる等高線の密度に戻る必要があります。",
    "q.m16#20.s0.p" to "第 1 段階：この Google マップでは、等高線の標高表示が 6200、6400、6600、6800… と続きます。等高間隔はいくらですか。",
    "q.m16#20.s0.o0" to "50 m",
    "q.m16#20.s0.o1" to "100 m",
    "q.m16#20.s0.o2" to "200 m",
    "q.m16#20.s0.o3" to "500 m",
    "q.m16#20.s0.e" to "隣り合う表示の差が 200 m なので、この等高線系では二本ごとに 200 m 上がることになります。200 m 間隔は全体の山容を見るには向いていますが、二本の間の地形の細部（たとえば落差 40 m の岩壁）は図から完全に消えてしまいます。",
    "q.m16#20.s1.p" to "第 2 段階：SRTM の図の等高間隔は 50 m です。200 m の Google の図と比べたとき、最も実質的な利点は何ですか。",
    "q.m16#20.s1.o0" to "画面がきれいに見える",
    "q.m16#20.s1.o1" to "同じ水平距離で線が密になり、4 倍細かい傾斜変化を識別できる",
    "q.m16#20.s1.o2" to "色が鮮やかになる",
    "q.m16#20.s1.o3" to "文字が大きくなる",
    "q.m16#20.s1.e" to "等高間隔が小さいほど、識別できる地形の細部が増えます。「この斜面を歩けるか」を判断する根拠はまさに等高線の密度です。200 m 間隔の描き方では落差 150 m の急崖が「均された」緩斜面になり、50 m 間隔ならそれをそのまま描き出せます。\n技術ルートの地形評価が SRTM のような高精度データに頼る理由もここにあります。",
    "q.m16#20.s2.p" to "第 3 段階：Google マップの版には明暗の陰影があり、立体的に見えます。斜面の急緩を判断するとき、この陰影はどう扱うべきですか。",
    "q.m16#20.s2.o0" to "陰影が濃いほど急なので、そのまま根拠にしてよい",
    "q.m16#20.s2.o1" to "陰影は光と斜面方位の関係にすぎず、傾斜の根拠にはできない",
    "q.m16#20.s2.o2" to "陰影は積雪の覆われた区域を表す",
    "q.m16#20.s2.o3" to "陰影は標高 7000 m 以上の区域を表す",
    "q.m16#20.s2.e" to "地形陰影（relief shading）は、ある方向から光が当たったときの斜面の明暗関係を模したものです。濃い色はその斜面が逆光であることしか示さず、急であることの証明にはなりません。北向きの緩斜面が、南向きの急斜面より暗いことさえあります。\n陰影を傾斜として使うのは、地形判読でよくある危険な誤読です。陰影は全体像を掴むのに向き、傾斜を数値化するには等高線の密度を見て、できれば標高表示のある高精度データで一度確認するのがよいでしょう。",

    "q.m16#21.p" to "「Google マップは直感的だが精度が低く、SRTM は精度が高いが直感的でない」という説明について、正しい理解はどれですか。",
    "q.m16#21.o0" to "SRTM のほうが正確なので、Google マップに使用価値はない",
    "q.m16#21.o1" to "両者を組み合わせるべきで、まず直感的な図で全体像を掴み、そのうえで高精度の等高線で数値判断を行う",
    "q.m16#21.o2" to "Google マップのほうが直感的なので、斜面の判断ではそちらを優先して信じる",
    "q.m16#21.o3" to "配色が違うだけで、情報量は同じ",
    "q.m16#21.e" to "この二つのデータ源は異なる問いを解きます。Google マップの地形陰影と地名表示は、空間感覚を素早く作るのに役立ちます。山がどこにあり、概形はどうで、ルートはどちら向きか。SRTM の 50 m 等高線は、数値化できる判断に使います。この斜面は何度か、キャンプを置ける場所があるか。\n直感的な図で絞り込み、高精度の図で確認する。これが最も実際的です。片方だけを使うと、遅いか、間違うかのどちらかになります。",

    "q.m16#22.p" to "図の上で、エベレスト（チョモランマ）の頂上があるおよその区域をクリックしてください。",
    "q.m16#22.c" to "これはエベレストとローツェ一帯の SRTM 等高線地形図で、8,000 m 級の二峰が同時に見えています。",
    "q.m16#22.e" to "峰頂を探すには、標高表示が最も高い閉じた等高線を探します。図のこの一帯は表示が 8600、8700 m まで上がり、閉曲線が層をなして内へ収まり、最も内側が峰頂（8,848 m）です。\n「高い」と「急」を混同しないでください。峰頂付近は斜面が最も急な場所ではないことが多く、最も急なのは等高線が最も密なところです。ルートのリスクを判断するとき、この点は決定的です。登頂が試すのは順応と体力で、技術的なリスクは登り下りの途中の数区間にあります。",

    "q.m16#23.p" to "同じ図で、エベレストとローツェの二つの密な閉曲線の間に、等高線が明らかに疎になり、わずかに凹んだ区域があります。これは地形上何ですか。",
    "q.m16#23.o0" to "氷河の源流",
    "q.m16#23.o1" to "二峰の間の鞍部",
    "q.m16#23.o2" to "尾根の最高点",
    "q.m16#23.o3" to "一筋の急崖",
    "q.m16#23.e" to "二つの密な閉曲線の高点のあいだで、等高線が疎になり地形が凹む場所、それが鞍部（コル）です。エベレストとローツェの間のこの鞍部がサウスコル（約 7,900 m）で、エベレスト南稜ルートの第 4 キャンプが置かれ、登頂前の最後の拠点になります。\n等高線図で鞍部を見分けられるのは実用的です。ふつう強風と露出を意味しますが、地形は比較的緩やか。キャンプには向きますが長居には向かない。だから登頂キャンプの多くは鞍部に置かれ、しかもその夜のうちに出発します。",

    "q.m16#24.p" to "図の上で、ムスタグアタ峰の頂上があるおよその区域をクリックしてください。",
    "q.m16#24.c" to "これはムスタグアタ峰（7,509 m）の SRTM 等高線地形図です。頂部は尖った峰ではなく、広いドーム状の雪原です。",
    "q.m16#24.e" to "ムスタグアタの峰頂の形は代表的です。ドーム状の山で、頂部は緩く広く、最高所の閉じた等高線は散らばっていて、尖峰のように層をなして締まりません。こうした峰頂を探すときは、標高表示の最高値（ここでは 7,500 m）とその閉環を見ます。\n形は登攀の体験に直結します。ドーム状の山は頂上区間が急ではない代わりに長く歩くことになり、起伏が小さく目印もないため、下山時に雪原で方向感覚を失いやすい。これもムスタグアタでしばしば挙げられるリスクの一つです。",

    // ---------- m17 高所キャンプの管理 ----------
    "q.m17#0.p" to "高所のキャンプ管理の中心的な目標は何ですか。",
    "q.m17#0.o0" to "キャンプを快適に整えること",
    "q.m17#0.o1" to "最小の消耗で戦力を維持すること",
    "q.m17#0.o2" to "燃料を節約すること",
    "q.m17#0.o3" to "映える写真を撮ること",
    "q.m17#0.e" to "高所では体力のすべてが有限の資源であり、キャンプは唯一「回復できる」場所です。だからキャンプ管理のあらゆる判断は、同じ問いに答えるべきです。その判断は明日の隊をより良い状態にできるのか。",

    "q.m17#1.p" to "キャンプ地を選ぶとき、まず考慮すべき要素は何ですか。",
    "q.m17#1.o0" to "景色と展望",
    "q.m17#1.o1" to "雪崩の走路、氷崩落の範囲、雪庇の直下、クレバスを避けること",
    "q.m17#1.o2" to "水源に近いこと",
    "q.m17#1.o3" to "ルートの起点に近いこと",
    "q.m17#1.e" to "選地の第一原則は「客観的な危険に直撃されないこと」です。キャンプは数時間、ときには丸一日滞在し、しかもほとんど素早く移動できない場所だからです。展望や便利さは二次的な変数にすぎません。",

    "q.m17#2.p" to "雪庇の下にテントを張ってはいけないのはなぜですか。",
    "q.m17#2.o0" to "地面が平らでないから",
    "q.m17#2.o1" to "雪庇はいつ崩れてもおかしくなく、大量の雪と氷がキャンプを直撃しうるから",
    "q.m17#2.o2" to "風が強いから",
    "q.m17#2.o3" to "景色が見えないから",
    "q.m17#2.e" to "雪庇の崩落に予測可能な前兆はありません。午後の昇温時にも、明け方の最も冷える時間にも落ちます。その直下にキャンプを置くことは、「監視できず、事前に反応できない」脅威を常に受け入れることです。",

    "q.m17#3.p" to "【複数選択】キャンプ選地で避けるべき区域はどれですか。",
    "q.m17#3.o0" to "雪崩の走路の下",
    "q.m17#3.o1" to "雪庇の直下や直上",
    "q.m17#3.o2" to "明らかなクレバス帯",
    "q.m17#3.o3" to "氷崩落の到達範囲",
    "q.m17#3.o4" to "見晴らしがよく展望の開けた眺望点",
    "q.m17#3.e" to "この四つはいずれも「客観的な危険の落下点がちょうどキャンプになる」状況です。共通する特徴は監視が難しく、起きたら隊全体に及ぶこと。だからキャンプの選地基準は、行進ルートより保守的であるべきなのです。",

    "q.m17#4.p" to "燃料と食料はどう配分すべきですか。",
    "q.m17#4.o0" to "すべて一人がまとめて管理する",
    "q.m17#4.o1" to "日ごとに小分けし、緊急分を別に確保する",
    "q.m17#4.o2" to "すべてテントの入口に置く",
    "q.m17#4.o3" to "人数で均等に分け、余りを残さない",
    "q.m17#4.e" to "日ごとの小分けは消費を追跡可能にし、緊急分の確保はどんな状況でも「安全に下山するためのエネルギー」が残ることを保証します。山では燃料は調理だけのものではありません。雪を溶かして水を作り、衣類を乾かし、体温を維持する手段でもあります。",

    "q.m17#5.p" to "なぜ緊急分を確保しておくのですか。",
    "q.m17#5.o0" to "食料が傷むから",
    "q.m17#5.o1" to "どんな状況でも安全に下山するための燃料と食料を残すため",
    "q.m17#5.o2" to "販売元がそう求めているから",
    "q.m17#5.o3" to "帰路の荷を軽くするため",
    "q.m17#5.e" to "緊急分が想定するのは最悪の状況です。天候が悪化し、滞在が一日延び、負傷者が出てゆっくり下山する必要がある。すべての資源を「最良の日程」で配分すると、遅れが出た瞬間に「補給もなく前進もできない」袋小路になります。",

    "q.m17#6.p" to "夜間、電子機器（携帯、カメラ、ヘッドランプの電池）はどう扱うべきですか。",
    "q.m17#6.o0" to "テントの外に置く",
    "q.m17#6.o1" to "体に密着させるか、シュラフの中に入れて保温する",
    "q.m17#6.o2" to "ザックの最外層に入れる",
    "q.m17#6.o3" to "とくに何もしなくてよい",
    "q.m17#6.e" to "リチウム電池は低温で容量が大きく落ち、そのまま電源が切れることもあります。保温は「機器を守る」ことではなく、翌朝ヘッドランプが点き、GPS が起動することを保証することです。これらは個人の用品ではなく安全装備です。",

    "q.m17#7.p" to "濡れた衣類はどう処理すべきですか。",
    "q.m17#7.o0" to "テントの外に掛けて凍らせる",
    "q.m17#7.o1" to "できるだけ体に密着させるかシュラフに入れ、体温で乾かす",
    "q.m17#7.o2" to "テントの隅に積んでおく",
    "q.m17#7.o3" to "そのままザックに詰める",
    "q.m17#7.e" to "高所の夜は極端に冷えるため、外に干した濡れ衣類はそのまま凍ります。体温で乾かすのは完全ではありませんが、少なくとも翌朝に着るとき氷になっていない状態にはできます。「体温を資源として使う」典型例です。",

    "q.m17#8.p" to "キャンプをつねに「すぐ撤収できる」状態に保つのはなぜですか。",
    "q.m17#8.o0" to "出発を楽にするため",
    "q.m17#8.o1" to "天候や隊員の状態によって、いつでも緊急退去が必要になりうるから",
    "q.m17#8.o2" to "撤収の時間を節約するため",
    "q.m17#8.o3" to "整理整頓のため",
    "q.m17#8.e" to "高所キャンプの天候の窓は突然閉じることがあり、隊員に高所症状が突然出ることもあります。そのとき「出発まで何分かかるか」がリスクの大きさを直接決めます。物をテントいっぱいに広げていれば、それだけで 30 分余計にかかりかねません。",

    "q.m17#9.p" to "高所で眠りにくくなる主な原因に当てはまらないものはどれですか。",
    "q.m17#9.o0" to "周期性呼吸による浅い覚醒の繰り返し",
    "q.m17#9.o1" to "低酸素と心拍の増加",
    "q.m17#9.o2" to "寒さと不快感",
    "q.m17#9.o3" to "テントの色が明るすぎる",
    "q.m17#9.e" to "前三項はいずれも実際の生理的な原因で、とくに周期性呼吸が典型的です。高所の夜間呼吸は不随意に断続し、繰り返し人を浅い睡眠へ引き戻します。しかも睡眠の質は順応に直結します。だから「よく眠れない」は小さな問題ではありません。",

    "q.m17#10.p" to "【並べ替え】キャンプの設営と撤収の合理的な順序はどれですか。",
    "q.m17#10.o0" to "到着前に周囲に雪崩、氷崩落、雪庇などの脅威がないか観察する",
    "q.m17#10.o1" to "テントの位置を決め、地面を平らに整えて固定する",
    "q.m17#10.o2" to "物資を配分し、雪を溶かして水を作り、翌日の行程と睡眠を整える",
    "q.m17#10.o3" to "撤収前に装備とゴミを点検し、キャンプを元の状態に戻す",
    "q.m17#10.e" to "第一段階が最も飛ばされやすいところです。とくに疲れているときは、平らな場所を見つけた瞬間に張りたくなります。しかし一度設営してしまうと移すコストは極めて高い。だから「まず周囲を見て、それから位置を決める」を習慣にすべきです。",

    "q.m17#11.p" to "キャンプが撤退の拠点でもあると言われるのはなぜですか。",
    "q.m17#11.o0" to "キャンプに物資があるから",
    "q.m17#11.o1" to "撤退は多くの場合まずキャンプに戻り、それから下り続けるか天候を待つかを決めるから",
    "q.m17#11.o2" to "キャンプに通信機器があるから",
    "q.m17#11.o3" to "ガイドがキャンプにいるから",
    "q.m17#11.e" to "高所からの下山は一気に下まで行くのではなく、まず最寄りのキャンプに戻って回復し、観察し、判断するのが普通です。つまりキャンプ自体が「信頼できる目的地」でなければなりません。自分が戻りたくないような場所では困るのです。",

    "q.m17#12.p" to "テントの換気を保つのはなぜですか。",
    "q.m17#12.o0" to "涼しくするため",
    "q.m17#12.o1" to "一酸化炭素の滞留と内部の霜を防ぎ、窒息と中毒のリスクを避けるため",
    "q.m17#12.o2" to "出入りを楽にするため",
    "q.m17#12.o3" to "風の抵抗を減らすため",
    "q.m17#12.e" to "高所でストーブを使うと、密閉したテント内の一酸化炭素濃度は急速に上がることがあります。しかもこの中毒は睡眠中に起きやすく、症状（頭痛、だるさ）は高所病と区別しにくい。これらが重なるからこそ、換気は絶対条件になります。",

    "q.m17#13.p" to "テント内でストーブを使うとき、最も警戒すべきものは何ですか。",
    "q.m17#13.o0" to "燃料の漏れ",
    "q.m17#13.o1" to "一酸化炭素中毒",
    "q.m17#13.o2" to "テントが焦げること",
    "q.m17#13.o3" to "騒音",
    "q.m17#13.e" to "一酸化炭素は無色無臭で、中毒の初期症状（頭痛、眠気）は高所病と高度に重なります。ここが危険な点です。人は「高所病だと思い込んだまま」眠ってしまいます。ストーブを使うときは必ず換気を保たねばなりません。",

    "q.m17#14.p" to "【複数選択】キャンプで意識して維持すべき健康管理はどれですか。",
    "q.m17#14.o0" to "十分な水分補給（雪を溶かして水を作る）",
    "q.m17#14.o1" to "食欲がなくても十分に食べる",
    "q.m17#14.o2" to "衣類を乾いた状態に保つ",
    "q.m17#14.o3" to "隊員の状態と歩容を互いに観察する",
    "q.m17#14.o4" to "コーヒーとエナジードリンクで食事を代用する",
    "q.m17#14.e" to "前三項は自己管理、第四項はチームでの管理です。しかも第四項は前三項より有効なことが多い。高所病の初期徴候（歩行の不安定さ、反応の鈍さ）は自分では気づきにくいのに、同行者には一目で分かるからです。",

    "q.m17#15.p" to "空欄を埋めてください。高所キャンプ以上では、燃料と食料はふつう（ ）ごとに小分けし、緊急分を確保します。",
    "q.m17#15.a0" to "日",
    "q.m17#15.a1" to "一日",
    "q.m17#15.a2" to "毎日",
    "q.m17#15.a3" to "1 日",
    "q.m17#15.e" to "日ごとの小分けです。これによって消費の進み具合が一目で分かり、遅れが出たときに「あと何日分か」を即座に把握できます。使い切ってから気づくのでは遅いのです。",

    // ---------- m18 7,000 m 級の山の肖像 ----------
    "q.m18#0.p" to "ムスタグアタ峰の標高はいくらですか。",
    "q.m18#0.o0" to "6,812 m",
    "q.m18#0.o1" to "7,126 m",
    "q.m18#0.o2" to "7,134 m",
    "q.m18#0.o3" to "7,509 m",
    "q.m18#0.e" to "ムスタグアタ峰は 7,509 m、新疆アクタオ（アクト）にあります。国内の 7,000 m 級で最初に選ばれる目標であり、四座のなかでも最も標高が高い山です。",

    "q.m18#1.p" to "ムスタグアタが「氷山の父」と呼ばれる主な理由は何ですか。",
    "q.m18#1.o0" to "世界最高峰だから",
    "q.m18#1.o1" to "氷河と雪の量が極めて多く、遠望すると巨大な氷帽のように見えるから",
    "q.m18#1.o2" to "最初に登頂された 7,000 m だから",
    "q.m18#1.o3" to "地元の伝説で神山とされているから",
    "q.m18#1.e" to "この呼び名は外観から来ています。頂部が巨大な氷帽に覆われ、雪の斜面が広く続くため、遠くから見ると白い巨山のようです。「氷山の父」という姿は登攀の特徴も説明します。雪の斜面が長く、ルートは緩やかだが時間がかかるのです。",

    "q.m18#2.p" to "ムスタグアタ登攀の技術的な特徴は何ですか。",
    "q.m18#2.o0" to "垂直な氷壁が主体で、技術難度が極めて高い",
    "q.m18#2.o1" to "雪の斜面が長く続き、技術難度は中程度だが順応と体力の要求が高い",
    "q.m18#2.o2" to "技術装備はほとんど不要",
    "q.m18#2.o3" to "主にフリークライミングの地形",
    "q.m18#2.e" to "これは 7,000 m 級の典型的な姿です。ルート自体は難しくないかもしれませんが、高所で長時間にわたり重量を背負って行軍することが、小さな問題をすべて増幅します。だから本当の準備の重心は順応と体力にあり、高度な技術ではありません。",

    "q.m18#3.p" to "アマ・ダブラムの実際の標高はいくらですか。",
    "q.m18#3.o0" to "6,812 m",
    "q.m18#3.o1" to "7,126 m",
    "q.m18#3.o2" to "7,509 m",
    "q.m18#3.o3" to "8,027 m",
    "q.m18#3.e" to "アマ・ダブラムは 6,812 m、ネパールのクンブ地区にあります。標高では 6,000 m 級ですが、7,000 m ステップに置かれているのは、その技術難度が 7,000 m 以上に対応しているからです。",

    "q.m18#4.p" to "アマ・ダブラムが 6,812 m しかないのに 7,000 m ステップに分類されるのはなぜですか。",
    "q.m18#4.o0" to "行政上の区分が 7,000 m 級だから",
    "q.m18#4.o1" to "切り立った岩雪混合の地形と強い露出感により、技術難度が 7,000 m 以上に対応するから",
    "q.m18#4.o2" to "登頂率が非常に低いから",
    "q.m18#4.o3" to "7,000 m の山域に位置しているから",
    "q.m18#4.e" to "これが本課でもっとも覚えておくべき点です。山の難度は標高と等しくありません。アマ・ダブラムは典型例で、標高は多くの 7,000 m 峰より低いのに、技術的な敷居と心理的な負荷はより大きい可能性があります。標高だけで山を選ぶのは危険な行為です。",

    "q.m18#5.p" to "レーニン峰の標高と位置はどれですか。",
    "q.m18#5.o0" to "7,126 m、ネパール",
    "q.m18#5.o1" to "7,134 m、パミール高原",
    "q.m18#5.o2" to "7,509 m、新疆",
    "q.m18#5.o3" to "6,812 m、ネパール・クンブ",
    "q.m18#5.e" to "レーニン峰は 7,134 m、パミール高原にあります。7,000 m 級のなかでは比較的穏やかな選択で、最初の 7,000 m 目標としてよく選ばれます。",

    "q.m18#6.p" to "ヒムルン峰の標高はいくらですか。",
    "q.m18#6.o0" to "7,126 m",
    "q.m18#6.o1" to "7,134 m",
    "q.m18#6.o2" to "7,509 m",
    "q.m18#6.o3" to "6,812 m",
    "q.m18#6.e" to "ヒムルン峰は 7,126 m、ネパール国内にあります。ルートは雪の斜面と氷壁の混合で、ネパールの 7,000 m 級のなかでは人気があります。",

    "q.m18#7.p" to "【並べ替え】次の山を標高の低い順に並べてください。",
    "q.m18#7.o0" to "アマ・ダブラム（6,812 m）",
    "q.m18#7.o1" to "ヒムルン峰（7,126 m）",
    "q.m18#7.o2" to "レーニン峰（7,134 m）",
    "q.m18#7.o3" to "ムスタグアタ峰（7,509 m）",
    "q.m18#7.e" to "この並びは、よくある誤解をちょうど露呈させます。標高で難度を選ぶと、アマ・ダブラムをムスタグアタより前に置くことになりますが、実際の技術難度は逆かもしれません。繰り返します。標高は数ある変数の一つにすぎません。",

    "q.m18#8.p" to "【複数選択】7,000 m 級が 6,000 m 級と比べて変わる主な点はどれですか。",
    "q.m18#8.o0" to "順応の期間が長くなり、高所キャンプのローテーションがより多く必要になる",
    "q.m18#8.o1" to "天候の窓が狭くなり、タイミングの要求が高まる",
    "q.m18#8.o2" to "撤退の難度が上がり、セルフレスキュー能力が必須になる",
    "q.m18#8.o3" to "技術地形と露出感が全般的に増す",
    "q.m18#8.o4" to "人工酸素が標準装備になる",
    "q.m18#8.e" to "四つの変化は足し算ではなく掛け算で効きます。順応が不十分だと窓を逃し、窓を逃すとより悪い条件で撤退することになり、撤退の難度は標高と技術地形でさらに増幅される。だから 7,000 m は分水嶺と呼ばれるのです。",

    "q.m18#9.p" to "7,000 m が「分水嶺」と言われるのはなぜですか。",
    "q.m18#9.o0" to "7,000 m 以上でないとピッケルが要らないから",
    "q.m18#9.o1" to "ここから先は技術、判断、体力、後方支援の四つが同時に作用し、どれか一つの強みでは補えなくなるから",
    "q.m18#9.o2" to "7,000 m 以上でないと氷河が見られないから",
    "q.m18#9.o3" to "7,000 m 以上でないと商業隊がないから",
    "q.m18#9.e" to "5,000 m 級の失敗は単一の原因（順応か体力）であることが多く、6,000 m 級で重なり始め、7,000 m 級ではすべてが揃っていなければなりません。このステップで技術、判断、天気、セルフレスキュー、キャンプ管理を並べている理由もそこにあります。もともと一つの体系だからです。",

    "q.m18#10.p" to "7,000 m の目標を選ぶとき、最も注目すべき指標は何ですか。",
    "q.m18#10.o0" to "標高",
    "q.m18#10.o1" to "ルートの種類、後方支援の条件、順応のペース、撤退計画の総合的な適合",
    "q.m18#10.o2" to "登山費用",
    "q.m18#10.o3" to "登頂率",
    "q.m18#10.e" to "どれか一つを見るだけでは足りません。標高が高いから難しいとは限らず、登頂率が高いから安全とは限らず、費用が安いから得とは限らない。本当の判断は「この四つを組み合わせたとき、今の自分が引き受けられるか」です。",

    "q.m18#11.p" to "ムスタグアタ登攀で、「長い雪の斜面」それ自体がリスクになるのはなぜですか。",
    "q.m18#11.o0" to "雪の斜面が滑りすぎるから",
    "q.m18#11.o1" to "長時間にわたり高所環境にさらされ、体力と判断力が下がり続け、しかも撤退距離が長いから",
    "q.m18#11.o2" to "雪の斜面で雪崩が頻発するから",
    "q.m18#11.o3" to "雪の斜面ではアンザイレンできないから",
    "q.m18#11.e" to "「難しくはないが長い」は 7,000 m 級の典型的なリスクモデルです。単点の難所は与えず、持続的に消耗させます。長時間の曝露は体力、注意力、判断の質を少しずつ下げ、しかも下がった分はそのまま安全余裕です。",

    "q.m18#12.p" to "【組み合わせ】山と、その典型的な特徴を結びつけてください。",
    "q.m18#12.l0" to "ムスタグアタ峰",
    "q.m18#12.l1" to "アマ・ダブラム",
    "q.m18#12.l2" to "レーニン峰",
    "q.m18#12.l3" to "ヒムルン峰",
    "q.m18#12.r0" to "氷山の父：雪の斜面が長く、順応と体力を試す",
    "q.m18#12.r1" to "切り立った岩雪混合で露出感が強く、8,000 m の試金石",
    "q.m18#12.r2" to "パミール高原にあり、7,000 m 級では比較的穏やか",
    "q.m18#12.r3" to "ネパール国内、雪の斜面と氷壁の混合",
    "q.m18#12.e" to "この四つの肖像は、実は四つの異なる準備の重点に対応します。ムスタグアタで順応を、アマ・ダブラムで技術と心理を、レーニン峰を進階の踏み台に、ヒムルンで総合的に検証する。並べて見れば、自分の弱点に合わせて選べます。",

    "q.m18#13.p" to "目標が 8,000 m なら、7,000 m ステップで山を選ぶ最も合理的な考え方はどれですか。",
    "q.m18#13.o0" to "標高が最も高い山を選ぶ",
    "q.m18#13.o1" to "自分の弱点（技術、順応、露出感）を補える山を重点的に選ぶ",
    "q.m18#13.o2" to "最も安い山を選ぶ",
    "q.m18#13.o3" to "登頂率が最も高い山を選ぶ",
    "q.m18#13.e" to "7,000 m 級を「弱点に合わせた訓練の場」と捉えるほうが、「レベルを上げる」より価値があります。たとえば技術が足りなければアマ・ダブラム、順応が弱ければ雪の斜面が長く高所キャンプのローテーションが整ったムスタグアタを選びます。",

    "q.m18#14.p" to "7,000 m 級の準備期間について、正しい認識はどれですか。",
    "q.m18#14.o0" to "6,000 m 級とほぼ同じ",
    "q.m18#14.o1" to "明らかに長く、十分な高所キャンプのローテーションと順応の時間が必要",
    "q.m18#14.o2" to "体力トレーニングだけでよい",
    "q.m18#14.o3" to "前回の登攀の直後から始められる",
    "q.m18#14.e" to "順応は累積の過程で、7,000 m 級ではしばしば複数回の高所キャンプのローテーションが必要です。日程を詰め、順応の時間を計算に入れないことが、多くの 7,000 m 級の隊が登頂できず、あるいは事故に至る直接の原因になります。",

    "q.m18#15.p" to "このステップで「危険の判断」を「技術の課」の後に置いているのはなぜですか。",
    "q.m18#15.o0" to "判断は技術より易しいから",
    "q.m18#15.o1" to "技術力が難しい地形に入る自信を高めるので、なおさら判断で制約する必要があるから",
    "q.m18#15.o2" to "課の分量の都合",
    "q.m18#15.o3" to "技術は重要でないから",
    "q.m18#15.e" to "これは現実に即した設計です。技術が熟練するほど行けるルートは難しくなり、「自分を制限する」必要性はむしろ上がります。判断の課を技術の課の後に置くことは、現実のこの順序に対応しています。まず能力があり、そのうえで抑制がある。",

    // ---------- m19 8,000 m 級の生理と戦略 ----------
    "q.m19#0.p" to "「デスゾーン」とはふつうどこを指しますか。",
    "q.m19#0.o0" to "7,000 m 以上",
    "q.m19#0.o1" to "8,000 m 以上",
    "q.m19#0.o2" to "5,500 m 以上",
    "q.m19#0.o3" to "6,000 m 以上",
    "q.m19#0.e" to "8,000 m 以上がデスゾーンと呼ばれる理由は単純です。この高さでは酸素分圧が低すぎて、どんなに順応しても人体が長期的に均衡を保てません。修辞ではなく生理的な事実であり、8,000 m 級と 7,000 m 級を分ける最も本質的な境界です。",

    "q.m19#1.p" to "8,000 m の気圧は、海面のおよそどれくらいですか。",
    "q.m19#1.o0" to "半分",
    "q.m19#1.o1" to "三分の二",
    "q.m19#1.o2" to "三分の一",
    "q.m19#1.o3" to "五分の一",
    "q.m19#1.e" to "およそ三分の一です。一回の呼吸で取り込む酸素分子は海面の三割ほどしかなく、しかも登攀は安静時の数倍の酸素を必要とします。この需給の差こそ、8,000 m 級のあらゆるリスクの源です。",

    "q.m19#2.p" to "人体が 8,000 m 以上に長く留まれないのはなぜですか。",
    "q.m19#2.o0" to "寒すぎるから",
    "q.m19#2.o1" to "酸素分圧が代謝を維持する下限を下回り、身体が衰え続けるから",
    "q.m19#2.o2" to "食料が足りないから",
    "q.m19#2.o3" to "風が強すぎるから",
    "q.m19#2.e" to "長く留まることは「消耗が修復を上回る」ことを意味します。休息中でも筋肉と体重を失い続け、認知能力も低下します。8,000 m の行程が「素早く入って素早く出る」しかない理由であり、条件が良くなるのを待つ選択肢はありません。",

    "q.m19#3.p" to "低酸素が最初に影響する能力は、ふつう何ですか。",
    "q.m19#3.o0" to "脚の力",
    "q.m19#3.o1" to "判断力と認知能力",
    "q.m19#3.o2" to "視力",
    "q.m19#3.o3" to "聴力",
    "q.m19#3.e" to "これが 8,000 m 級で最も危険な仕組みです。判断力が落ちた人は、自分の判断力が落ちたことを判断できません。逆に脚の力が落ちればすぐ分かりますが、「まだ行ける」という考え自体がすでに低酸素の産物かもしれません。",

    "q.m19#4.p" to "「判断力の低下」が 8,000 m でとくに危険なのはなぜですか。",
    "q.m19#4.o0" to "道に迷うから",
    "q.m19#4.o1" to "すでに損なわれた判断力で、続行すべきか撤退すべきかを判断しなければならないから",
    "q.m19#4.o2" to "同行者に影響するから",
    "q.m19#4.o3" to "登攀速度が落ちるから",
    "q.m19#4.e" to "これは再帰的な罠です。重要な決定（続行か撤退か）を迫られるまさにそのとき、あなたの決定能力が最も当てにならない。「もう少し進んで様子を見よう」は 4,000 m なら妥当でも、8,000 m では低酸素に駆られた誤判断になっている可能性があります。",

    "q.m19#5.p" to "【複数選択】低酸素による認知能力の低下の典型的な表れはどれですか。",
    "q.m19#5.o0" to "反応が遅くなり、言葉が不明瞭になる",
    "q.m19#5.o1" to "計算や判断を誤る",
    "q.m19#5.o2" to "リスクの評価が過度に楽観的になる",
    "q.m19#5.o3" to "感情の起伏、いらだち、あるいは無関心",
    "q.m19#5.o4" to "手指と足趾の凍傷の感覚が鈍る",
    "q.m19#5.e" to "四項目はいずれも典型的で、しかも共通点は本人が気づきにくいことです。だから有効なのは外化です。記憶の代わりにチェックリスト、『だいたい大丈夫』の代わりに固定した時刻、自己評価の代わりに同行者どうしの確認。",

    "q.m19#6.p" to "判断力の低下というリスクに対して、最も有効な対策は何ですか。",
    "q.m19#6.o0" to "意志の力で意識を保つよう自分に言い聞かせる",
    "q.m19#6.o1" to "判断を、事前に書いたチェックリストと固定の規則（時刻、酸素残量、天候のしきい値）に外化する",
    "q.m19#6.o2" to "温かい水を多く飲む",
    "q.m19#6.o3" to "速度を落とす",
    "q.m19#6.e" to "意志の力こそ低酸素が最初に削るものです。信頼できる方法は、状態がまだ良いうちに規則を書き留めておくこと。何時に必ず引き返す、酸素残量がいくつになったら下山する。そのときは事実を照合するだけで、判断し直す必要はありません。",

    "q.m19#7.p" to "8,000 m の行程で「早出発・早帰還」が強調されるのはなぜですか。",
    "q.m19#7.o0" to "人混みを避けるため",
    "q.m19#7.o1" to "午後は天候悪化の確率が上がり、低温と強風が体力と酸素を急激に奪うから",
    "q.m19#7.o2" to "午前のほうがルートが短いから",
    "q.m19#7.o3" to "ガイドの習慣だから",
    "q.m19#7.e" to "8,000 m では「遅れ」の代償が極端に大きくなります。同じ道でも午後に歩けば体力を倍消耗し、日が落ちれば気温と判断力が同時に下がる。「下山が遅すぎた」は、ほぼつねに事故の連鎖の共通する起点です。",

    "q.m19#8.p" to "8,000 m 級で「意思決定を単純化する」必要があるのはなぜですか。",
    "q.m19#8.o0" to "時間を節約するため",
    "q.m19#8.o1" to "認知資源は限られており、本当に重要な決定のために残すべきだから",
    "q.m19#8.o2" to "高所では考えたくないから",
    "q.m19#8.o3" to "同行者が決めてくれるから",
    "q.m19#8.e" to "具体的には、装備の位置と順序を固定する、操作手順をチェックリスト化する、行程をあらかじめ固定する。「今日は何を着るか、まず何をするか」を考えなくてよい既定動作にすることで、貴重な判断力を「続行か撤退か」に残せます。",

    "q.m19#9.p" to "経験豊富な登攀者でも 8,000 m でチェックリストを使う必要があるのはなぜですか。",
    "q.m19#9.o0" to "記憶が当てにならないから",
    "q.m19#9.o1" to "低酸素は作業記憶を優先的に損なうが、チェックリストは記憶に依存しないから",
    "q.m19#9.o2" to "規則がそう定めているから",
    "q.m19#9.o3" to "新人に学ばせるため",
    "q.m19#9.e" to "航空業界の論理と同じです。高負荷・高影響の環境では、「自分は忘れないはずだ」に頼れません。チェックリストの役割は新人教育ではなく、専門家にも起こる抜けに対して保険をかけることです。",

    "q.m19#10.p" to "高所で体重が減り続ける主な理由は何ですか。",
    "q.m19#10.o0" to "食事がおいしくないから",
    "q.m19#10.o1" to "低酸素状態で身体が自分の組織を分解し続け、しかも食欲低下で摂取が足りなくなるから",
    "q.m19#10.o2" to "運動量が多いから",
    "q.m19#10.o3" to "水分が足りないから",
    "q.m19#10.e" to "二つの要因が同時に働きます。一方で低酸素は身体を分解が合成を上回る状態にし、他方で高所反応そのものが食欲を抑えます。だから高所で「食べられること」は楽しみではなく能力なのです。",

    "q.m19#11.p" to "8,000 m で眠りにくくなるのはなぜですか。",
    "q.m19#11.o0" to "テントが快適でないから",
    "q.m19#11.o1" to "低酸素による周期性呼吸で呼吸が断続し、睡眠から引き戻されるから",
    "q.m19#11.o2" to "風が強いから",
    "q.m19#11.o3" to "昼間に寝すぎたから",
    "q.m19#11.e" to "周期性呼吸は高所睡眠の典型現象です。呼吸の駆動が不安定になり、「無呼吸→覚醒」が繰り返されます。しかも睡眠の質は翌日の順応と体力に直結します。だから高所キャンプでは「眠れること」も中核的な力になります。",

    "q.m19#12.p" to "【並べ替え】低酸素が身体機能に与える影響を、「ふつう現れる順」に並べてください。",
    "q.m19#12.o0" to "呼吸の増加、心拍の上昇（代償）",
    "q.m19#12.o1" to "長時間の活動での持久力低下",
    "q.m19#12.o2" to "判断力と計算能力の低下",
    "q.m19#12.o3" to "意識の変容、運動失調",
    "q.m19#12.e" to "前二項は身体が「なんとかしようとしている」段階、後二項は「持ちこたえられなくなりつつある」段階です。危険なのは第三項で、明らかな意識変容より前に現れます。だから「見た目は普通」は「頭も正常」と等しくありません。",

    "q.m19#13.p" to "8,000 m の低酸素に対処する最も直接的で確実な手段は何ですか。",
    "q.m19#13.o0" to "食事を増やす",
    "q.m19#13.o1" to "補助酸素を使う",
    "q.m19#13.o2" to "よく休む",
    "q.m19#13.o3" to "行進速度を落とす",
    "q.m19#13.e" to "他の手段は「消耗を減らす」か「順応を速める」段階にとどまりますが、酸素の補給は吸入酸素分圧そのものを押し上げ、根源の変数を変えます。8,000 m 級で補助酸素が標準の安全装備とされる理由もここにあります。",

    "q.m19#14.p" to "「順応の上限」について、正しい理解はどれですか。",
    "q.m19#14.o0" to "順応は際限なく進められる",
    "q.m19#14.o1" to "順応には上限があり、ある標高を超えるとどんなに順応しても完全には代償できない",
    "q.m19#14.o2" to "順応は一日で完了する",
    "q.m19#14.o3" to "順応は標高と関係ない",
    "q.m19#14.e" to "順応は限界のある過程で、どこまでも上がり続ける曲線ではありません。8,000 m 以上で酸素と「素早く出入りする」戦略に頼らざるをえない根本理由でもあります。準備不足ではなく、生理的に「順応してから滞在する」という選択肢が存在しないのです。",

    "q.m19#15.p" to "8,000 m 級の事故の根本原因が単一の出来事でないことが多いのはなぜですか。",
    "q.m19#15.o0" to "運が悪いから",
    "q.m19#15.o1" to "低酸素が判断、体力、協調運動を同時に弱め、複数の環が一斉に脆くなるから",
    "q.m19#15.o2" to "装備がよくないから",
    "q.m19#15.o3" to "人が多いから",
    "q.m19#15.e" to "低所では一つのミスを補う余裕が残ることが多いのに対し、8,000 m では判断、体力、動作制御が同時に落ち、小さなミスがそのまま事故へ直結しやすくなります。だから 8,000 m 級の安全戦略は「もう少し気をつける」ではなく「保険を何層も重ねる」でなければなりません。",

    "q.m19#16.p" to "【複数選択】8,000 m 級の主な死因はどれですか。",
    "q.m19#16.o0" to "雪崩と氷崩落",
    "q.m19#16.o1" to "滑落",
    "q.m19#16.o2" to "低体温症",
    "q.m19#16.o3" to "高所疾病とその合併症",
    "q.m19#16.o4" to "雪盲や日焼けなどの環境障害",
    "q.m19#16.e" to "四つともよく起こり、しかも重なり合います。滑落して自力で動けず → 低温のなかで待ち → 低体温 → 高所疾病が悪化する。8,000 m 級の訓練で「高所病」だけを見ていられず、技術、判断、システムをすべて組み込まねばならない理由もここにあります。",

    "q.m19#17.p" to "空欄を埋めてください。8,000 m 以上は「（ ）地帯」と呼ばれます。",
    "q.m19#17.a0" to "死亡",
    "q.m19#17.a1" to "死",
    "q.m19#17.e" to "デスゾーン（死亡地帯）です。この用語の実用的な価値は、厳しい制約を伝えることにあります。ここには「ちょっと待つ」「少し緩める」という選択肢がありません。計画、補給、判断のすべてを「できるだけ早く通過する」ことを中心に設計しなければなりません。",

    "q.m19#18.p" to "8,000 m で「どうしても登頂を続けたくなった」と気づいたとき、まずすべきことは何ですか。",
    "q.m19#18.o0" to "自分の直感を信じて上へ進む",
    "q.m19#18.o1" to "それがまさに低酸素によるリスクの過小評価かもしれないと警戒し、事前に定めた折り返し条件と照合する",
    "q.m19#18.o2" to "速度を上げて一気に登頂する",
    "q.m19#18.o3" to "同行者に決めてもらう",
    "q.m19#18.e" to "非常に代表的な状況です。強い「続けたい」は低所では単なる渇望かもしれませんが、8,000 m では判断力が損なわれたサインかもしれません。このとき唯一信頼できる参照は感覚ではなく、出発前に書いておいた客観的な条件です。",

    // ---------- m20 補助酸素システム ----------
    "q.m20#0.p" to "8,000 m 級における補助酸素の主な役割は何ですか。",
    "q.m20#0.o0" to "体力トレーニングの代わりになる",
    "q.m20#0.o1" to "血中酸素を上げ、高所病のリスクを下げ、行動能力と判断力を改善する",
    "q.m20#0.o2" to "保温",
    "q.m20#0.o3" to "装備の重量を減らす",
    "q.m20#0.e" to "このうち「判断力を改善する」が見落とされやすい一方で、安全上は最も重要です。8,000 m で最も危険な要素に直接対抗するからです。だからこそ酸素は 8,000 m 級では「省力の道具」ではなく標準の安全装備に位置づけられます。",

    "q.m20#1.p" to "補助酸素システムの構成要素はどれですか。",
    "q.m20#1.o0" to "ボンベ、レギュレーター、流量計、マスク／鼻カニュラ",
    "q.m20#1.o1" to "ボンベとザック",
    "q.m20#1.o2" to "マスクと保温層",
    "q.m20#1.o3" to "レギュレーターとヘルメット",
    "q.m20#1.e" to "四つの部分がそれぞれ役割を担います。ボンベが貯蔵し、レギュレーターが高圧を安全な範囲まで下げ、流量計が出力を制御し、マスク／鼻カニュラが供給を担います。どれか一环でも不調なら実際の吸入量は想定を下回ります。だからこそ区間ごとの点検が必要です。",

    "q.m20#2.p" to "登攀中によく使われる酸素流量の範囲はおよそどれですか。",
    "q.m20#2.o0" to "0.5〜1 L/min",
    "q.m20#2.o1" to "2〜4 L/min",
    "q.m20#2.o2" to "8〜10 L/min",
    "q.m20#2.o3" to "15 L/min 以上",
    "q.m20#2.e" to "2〜4 L/min が登攀中の常用範囲で、具体的な値は標高、体力消耗、個人の反応によって変わります。流量が高いほど楽ですが減りも早い。このトレードオフが、8,000 m でどれだけ滞在できるかを直接決めます。",

    "q.m20#3.p" to "酸素量を計算するとき、なぜ「緊急予備」を別に確保しなければならないのですか。",
    "q.m20#3.o0" to "少し多めに持つため",
    "q.m20#3.o1" to "行程の遅れ、同行者への支援、システムの故障で余分に消費しうるから",
    "q.m20#3.o2" to "ボンベが漏れるから",
    "q.m20#3.o3" to "規則が求めているから",
    "q.m20#3.e" to "酸素計画の典型的な誤りは「頂上までちょうど足りる」計算です。実際の行程はほぼつねに計画より遅れ、同行者の酸素不足やシステムの漏れも起こりえます。緊急分がなければ、ずれが生じた瞬間に最も危険な標高で「賭ける」しかありません。",

    "q.m20#4.p" to "酸素が尽きたとき、何が起こりえますか。",
    "q.m20#4.o0" to "何の影響もない",
    "q.m20#4.o1" to "身体が高い吸入酸素濃度に慣れているため、状態が急速に悪化しうる",
    "q.m20#4.o2" to "ただちに高所病の発作が起きる",
    "q.m20#4.o3" to "自動的に空気呼吸に切り替わる",
    "q.m20#4.e" to "高濃度酸素から環境の酸素分圧へ突然戻るのは、8,000 m で「突然ひと区切り標高が上がった」のと同じです。しかもキャンプから遠く体力を使い切っていれば、状況は急速に危険になります。酸素の余量を保守的に残さねばならない理由です。",

    "q.m20#5.p" to "【複数選択】酸素システムを使ううえで守るべき規律はどれですか。",
    "q.m20#5.o0" to "区間ごとに流量と接続部を点検する",
    "q.m20#5.o1" to "計画した流量で使い、勝手に上げない",
    "q.m20#5.o2" to "残量と、あと何時間もつかを記録する",
    "q.m20#5.o3" to "残量がいくつになったら必ず下山するかをあらかじめ取り決める",
    "q.m20#5.o4" to "具合が悪いと感じたら流量を最大にする",
    "q.m20#5.e" to "第四項が最も重要です。「残量がいくつになったら撤退」を、現場で相談するのではなく事前に決めた数字にしておく。その時点で、この規則を必要とする人自身が正確な判断力を失っているかもしれないからです。",

    "q.m20#6.p" to "「酸素を使うのはズルではない」と言われるのはなぜですか。",
    "q.m20#6.o0" to "規則が認めているから",
    "q.m20#6.o1" to "8,000 m 以上は人体が長期に代償できる生理的範囲を超えており、酸素の使用は生理的事実に基づく標準的な方法だから",
    "q.m20#6.o2" to "みんな使っているから",
    "q.m20#6.o3" to "登頂率が上がるから",
    "q.m20#6.e" to "「ズル」という言い方には「少し多く使えば誤魔化せる」という前提が隠れています。しかし 8,000 m の制約は規則ではなく、物理と生理の制約です。酸素を使うのは生理的な上限を少し押し上げるだけで、「長期滞在できない」という事実は変わりません。",

    "q.m20#7.p" to "マスクと鼻カニュラの主な違いは何ですか。",
    "q.m20#7.o0" to "マスクはより安定した酸素濃度を得られるが、動作時に息苦しく視界にも影響する",
    "q.m20#7.o1" to "鼻カニュラのほうが高い濃度を得られる",
    "q.m20#7.o2" to "両者はまったく同じ",
    "q.m20#7.o3" to "マスクのほうが軽い",
    "q.m20#7.e" to "マスクは密閉性が高く濃度が安定しますが、呼吸抵抗が大きく、曇りやすく、動作時には不快です。鼻カニュラは快適で視界もよい反面、実際の吸入濃度は呼吸の仕方に左右されます。選択は地形、強度、個人の耐性で決まるもので、単純な「どちらが良い」ではありません。",

    "q.m20#8.p" to "流量を上げるか下げるかで、何を天秤にかけることになりますか。",
    "q.m20#8.o0" to "快適さと持続時間",
    "q.m20#8.o1" to "重量と価格",
    "q.m20#8.o2" to "トレードオフはない",
    "q.m20#8.o3" to "標高と気温",
    "q.m20#8.e" to "流量が高いほど身体は楽で判断力も保てますが、もつ時間は短くなります。つまり酸素計画は実質的に「高所でどれだけ滞在できるか」の予算であり、登頂日の時間窓と折り返し時刻を直接決めます。",

    "q.m20#9.p" to "酸素ボンベの重量が後方支援の難題になるのはなぜですか。",
    "q.m20#9.o0" to "体積が大きいから",
    "q.m20#9.o1" to "ボンベ本体もガスも重く、しかも高所キャンプ以上へは人力で運ぶ必要があるから",
    "q.m20#9.o2" to "預け入れできないから",
    "q.m20#9.o3" to "壊れやすいから",
    "q.m20#9.e" to "高所では 1 kg の代償が増幅され、しかも酸素ボンベは「重くて圧縮できない」装備です。酸素計画をキャンプ配置や人員配置と一体で設計しなければならない理由であり、独立した装備の話では済みません。",

    "q.m20#10.p" to "酸素を高所キャンプに前もって置いておくのはなぜですか。",
    "q.m20#10.o0" to "登頂日の負担を減らし、登頂日に使える酸素を確保するため",
    "q.m20#10.o1" to "盗難を防ぐため",
    "q.m20#10.o2" to "山のほうが寒いから",
    "q.m20#10.o3" to "費用を節約するため",
    "q.m20#10.e" to "登頂日は最も重要で体力が最も少ない日で、酸素を担いで登る余裕はありません。だから酸素は事前に何度も運び上げる必要があり、その結果、酸素量、人員、天候の窓が計画段階で互いに縛り合います。",

    "q.m20#11.p" to "途中で酸素システムが故障したら、どうすべきですか。",
    "q.m20#11.o0" to "登攀を続け、帰ってから直す",
    "q.m20#11.o1" to "残りの酸素と自分の標高をただちに評価し、計画に従って下降するか予備システムを使う",
    "q.m20#11.o2" to "流量を上げて直そうとする",
    "q.m20#11.o3" to "分解して修理する",
    "q.m20#11.e" to "酸素の故障は、より高い標高の条件で「丸腰」になることを意味します。対処の優先度は何よりも高い。予備システムで続けられるかをまず判断し、無理なら下降する。8,000 m では後退は意味のある選択であり、失敗ではありません。",

    "q.m20#12.p" to "【並べ替え】登頂日の酸素システムの点検順序はどれですか。",
    "q.m20#12.o0" to "ボンベ内の圧力と、あと何時間もつかを確認する",
    "q.m20#12.o1" to "レギュレーター、配管、マスク／鼻カニュラが正常かを点検する",
    "q.m20#12.o2" to "流量を開き、実際に正常な出気があるか確認する",
    "q.m20#12.o3" to "残量を記録し、同行者と後方に伝える",
    "q.m20#12.e" to "前三段階は技術的な点検、第四段階はチーム内の共有です。後者は高所でとくに重要です。同行者があなたの酸素残量を知っていれば、あなたの状態が崩れたとき、本人より早く異変に気づけるからです。",

    "q.m20#13.p" to "酸素が順応の代わりにならないのはなぜですか。",
    "q.m20#13.o0" to "酸素が高すぎるから",
    "q.m20#13.o1" to "順応は身体自身が生み出す生理的な代償で、酸素は吸入濃度を押し上げるだけだから",
    "q.m20#13.o2" to "酸素が失効するから",
    "q.m20#13.o3" to "酸素は高所病にしか効かないから",
    "q.m20#13.e" to "順応が変えるのは「身体がどう酸素を使うか」、酸素が変えるのは「どれだけ入ってくるか」です。前者を後者で得ることはできません。だから下山、段階的な上昇、十分な順応の時間は、8,000 m 級でも省けない前提条件なのです。",

    "q.m20#14.p" to "【複数選択】酸素システムのよくある故障はどれですか。",
    "q.m20#14.o0" to "接続部の凍結や詰まり",
    "q.m20#14.o1" to "配管の漏れ",
    "q.m20#14.o2" to "レギュレーターの故障による流量の不正確さ",
    "q.m20#14.o3" to "ボンベのバルブが開きにくい",
    "q.m20#14.o4" to "ボンベの重量が想定を超える",
    "q.m20#14.e" to "四つとも低温、凍結、操作のしにくさに関係し、しかもいずれも最も対処しにくい高所・疲労下で起こります。予備システムに加えて「故障時の判断の計画」が必要な理由でもあります。",

    "q.m20#15.p" to "酸素計画を行程表に書き込まねばならないのはなぜですか。",
    "q.m20#15.o0" to "見栄えのため",
    "q.m20#15.o1" to "酸素量が、実行可能な折り返し時刻と滞在の上限を直接決めるから",
    "q.m20#15.o2" to "支出を記録するため",
    "q.m20#15.o3" to "精算しやすくするため",
    "q.m20#15.e" to "酸素は「持って行けばよい」物資ではなく、定量の予算です。何本、どの流量で、何時間もつか。この数字が折り返し時刻を逆算して決めます。だからタイムテーブルと一緒に設計する必要があり、別々のリストにしてはいけません。",

    "q.m20#16.p" to "空欄を埋めてください。登攀中によく使われる酸素流量はおよそ 2〜（ ）L/min です。",
    "q.m20#16.a0" to "4",
    "q.m20#16.a1" to "四",
    "q.m20#16.e" to "2〜4 L/min です。この範囲は「十分な血中酸素を保つ」ことと「ガスを節約する」ことの均衡点です。酸素管理は結局のところ、資源を配分し続ける問題なのです。",

    "q.m20#17.p" to "同行者の酸素が不足しているとき、あなたはどうすべきですか。",
    "q.m20#17.o0" to "登頂を続け、各自が自分の分を管理する",
    "q.m20#17.o1" to "ただちに情報と残量を共有し、計画に従って全員で下山するか酸素を配分するかを決める",
    "q.m20#17.o2" to "本人に何とかさせる",
    "q.m20#17.o3" to "自分の酸素をすべて渡す",
    "q.m20#17.e" to "酸素不足は個人の問題ではなく隊の出来事です。撤退の速度と相互の気づかいに影響します。最悪の選択は「登頂を続ける」と「自分を完全に犠牲にする」の両極端で、合理的なのは資源を再配分し、全員の下山を優先することです。",

    "q.m20#18.p" to "使用可能な酸素量を 1,200 リットルとします。3 L/min の流量で使うと、およそ何分もちますか。",
    "q.m20#18.a0" to "400",
    "q.m20#18.e" to "約 400 分（約 6.7 時間）です。計算は 1200 ÷ 3 ＝ 400。この種の計算は登頂日にとても実用的で、8,000 m でどれだけ滞在できるか、ひいては折り返しを何時にするかを直接決めます。",

    "q.m20#19.p" to "登頂計画：上り 5 時間、下り 3 時間、流量 2 L/min、さらに緊急用に 60 分分を確保します。必要な酸素の総量はおよそ何リットルですか。",
    "q.m20#19.a0" to "1080",
    "q.m20#19.e" to "1080 リットルです。計算は（5 + 3）時間 × 60 分 × 2 L/min ＝ 960 リットル、さらに緊急分 60 × 2 ＝ 120 リットルを加えて 1080 リットル。「往路＋復路＋緊急」の三つを分けて計算することが酸素計画の基本の規律です。「上る分だけ足りるか」しか見ないのが最もよくある誤りです。",

    // ---------- m21 8,000 m 級の全景・ヒマラヤ ----------
    "q.m21#0.p" to "世界に 8,000 m を超える山はいくつありますか。",
    "q.m21#0.o0" to "10 座",
    "q.m21#0.o1" to "12 座",
    "q.m21#0.o2" to "14 座",
    "q.m21#0.o3" to "18 座",
    "q.m21#0.e" to "14 座で、すべてヒマラヤ山脈とカラコルム山脈に集中しています。登山界の「14 座」という目標もこの数字から来ています。",

    "q.m21#1.p" to "14 座の 8,000 m 峰はどの国に分布していますか。",
    "q.m21#1.o0" to "中国、ネパール、インド、パキスタン",
    "q.m21#1.o1" to "中国、ネパール、ブータン、インド",
    "q.m21#1.o2" to "ネパール、パキスタン、アフガニスタン、タジキスタン",
    "q.m21#1.o3" to "中国、インド、パキスタン、ミャンマー",
    "q.m21#1.e" to "四国です。中国、ネパール、インド、パキスタン。この分布の理解は重要で、許可、後方支援、救助、政治的なリスクに直結します。そしてそれらは 8,000 m 級では計画の一部です。",

    "q.m21#2.p" to "エベレストの標高はいくらですか。",
    "q.m21#2.o0" to "8,611 m",
    "q.m21#2.o1" to "8,848 m",
    "q.m21#2.o2" to "8,586 m",
    "q.m21#2.o3" to "8,516 m",
    "q.m21#2.e" to "8,848 m です（2020 年に中国とネパールの共同測定で 8,848.86 m）。世界最高峰であり、商業登攀が最も成熟した山でもあります。ただし「成熟」は後方支援とルートが成熟しているという意味で、リスクが低いという意味ではありません。混雑、費用、判断の難しさも現実のリスクです。",

    "q.m21#3.p" to "アンナプルナ I 峰は 8,000 m 級の歴史でどのような位置にありますか。",
    "q.m21#3.o0" to "最も遅く登頂された",
    "q.m21#3.o1" to "最初に登頂された 8,000 m 峰",
    "q.m21#3.o2" to "死亡率が最も低い",
    "q.m21#3.o3" to "最も登頂が容易",
    "q.m21#3.e" to "アンナプルナ I 峰は 8,091 m、1950 年の初登頂で、人類が最初に登った 8,000 m 峰です。死亡率は長く上位にあります。最初に登られたことは、易しさとは関係ありません。",

    "q.m21#4.p" to "シシャパンマの特徴は何ですか。",
    "q.m21#4.o0" to "ネパール国内にある",
    "q.m21#4.o1" to "唯一完全に中国国内にある 8,000 m 峰で、14 座のなかで最も遅く登頂された",
    "q.m21#4.o2" to "最も高い",
    "q.m21#4.o3" to "難度が最も低い",
    "q.m21#4.e" to "シシャパンマは 8,027 m、チベットにあり、唯一完全に中国領内に位置する 8,000 m 峰です。1964 年に中国登山隊が初登頂し、14 座のなかで最も遅い登頂となりました。",

    "q.m21#5.p" to "ローツェとエベレストの関係はどれですか。",
    "q.m21#5.o0" to "互いに遠く離れている",
    "q.m21#5.o1" to "ローツェはエベレストに隣接し、しばしば同じアプローチルートを使う",
    "q.m21#5.o2" to "ローツェのほうがエベレストより高い",
    "q.m21#5.o3" to "両者は同じ山脈にない",
    "q.m21#5.e" to "ローツェは 8,516 m でエベレストに隣接し、南側からアプローチする際はルートとキャンプの大部分を共有できます。だから後方支援と順応の面で、二峰は同じ行程でまとめて考えられることが多いのです。",

    "q.m21#6.p" to "チョ・オユーについて、よくされる評価はどれですか。",
    "q.m21#6.o0" to "技術難度が最も高い 8,000 m 峰",
    "q.m21#6.o1" to "8,000 m 級のなかでは技術難度が低いほうだと一般に考えられている",
    "q.m21#6.o2" to "死亡率が最も高い 8,000 m 峰",
    "q.m21#6.o3" to "商業隊が登らない",
    "q.m21#6.e" to "チョ・オユーは 8,188 m、ルートが比較的緩やかで後方支援も成熟しているため、8,000 m 級のなかでは技術難度が低いほうとされます。ただし「比較的容易」でも死の地帯で数日行動する必要があり、この量級を過小評価してはいけません。",

    "q.m21#7.p" to "ナンガ・パルバットは何で知られていますか。",
    "q.m21#7.o0" to "穏やかなルート",
    "q.m21#7.o1" to "巨大な標高差と深刻な雪崩リスク",
    "q.m21#7.o2" to "最も安い登攀費用",
    "q.m21#7.o3" to "最も充実した後方支援",
    "q.m21#7.e" to "ナンガ・パルバットは 8,126 m、「裸の山」と呼ばれます。谷から立ち上がる高さが極めて大きく、雪崩と落石のリスクが際立っています。歴史的な登攀の代償は 8,000 m 級のなかでも高いものでした。",

    "q.m21#8.p" to "【組み合わせ】山と、その標高を結びつけてください。",
    "q.m21#8.l0" to "エベレスト",
    "q.m21#8.l1" to "カンチェンジュンガ",
    "q.m21#8.l2" to "ローツェ",
    "q.m21#8.l3" to "マカルー",
    "q.m21#8.r0" to "8,848 m",
    "q.m21#8.r1" to "8,586 m",
    "q.m21#8.r2" to "8,516 m",
    "q.m21#8.r3" to "8,485 m",
    "q.m21#8.e" to "この四座は世界の第 1、第 3、第 4、第 5 峰です。覚えるときは数字だけを暗記せず、順位と所属山脈を押さえてください。数字は調べられますが、全体の配置は頭に入れておく必要があります。",

    "q.m21#9.p" to "「14 座」が登山界の共通目標になったのはなぜですか。",
    "q.m21#9.o0" to "切りのよい数だから",
    "q.m21#9.o1" to "高所登攀の完全な境界をちょうど成しており、しかも追い求められる範囲の数だから",
    "q.m21#9.o2" to "商業会社が煽ったから",
    "q.m21#9.o3" to "国際山岳連盟が定めたから",
    "q.m21#9.e" to "14 座の独特さは、客観的で明確な境界（標高 8,000 m 超）があり、数が限られ、一つずつ列挙できることです。だから明確でありながら一生をかけられる挑戦になり、指標として定着しました。",

    "q.m21#10.p" to "【複数選択】8,000 m 峰の登頂には、ふつうどんな条件が必要ですか。",
    "q.m21#10.o0" to "完全な順応の期間と高所キャンプのローテーション",
    "q.m21#10.o1" to "技術力と氷河行進の経験",
    "q.m21#10.o2" to "信頼できる酸素と後方支援のシステム",
    "q.m21#10.o3" to "7,000 m 級で検証済みの体力と判断力",
    "q.m21#10.o4" to "専門の撮影クルー",
    "q.m21#10.e" to "四項目は四つの次元に対応します。生理（順応）、技術、後方支援、経験の蓄積。8,000 m ではこれらが同時に作用し、どれか欠ければ短板になり、短板は高所で急速に増幅されます。",

    "q.m21#11.p" to "ダウラギリ、マナスル、アンナプルナは共同でどの国にありますか。",
    "q.m21#11.o0" to "中国",
    "q.m21#11.o1" to "ネパール",
    "q.m21#11.o2" to "パキスタン",
    "q.m21#11.o3" to "インド",
    "q.m21#11.e" to "三座はいずれもネパール国内にあります。ネパールは 8,000 m 級の山を最も多く擁し、登攀産業がこれほど発達した理由でもあり、同時に許可、管理、環境保護における継続的な負荷も生んでいます。",

    "q.m21#12.p" to "8,000 m 級の「成熟した商業ルート」がなお危険なのはなぜですか。",
    "q.m21#12.o0" to "費用が高いから",
    "q.m21#12.o1" to "標高そのものは変わらず、混雑、待機、救助の困難が新たなリスクを生むから",
    "q.m21#12.o2" to "ガイドが未熟だから",
    "q.m21#12.o3" to "装備がよくないから",
    "q.m21#12.e" to "商業化は後方支援とルートの熟知を解決できますが、標高そのものを下げることはできません。逆に、多くの隊が同じ窓に集中すれば順番待ちが生まれ、8,000 m での待機は余分な酸素と体温の消耗を意味します。",

    "q.m21#13.p" to "【並べ替え】次の山を標高の高い順に並べてください。",
    "q.m21#13.o0" to "エベレスト（8,848）",
    "q.m21#13.o1" to "カンチェンジュンガ（8,586）",
    "q.m21#13.o2" to "マカルー（8,485）",
    "q.m21#13.o3" to "アンナプルナ I 峰（8,091）",
    "q.m21#13.e" to "この並びの背後には「世界第 5 位」から「第 10 位」への幅があります。正確な数字より順序を覚えるほうが実用的です。ルート、後方支援、難度を比べるときに必要なのは、多くの場合、相対的な位置だからです。",

    "q.m21#14.p" to "8,000 m 峰の知識を学ぶときに初登の歴史も知るべきなのはなぜですか。",
    "q.m21#14.o0" to "試験のため",
    "q.m21#14.o1" to "初登の過程が、その峰の核心的な難所とリスクの種類をしばしば露わにするから",
    "q.m21#14.o2" to "人名を覚えるため",
    "q.m21#14.o3" to "登攀と関係ない",
    "q.m21#14.e" to "初期の隊の失敗と犠牲は、その峰の主要な難所を正確に指し示すことが多いものです。雪崩の頻発区間、強風区間、露出した区間など。初登史を物語としてではなく「リスクの記録」として読むほうが、はるかに役に立ちます。",

    "q.m21#15.p" to "【複数選択】次のうちヒマラヤ山脈の 8,000 m 峰はどれですか。",
    "q.m21#15.o0" to "エベレスト",
    "q.m21#15.o1" to "アンナプルナ I 峰",
    "q.m21#15.o2" to "シシャパンマ",
    "q.m21#15.o3" to "K2（チョゴリ）",
    "q.m21#15.e" to "前三項はヒマラヤ、K2 はカラコルム山脈です。二つの山脈は地理的に隣接しますが地質が異なり、登攀シーズンと気候パターンにも差があります。14 座が山脈ごとにまとめて語られる理由でもあります。",

    "q.m21#16.p" to "「世界最高峰」という称号は戦略にどう影響しますか。",
    "q.m21#16.o0" to "まったく影響しない",
    "q.m21#16.o1" to "メディアと商業の注目が最も高く、隊の密度と混雑のリスクも最大になる",
    "q.m21#16.o2" to "ルートが最も簡単になる",
    "q.m21#16.o3" to "救助が最も便利になる",
    "q.m21#16.e" to "注目は資源をもたらし、人ももたらします。多くの隊が同じ窓に集中すると、待機、混雑、「順番を手放したくない」という心理的な圧力が新たなリスク源になります。これが「最高峰」特有の戦略問題です。",

    "q.m21#17.p" to "空欄を埋めてください。世界に標高 8,000 m を超える山は（ ）座あります。",
    "q.m21#17.a0" to "14",
    "q.m21#17.a1" to "十四",
    "q.m21#17.e" to "14 座です。数は少ないものの、高所登攀の完全な境界を表しています。だからこそ「14 座」は、いまも一生をかけられる目標と見なされるのです。",

    // ---------- m22 8,000 m 級の全景・カラコルム ----------
    "q.m22#0.p" to "カラコルム山脈には 8,000 m 峰がいくつありますか。",
    "q.m22#0.o0" to "2 座",
    "q.m22#0.o1" to "4 座",
    "q.m22#0.o2" to "6 座",
    "q.m22#0.o3" to "10 座",
    "q.m22#0.e" to "四座です。K2、ガッシャーブルム I 峰、ガッシャーブルム II 峰、ブロード・ピーク。それぞれ K2、K4、K5、K3 とも呼ばれ、「K」はカラコルムを意味します。",

    "q.m22#1.p" to "K2（チョゴリ）の標高と一般的な位置づけはどれですか。",
    "q.m22#1.o0" to "8,611 m、世界第 2 峰で、技術難度と死亡率が最も高い 8,000 m 峰の一つ",
    "q.m22#1.o1" to "8,848 m、世界最高峰",
    "q.m22#1.o2" to "8,586 m、世界第 3 峰",
    "q.m22#1.o3" to "8,051 m、比較的容易な一座",
    "q.m22#1.e" to "K2 は 8,611 m、世界第 2 峰です。最も難しく危険な 8,000 m 峰の一つとされ、だからこそ「登攀者の山」と呼ばれます。ここでは技術と判断の重みが、後方支援のはるか上にあります。",

    "q.m22#2.p" to "カラコルムとヒマラヤの登攀シーズンがしばしば異なるのはなぜですか。",
    "q.m22#2.o0" to "緯度経度が違うから",
    "q.m22#2.o1" to "異なる気候系の影響を受け、カラコルムは偏西風帯の影響がより明瞭だから",
    "q.m22#2.o2" to "標高が違うから",
    "q.m22#2.o3" to "管理規則が違うから",
    "q.m22#2.e" to "ヒマラヤの最良の季節は主にモンスーンの周期と関係し、カラコルムは偏西風帯と地形性降水の影響をより強く受けます。これが「いつ行くか」を直接決め、季節を誤ればどんな優れた隊でも登頂の窓を得られません。",

    "q.m22#3.p" to "ブロード・ピークは別名を何といいますか。",
    "q.m22#3.o0" to "K1",
    "q.m22#3.o1" to "K2",
    "q.m22#3.o2" to "K3",
    "q.m22#3.o3" to "K5",
    "q.m22#3.e" to "ブロード・ピークは別名 K3、標高 8,051 m です。地形は比較的開けていますが、雪が多く強風が頻繁で、歴史的に過小評価による事故が多く出ています。",

    "q.m22#4.p" to "ガッシャーブルム I 峰と II 峰は、それぞれ別名を何といいますか。",
    "q.m22#4.o0" to "K4 と K5",
    "q.m22#4.o1" to "K5 と K4",
    "q.m22#4.o2" to "K2 と K3",
    "q.m22#4.o3" to "K3 と K4",
    "q.m22#4.e" to "I 峰が K5（8,080 m）、II 峰が K4（8,035 m）です。番号と標高の順序が一致しておらず、ここが混同しやすい点です。「K 系の番号は高さ順ではない」と覚えておけば間違えません。",

    "q.m22#5.p" to "14 座の 8,000 m 峰は、どの二つの山脈に集中していますか。",
    "q.m22#5.o0" to "ヒマラヤと天山",
    "q.m22#5.o1" to "ヒマラヤとカラコルム",
    "q.m22#5.o2" to "カラコルムとアルプス",
    "q.m22#5.o3" to "ニェンチェンタンラとヒマラヤ",
    "q.m22#5.e" to "すべてヒマラヤとカラコルムの二山脈に集中しています。地理的には隣接しながら、異なる気候系の下にあります。8,000 m 級では地理位置そのものが重要な情報になる、ということを改めて示しています。",

    "q.m22#6.p" to "【組み合わせ】山と、その標高を結びつけてください。",
    "q.m22#6.l0" to "K2（チョゴリ）",
    "q.m22#6.l1" to "ナンガ・パルバット",
    "q.m22#6.l2" to "ガッシャーブルム I 峰",
    "q.m22#6.l3" to "シシャパンマ",
    "q.m22#6.r0" to "8,611 m",
    "q.m22#6.r1" to "8,126 m",
    "q.m22#6.r2" to "8,080 m",
    "q.m22#6.r3" to "8,027 m",
    "q.m22#6.e" to "四座はそれぞれ世界第 2、第 9、第 11、第 14 峰にあたります。幅は大きいのに「8,000 m 以上」という区分では同列です。ここが 8,000 m 級の特異な点で、境界は明確だが内側の差は極めて大きいのです。",

    "q.m22#7.p" to "「8,000 m の順位と難度」の関係について、正しい見方はどれですか。",
    "q.m22#7.o0" to "標高が高いほど必ず難しい",
    "q.m22#7.o1" to "難度は主に技術地形、気候、後方支援で決まり、標高の順位とは直接対応しない",
    "q.m22#7.o2" to "標高が低いほど必ず易しい",
    "q.m22#7.o3" to "難度はまったく比較できない",
    "q.m22#7.e" to "14 座の全景でもっとも重要な認識です。8,188 m のチョ・オユーは比較的容易とされ、8,611 m の K2 は最も難しい部類に入ります。標高差は 500 m に満たないのに、実際の敷居は別の山といってよいほど違います。",

    "q.m22#8.p" to "【複数選択】8,000 m 峰の実際の難度に影響する要素はどれですか。",
    "q.m22#8.o0" to "技術地形と露出感",
    "q.m22#8.o1" to "気候と天候の窓",
    "q.m22#8.o2" to "後方支援とアプローチルート",
    "q.m22#8.o3" to "救助の実現可能性",
    "q.m22#8.o4" to "その山の標高順位",
    "q.m22#8.e" to "四項目はどれも欠かせません。とくに「救助の実現可能性」は見落とされがちです。救助がほぼ不可能な山は、ルート自体が難しくなくてもリスクの等級がまったく変わります。「万一」に対する緩衝がないからです。",

    "q.m22#9.p" to "【並べ替え】次の山を標高の高い順に並べてください。",
    "q.m22#9.o0" to "K2（8,611）",
    "q.m22#9.o1" to "ナンガ・パルバット（8,126）",
    "q.m22#9.o2" to "ガッシャーブルム I 峰（8,080）",
    "q.m22#9.o3" to "シシャパンマ（8,027）",
    "q.m22#9.e" to "この並びはちょうど 14 座の「後半」をカバーします。前の課の並びと合わせれば、14 座の標高序列が完成します。「ある山がどの段階に属するか」を判断する基礎にもなります。",

    "q.m22#10.p" to "「14 座」が極めて高い敷居の目標だと言われるのはなぜですか。",
    "q.m22#10.o0" to "費用が極めて高いから",
    "q.m22#10.o1" to "技術、体力、順応力、判断力を長期にわたり維持し、しかも複数国の後方支援体系をまたぐ必要があるから",
    "q.m22#10.o2" to "時間が長すぎるから",
    "q.m22#10.o3" to "許可が取りにくいから",
    "q.m22#10.e" to "14 座は十年以上かかることが多く、その間に身体は衰え、生活状況も変わります。試されるのは登攀力だけでなく、長期にわたる維持能力とリスク管理の一貫性です。",

    "q.m22#11.p" to "8,000 m 級の成否が技術ではなく「天候の窓」で決まることが多いのはなぜですか。",
    "q.m22#11.o0" to "技術が重要でないから",
    "q.m22#11.o1" to "技術が十分でも、高所で長く待てば安全余裕が削られていくから",
    "q.m22#11.o2" to "技術は山の上で覚えられるから",
    "q.m22#11.o3" to "ガイドがすべてやってくれるから",
    "q.m22#11.e" to "これが 8,000 m 級の現実です。技術は入場券にすぎず、窓が「状態が残っているうちに通過できるか」を決めます。8,000 m 級の行程計画に大きな余裕日を確保する必要がある理由でもあります。",

    "q.m22#12.p" to "最初の 8,000 m 峰を一座だけ選ぶなら、より合理的な考え方はどれですか。",
    "q.m22#12.o0" to "K2 を選んで一気に仕上げる",
    "q.m22#12.o1" to "ルートが成熟し、後方支援が確実で、救助が可能な山を選び、「最初の一回」を経験の蓄積に使う",
    "q.m22#12.o2" to "標高が最も低い山でよい",
    "q.m22#12.o3" to "どれでも同じ",
    "q.m22#12.e" to "「最初の一座」の価値は、死の地帯で自分がどうなるかを把握することにあります。酸素をどう使うか、判断力がどれだけ落ちるか、速度はどうか。それを敷居の高い山に使うのは、複数の未知の変数を同時に試すことになります。",

    "q.m22#13.p" to "【複数選択】次のうちカラコルム山脈の 8,000 m 峰はどれですか。",
    "q.m22#13.o0" to "K2（チョゴリ）",
    "q.m22#13.o1" to "ガッシャーブルム I 峰",
    "q.m22#13.o2" to "ガッシャーブルム II 峰",
    "q.m22#13.o3" to "ブロード・ピーク",
    "q.m22#13.o4" to "マナスル",
    "q.m22#13.e" to "四座すべてカラコルムに属し、この山脈の 8,000 m 峰のすべてでもあります。だから「カラコルムの四座」は定まった言い方になり、ヒマラヤの十座と合わせてちょうど 14 になります。",

    "q.m22#14.p" to "14 座の全景を学ぶ最も実用的な利点は何ですか。",
    "q.m22#14.o0" to "すべての標高を暗唱できる",
    "q.m22#14.o1" to "「なぜ難度と標高が一致しないのか」を理解し、それに基づいて自分の目標を評価できる",
    "q.m22#14.o2" to "他人に登攀を指導できる",
    "q.m22#14.o3" to "攻略記事を書ける",
    "q.m22#14.e" to "14 座の全景の本当の価値は「多次元の難度観」を築くことにあります。技術、気候、後方支援、救助の四次元が、その山の実際の敷居を決める。この枠組みは 5,000 m 級や 6,000 m 級の選択にもそのまま使えます。",

    "q.m22#15.p" to "8,000 m 峰の「アプローチルート」もリスク要因になるのはなぜですか。",
    "q.m22#15.o0" to "長く歩くから",
    "q.m22#15.o1" to "アプローチ区間は氷河や雪崩の区域を通ることが多く、しかも隊はまだ十分に順応していないから",
    "q.m22#15.o2" to "景色がよくないから",
    "q.m22#15.o3" to "許可が必要だから",
    "q.m22#15.e" to "アプローチは標高を上げている最中に行われることが多く、まさに順応が最も悪く判断が最も不安定な段階で、しかもクレバスや雪崩の地形に向き合います。この「二重の脆弱期」が多くの事故の起きる時間帯です。",

    "q.m22#16.p" to "8,000 m 級の「目標リスト」を作るなら、まず何を決めるべきですか。",
    "q.m22#16.o0" to "行きたい山の名前",
    "q.m22#16.o1" to "自分の弱点（技術、順応、判断、後方支援の経験）を洗い出し、それを補える山を合わせる",
    "q.m22#16.o2" to "予算",
    "q.m22#16.o3" to "休暇の長さ",
    "q.m22#16.e" to "弱点から山を選ぶことは、8,000 m 級を「達成の収集」ではなく「成長の道筋」として扱うことです。同じ山でも人によって価値が違うのは、自分のどの部分を補えるかで決まります。",

    // ---------- m23 基礎能力の総合 ----------
    "q.m23#0.p" to "【状況】4,500 m で同行者が頭痛と吐き気を訴え、「もう一日順応すれば登れる」と言い張っています。環境科学の観点から正しい判断はどれですか。",
    "q.m23#0.o0" to "もう一日順応すれば必ず治るので、続けるよう励ます",
    "q.m23#0.o1" to "症状が出たのは代償が不足している証拠で、症状が消えないうちは上昇すべきではない",
    "q.m23#0.o2" to "薬を飲ませてから上昇を続ける",
    "q.m23#0.o3" to "100 m 下げれば十分",
    "q.m23#0.e" to "この連鎖は最も基本の因果から始まります。気圧が低い → 酸素分圧が低い → 身体に順応の時間が必要。症状の出現は「時間が足りない」というサインであり、もう一日待っても必ず良くなる保証はありません。だから正しいのは上昇を止めることで、明日に賭けることではありません。",

    "q.m23#1.p" to "【複数選択】ある隊員が 5,000 m の硬い雪の斜面へ向かいます。確認すべき装備はどれですか。",
    "q.m23#1.o0" to "ブーツに厳密に適合したアイゼン",
    "q.m23#1.o1" to "身長に合ったピッケル",
    "q.m23#1.o2" to "UV400 のサングラスと高倍の日焼け止め",
    "q.m23#1.o3" to "レイヤリングに対応した保温層と防水層",
    "q.m23#1.o4" to "登頂写真用のカメラと予備電池",
    "q.m23#1.e" to "四項目は四種類のリスクに対応します。滑る（アイゼン）、制動（ピッケル）、紫外線（サングラスと日焼け止め）、低体温（レイヤリング）。装備点検の正しいやり方は「習慣で物を持つのではなく、リスクから一覧を作る」ことです。",

    "q.m23#2.p" to "【組み合わせ】三層のウェアシステムと、その役割を結びつけてください。",
    "q.m23#2.l0" to "ベースレイヤー（肌着）",
    "q.m23#2.l1" to "ミドルレイヤー",
    "q.m23#2.l2" to "アウターシェル",
    "q.m23#2.l3" to "ダウン層（極寒時）",
    "q.m23#2.r0" to "汗を皮膚から運び去り、乾いた状態を保つ",
    "q.m23#2.r1" to "空気の層を固定して保温する（フリースは濡れても保温力を保つ）",
    "q.m23#2.r2" to "防水・防風かつ透湿で、外部の天候に耐える",
    "q.m23#2.r3" to "乾いた環境で最も高い保温効率を発揮する",
    "q.m23#2.e" to "四層がそれぞれ一つの役割を担います。この分担が分かれば、「着れば着るほど暖かい」がなぜ誤りかも理解できます。排汗層を省けば身体は自前の湿った環境を抱え、アウターが透湿しなければ汗気が内側で結露します。",

    "q.m23#3.p" to "【状況】雪の斜面を登る途中、前方の隊員が蹴るステップが不均一です。最も起こりやすい結果は何ですか。",
    "q.m23#3.o0" to "隊の行進速度が上がる",
    "q.m23#3.o1" to "後続の隊員が重心を余分に調整する必要があり、体力消耗が増えて不安定になりやすい",
    "q.m23#3.o2" to "雪の斜面が崩壊する",
    "q.m23#3.o3" to "ほとんど影響はない",
    "q.m23#3.e" to "ステップは隊全体の「土台」です。不均一なステップは、全員に足場を探し直させ、しかも高所ではもともと乏しい平衡能力に負担をかけます。典型的な「小さな問題が積み重なって大きなリスクになる」例です。",

    "q.m23#4.p" to "【並べ替え】ピッケルによる制動の動作を、正しい順序に並べてください。",
    "q.m23#4.o0" to "ピッケルを確実に握り、握り方が正しいことを確認する",
    "q.m23#4.o1" to "身体を反転させてうつ伏せになり、雪面に向く",
    "q.m23#4.o2" to "体重をかけてピックの先を雪面に押し込む",
    "q.m23#4.o3" to "両脚を持ち上げ、アイゼンが刺さって回転するのを防ぐ",
    "q.m23#4.e" to "この動作の流れは技術体系全体の土台です。「考えなくても実行できる」状態でなければなりません。実際に滑落したとき、思考に使える時間は一、二秒しかなく、その二秒は完全に筋肉の記憶が占めるからです。",

    "q.m23#5.p" to "【状況】ある登攀者が硬い雪の斜面で滑落し、制動に失敗しました。事後の分析で最も考えられる原因は何ですか。",
    "q.m23#5.o0" to "ピッケルが短すぎた",
    "q.m23#5.o1" to "ピックの先が硬い雪に効きにくく、硬い雪の斜面ではあらかじめ固定したロープの確保を優先すべきだった",
    "q.m23#5.o2" to "靴が合っていなかった",
    "q.m23#5.o3" to "手袋をしていなかった",
    "q.m23#5.e" to "硬い雪や氷の上では制動の成功率が明らかに下がります。これは技術そのものの限界です。だから本当の問題はもっと手前にあります。なぜシステムによる確保なしで硬い雪の急斜面に取り付いたのか、という点です。",

    "q.m23#6.p" to "【複数選択】下山の段階で見落とされやすいリスクはどれですか。",
    "q.m23#6.o0" to "体力低下による脚のコントロールの悪化",
    "q.m23#6.o1" to "目標達成後の警戒心の低下",
    "q.m23#6.o2" to "雪面の凍結や軟化により、上りとは路面状況が変わる",
    "q.m23#6.o3" to "日が陰り、視界と判断力が落ちる",
    "q.m23#6.o4" to "下山ルートはふつう上りルートより短い",
    "q.m23#6.e" to "これらが重なると、なぜ多くの事故が下山中に起きるかが説明できます。だから下山は「任務完了後の帰路」ではなく、別途計画すべき同じく高リスクの区間なのです。",

    "q.m23#7.p" to "【状況】ハイドレーションの吸い口が外気で急速に凍ってしまいました。どうすべきですか。",
    "q.m23#7.o0" to "広口の保温ボトルに切り替え、使うたびに吸い口へ息を吹き戻すか、逆さにして収納する",
    "q.m23#7.o1" to "そのまま使い続け、溶けるのを待つ",
    "q.m23#7.o2" to "ハイドレーションをザックの外に出す",
    "q.m23#7.o3" to "水分補給をやめる",
    "q.m23#7.e" to "具体的ですが重要な小技です。高所の脱水は「水を持っていない」ことより「水が凍って飲めない」ことで起きます。飲水の仕組みを「凍らない設計」にしてはじめて、補水の準備ができたといえます。",

    "q.m23#8.p" to "空欄を埋めてください。標高が 1,000 m 上がるごとに、気温は平均して約（ ）℃ 下がります。",
    "q.m23#8.a0" to "6.5",
    "q.m23#8.a1" to "六点五",
    "q.m23#8.e" to "6.5℃ です。この数字は講座全体を貫きます。雪線を説明し、装備の厚さを決め、雪崩や氷の状態の変化にも影響します。これを使って推論できてはじめて、理解したといえます。",

    "q.m23#9.p" to "【状況】5,000 m でゴーグルがひどく曇り、地形が見えなくなりました。最も重要なリスクは何ですか。",
    "q.m23#9.o0" to "不快なだけ",
    "q.m23#9.o1" to "地形を判断する能力を失い、急斜面や雪庇、クレバス帯に誤って入り込む可能性",
    "q.m23#9.o2" to "雪盲になる",
    "q.m23#9.o3" to "同行者に文句を言われる",
    "q.m23#9.e" to "「見えない」の本質は判断の根拠を失うことです。地形の複雑な雪の斜面では、一、二歩の踏み外しの代償が非常に大きくなります。だから「見えるかどうか」は装備の信頼性の必須指標として扱うべきです。",

    "q.m23#10.p" to "【複数選択】ある隊員が高所でひどい食欲低下に陥りました。どうすべきですか。",
    "q.m23#10.o0" to "少量を頻回に摂るよう働きかけ、高炭水化物で消化のよいものを選ぶ",
    "q.m23#10.o1" to "均一で十分な水分補給を確保する",
    "q.m23#10.o2" to "食欲低下を順応の問題のサインかもしれないと考えて観察する",
    "q.m23#10.o3" to "大量のコーヒーとエナジードリンクで食事を代替する",
    "q.m23#10.e" to "前三項は正しく、第四項は分かりやすい誤りです。カフェインは「一時的な感覚」を与えてもエネルギーの代わりにはなりません。高所ではエネルギー摂取不足が順応力を直接削り、悪循環を作ります。",

    "q.m23#11.p" to "【状況】標高 5,000 m の雪の斜面で、携帯の残量が 40% から突然電源断になりました。最も合理的な対応はどれですか。",
    "q.m23#11.o0" to "身体に密着させて温めてから電源を入れる",
    "q.m23#11.o1" to "何度も電源を入れ直す",
    "q.m23#11.o2" to "電子機器の使用を諦める",
    "q.m23#11.o3" to "残量を使い切って救助要請を送る",
    "q.m23#11.e" to "低温下のリチウム電池の典型的な挙動で、容量が急減しただけで尽きたわけではありません。密着させて温めれば給電が戻ることが多い。電子機器は「突然使えなくなる安全装備」として管理すべきだ、という教訓です。",

    "q.m23#12.p" to "【並べ替え】装備点検の一連の流れを、合理的な順序に並べてください。",
    "q.m23#12.o0" to "リスクから一覧を作る（地形、天候、標高それぞれに何が必要か）",
    "q.m23#12.o1" to "一つずつ完全性と作動状態を点検する",
    "q.m23#12.o2" to "身につけて主要装備を試運転する（アイゼン、ハーネス、ヘルメット、ヘッドランプ）",
    "q.m23#12.o3" to "自分の装備状態と予備案を整理し、同行者に伝える",
    "q.m23#12.e" to "要点は第三段階の「試運転」です。装備が揃っていることは使えることと等しくありません。アイゼンのバックルが最後まで掛かっていない、ヘッドランプに古い電池が入っている。こうした問題は身につけて操作してはじめて露見します。",

    "q.m23#13.p" to "【状況】天候を理由に隊は下山を決めましたが、一人が「ここまで来るのに苦労した」と続行を主張しています。最も適切な対応はどれですか。",
    "q.m23#13.o0" to "個人の選択を尊重し、単独で続けさせる",
    "q.m23#13.o1" to "全員での下山を貫く。高所で単独行動は認められず、しかも高所での「こだわり」自体が低酸素の産物かもしれない",
    "q.m23#13.o2" to "多数決で決める",
    "q.m23#13.o3" to "一時間待ってから決めさせる",
    "q.m23#13.e" to "理由は二つです。高所の単独行はリスクが極めて高いこと。そして「苦労したのに」はサンクコストの典型的な言い回しで、高所ではこうした感情と判断力の低下がしばしば絡み合い、信頼できる意見として扱えません。",

    "q.m23#14.p" to "「体力のある人のほうが高所病になりやすいか」について、正しい説明はどれですか。",
    "q.m23#14.o0" to "体力があるほどなりにくい",
    "q.m23#14.o1" to "高所病は体力と直接の関係がなく、上昇速度、睡眠標高、個人の反応に関係する",
    "q.m23#14.o2" to "体力があるほどなりやすい",
    "q.m23#14.o3" to "体力の弱い人しかならない",
    "q.m23#14.e" to "体力と高所順応を混同するのは、入門段階で最もよくある認識の誤りです。実際には体力のある人のほうが「速く歩き、高く上がりすぎる」ことで問題を起こしやすい。現実的な罠です。",

    "q.m23#15.p" to "【複数選択】滑落リスクを有効に下げられるのはどれですか。",
    "q.m23#15.o0" to "行進中つねにピッケルで自己確保を行う",
    "q.m23#15.o1" to "持続可能な一定ペースを保ち、急に力を入れない",
    "q.m23#15.o2" to "隊で最も遅い人のペースで行進する",
    "q.m23#15.o3" to "硬い雪や氷の斜面に固定ルートロープを設置する",
    "q.m23#15.o4" to "下りでは制動操作を減らし、速度を上げて通過する",
    "q.m23#15.e" to "四項目はそれぞれ個人技術、ペース管理、隊の協調、システムによる確保に対応します。滑落予防は決して単一の動作ではなく、「保険に保険を重ねる」設計そのものです。",

    "q.m23#16.p" to "【状況】雪の斜面で休憩中、ある隊員がピッケルを雪に突き刺したまま離れました。どんなリスクがありますか。",
    "q.m23#16.o0" to "ピッケルを失くすかもしれない",
    "q.m23#16.o1" to "もし滑落したとき、手元に制動の道具が何もない",
    "q.m23#16.o2" to "同行者に踏まれるかもしれない",
    "q.m23#16.o3" to "リスクはない",
    "q.m23#16.e" to "滑落は極めて速く起き、ピッケルは唯一の制動手段です。ピッケルを雪に刺したままにするのは、一時的に制動能力を手放すこと。そして雪の斜面では、その「一時的」が最も危険な時間帯なのです。",

    "q.m23#17.p" to "本課が試す中心的な能力は何ですか。",
    "q.m23#17.o0" to "すべてのデータを暗記すること",
    "q.m23#17.o1" to "環境、装備、ウェア、歩行の知識を組み合わせ、具体的な状況に対して正しい判断を下すこと",
    "q.m23#17.o2" to "すべての用語を暗唱すること",
    "q.m23#17.o3" to "器材のブランドに精通すること",
    "q.m23#17.e" to "これが講座全体の設計思想です。単独の知識は覚えやすいものの、山で向き合うのは「組み合わせ問題」です。具体的な状況でいくつかの知識をつなげられてこそ、本当の習得です。",

    // ---------- m24 総合考核 ----------
    "q.m24#0.p" to "【状況】同行者がクレバスに落ち、あなたの身体だけで彼の体重を受けています。次に優先すべきことは何ですか。",
    "q.m24#0.o0" to "すぐに引き上げ始める",
    "q.m24#0.o1" to "まずビレイステーションを構築し、体重をそこへ移してから引き上げを考える",
    "q.m24#0.o2" to "まず救助を要請する",
    "q.m24#0.o3" to "まず写真を記録する",
    "q.m24#0.e" to "体重が自分の上にあるかぎり、システムを操作する余力はありません。だから「建站 → 転荷 → 引き上げ」の順序は入れ替えできません。救助体系のなかで最も実用的な一条であり、同時に緊張のなかで最も飛ばされやすい一歩です。",

    "q.m24#1.p" to "【組み合わせ】ロープの結びと、その用途を結びつけてください。",
    "q.m24#1.l0" to "エイトノット（figure-eight）",
    "q.m24#1.l1" to "ダブルフィッシャーマンズ",
    "q.m24#1.l2" to "摩擦結び（プルージック）",
    "q.m24#1.l3" to "もやい結び（ボウライン）",
    "q.m24#1.r0" to "ハーネスと固定点を連結する",
    "q.m24#1.r1" to "二本のロープをつなぐ、または補助ロープの環を作る",
    "q.m24#1.r2" to "摩擦結び。一方向にのみ把持する",
    "q.m24#1.r3" to "固定点に結ぶ。係留に多用される",
    "q.m24#1.e" to "四つの結びは、氷河行進と基礎的な確保のほとんどの場面をカバーします。考核の意味は、暗闇でも手袋をしていても結べることでなければなりません。",

    "q.m24#2.p" to "【状況】二つの支点のスリングのなす角が 100° に近づいています。これは何を意味しますか。",
    "q.m24#2.o0" to "荷重がより均等になる",
    "q.m24#2.o1" to "各支点の負担が明らかに大きくなる（角度が開くほど単点の受力が増す）",
    "q.m24#2.o2" to "影響はない",
    "q.m24#2.o3" to "ロープが自動的に均衡を取る",
    "q.m24#2.e" to "データは明快です。角度 0° で各点ほぼ 50%、60° で約 58%、90° で約 71%。100° では各点の負担はすでに大きなものになります。だから現場では角度を 60° 以内に収めるのが通例です。",

    "q.m24#3.p" to "【複数選択】要件を満たすビレイステーションが備えるべき性質はどれですか。",
    "q.m24#3.o0" to "各支点そのものが強固である",
    "q.m24#3.o1" to "各点が独立して破断する（偽の冗長性がない）",
    "q.m24#3.o2" to "荷重が合理的に配分され、あらかじめ張ってある",
    "q.m24#3.o3" to "素早く構築でき、露出時間を短くできる",
    "q.m24#3.o4" to "器材を節約するため支点は一つにする",
    "q.m24#3.e" to "前三項は安全の要件、第四項は効率の要件です。そして効率もまた安全です。構築の過程そのものが、リスクにさらされている時間だからです。",

    "q.m24#4.p" to "【状況】同行者に歩行の不安定さと意識の混濁が現れました。最優先の処置はどれですか。",
    "q.m24#4.o0" to "酸素を投与して観察する",
    "q.m24#4.o1" to "ただちに下降し、医療の監視下でデキサメタゾンを投与する",
    "q.m24#4.o2" to "早くキャンプに着くため上昇を続ける",
    "q.m24#4.o3" to "鎮痛薬を飲ませて休ませる",
    "q.m24#4.e" to "歩行の不安定さと意識の変容は HACE の中核的な徴候で、内科の救急疾患です。下降が唯一の確実な治療であり、デキサメタゾンは下降のための時間を稼ぐだけ。両者は代替関係にありません。",

    "q.m24#5.p" to "【複数選択】高所の薬について、正しい記述はどれですか。",
    "q.m24#5.o0" to "デキサメタゾンは順応性に影響せず、肺浮腫にも治療作用がない",
    "q.m24#5.o1" to "アセタゾラミドは順応の速度を上げ、上昇 1 日前から始めて上昇後およそ 2 日で中止する",
    "q.m24#5.o2" to "ニフェジピンは血圧の急低下を起こしうる",
    "q.m24#5.o3" to "薬は下降の代わりにならない",
    "q.m24#5.o4" to "アセタゾラミドは身体の順応過程の代わりになる",
    "q.m24#5.e" to "四項目はいずれも重要な知識で、共通する結論は「薬は下降の代わりにならない」ことです。どの薬を飲んでいても、下降がつねに根本の処置です。薬は下降のための条件を整えるだけです。",

    "q.m24#6.p" to "【状況】ある隊員が寒さのなかで震えを止め、言葉が不明瞭になりました。最も避けるべきことは何ですか。",
    "q.m24#6.o0" to "濡れた衣類を替え、保温材で包む",
    "q.m24#6.o1" to "本人に歩かせて熱を産ませる",
    "q.m24#6.o2" to "体幹の復温を優先する",
    "q.m24#6.o3" to "乱暴に動かさない",
    "q.m24#6.e" to "「震えが止まる」は中等度以上の低体温に入ったことを意味し、低温の心筋は不整脈を誘発されやすい状態です。歩かせることや乱暴な搬動が直接の引き金になりえます。低体温の応急処置のなかで最も直感に反する一条です。",

    "q.m24#7.p" to "【並べ替え】アンザイレン救助の四段階を、順序どおりに並べてください。",
    "q.m24#7.o0" to "自己制動で体勢を安定させる",
    "q.m24#7.o1" to "独立したビレイステーションを構築する",
    "q.m24#7.o2" to "体重をステーションへ移す",
    "q.m24#7.o3" to "3:1 システムで引き上げる",
    "q.m24#7.e" to "四段階は入れ替えできません。考核では順番に暗唱できるかもしれませんが、実際の場面では最初の三段階を数十秒で終える必要があります。そこがこの知識の本当の敷居です。",

    "q.m24#8.p" to "【状況】予報は「曇り」ですが、現場では積雲が急速に垂直発達しています。どうすべきですか。",
    "q.m24#8.o0" to "予報を信じ、計画どおり行動する",
    "q.m24#8.o1" to "悪化する前提で判断し、早めの下山も視野に入れる",
    "q.m24#8.o2" to "一時間待ってから見る",
    "q.m24#8.o3" to "上昇を続けるが速度を上げる",
    "q.m24#8.e" to "予報が与えるのは地域の背景で、現場の雲況は「いま、ここ」の証拠です。両者が衝突するときは現場が優先します。まして高所では積雲の発達は分単位で進みます。",

    "q.m24#9.p" to "【複数選択】雪崩地形を通過するとき、正しい作法はどれですか。",
    "q.m24#9.o0" to "一人ずつ通過し、間隔を保つ",
    "q.m24#9.o1" to "安全な位置に観察者を指定する",
    "q.m24#9.o2" to "撤退ルートと集合地点をあらかじめ計画する",
    "q.m24#9.o3" to "曝露を短くするため全員で同時に素早く通過する",
    "q.m24#9.e" to "前三項はリスクを個人一人分に限定します。「全員同時通過」はリスクを隊全体の規模に拡大し、「一人埋まるかも」を「全員埋まるかも」に変える、最も選ぶべきでない方法です。",

    "q.m24#10.p" to "【状況】隊は頂上まで一時間の地点に達しましたが、すでに折り返し時刻を過ぎています。正しい対応はどれですか。",
    "q.m24#10.o0" to "あと一時間なので登頂を続ける",
    "q.m24#10.o1" to "ただちに下山する。折り返し時刻の意味は、まさに「あと少し」のときにこそ働くことにある",
    "q.m24#10.o2" to "さらに 30 分延ばす",
    "q.m24#10.o3" to "体力のある人だけ続けさせる",
    "q.m24#10.e" to "この問題が本当に試しているのは「折り返し時刻は何のためにあるか」です。楽なときにだけ守られ、「あと少し」のときに緩められるなら、それは初めから存在しません。そして事故はまさにその「あと少し」で起きます。",

    "q.m24#11.p" to "【複数選択】「高リスク環境における正しいチームの意思決定」に当たるものはどれですか。",
    "q.m24#11.o0" to "出発前に撤退のシグナルを数値化しておく",
    "q.m24#11.o1" to "最も保守的な意見を優先する",
    "q.m24#11.o2" to "意識的に反対意見を作る（一人ずつ意見を述べるなど）",
    "q.m24#11.o3" to "少数が多数に従う",
    "q.m24#11.e" to "前三項は「集団の誤判断に対抗する」仕組みを構成します。少数が多数に従うのは逆で、少数者の妥当な懸念をそのまま押しつぶします。そして危険のサインは、まさに少数の人が先に気づくものなのです。",

    "q.m24#12.p" to "【状況】通信が途絶しました。計画では一時間後に後方へ連絡する予定でした。どうすべきですか。",
    "q.m24#12.o0" to "計画どおり行動し、電波が戻るのを待つ",
    "q.m24#12.o1" to "出発前に取り決めた不通時の計画に従う（合流地点で待つなど）",
    "q.m24#12.o2" to "手分けして電波を探す",
    "q.m24#12.o3" to "全員でただちに下山する",
    "q.m24#12.e" to "山で通信が途絶えるのは例外ではなく日常です。だからこそ出発前に計画を持っておく必要があります。計画があれば不通は「既知の分岐」にすぎませんが、なければ現場が混乱するだけです。",

    "q.m24#13.p" to "【並べ替え】重傷者に遭遇した後の一連の処置を、順序どおりに並べてください。",
    "q.m24#13.o0" to "現場の安全を確保し、二次事故を避ける",
    "q.m24#13.o1" to "意識、呼吸、循環を評価し、生命に関わる問題を処置する",
    "q.m24#13.o2" to "救助を要請し、正確な位置と傷情を伝える",
    "q.m24#13.o3" to "保温・固定と継続的な観察を行い、搬送または専門救助を待つ",
    "q.m24#13.e" to "順序が表しているのは「まず安全、次に救命、同時に通報、そして維持」です。現実に最も多い誤りは第一段階を飛ばして傷病者へ直行すること。それこそが「二人目の傷病者を作る」典型の道です。",

    "q.m24#14.p" to "【複数選択】技術登攀のなかで「必ず現場で練習すべき」技能はどれですか。",
    "q.m24#14.o0" to "ピッケルによる自己制動",
    "q.m24#14.o1" to "摩擦結びとアンザイレンシステムの操作",
    "q.m24#14.o2" to "ビレイステーションの構築",
    "q.m24#14.o3" to "クレバス救助の手順",
    "q.m24#14.o4" to "14 座の 8,000 m 峰の名称と標高を覚えること",
    "q.m24#14.e" to "四項目はいずれも読書では身につきません。共通する特徴は、プレッシャーの下で実行する必要があり、許容できる誤りの幅が極端に小さく、筋肉の記憶に依存することです。だから本アプリでも繰り返し「インストラクターの評価が必要」と記しています。",

    "q.m24#15.p" to "【状況】あなたは理論考核をすべて通過しました。このとき自分の能力をどう捉えるべきですか。",
    "q.m24#15.o0" to "すでに 8,000 m を単独で登る能力がある",
    "q.m24#15.o1" to "理論の基礎と判断の枠組みはあるが、技術技能はすべてインストラクターの現場評価を受けてから実地で使うべき",
    "q.m24#15.o2" to "すぐにガイドを務められる",
    "q.m24#15.o3" to "理論を通れば能力も基準に達したのと同じ",
    "q.m24#15.e" to "これは講座全体でもっとも重要な声明です。理論の習得は実地の能力と等しくありません。本アプリが築くのは認知と判断の枠組みであり、氷壁であなたを救うのは、安全な場所で数百回繰り返したあの動作です。",

    "q.m24#16.p" to "全課程を終えたとき、あなたが手にする中核的な資産は何ですか。",
    "q.m24#16.o0" to "装備リスト一式",
    "q.m24#16.o1" to "「リスクを識別し、評価し、判断する」思考の枠組み、そしてどこで続けるべきでないかを知っていること",
    "q.m24#16.o2" to "登山の認定証",
    "q.m24#16.o3" to "知識の寄せ集め",
    "q.m24#16.e" to "5,000 m の入門から 8,000 m の最終考核まで、講座全体が繰り返し伝えているのは同じことです。安全は技術の結果ではなく判断の結果であり、技術は判断に余裕を生むためにある。",

    "q.m24#17.p" to "空欄を埋めてください。不確実な状況での意思決定では、最も（ ）意見を優先して採るべきです。",
    "q.m24#17.a0" to "保守的な",
    "q.m24#17.e" to "「保守優先」は講座全体の締めくくりの原則です。その場で実行できるほど単純で、しかもほとんどの認知の偏りに対抗できるほど強い。山はいつもそこにあり、人はそうではありません。",

    // ---------- m25 はじめての高所：人と判断 ----------
    "q.m25#0.p" to "高所に上がったあと、頭が張る感じと息苦しさがあります。隊は計画どおり上昇を続けています。このとき最もすべきことは何ですか。",
    "q.m25#0.o0" to "我慢する。せっかくここまで来たのだから",
    "q.m25#0.o1" to "立ち止まり、ガイドや同行者に正直に伝えて、休んで観察する",
    "q.m25#0.o2" to "自分で薬を飲んで、隊に遅れずについていく",
    "q.m25#0.o3" to "速度を上げて早くキャンプに着けば治る",
    "q.m25#0.e" to "高所で身体のサインに対して最も避けるべき対応は二つあります。我慢して言わないこと、そして自分だけで処理すること。正しい第一歩は、感じていることを正直に話し、立ち止まって休みながら観察することです。\nこれは弱さではありません。ガイドは状況を知ってはじめて判断できますし、あなた自身も「和らいでいるのか、悪化しているのか」を見分ける時間が必要です。",

    "q.m25#1.p" to "「せっかく来たのだから」という言葉が、高所の行程で危険なのはなぜですか。",
    "q.m25#1.o0" to "時間の無駄になるから",
    "q.m25#1.o1" to "すでに投じた時間を、危険を続ける理由にすり替えてしまうから",
    "q.m25#1.o2" to "隊の雰囲気に影響するから",
    "q.m25#1.o3" to "専門家らしく聞こえないから",
    "q.m25#1.e" to "これは典型的なサンクコスト思考です。これだけ歩き、これだけ費用をかけ、これだけ長い休暇を取った。だから「無駄にはできない」。\nしかしリスクは、あなたがどれだけ投入したかで下がりません。投じたものは取り戻せませんが、上昇を続ける代償は、取り戻せないものをさらに増やすかもしれません。",

    "q.m25#2.p" to "明らかに隊のペースについていけず、ずっと無理をして合わせています。最も適切なのはどれですか。",
    "q.m25#2.o0" to "歯を食いしばってついていき、迷惑をかけない",
    "q.m25#2.o1" to "正直に伝え、隊に最も遅い人のペースで歩いてもらう",
    "q.m25#2.o2" to "こっそり速度を落とし、平気なふりをする",
    "q.m25#2.o3" to "誰にも言わず、一人で下山する",
    "q.m25#2.e" to "高所での「無理に合わせる」は隠れた前借りです。その場の代償は疲れだけですが、それが積み重なって翌日に一気に崩れます。しかも隊が最も速いペースで歩けば、それ自体が全員を危険の縁へ押しやります。\n正しいのは、最も遅い人が持続できる速度に合わせること。これは個人を守り、同時に隊全体を守ります。",

    "q.m25#3.p" to "同行者が「少し具合が悪い」と言いながら、「大丈夫、歩ける」と主張しています。あなたはどうすべきですか。",
    "q.m25#3.o0" to "本人の判断を信じて、歩き続ける",
    "q.m25#3.o1" to "真剣に受け止め、その状況をガイドに伝える",
    "q.m25#3.o2" to "干渉せず、本人に任せる",
    "q.m25#3.o3" to "本気にしない。多くの人がそう言うものだ",
    "q.m25#3.e" to "高所の不調には残酷な特徴があります。判断力が先に影響を受けるので、「自分は行けると思う」は高所では割り引いて考える必要があります。\n同行者の状況をガイドに伝えるのは、本人に対する責任ある行動です。本当に問題なければ確認が一回増えるだけ。本当に問題があれば、あなたが唯一の早期発見者かもしれません。",

    "q.m25#4.p" to "出発前、ガイドが「明日のあの区間は必ずアンザイレンで通過する」と説明しました。ある人が「あんな緩い斜面に必要ない」と言います。正しい認識はどれですか。",
    "q.m25#4.o0" to "緩い斜面ならアンザイレンは不要",
    "q.m25#4.o1" to "アンザイレンの要否はガイドの判断に従うべきで、地形と雪況の情報を持っているのはガイドだから",
    "q.m25#4.o2" to "アンザイレンは主に見た目を整えるため",
    "q.m25#4.o3" to "体力が最もある人が決めるべき",
    "q.m25#4.e" to "遠くから見た「緩さ」と、現場でクレバス、スノーブリッジ、隠れた亀裂の分布を見ることとは別の話です。ガイドが持つ情報はあなたと違い、そこにこそ価値があります。\n技術的な決定では、最も情報を持つ人に判断を委ねる。それが隊の効率と安全の基本原則です。",

    "q.m25#5.p" to "隊の真ん中を歩いていて、水が尽きたことに気づきました。次の補給点まではまだ 2 時間あります。どうすべきですか。",
    "q.m25#5.o0" to "我慢して言わない。人に迷惑をかけないように",
    "q.m25#5.o1" to "すぐにリーダーに伝え、調整できるか確認する",
    "q.m25#5.o2" to "最も近い同行者に水をもらうが、リーダーには言わない",
    "q.m25#5.o3" to "少しずつ飲んで、耐え続ける",
    "q.m25#5.e" to "水と食料の不足は個人の小事ではなく、隊レベルの情報です。リーダーの全体のペースと補給点の判断に影響します。\n同行者にこっそり頼むのは「迷惑をかけない」ように見えて、実は情報を遮断しています。リーダーは全員が順調だと思ったまま、計画どおり進めてしまうかもしれません。",

    "q.m25#6.p" to "高所での「遅いことは速い」という言葉の、正しい理解はどれですか。",
    "q.m25#6.o0" to "ゆっくり歩けば必ず登頂できる",
    "q.m25#6.o1" to "持続可能な一定の速さで進むほうが、繰り返し飛ばすより時間も安全も有利になる",
    "q.m25#6.o2" to "遅いのは体力の弱い人に合わせるため",
    "q.m25#6.o3" to "高所では速度は重要でない",
    "q.m25#6.e" to "高所では酸素供給能力に限りがあり、急な全力動作を繰り返すと乳酸が急速に溜まり低酸素が悪化します。\n安定した一定ペースのほうが結果的に速い。頻繁に止まって回復する必要がなく、消耗しすぎて途中で撤退を余儀なくされる確率も下がるからです。この言葉はエネルギー代謝の法則を述べたもので、慰めではありません。",

    "q.m25#7.p" to "予定より 2 時間遅れてキャンプに着き、すでに暗くなっています。このとき最もすべきことは何ですか。",
    "q.m25#7.o0" to "夜通し歩いて次のキャンプへ向かう",
    "q.m25#7.o1" to "その場にテントを張り、後方に自分の位置を知らせる",
    "q.m25#7.o2" to "一人で戻って遅れた人を探す",
    "q.m25#7.o3" to "前の隊に追いつくまで歩き続ける",
    "q.m25#7.e" to "高所での夜間強行は事故の起きやすい組み合わせです。暗さ＋疲労＋低温＋地形が読めない。その場で張るのが堅実な選択です。\nただし必ず一つ加えます。後方に自分の位置を知らせること。万一救助が必要になったとき、どこを探せばよいかが分かります。逆に単独行動は、隊が一度に二人を失うことになります。",

    "q.m25#8.p" to "同行者が途中で明らかに不調になり、どんどん遅れています。隊では「待つ」か「一部が先に行く」かで意見が割れています。より合理的なのはどれですか。",
    "q.m25#8.o0" to "隊全員が元の速度で進む",
    "q.m25#8.o1" to "絶対に分かれず、全員で速度を落とす",
    "q.m25#8.o2" to "経験のある一人が付き添い、残りは先へ進んで連絡を保つ",
    "q.m25#8.o3" to "本人にゆっくり歩かせ、キャンプで合流する",
    "q.m25#8.e" to "高所での「分隊」自体にリスクはありますが、人手が足りるなら、最も経験のある人が遅れた人に付き添い、残りが先へ進むほうが、「全員で遅くなる」よりも「全員で無理に合わせる」よりも合理的なことが多いのです。\n要点は三つ。誰かが付き添う、連絡を保つ、状況と到着見込みを前方に伝える。完全に一人きりにするのが最悪の選択です。",

    "q.m25#9.p" to "行程全体における「登頂」の位置について、正しい認識はどれですか。",
    "q.m25#9.o0" to "登頂が行程の終点である",
    "q.m25#9.o1" to "登頂は行程の半分にすぎず、下山こそリスクが最も集中する段階である",
    "q.m25#9.o2" to "登頂が最も重要で、他は重要でない",
    "q.m25#9.o3" to "登頂できなければ行程は失敗である",
    "q.m25#9.e" to "多くの事故が下山中に起きます。目標を達成したあと警戒心が下がり、しかも体力は限界に近いからです。\n登頂を「半分」と捉えることは、下山のために同等の時間、体力、確保を計画に残すという意味です。すべての資源を上ることだけに使ってはいけません。",

    "q.m25#10.p" to "シナリオ：初めての高所での 24 時間",
    "q.m25#10.c" to "あなたは初めて 5,000 m 級のトレッキング登山に参加しました。標高 4,300 m のキャンプに着いてから、24 時間のあいだにいくつかの出来事が起きます。",
    "q.m25#10.e" to "この四段階の核心は医学知識ではなく、二つの習慣です。正直に話すこと、そして評価し直すこと。高所の行程で人を危険へ押し込むのは、ある一度の判断ミスではなく、「我慢する」「迷惑をかけない」という小さな選択の積み重ねです。",
    "q.m25#10.s0.p" to "第 1 段階：夕方、頭痛が始まり食事が取れません。同行者は「よくあること、寝れば治る」と言います。どうすべきですか。",
    "q.m25#10.s0.o0" to "同行者の言うとおりにして、寝て治るのを待つ",
    "q.m25#10.s0.o1" to "感じていることをガイドに正直に伝え、指示に従って休み、少量ずつ頻回に飲食する",
    "q.m25#10.s0.o2" to "自分で薬を探して飲み、誰にも言わない",
    "q.m25#10.s0.o3" to "寝つきをよくするため少し酒を飲む",
    "q.m25#10.s0.e" to "頭痛と食欲低下は高所でよく起こりますが、「よくある」は「無視してよい」と等しくありません。正直な報告＋基本的な処置（休息、水分、少量の食事）が標準的な対応です。\n要点は、あなたの状態が変わったとき、ガイドがその瞬間に知れること。翌朝になって初めて気づくのでは遅いのです。",
    "q.m25#10.s1.p" to "第 2 段階：夜はほとんど眠れませんでした。翌朝、隊は上昇を続ける準備をしています。あなたの選択は？",
    "q.m25#10.s1.o0" to "何も言わず、そのままついていく",
    "q.m25#10.s1.o1" to "睡眠の状況を伝え、続行すべきかガイドに評価してもらう",
    "q.m25#10.s1.o2" to "自分で残ることに決め、隊には伝えない",
    "q.m25#10.s1.o3" to "隊全体に止まって回復を待つよう求める",
    "q.m25#10.s1.e" to "睡眠不足は高所で最もよくある悩みの一つで、それ単独では通常、上昇を止める理由になりません。ただし評価の材料には含めねばならず、黙って抱え込むべきではありません。\nガイドは頭痛、食欲、動作の状態と合わせて判断します。そこが経験の価値です。",
    "q.m25#10.s2.p" to "第 3 段階：隊は上昇を続け、あなたは昨日より少し楽ですが、歩みはとても遅い。このときの心構えとして最も警戒すべきものは何ですか。",
    "q.m25#10.s2.o0" to "同行者に笑われるのではないかという不安",
    "q.m25#10.s2.o1" to "「せっかく来たのだから無駄にできない」という考え。それは止まるべきときに止まれなくさせる",
    "q.m25#10.s2.o2" to "写真を撮りたい衝動",
    "q.m25#10.s2.o3" to "天候への心配",
    "q.m25#10.s2.e" to "サンクコストは二日目に最も顔を出します。一晩つらかった。ここで諦めたら、昨夜のつらさが「無駄」になる。\nこの考えは、すでに払った代償を「続ける理由」に変えてしまい、評価し直すべきサインとして扱えなくします。",
    "q.m25#10.s3.p" to "第 4 段階：結局頂上には届かず、終点まで一時間の地点で下山しました。この行程をどう捉えますか。",
    "q.m25#10.s3.o0" to "失敗だった。次は来ないほうがよい",
    "q.m25#10.s3.o1" to "有効な順応の経験だった。下山は判断力の表れであり、失敗ではない",
    "q.m25#10.s3.o2" to "同行者が足を引っ張ったせいだ",
    "q.m25#10.s3.o3" to "次は何があっても頂上まで行く",
    "q.m25#10.s3.e" to "高所順応は何度もさらされてはじめて築かれます。初めて 4,000〜5,000 m に来た時点で、「登頂」を唯一の目標にすべきではありません。\nしかも、引くべきときに引けることこそ、このスポーツで最も評価される能力です。それは一度のまぐれ当たりの登頂より、あなたを遠くへ連れて行きます。",

    "q.m25#11.p" to "シナリオ：隊のプレッシャー",
    "q.m25#11.c" to "行程 4 日目、天候が悪化しはじめ、隊のなかに意見の相違が生まれています。あなたの心のなかには、みんなとは少し違う判断があります。",
    "q.m25#11.e" to "このシナリオが試すのは「保留意見を口にすること」です。現実には難しい。代償は社交的なもの（水を差す、輪を乱す）に見え、利益は見えにくい（起こりえた事故を避けた）からです。この三点を覚えておけば、次はもっと早く口を開けます。",
    "q.m25#11.s0.p" to "第 1 段階：「突っ込もう、明日は天気が良くなるかもしれない」と言う人と、下山を主張する人がいます。あなたは下山寄りですが、水を差す人にはなりたくありません。どうすべきですか。",
    "q.m25#11.s0.o0" to "黙って流れに従う",
    "q.m25#11.s0.o1" to "自分の判断と根拠を口に出す",
    "q.m25#11.s0.o2" to "陰で少し愚痴って終わりにする",
    "q.m25#11.s0.o3" to "続行に賛成するふりをして、内心では保留しておく",
    "q.m25#11.s0.e" to "高リスク環境の「沈黙する少数」は、事故の振り返りで常連です。保留があるのに言わないことは、隊に不完全な情報で判断させることになります。\n懸念を口にする代償は小さく、ゼロで済むかもしれません。言わない代償は、非常に大きくなりえます。",
    "q.m25#11.s1.p" to "第 2 段階：議論の末、隊は上昇を続けることに決めました。それでもあなたは不適切だと感じています。次にどうすべきですか。",
    "q.m25#11.s1.o0" to "消極的に実行し、最低限のことだけやる",
    "q.m25#11.s1.o1" to "保留を明確に伝え、折り返し条件と撤退計画を確認する",
    "q.m25#11.s1.o2" to "すぐに一人で下山する",
    "q.m25#11.s1.o3" to "もう何も言わず、心のなかで不満を持つ",
    "q.m25#11.s1.e" to "決定が下されたあとにできることは三つです。明確な記録を残す（私は反対、理由は……）、撤退条件が明確かを確認する、自分がまだ実行する意思と能力があるかを確かめる。\n保留意見は消極的実行と等しくありません。意見を述べたあとも、自分の担当はきちんと果たします。",
    "q.m25#11.s2.p" to "第 3 段階：結果としてあなたの懸念は当たり、隊は早めに下山しました。この経験の価値はどこにありますか。",
    "q.m25#11.s2.o0" to "自分が他人より優れていると証明された",
    "q.m25#11.s2.o1" to "「事前に保留を伝えること」が有効で、しかも関係を壊さないと確認できた",
    "q.m25#11.s2.o2" to "今後は単独で行動すべきだと分かった",
    "q.m25#11.s2.o3" to "登頂していないので価値はない",
    "q.m25#11.s2.e" to "初めて保留を口にするとき、多くの人は「輪を乱す人」と思われるのを恐れます。しかし実際の隊は、こうしたやり取りによって互いへの信頼をむしろ深めます。隊のなかに真実を言う人がいると分かるからです。\nこの経験を覚えておけば、次はもっと早く口を開けます。"
)
